-- ============================================================
-- Son18a (1/4): Günə-özəl push bildirişlərinin ru+tr tərcüməsi
-- pregnancy_day_notifications (294) + mommy_day_notifications (4370) — Azure/Fable
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3'::uuid, 'Самое маленькое начало 🫧', 'Пока его не увидеть невооружённым глазом. Будущий малыш — всего лишь одна клетка, но у него большие планы!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'Волшебный момент настал? ✨', 'Обычно оплодотворение происходит именно в эти дни. Вы можете ничего не чувствовать, но чудесный процесс уже начался.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'Белковая бомба 🍳', 'На завтрак яйца? Белок необходим для обновления клеток. Приятного аппетита!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'Прогуляемся? 👟', 'Свежий воздух поднимет вам настроение. Загляните в раздел упражнений и попробуйте программу лёгкой ходьбы.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'Размером с маковое зёрнышко 🌱', 'Малыш уже устраивается в матке. Хотя он ещё совсем крошечный, его сердце начинает формироваться.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'Пакет ДНК готов! 🧬', 'Цвет глаз, волосы и пол малыша уже закодированы. Как думаете, на кого он будет похож?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'Ягодный фейерверк 🍓', 'Малина или клубника? Эти богатые антиоксидантами ягоды помогут укрепить ваш иммунитет.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'Происходит тихая революция 🤫', 'Оплодотворённая яйцеклетка прикрепляется к стенке матки. Вы можете ничего не чувствовать, но внутри происходит удивительный процесс.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'Кальций для костей 🥛', 'Молоко, йогурт или сыр? Сегодня обязательно включите в рацион молочные продукты — они нужны для формирования будущего скелета малыша.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'Нет сил? На то есть причина 🥱', 'Уровень гормона прогестерона повышается. Если вас тянет в постель, не сопротивляйтесь — отдохните!'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'Забыли принять витамин? 😬', 'Фолиевая кислота — основа моего будущего позвоночника! Загляните в «Напоминание о лекарствах»: вы приняли сегодняшнюю дозу? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'Кровянистые выделения — это нормально? 🩸', 'Не пугайтесь, это может быть имплантационное кровотечение. Если у вас есть сомнения, загляните в раздел «Врачи».'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'Вы — железная леди? 🥩', 'Объём вашей крови будет увеличиваться. Ешьте красное мясо или чечевицу и скажите анемии «стоп».'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'Волнительное ожидание... 🧘‍♀️', 'Приближается время менструации. Чтобы снизить уровень стресса, послушайте записи в разделе «Белый шум».'),
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d', 'Начинается новое путешествие! 🚀', 'Ваше тело готовится принять великое чудо. А вы готовы?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'Забыли о витаминах? 💊', 'Фолиевая кислота сейчас — ваш лучший друг. Загляните в раздел «Питание», чтобы заложить здоровую основу для будущего малыша!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'Как вы себя сегодня чувствуете? 🌈', 'В начале нового периода ваши эмоции могут меняться. Запишите сегодняшние чувства в Дневник настроения и наблюдайте за своим состоянием.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'Пока он микроскопический 🔬', 'Большие истории начинаются с крошечных частиц. Сейчас будущий малыш существует лишь как замысел, но его потенциал безграничен!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'Время детокса! 🚫', 'Сигареты, алкоголь или избыток кофеина? Самое время с ними попрощаться. Здоровая мама = Здоровое начало.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'Бутылка воды рядом? 💧', 'Сейчас поддерживать водный баланс организма вдвойне важно. Не забывайте выпивать свою дневную норму воды.'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'Планируйте будущее 💭', 'Хотите загрузить в Альбом беременности первую фотографию — самое «начало» вашей истории?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'Закладываем фундамент 🏗️', 'Ваше тело готовится к новому чуду, а менструация подходит к концу. Для здорового развития будущего малыша важно обеспечить запас фолиевой кислоты (B9). Вы уже заглянули в раздел «Питание», чтобы ознакомиться с богатым меню? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'Сон — это так приятно 😴', 'Вам нужно набираться сил. Пока не наступили бессонные ночи, старайтесь спать не менее 8 часов в сутки.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'Включите силу зелени! 🥦', 'Шпинат и брокколи — не просто овощи, а настоящая природная кладовая витаминов. Обязательно добавьте сегодня в своё меню что-нибудь зелёное.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'Вы уже выбрали врача? 👩‍⚕️', 'Начните заранее искать специалиста, которому сможете доверять. Отзывы в разделе «Врачи и клиники» помогут вам определиться с выбором.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'Тело подаёт сигналы? 🌡️', 'Приближается овуляция. Следите за температурой тела — наступают дни с самыми высокими шансами на зачатие!'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'Время орехов и миндаля 🥜', 'Для перекуса выбирайте не чипсы, а орехи. Омега-3 необходима и вам, и будущему малышу.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'Уделите время себе 💆‍♀️', 'Прогоним гормоны стресса! Посмотрите сегодня любимый фильм или примите тёплый душ.'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'Имбирный чай спешит на помощь! 🍵', 'Тошнота не отступает? Имбирь успокаивает желудок. Рецепты вы найдёте в разделе питания.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'Усталость на пике? 😴', 'Ваш организм работает как фабрика энергии. Короткий дневной сон — ваше законное право будущей мамы!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'Сладкая горошинка 🟢', 'Примерно 6 mm. Ручки и ножки начинают появляться в виде крошечных почек. Маленький пловец!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'Как гоночная машина! 🏎️', 'Сердце малыша бьётся 100-160 раз в минуту. Вдвое быстрее вашего! Этот звук покажется вам музыкой.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'Не допускайте снижения сахара в крови! 📉', 'На пустой желудок тошнота усиливается. Всегда держите в сумке крекеры или сухофрукты.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'Туалетный марафон? 🚻', 'Частые походы в туалет — это нормально. Ваши почки работают активнее. Но не сокращайте количество воды, а пейте больше!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'Тебя тошнит? Прости! 🥺', 'Гормоны устроили вечеринку, и виновник — я. Я тебя мучаю? Давай съедим солёный крекер? 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'Формируется личико 👀', 'Появляются глаза, нос и уши. Пока они похожи на чёрные точки, но черты лица уже намечаются.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'Где найти витамин B6? 🍌', 'Банан, авокадо или куриное мясо... Этот витамин может облегчить тошноту.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'Тайная танцевальная вечеринка! 💃', 'Хотя вы ещё ничего не чувствуете, малыш уже двигается. Его первые движения похожи на лёгкие подёргивания.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'Солёный огурец или шоколад? 🥒', 'Необычные пищевые желания — это нормально. Но следите за сахаром! В разделе питания вы найдёте полезные альтернативы.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'Брюки стали тесными? 👖', 'Вы указали свой исходный вес в трекере веса? 📈'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'Снова как в подростковом возрасте? 😳', 'На лице могут появиться прыщи. Всё из-за гормонов! Поддерживайте кожу в чистоте и не принимайте лекарства без назначения врача.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'Уже сделали наше первое фото? 🤰', 'Загрузите в галерею первое фото вашего животика! ✨'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'Заглянули в календарь? 🗓️', 'Если менструация задерживается, возможно, пора сделать тест? Поделитесь с нами радостной новостью!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'Размером с кунжутное семечко! 🌱', 'Теперь малыш официально называется эмбрионом. Он быстро растёт, а вы меняетесь.'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'Тошнит? 🤢', 'По утрам особенно тяжело? Имбирный чай или вода с лимоном могут помочь. Не оставляйте желудок пустым.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'Идёт важное строительство! 🚧', 'Формируются головной мозг и позвоночник. Продолжайте принимать фолиевую кислоту!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'Утренняя тошнота? 🤢', 'Съешьте солёный крекер, не вставая с постели. Ешьте понемногу, чтобы поддерживать стабильный уровень сахара в крови.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'Тук-тук... Слышите? 💓', 'Моё сердце начало биться! Уже не терпится услышать этот маленький моторчик? Отметьте в календаре дату первого УЗИ! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'Пора получить официальное подтверждение! ✅', 'Если вы ещё не были у врача, запишитесь на приём. Найдите подходящего специалиста в разделе «Врачи».'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'Первые удары сердца 💓', 'Хотя вы их пока не слышите, крошечное сердце уже работает. Оно бьётся более 100 раз в минуту!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'Чудо воды с лимоном 🍋', 'Она может уменьшить тошноту и помогает поддерживать водный баланс. Недостаток жидкости может вызвать головную боль.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'Батарейка садится? 🔋', 'Силы могут быстро заканчиваться. Короткий дневной сон поможет вам восстановиться.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'Мне нужен бассейн! 🏊‍♀️', 'Мама, вы создаёте воду, в которой я буду плавать, — амниотическую жидкость. Откройте Трекер воды. Вы уже выпили стакан воды? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'Эмоциональные качели 🎢', 'Сначала смех, потом слёзы... Гормоны не сводят вас с ума — они просто делают свою работу.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'Стали чувствительнее к запахам? 👃', 'Не заставляйте себя есть то, что вам неприятно. Подходящие альтернативы ищите в разделе «Питание».'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'Мозг развивается! 🧠', 'Нервная трубка закрывается. Не прекращайте принимать фолиевую кислоту — сейчас закладывается основа будущего гения!'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'Проблемы с запором? 🚽', 'Пейте больше воды и ешьте продукты, богатые клетчаткой. Киви и курага могут творить чудеса.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'Я вас стесняю? Простите!', 'Хотя вы ещё не набрали вес, я расширяю свой домик. Давайте снимем эти тесные брюки и наденем что-нибудь удобное. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'Соленья или шоколад? 🍫', 'Загляните в раздел питания — что полезного сегодня в меню? 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'Формируется чувство вкуса 👅', 'На языке малыша появляются вкусовые рецепторы. Он тоже будет чувствовать вкус блюд, которые вы едите.'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'Вы сократили потребление кофеина? ☕', 'Не больше 1 чашки в день. Попробуйте чай без кофеина или травяные чаи.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'Я танцую! 🕺', 'Ручки и ножки малыша сгибаются. Он занимается акробатикой в вашей матке, но вы пока этого не чувствуете.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'Овощной суп? 🥣', 'Если желудок не принимает тяжёлую пищу, съешьте лёгкий суп. Это и витамины, и жидкость!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'Время двигаться 🧘‍♀️', 'Хотите больше двигаться? Давайте посмотрим, какие упражнения подходят вам в разделе тренировок.'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'Привлеките и папу 🗣️', 'Это не только ваше приключение. Вместе посмотрите первый снимок УЗИ и обсудите планы на будущее.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'Зубки пока не режутся... 😬', 'Молоко, йогурт, сыр... Есть ли они сегодня в вашем рационе? 🥛'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'Не переносите запах мяса? 🥩', 'Вам необходим белок! Если вы не можете есть мясо, замените его чечевицей, нутом или орехами.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'Бюстгальтер стал тесным? 👙', 'Грудь увеличивается и становится чувствительной. Пора перейти на удобное бельё спортивного типа без косточек.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'Вашему организму нужна вода! 💧', 'Обезвоживание может вызвать головную боль. Откройте Трекер воды и выпейте стакан воды! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'Он уже похож на человечка! 👶', 'А как насчёт того самого сияния беременности на вашем лице? ✨ Сохраните эту красоту навсегда в Галерее!'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'Пора раскрыть секрет? 📢', '1-й триместр подходит к концу. Риск снизился. Вы готовы поделиться радостной новостью с друзьями?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'Скелет становится крепче! 🦴', 'Мягкие хрящи превращаются в кости. Пополняйте запасы кальция, чтобы малыш рос крепким!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'Вы создаёте целый океан! 🌊', 'Амниотическая жидкость обновляется. Не забывайте пить достаточно воды, чтобы малыш плавал в чистом бассейне.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'Чешется живот? 🌵', 'Зуд при растяжении кожи — это нормально. Нанесите миндальное масло или специальный крем, чтобы почувствовать облегчение.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'Энергия возвращается? 🔋', 'Как вы себя сегодня чувствуете? Запишите это в Дневнике симптомов! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'Я назову тебя мамой... 🥺', 'Мои голосовые связки формируются. Сейчас я ещё молчу, но представляешь ли ты тот день, когда я впервые позову тебя? А я представляю...'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'Сила орехов 🐿️', 'Омега-3 важна для развития мозга. Носите в сумке орехи: они и насыщают, и способствуют развитию интеллекта малыша.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'Золотой период начался! ✨', 'Поздравляем! Вы вступили во 2-й триместр. Энергии становится больше, а риск снижается. Теперь самое время наслаждаться беременностью.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'Нужна энергетическая бомба 💥', 'Малыш быстро растёт. Красное мясо, яйца или бобовые... Не забывайте пополнять запасы железа и белка.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'Размером с лимон! 🍋', 'Примерно 7-8 см. Малыш уже умеет поворачивать голову и хмуриться. Его мимика развивается!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'Загляните в свой гардероб 👗', 'Пуговицы не застёгиваются? Отложите тесные брюки. Переходите на свободную, удобную одежду из натуральных тканей.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'Девочка или мальчик? 🩷💙', 'Половые органы полностью формируются. Хотя на УЗИ пол пока трудно определить, малыш уже знает, кто он! Как вы думаете, кто там?'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'Клетчатка — настоящий герой 🌾', 'Чтобы улучшить пищеварение, отдавайте предпочтение овсянке, овощам и фруктам. В разделе «Питание» есть рецепты вкусных салатов.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'Поднимаете тяжести? 🏋️‍♀️', 'У малыша уже накапливается подкожный жир, а его скелет становится крепче. Мы быстро набираем вес!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'Поток питательных веществ ускорился!', 'Что полезного вы сегодня съели? Загляните в список продуктов! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'Сосёт пальчик! 👍', 'Во время УЗИ вы можете увидеть, как малыш сосёт большой палец. Так он тренирует сосательный рефлекс, который понадобится после рождения.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'Любите плавать? 🏊‍♀️', 'Малыш живёт в водной среде. Чтобы околоплодных вод было достаточно, пейте больше воды в течение дня.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'Говорите громче! 🗣️', 'Малыш уже отчётливо слышит ваш голос и сердцебиение. Начните петь ему колыбельные — это его успокаивает. 🎶'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'Вы — Железная леди! 🦸‍♀️', 'Чтобы избежать головокружения, ешьте красное мясо или чечевицу. Рецепты вы найдёте в разделе питания.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'Размером с яблоко 🍎', 'Можете смело расстегнуть пуговицу на брюках и расслабиться! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'Кровоточат дёсны? 😬', 'Из-за гормонов дёсны становятся чувствительными. Пользуйтесь мягкой зубной щёткой и полощите рот солёной водой.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'Я слышу тебя, мама! 👂', 'Слуховые косточки укрепляются. Малыш уже узнаёт интонации вашего голоса, смех и сердцебиение.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'Скелет малыша укрепляется🦴', 'Чтобы поддержать запасы кальция, включите в рацион молоко, йогурт или миндаль.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'Спите на левом боку 🛌', 'Сон на спине может затруднять кровообращение. Положение на левом боку улучшает поступление кислорода и к вам, и к малышу.'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'День SPA? ✨', 'Кожа малыша покрыта специальной защитной смазкой, чтобы не размокать в околоплодных водах. А вы? Сегодня обязательно уделите время себе! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'Я вижу свет! 💡', 'Хотя веки малыша ещё закрыты, он уже чувствует яркий свет. Если посветить фонариком на живот, он может отвернуться.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'Убегаем от запора 🏃‍♀️', 'Вместо лекарств пейте больше воды, ешьте чернослив и киви.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'Где ключи? 🔑', 'Забывчивость — это нормально. Ваш мозг сейчас занят гораздо более важным делом: создаёт человека! Начните составлять списки.'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'Взрыв витамина C 🍊', 'Апельсин, киви или сладкий перец... Поддерживайте иммунитет крепким как сталь — болеть сейчас нельзя!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'Почки заработали! 🚽', 'Невероятно, но малыш уже мочится. Он заглатывает амниотическую жидкость и выводит её. Круговорот начался!'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'Не забывайте о кальции 🥛', 'Формируются зачатки зубов. Творог, сыр или йогурт... Всё это необходимо для его будущей улыбки!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'Болит голова? 🤕', 'Не спешите принимать лекарство. Отдых в тёмной комнате, холодный компресс или массаж могут помочь лучше.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'Кровообращение набирает обороты! 🌊', 'Объём крови в сосудах увеличивается, а сердце работает быстрее. Вода необходима для охлаждения этой системы. Не забывайте пить воду, чтобы избежать головокружения! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'Идут строительные работы! 🏗️', 'Малышу нужен кальций! Загляните в раздел питания и обратите внимание на молочные продукты. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'Рыбный день! 🐟', 'Выбирайте рыбу с низким содержанием ртути. Омега-3 незаменима для развития мозга.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'Скажите растяжкам «Нет»! 🧴', 'Даже если живот ещё не округлился, увлажняйте кожу. Миндальное или кокосовое масло также помогает уменьшить зуд.'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'Уже размером с грейпфрут! 🍊', 'Ваша талия может стать шире. Цифры изменились? Запишите их в Трекере веса! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'Пора пройти двойной тест? 🗓️', 'Период между 11-14 неделями очень важен. Обсудите с врачом обследование для оценки риска синдрома Дауна.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'Вы голодны или хотите пить? 🤔', 'Иногда мозг путает голод с жаждой. Сначала выпейте стакан воды. Если вы всё ещё голодны, значит, пора перекусить.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'Время гимнастики! 🤸', 'Малыш уже сжимает кулачки и открывает рот. Вы пока этого не чувствуете, но внутри проходит настоящая олимпиада!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'Растёт маленький умница! 🧠', 'Йод необходим для развития мозга. Есть ли в вашем меню йодированная соль, рыба или молочные продукты?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'Я потягиваюсь! 🤸', 'И вы не оставайтесь без движения, мама. Посмотрим лёгкие упражнения йоги в разделе тренировок?'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'Кто дружит с железом? 🍊', 'Если вы принимаете железо, обязательно сочетайте его с витамином C. Так железо усваивается лучше.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'Болит поясница? 👠', 'Уберите обувь на высоком каблуке в шкаф — пришло время комфорта! Выбирайте ортопедическую обувь.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'Тянет по бокам? ⚡', 'Может внезапно кольнуть, не пугайся — я просто расширяю свой домик! Попробуй расслабляющие упражнения из раздела с упражнениями. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'Паспорт готов! 🛂', 'Отпечатки пальцев полностью сформировались. У малыша уже есть узоры, которых нет больше ни у кого в мире. Скоро появится уникальная личность!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'Вода кажется безвкусной? 💧', 'Если вам трудно пить обычную воду, попробуйте добавить в неё огурец, арбуз или мяту. Обезвоживание может вызвать головную боль.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'Мама, я тебя слышу! 👂', 'Твой голос звучит для меня как колыбельная. А биение твоего сердца — самый прекрасный ритм. Разговаривай со мной чаще, я хочу тебя узнать.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'Цинк: тайный герой 🛡️', 'Мои клетки быстро делятся. Мне нужен строительный материал! В твоём меню есть красное мясо, сыр или орехи?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'Я размером с манго! 🥭', 'Примерно 15 см. Моя кожа пока тонкая, но уже начинает формироваться жировая прослойка. Теперь я выгляжу более пухленьким, мама!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'Почувствовала? Это толчок! ⚽', 'Мама, я не сплю! Это лёгкое трепетание — так я говорю тебе: «Привет!». Положи руку на живот — может, я снова толкнусь?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'Мальчик или девочка? 💙💗', 'Приближается время УЗИ, на котором можно будет узнать мой пол. Волнуешься?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'У меня появилась первая игрушка!', 'Я хватаю пуповину, играю с ней и иногда сжимаю её. Мои пальчики уже учатся хватать.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'Время важной встречи! 🗓️', '18-22 недели — время самого подробного УЗИ. Врач рассмотрит мои пальчики, сердце и всё остальное. Ты уже записалась на приём?'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'Я размером с банан! 🍌', 'Примерно 18-20 см. Теперь меня измеряют от макушки до пяток. Я расту в длину, а моё тело становится более пропорциональным.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'Тс-с, я сплю 😴', 'У меня тоже есть режим сна, мама. Когда ты ходишь, меня укачивает и я засыпаю, а когда ложишься — просыпаюсь и устраиваю дискотеку! Прости 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'Половина пути позади! 🏁', 'Поздравляем! Уже прошло 20 недель. Вы на экваторе беременности. Вы великолепны — это стоит отметить!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'Загрузка... 50% ⏳', 'Поздравляю! Мы прошли половину пути. В честь этого знаменательного дня стоит добавить фотографию в Галерею! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'Папа меня почувствует?', 'Если он положит руку вам на живот, возможно, я тоже с ним поздороваюсь.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'Вам снятся яркие сны?', 'Сны во время беременности похожи на фильмы, правда? Я тоже появляюсь в ваших снах? 😴'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'Нужно железо 🏗️', 'Я занят созданием красных кровяных клеток. Помогите мне: съешьте говядину, шпинат или чечевицу.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'Отёки ног? 👠', 'Могут появиться отёки. На работе или дома старайтесь по возможности держать ноги приподнятыми. Выбирайте удобную обувь!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'Ик... Ик... 🤭', 'Живот ритмично подрагивает? Не бойтесь, мама, это всего лишь икота! Я тренирую диафрагму.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'Различает вкусы! 👅', 'Вкус околоплодных вод меняется в зависимости от того, что вы едите. Съели острый перец? Малыш это почувствует!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'Мои глаза танцуют...', 'Хотя мои веки закрыты, я уже вижу сны. Как вы думаете, что мне снится?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'Мучает изжога? 🔥', 'Матка давит на желудок. Ешьте небольшими порциями, но часто. Не ложитесь сразу после еды, посидите прямо.'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'День заботы о себе 💅', 'Если появились пигментные пятна, защищайте кожу от солнца. Как насчёт того, чтобы сегодня сделать маску для лица?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'Изучает своё лицо! 👶', 'Малыш трогает руками лицо, нос и даже пуповину. Осязание развивается. Он знакомится с собой!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'Солёные огурцы с мороженым? 🥒🍦', 'Хочется необычных сочетаний? Это сигналы вашего организма. Но старайтесь употреблять сахар и соль в умеренных количествах.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'Размером с кокос! 🥥', 'Примерно 28 см. Вес малыша уже превысил полкилограмма! Теперь он толкается сильнее.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'Судороги в ногах? 🦵', 'Возможно, вам не хватает магния и кальция. Съешьте банан, миндаль или йогурт. И не забывайте пить достаточно воды!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'Размером с грушу! 🍐', 'Малыш растёт, а его тело выпрямляется. Теперь он уже может держать голову прямо. Он растёт, а вы становитесь ещё прекраснее!'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'Тянет живот? 😣', 'Не делайте резких движений. Тёплый душ или лёгкий массаж могут уменьшить боль.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'Отпечатки пальцев готовы! 🖐️', 'Уникальные узоры, которых больше нет ни у кого в мире, уже сформировались. Малыш уже сейчас неповторим. Разве это не удивительно?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'Часто хочется есть? 😋', 'Повышенный аппетит — это прекрасно, но есть за двоих не нужно. Выбирайте полезные и питательные продукты: орехи, фрукты и овощи.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'Заложен нос? 🤧', 'Это не простуда, а ринит беременных. Используйте солевой спрей и увлажняйте воздух в комнате.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'Быстрая доставка! 🚚', 'Когда мне хочется есть, я могу начать толкаться. Что полезного на сегодня есть в разделе питания? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'Формируется жировая прослойка 🧸', 'Малыш начинает накапливать жир, чтобы сохранять тепло.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'Запор не отступает? 🚽', 'Продукты, богатые клетчаткой, и достаточное количество воды — лучшие помощники. Не оставайтесь без движения: ежедневные прогулки стимулируют работу кишечника.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'Кости становятся крепче! 🦴', 'Мягкие, словно резина, хрящи превращаются в кости. Пополняйте запасы кальция, чтобы скелет малыша стал крепким как сталь!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'Покончим с головокружением! 🛑', 'По мере увеличения объёма крови растёт и потребность в железе. Шпинат, гречка или красное мясо... Обязательно добавьте их в своё меню!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'В животе дискотека? 💃', 'Я учусь делать сальто! Вы почувствовали?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'Снятся странные сны? 😴', 'Из-за гормонов ночи могут превратиться в настоящее кино. Не пугайтесь, это нормально. Записывайте свои сны в Дневник настроения!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'Природный защитный крем! 🧴', 'Чтобы кожа малыша не сморщилась, она покрывается белым сыроподобным веществом — верниксом. Это природный защитный крем!'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'Включим музыку? 🎶', 'Мама, я слышу звуки снаружи! Мне тоже нравятся ваши любимые песни. Потанцуем вместе?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'Пупок стал выпуклым? 🔘', 'По мере роста живота пупок может выпячиваться. Не волнуйтесь, после родов всё вернётся в норму!'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'Схватки или тренировка? 🤔', 'Живот становится твёрдым? Это могут быть тренировочные схватки. Матка готовится к родам. Если боли нет, это нормально.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'Избегайте солёной пищи 🧂', 'Если отекают ноги, уменьшите количество соли. Также могут помочь обильное питьё и петрушка. Кольцо не стало тесным на пальце?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'Маленькая фабрика заработала! 🏭', 'Теперь клетки крови вырабатывает уже не моя печень, а костный мозг. Какие продукты, богатые железом, помогут мне?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'Тсс, я сплю... 🤫', 'Мама, почему я не двигаюсь? Потому что большую часть дня я сплю. Пока я сплю, вы тоже отдыхайте.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'Время для незаметной тренировки! 🧘‍♀️', 'Не забывайте об упражнениях Кегеля. Сидя на месте, напрягайте и расслабляйте мышцы тазового дна. Это пригодится во время родов!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'Первые дыхательные тренировки! 🫁', 'В моих лёгких вырабатывается сурфактант. Это вещество поможет мне сделать первый вдох после рождения. Я тренируюсь!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'Что это был за звук, мама? 🔊', 'От внезапного шума я вздрагиваю. Когда вы спокойны, я тоже спокоен. Споёте мне колыбельную?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'Вы — моя колыбель... 💤', 'Когда вы ходите, меня укачивает, и я засыпаю. А когда останавливаетесь — просыпаюсь! Продолжим неспешные прогулки, чтобы убаюкать меня? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'Выпили сладкую воду? 🥤', 'Тест на гестационный диабет очень важен. Обязательно пройдите его ради здоровья нас обоих.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'На животе появилась полоска? ➖', 'Тёмная линия на животе, или Linea Nigra, появляется из-за гормонов. Не волнуйтесь, после родов она исчезнет. Вы прекрасны в любом состоянии!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'Мои шансы выжить выросли! 🌟', 'Мне исполнилось 24 недели! С медицинской точки зрения теперь я считаюсь жизнеспособным. Это очень важный этап, мама.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'Мучает изжога? 🔥', 'Она возникает не из-за того, что у меня растут волосы, а потому, что матка давит на желудок. Не ложитесь сразу после еды, посидите с прямой спиной.'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'Мама, мне скучно! 🤸', 'Когда вы отдыхаете, я просыпаюсь. Погладьте животик — может быть, я отвечу вам лёгким толчком?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'Я уже размером с дыню! 🍈', 'Мой вес — примерно 600 граммов. Теперь мне становится немного тесно. Мои толчки могут стать сильнее, простите! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'Обувь стала тесной? 👟', 'Размер вашей ноги может увеличиться. Сейчас главное не стиль, а комфорт. Перейдите на просторные кроссовки!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'Мои волосы обретают цвет! 🎨', 'Генетическая лотерея началась. Блондин, брюнет или рыженький? В моих волосах появляется пигмент. Как думаете, на кого я буду похож?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'Устали от отёков? 🎈', 'Парадокс: вода помогает уменьшить отёки. Продукты с высоким содержанием воды, например огурцы и арбуз, тоже могут помочь. Старайтесь есть меньше соли.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'Я розовею...', 'Моя кожа уже не прозрачная, как стекло! Капилляры наполняются кровью, и кожа приобретает розовый оттенок. Для хорошего кровообращения не забывайте пить воду с помощью Трекера воды! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'Ой! Что это был за звук? 😳', 'Я вздрогнул, когда хлопнула дверь. Мама, я уже очень хорошо слышу. Включите спокойную музыку, и давайте отдохнём вместе.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'Мой носик открылся! 👃', 'Раньше мои ноздри были закрыты, а теперь открылись. Я тренируюсь дышать.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'Пищеварение замедлилось? 🐌', 'Прогестерон замедляет работу кишечника. Курага, чернослив и хлеб с отрубями могут стать вашими помощниками.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'Постройте крепость из подушек! 🏰', 'Не получается удобно устроиться во время сна? Положите подушки между ног и под живот. Поддержка сейчас необходима!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'Я мастер йоги! 🦶', 'Вы не поверите, но я могу схватить пальчик ноги и положить его в рот! Я очень гибкий. А вам уже трудно наклоняться?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'Я открыл глаза! 👀', 'Мама, вы не поверите, но я уже поднял веки. Хотя вокруг темно, мой взгляд уже формируется. Совсем скоро я вас увижу!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'Я слышу папу? 🗣️', 'Мужской голос звучит ниже, поэтому я слышу его лучше. Поговорите с папой, пусть он почитает мне сказку.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'Вы — мой щит!', 'Моя иммунная система формируется, и от вас ко мне поступают антитела. Вы защищаете меня от болезней, мама. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'Мучают судороги? 🦶', 'Ночью сводит икры? Возможно, не хватает магния. Банан, миндаль или йогурт... Вашим мышцам нужно расслабиться.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'Я открыл глаза! 👀', 'Хотя вокруг темно, я уже могу открывать глаза. Я моргаю ресничками. День, когда я увижу мир, уже близко!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'Мама, я вижу свет! ☀️', 'Я моргаю! Когда солнечный свет падает на твой живот, я вижу его сияние. Интересно, какого цвета мир?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'Время увлажнять кожу 🧴', 'Ваш живот быстро растёт, и кожа растягивается. Чтобы уменьшить зуд, ежедневно наносите увлажняющий крем.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'Первая защита — от вас 🛡️', 'Ваши антитела передаются малышу. Они будут защищать его в первые месяцы после рождения.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'Солёные огурцы? Нет! 🚫', 'Если у вас отекают ноги, сократите потребление соли до минимума. Соленья вкусные, но могут усиливать отёки. Лучше пейте воду с лимоном.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'Мир такой шумный... 🔊', 'Мой слух стал настолько чутким, что я слышу даже автомобильные сигналы с улицы. Давай немного отдохнём в тишине? Включи мне звук дождя из Белых шумов, и мы вместе подремлем. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'Я держу ритм 🥁', 'Моё сердце бьётся ритмично, а я тренируюсь дышать. Иногда я икаю.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'Впереди финишная прямая! 🏁', 'Последние дни 2-го триместра. Хорошенько выспитесь перед началом 3-го!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', 'Добро пожаловать в 3-й триместр! 🏁', 'Начался заключительный этап! Теперь вам будет становиться тяжелее, но финиш уже виден. Наберитесь терпения, мама!'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'В желудке пожар? 🔥', 'Матка давит на желудок снизу вверх. Молоко или горсть сырого миндаля могут помочь унять жжение.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'Размером с кочан брокколи 🥦', 'Моя жировая прослойка увеличивается, а ручки и ножки становятся пухленькими.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'Обустраиваем гнёздышко? 🐣', 'Моя кроватка, маленькая одежда... Составьте список вместе с папой в Совместных покупках! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'У вас отрицательная группа крови? 🩸', 'Это важная неделя для мам с отрицательным резус-фактором. Может потребоваться инъекция иммуноглобулина. Обсудите это с врачом!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'Ресницы выросли! 👁️', 'Я открываю и закрываю глаза. Различаю свет и темноту. Если вы посветите фонариком на живот, я отвернусь. Хотите попробовать?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'Рыба, рыба, рыба! 🐟', 'Сейчас мой мозг развивается особенно быстро. Мне нужна Омега-3. Вы едите рыбу 2 раза в неделю?'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'Какой у меня будет характер? ✨', 'Упрямый или чувствительный? Что говорит мой знак зодиака, определённый по предполагаемой дате рождения? Совместим ли он с вашим знаком? Давайте заглянем в гороскоп! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'Болят рёбра? 🥊', 'Прости, мама, мне здесь тесно. Когда я вытягиваю ножки, то упираюсь в твои рёбра. Попробуй сидеть прямо — это может помочь.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'Считаете толчки? 🦶', 'У меня уже формируется режим активности. Откройте Счётчик толчков и следите за моими движениями. Всё в порядке?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'В моём мозге появляются извилины! 🧠', 'Раньше он был гладким, а теперь на нём образуются извилины и борозды. Это значит, что миллиарды нейронов начинают работать. Растёт гений!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'Рефлюкс вас утомляет? 🔥', 'Желудочная кислота подступает к горлу? После еды может помочь жевательная резинка или тёплое молоко.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'Я размером с тыкву! 🎃', 'Примерно 39-40 см. Я вешу уже 1.2 кг! Вам тяжело меня носить? Простите, мама, но мне нужно набирать вес.'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'Я здесь, мама! 👋', 'Иногда я затихаю, а иногда танцую. Вы считаете мои толчки? Всё в порядке, просто мне становится тесно.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'На ногах появилась сосудистая сеточка? 🕸️', 'Может появиться варикозное расширение вен. Не стойте подолгу. По вечерам ложитесь и поднимайте ноги, опираясь ими о стену.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'Фабрика крови заработала 🩸', 'До сих пор клетки крови вырабатывала печень, а теперь это делает костный мозг. Так я готовлюсь к самостоятельной жизни!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'Железо+C витамин — отличная пара 🥩🍊', 'Чтобы снизить риск анемии, пейте апельсиновый сок вместе с мясом. C витамин улучшает усвоение железа в 2 раза.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'Большой кочан капусты 🥬', 'Моя кожа становится более гладкой, а щёчки округляются. Не могу дождаться встречи с вами!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'Трудно дышать? 😮‍💨', 'Поднимаясь выше, я давлю на диафрагму. Постарайтесь глубоко дышать, мама. Осталось совсем немного — скоро я опущусь ниже.'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'Вы уже подумали о сумке? 👜', 'Ещё не рано! Загляните в список вещей в роддом. Если собрать всё необходимое заранее, будет меньше стресса.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'Хотите, открою секрет? 🤫', 'Когда вы спите, я засыпаю, представляя ваш голос. Как думаете, кого я вижу во сне? Конечно же, вас! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'Это был шоколад? 🍫', 'М-м-м, его вкус добрался и до меня! Теперь у меня энергия бьёт через край. Давайте потанцуем, мама! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'Я уже размером с тыкву! 🎃', 'Мои щёчки становятся такими пухлыми, что вам захочется их покусать! Здесь тесновато, но мне нравится быть рядом с вами.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'Я лежу вниз головой! 🙃', 'Интересно смотреть на мир вверх тормашками! Я готовлюсь к родам, мама. В таком положении я ещё ближе к вам.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'Живот становится твёрдым? 🤰', 'Не пугайтесь, мамочка! Это всего лишь тренировка. Мы с вами — одна команда и вместе готовимся к этому важному дню!'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'Я слышу голос папы! 🧔', 'Когда я слышу его голос, моё сердце бьётся сильнее. Скажите ему, что я тоже здесь и передаю привет! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'Помогите моим косточкам окрепнуть! 💪', 'Мне нужен кальций, мама. Если вы выпьете стакан молока или йогурта, мы оба станем невероятно сильными! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'Тук-тук! Кто там? ✊', 'Иногда мои толчки причиняют вам боль? Простите 🥺 Я просто хочу прикоснуться к вам.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'Вам трудно дышать? 😮‍💨', 'Я поднялся немного выше и давлю на ваши лёгкие. Простите, мама, скоро я опущусь ниже, и вам станет легче дышать! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'Я почувствую ваш запах...', 'Вы представляете тот момент, когда возьмёте меня на руки? Я расту каждый день, мечтая об этом мгновении, мама! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'В моём домике становится тесно... 🏠', 'Теперь мои движения больше похожи на удары кулачками и локтями. Всё ли в порядке? Давайте вместе проверим Счётчик шевелений!'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'Вам нужен свежий воздух 🌿', 'Может, сегодня выйдем из дома и выпьем чаю в уютном месте с чистым воздухом? Загляните в раздел «Места для мам»!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'Тот самый важный день... ✨', 'Не будем спешить, но начнём понемногу собирать сумку. Давайте посмотрим, что входит в список вещей в роддом?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'Тсс... Я сплю 😴', 'Мой мозг развивается так быстро, что большую часть времени я сплю. Вы тоже отдохните, мама.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'Как вы меня назовёте? 👶', 'Если вы ещё не решили, загляните вместе с папой в список имён для малышей. Какое имя подойдёт мне больше всего?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'Моя комната, кроватка, маленькие вещички... 🐣', 'Вы купили всё необходимое? Загляните в раздел рекомендованных товаров — возможно, что-то забыли.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'Мышцы матки готовятся к родам.', 'Не бойтесь, это всего лишь тренировка. Если сокращения участились, проверьте интервал с помощью Счётчика схваток!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'Мой маникюр готов!', 'Вы не поверите, но мои ноготки уже доросли до кончиков пальцев.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'Встречи с врачом становятся чаще! 🩺', 'Вы уже выбрали роддом и врача для родов? Загляните в список врачей и клиник! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'То смеётесь, то плачете?', 'Это гормоны снова шалят. Страх перед родами смешивается с радостью от скорой встречи. Излейте душу в Дневнике настроения — вам станет легче. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'От вас ко мне переходит суперсила! 🛡️', 'Не болейте, мама! Ваш иммунитет станет моей первой бронёй. Мы непобедимая команда! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'Вам снова не спится? 🥺', 'А я сладко сплю. Закройте глаза и представьте меня... Может быть, мы встретимся во сне? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'Мои косточки становятся крепкими! 🦴', 'Но для этого я забираю ваши запасы... Простите! 🙈 Выпьете стакан молока — и мы помиримся? 🥛'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'Спойте эту песню ещё раз! 🎶', 'Ваш голос так меня успокаивает... Когда вы поёте, я танцую внутри. Чувствуете? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'Стены сжимаются вокруг меня! 🏠', 'Мне здесь уже совсем тесно, мама. Вытягиваю ножку и попадаю вам по рёбрам... Если было больно, можно я поцелую — и всё пройдёт? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'Вы погладили мою одежду? 👗', 'Я уже чувствую её запах. Знаю, вам не терпится увидеть меня в этих нарядах! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'В моём бассейне стало меньше воды... 💧', 'Мне нравится плавать в чистой воде, когда её много. Выпьете ради меня стакан воды? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'Проверяю путь! 🔦', 'Я лежу головой вниз и смотрю в сторону выхода. Просто глубоко дышите — всё будет отлично!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'Чья это тёплая рука? 🖐️', 'Папина? Когда я чувствую его прикосновение, то успокаиваюсь. Скажите ему, что я тоже приложил ручку — давайте пять! ✋'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'Я широко раскрыл глаза! 👀', 'Хотя здесь темно, я за всем наблюдаю. Интересно, я похож на вас или на папу? Вы уже поспорили? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'Тсс... Я сплю! 😴', 'Мой мозг развивается так быстро, что мне нужно много спать. Мама, отдохнёте вместе со мной? 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'Наводите дома порядок? 🌪️', 'Вам хочется всё убрать, разобрать шкафы... Это инстинкт гнездования! Но не переутомляйтесь: мне нужна отдохнувшая мама.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'Здесь стало совсем тесно! 🏠', 'Хочу повернуться, но места уже нет. Если выставлю локоть, ваш живот станет бугристым. Посмотрите и улыбнитесь! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'Мне нужны полезные жиры! 🥑', 'Авокадо, орехи или оливковое масло... Именно вы помогаете мне становиться пухленьким!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'Ваше сердце — моя колыбельная... 💓', 'Я лежу головой вниз, и моё ушко теперь ближе к вашему сердцу. Его ритм — единственная музыка, которая меня успокаивает.'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'Моя комната готова? 🧸', 'Смотрите на мою кроватку и мечтаете? Не могу дождаться, когда обниму игрушку, которую вы туда положили! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'Я опускаюсь ниже, чувствуете? ⬇️', 'Я устраиваюсь между костями вашего таза. Теперь вам станет легче дышать, зато в туалет придётся бегать чаще! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'Мой иммунитет укрепляется 🛡️', 'Антитела, которые я получаю от вас, готовят меня к встрече с миром микробов. А ваше молоко тоже будет защищать меня, мама!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'Где моя первая одежда? 👕', 'Вы уже собрали сумку в роддом? Погладьте тот маленький комбинезон, который наденете на меня...')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('deba1190-6096-4dec-88eb-70e669fb3ccb'::uuid, 'Я хочу вас увидеть! 👀', 'Мои глаза открыты, но здесь темно. Я считаю дни до встречи с вашим лицом и улыбкой. Осталось совсем немного! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'Моя кожа становится гладкой! 🧖‍♀️', 'Пушок на моём теле исчезает, а слой подкожного жира увеличивается. Я готовлюсь к вашим нежным прикосновениям, мама. Я буду мягким, как облачко! ☁️'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'Я набираюсь сил! ⚡', 'Я мало двигаюсь? Не бойтесь. Сейчас мне нужно поспать. Я коплю энергию для важного дня. Вы тоже отдохните! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'Почувствовали мой локоток? 💪', 'Простите, мама! Я хочу потянуться, но мне совсем тесно. Вы смеётесь, когда живот принимает причудливую форму? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'Ходите как пингвин? 🤭', 'Я опустился ниже, поэтому ваша походка изменилась. Но как бы вы ни выглядели и ни ходили, вы самая прекрасная мама на свете! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'Ик... Ик... 😲', 'Я снова икаю! Тренирую диафрагму. Если живот ритмично вздрагивает, знайте — это я!'),
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800', 'Мы были у врача? 👩‍⚕️', 'Когда этот холодный гель касается живота, мне щекотно! 🙈 Но я знаю, что звук моего сердцебиения успокаивает вас.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'Мы — одна команда! 🤝', 'Когда начнутся схватки, не бойтесь. Дышите глубоко. Вместе мы справимся, обещаю!'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'Сумки уже у двери? 🎒', 'В любой момент я могу сказать: «Сюрприз!». Вы положили в сумку ту самую первую шапочку, которую наденете на меня? Не хочу замёрзнуть. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'До финиша совсем немного! 🏆', '37-я неделя подходит к концу! Теперь у нас ранний доношенный срок. Это значит, что, даже если я появлюсь на свет сегодня, мои лёгкие уже готовы дышать!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'Вы приснились мне... 💤', 'Ваш голос, запах, тепло... Мне не терпится проснуться и по-настоящему обнять вас, мама!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'Живот напрягся? 🤰', 'Это всего лишь тренировочные схватки или я уже иду? Если сомневаетесь, откройте Счётчик схваток. Он точно подскажет: пора в роддом или можно отдохнуть?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'Я всё ещё здесь! 👋', 'Мне очень тесно, поэтому я двигаюсь меньше. Но если вы беспокоитесь, откройте Счётчик шевелений. Давайте посчитаем вместе! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'Вы положили мои носочки? 🧦', 'Я не хочу замёрзнуть, мама! В последний раз проверьте список для Сумки в роддом. Там есть мой первый комбинезон? 🥰'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'Не можете уснуть? 🥺', 'Сон никак не идёт? Давайте уже сейчас послушаем звуки, которые вы будете включать мне после рождения. Раздел «Белый шум» поможет успокоиться нам обоим. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'Я собрал чемодан и жду у двери! 🚪', '38 недель! Теперь я официально готов появиться на свет. Мои лёгкие, мозг — всё уже полностью сформировано.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'Что делать, если отошли воды? 💦', 'Без паники! Прочитайте в разделе «Блог» статью «3 главных признака родов».'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'Я опускаюсь всё ниже... ⬇️', 'Знаю, я давлю на кости таза. Но это единственный путь к нашей встрече. Моя сильная мама! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'Бессонные ночи? 🥱', 'По мере приближения родов уснуть может становиться всё труднее. Так организм готовит вас к режиму малыша.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'Как бьётся моё сердце? 💓', 'Когда соскучитесь, положите руку на живот. Наши сердца бьются в унисон. Всё хорошо, мы просто ждём дня нашей встречи. 🗓️'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'Тук-тук, это я! ✊', 'Боль в животе то появляется, то проходит? Не теряйте времени — нажмите кнопку «Счётчик схваток». Если интервалы сокращаются, значит, великий день настал! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'Появилось золотое молоко? ✨', 'Из груди может выделяться желтоватая жидкость — это молозиво, первая защита малыша. Почитайте в блоге о грудном вскармливании. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'Тренировочные или настоящие? 🤔', 'Живот напрягается, а затем расслабляется? Если схватки нерегулярные, они тренировочные. Чтобы убедиться, откройте «Счётчик схваток» и проверьте!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'Отошла слизистая пробка? 🩸', 'Если появились густые слизистые выделения, значит, шейка матки начинает раскрываться. Не пугайтесь — это лишь сигнал о том, что пора готовиться.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'Шлёп! Что это был за звук? 💦', 'Если отошли воды, не паникуйте. Просто глубоко вдохните и сообщите врачу. Я уже иду! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'Пора прогнать стресс! 😮‍💨', 'Волнуетесь? Уже сейчас освойте техники дыхания в родах в разделе «Упражнения». Они очень пригодятся вам во время схваток.'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'Я стал меньше толкаться? 🦶', 'Мне здесь тесно, мама! Но вы должны чувствовать мои движения. Если сомневаетесь, съешьте что-нибудь сладкое и откройте «Счётчик шевелений».'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'Все документы на месте? 📄', 'Удостоверение личности, результаты анализов... Проверьте сумку в последний раз. Вы отметили все пункты в списке «Сумка в роддом»? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'Закройте глаза... 😌', 'Не бойтесь родов. Просто представьте тот миг, когда впервые возьмёте меня на руки. Мой запах поможет забыть всю боль.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'Шейка матки 🗝️', 'Идёт незаметная работа! Шейка матки размягчается, истончается и раскрывается. Даже если вы этого не чувствуете, ваше тело открывает мне путь.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'Сегодня тот самый день? 🗓️', 'Ровно 40 недель! Календарь указывает на сегодняшний день. Мне уже появиться или ещё немного покапризничать? Я могу преподнести сюрприз в любой момент! Будьте готовы! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'Я вовсе не опаздываю! 👑', 'Просто звёзды выходят на сцену последними, мама! Ещё немного покапризничаю, а потом появлюсь. Наберитесь терпения! 😌'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'Помощь естественным путём 🍍', 'Считается, что финики и ананас способствуют размягчению шейки матки. Добавьте их сегодня в своё меню в разделе питания. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'Сердцебиение... ❤️', 'После 40 недель важно пройти КТГ (НСТ), чтобы оценить состояние плаценты. Убедитесь, что всё в порядке.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'Поднимемся по лестнице? 🪜', 'Покажите мне дорогу! Подъём по лестнице или приседания могут помочь мне опуститься ниже. Загляните в раздел упражнений.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'Здесь так хорошо 🌡️', 'Тепло, темно и уютно... Вы ведь не рассердитесь, если я скажу, что не хочу выходить? 🥺 Шучу, уже иду!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'Как бьётся моё сердце? 💓', 'Мы у врача на НСТ? Как же вы успокаиваетесь, когда слышите это «тук-тук»...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'Вы едите финики? 🌴', 'Ради естественных родов стоит попробовать этот вкусный способ!'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'Я ведь набираю вес! ⚖️', 'С каждым днём здесь я становлюсь всё пухлее. Мои щёчки становятся милее, но вам будет сложнее. Простите! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'Вы положили перекус в сумку? 🍫', 'После родов вы очень проголодаетесь! Добавьте в больничную сумку любимое печенье или шоколад.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'Плацента стареет? 🍂', 'Врач проверяет количество околоплодных вод? Если мне по-прежнему поступает достаточно кислорода, значит, всё в порядке. Просто наступили наши последние дни вместе.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'Ночью начались схватки? 🌙', 'Эта боль, от которой вы проснулись... Схватки настоящие? Не теряйте времени — запустите Счётчик схваток. Возможно, сегодня ТА САМАЯ НОЧЬ! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'Пришёл приказ об эвакуации? 📢', 'Врач предлагает стимуляцию родов? Не бойтесь. Главное, чтобы я появился на свет здоровым и оказался в ваших объятиях. Каким путём — неважно!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'Ваше последнее фото с животиком... 📸', 'Посмотрите на этот животик в последний раз. Возможно, уже завтра я буду у вас на руках. Гордитесь своим удивительным телом, мама!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d'::uuid, 'Yeni bir yolculuk başlıyor! 🚀', 'Vücudunuz büyük bir mucizeye ev sahipliği yapmaya hazırlanıyor. Siz buna hazır mısınız?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'Vitaminlerinizi unuttunuz mu? 💊', 'Folik asit artık en yakın dostunuz. Gelecekteki bebeğinizin sağlıklı temelleri için Beslenme bölümüne göz atın!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'Bugün kendinizi nasıl hissediyorsunuz? 🌈', 'Yeni dönemin başlangıcında duygularınız değişebilir. Bugünkü hislerinizi Duygu Günlüğü''ne kaydedin ve kendinizi takip edin.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'Şimdilik mikroskobik 🔬', 'Büyük hikâyeler küçük parçacıklarla başlar. Şu anda gelecekteki bebeğiniz yalnızca bir fikir gibi, ancak potansiyeli sonsuz!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'Detoks zamanı! 🚫', 'Sigara, alkollü içecekler veya fazla kafein? Onlarla vedalaşmanın tam zamanı. Sağlıklı anne = Sağlıklı başlangıç.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'Su şişeniz yanınızda mı? 💧', 'Vücudunuzun yeterince su alması artık iki kat daha önemli. Günlük su hedefinizi tamamlamayı unutmayın.'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'Geleceği planlayın 💭', 'Hamilelik Albümü''ne ilk ''başlangıç'' fotoğrafınızı yüklemek istemez misiniz?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'Temelleri atıyoruz 🏗️', 'Vücudunuz yeni bir mucizeye hazırlanıyor, regliniz bitmek üzere. Gelecekteki bebeğinizin sağlıklı temelleri için folik asit (B9) rezervi şart. Beslenme bölümündeki zengin menüye göz attınız mı? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'Uyku gibisi yoktur 😴', 'Enerji toplamanız gerekiyor. Uykusuz geceler gelmeden önce günde en az 8 saat uyumaya çalışın.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'Yeşilin gücünü harekete geçirin! 🥦', 'Ispanak ve brokoli yalnızca sebze değil, doğal birer vitamin deposudur. Bugün menünüze mutlaka yeşil renk katın.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'Doktorunuzu seçtiniz mi? 👩‍⚕️', 'Güvenebileceğiniz uzmanı şimdiden araştırın. Doktorlar ve Klinikler bölümündeki yorumlara göz atarak seçiminizi netleştirebilirsiniz.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'Vücudunuz sinyal mi veriyor? 🌡️', 'Yumurtlama dönemi yaklaşıyor. Vücut sıcaklığınıza dikkat edin; hamile kalma şansınızın en yüksek olduğu günlerdesiniz!'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'Ceviz ve badem zamanı 🥜', 'Atıştırmalık olarak cips yerine kuruyemiş tercih edin. Omega-3 hem sizin hem de gelecekteki bebeğiniz için gereklidir.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'Kendinize zaman ayırın 💆‍♀️', 'Stres hormonlarını uzaklaştırıyoruz! Bugün sevdiğiniz bir filmi izleyin veya ılık bir duş alın.'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'Zencefil çayı yardımınıza koşuyor! 🍵', 'Mide bulantısı peşinizi bırakmıyor mu? Zencefil mideyi yatıştırır. Beslenme bölümünde tarifler var.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'Yorgunluk zirvede mi? 😴', 'Vücudunuz bir enerji fabrikası gibi çalışıyor. Öğle saatlerinde kısa bir uyku annelik hakkınız!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'Tatlı bir bezelye tanesi 🟢', 'Yaklaşık 6 mm. Kolları ve bacakları küçük tomurcuklar gibi belirmeye başlıyor. Minik yüzücü!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'Yarış arabası gibi! 🏎️', 'Kalbi dakikada 100-160 kez atıyor. Sizinkinden iki kat hızlı! Bu ses size müzik gibi gelecek.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'Kan şekeriniz düşmesin! 📉', 'Mide boş kaldığında bulantı artar. Çantanızda her zaman kraker veya kuru meyve bulundurun.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'Tuvalet maratonu mu? 🚻', 'Sık sık tuvalete gitmek normaldir. Böbrekleriniz daha fazla çalışıyor. Ama suyu azaltmayın, artırın!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'Mideniz mi bulanıyor? Özür dilerim! 🥺', 'Hormonlar parti yapıyor, suçlusu benim. Sizi üzüyor muyum? Biraz tuzlu kraker yiyelim mi? 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'Yüzü şekilleniyor 👀', 'Gözleri, burnu ve kulakları oluşuyor. Şimdilik siyah noktalar gibi görünseler de yüz hatları belirginleşiyor.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'B6 Vitamini nerede bulunur? 🍌', 'Muz, avokado veya tavuk eti... Bu vitamin mide bulantısını hafifletebilir.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'Gizli dans partisi! 💃', 'Siz hissetmeseniz de o artık hareket ediyor. İlk hareketleri yalnızca küçük seğirmeler gibi.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'Turşu mu, çikolata mı? 🥒', 'Sıra dışı aşermeler normaldir. Ama şekere dikkat edin! Beslenme bölümünde sağlıklı alternatifler var.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'Pantolonunuz dar mı geliyor? 👖', 'Kilo Takibi''ne başlangıç kilonuzu kaydettiniz mi? 📈'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'Ergenlikteki gibi mi? 😳', 'Yüzünüzde sivilceler çıkabilir. Hormonların işi! Cildinizi temiz tutun, doktorunuza danışmadan ilaç kullanmayın.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'İlk fotoğrafımızı çektiniz mi? 🤰', 'Galeriye ilk Baby Bump fotoğrafınızı yükleyin! ✨'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'En küçük başlangıç 🫧', 'Şimdilik gözle görülmüyor. Gelecekteki bebeğiniz henüz tek bir hücre, ama büyük planları var!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'Sihirli an geldi mi? ✨', 'Döllenme genellikle bu günlerde gerçekleşir. Siz hissetmeseniz de mucizevi süreç başladı.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'Protein bombası 🍳', 'Kahvaltıda yumurta var mı? Hücrelerin yenilenmesi için protein önemlidir. Afiyet olsun!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'Yürüyüşe çıkalım mı? 👟', 'Temiz hava moralinizi yükseltecek. Egzersizler bölümündeki hafif yürüyüş programına göz atın.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'Haşhaş tohumu kadar 🌱', 'Bebek artık rahminize yerleşiyor. Boyutu küçük olsa da kalbi oluşmaya başlıyor.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'DNA paketi hazır! 🧬', 'Bebeğin göz rengi, saçı ve cinsiyeti şimdiden kodlandı. Sizce kime benzeyecek?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'Meyve şöleni 🍓', 'Ahududu mu, çilek mi? Antioksidanlarla dolu bu meyveler bağışıklığınızı güçlendirecek.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'Sessiz bir devrim yaşanıyor 🤫', 'Döllenmiş yumurta rahminize yerleşiyor. Siz hissetmeseniz de muhteşem bir süreç yaşanıyor.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'Kemikler için kalsiyum 🥛', 'Süt, yoğurt veya peynir? Bebeğin gelecekteki iskeleti için bugün mutlaka bir süt ürünü tüketin.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'Halsiz misiniz? Bir nedeni var 🥱', 'Progesteron hormonu yükseliyor. Yatağınız sizi çağırıyorsa ona hayır demeyin, dinlenin!'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'Vitamini unuttunuz mu? 😬', 'Folik asit, gelecekteki omurgamın temelidir! İlaç Hatırlatıcısına göz atın, bugünkü dozunuzu aldınız mı? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'Lekelenme normal mi? 🩸', 'Korkmayın, bu yerleşme kanaması olabilir. Şüpheniz varsa Doktorlar bölümüne göz atın.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'Demir leydi misiniz? 🥩', 'Kan hacminiz artacak. Kırmızı et veya mercimek tüketerek anemiye dur deyin.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'Heyecanlı bekleyiş... 🧘‍♀️', 'Regl zamanınız yaklaşıyor. Stresi azaltmak için Beyaz Sesler bölümünü dinleyin.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'Takvime baktınız mı? 🗓️', 'Regliniz geciktiyse belki de test yapma zamanı gelmiştir. Mutlu haberi bizimle paylaşın!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'Bir susam tanesi kadar! 🌱', 'Artık resmen embriyo olarak adlandırılıyor. O hızla büyürken siz de değişiyorsunuz.'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'Mide bulantınız mı var? 🤢', 'Sabahlar zor mu geçiyor? Zencefil çayı veya limonlu su yardımınıza koşabilir. Midenizi boş bırakmayın.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'Önemli bir inşa süreci devam ediyor! 🚧', 'Beyin ve omurga oluşuyor. Folik asit almaya devam edin!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'Sabah bulantıları mı? 🤢', 'Yataktan kalkmadan önce tuzlu kraker yiyin. Kan şekerinizi dengede tutmak için az az ve sık sık beslenin.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'Güm güm... Duyuyor musunuz? 💓', 'Kalbim atmaya başladı! Bu minik motorun sesini duymak için sabırsızlanıyor musunuz? İlk ultrason randevunuzu takvime kaydedin! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'Resmî onay zamanı! ✅', 'Henüz gitmediyseniz doktor randevusu alın. Doktorlar bölümünden size uygun olanı bulun.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'İlk kalp atışları 💓', 'Siz henüz duyamıyor olsanız da o minik kalp çalışmaya başladı. Dakikada 100''den fazla atıyor!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'Limonlu su mucizesi 🍋', 'Mide bulantısını azaltır, vücudu arındırır. Susuz kalmak baş ağrısına yol açabilir.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'Piliniz mi bitiyor? 🔋', 'Enerjiniz çabucak tükenebilir. Öğle saatlerinde kısa bir uyku size çok iyi gelecektir.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'Bir havuza ihtiyacım var! 🏊‍♀️', 'İçinde yüzeceğim suyu (amniyotik sıvıyı) siz oluşturuyorsunuz, Anne. Su Takibi''ne girin. Bir bardak su içtiniz mi? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'Duygusal hız treni 🎢', 'Gülmek, ardından ağlamak... Hormonlar sizi delirtmedi, sadece işlerini yapıyorlar.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'Kokulara karşı hassas mısınız? 👃', 'Sevmediğiniz yiyecekleri kendinizi zorlayarak yemeyin. Alternatifler için Beslenme bölümüne göz atın.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'Beyin gelişiyor! 🧠', 'Nöral tüp kapanıyor. Folik asit almayı bırakmayın; geleceğin dâhisinin temelleri atılıyor!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'Besin akışı hızlandı!', 'Bugün faydalı ne yediniz? Beslenme listesini kontrol edin! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'Parmağını emiyor! 👍', 'Ultrason muayenesinde onu başparmağını emerken görebilirsiniz. Bu, doğumdan sonraki emme refleksinin provasıdır.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'Yüzmeyi sever misiniz? 🏊‍♀️', 'O, suyun içinde yaşıyor. Amniyotik sıvının temiz ve bol olması için siz de gün boyunca bol su içmelisiniz.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'Sesinizi yükseltin! 🗣️', 'Bebek artık sesinizi ve kalp atışlarınızı net bir şekilde duyuyor. Ona ninni söylemeye başlayın, bu onu sakinleştirir. 🎶'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'Demir Leydi sizsiniz! 🦸‍♀️', 'Baş dönmesini önlemek için kırmızı et veya mercimek yiyin. Beslenme bölümünde tarifler var.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'Bir elma büyüklüğünde 🍎', 'Pantolonunuzun düğmesini açabilirsiniz, rahatlayın! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'Diş etleriniz kanıyor mu? 😬', 'Hormonlar diş etlerini hassaslaştırır. Yumuşak bir diş fırçası kullanın ve tuzlu suyla gargara yapın.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'Sizi duyuyorum, Anne! 👂', 'Kulak kemikleri sertleşiyor. Artık ses tonunuzu, gülüşünüzü ve kalp atışlarınızı tanıyor.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'Bebeğin iskeleti güçleniyor🦴', 'Kalsiyum depolarınızı tüketmemesi için süt, yoğurt veya badem tüketin.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'Sol tarafınıza yatın 🛌', 'Sırtüstü yatmak kan dolaşımını zorlaştırabilir. Sol tarafınıza yatmak hem size hem de bebeğe daha fazla oksijen sağlar.'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'SPA günü mü? ✨', 'Bebeğin cildi suda buruşmasın diye özel bir kremle kaplanıyor. Peki ya siz? Bugün kendinize zaman ayırın! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'Işığı gördüm! 💡', 'Göz kapakları kapalı olsa da güçlü ışığı hissediyor. Karnınıza bir fener tutarsanız yüzünü çevirebilir.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'Kabızlıktan kaçının 🏃‍♀️', 'İlaç yerine bol su için, kuru erik ve kivi yiyin.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'Anahtar nerede? 🔑', 'Unutkanlık normaldir. Beyniniz şu anda daha önemli bir işle meşgul: Bir insan yaratıyor! Liste tutmaya başlayın.'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'Kabızlık sorunu mu? 🚽', 'Bol su ve lifli gıdalar dostunuzdur. Kivi ve kuru kayısı mucizeler yaratabilir.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'Sizi sıkıştırıyor muyum? Affedin!', 'Kilonuz artmasa da evimi genişletiyorum. Haydi, o dar pantolonu çıkarıp rahat bir şeyler giyelim. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'Turşu mu, Çikolata mı? 🍫', 'Beslenme bölümüne göz atın, bakalım bugün menüde hangi sağlıklı yiyecekler var? 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'Tat alma duyusu gelişiyor 👅', 'Dilinde tat tomurcukları oluşuyor. Sizin yediğiniz yiyeceklerin tadını o da hissedecek.'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'Kafeini azalttınız mı? ☕', 'Günde 1 fincandan fazla tüketmeyin. Kafeinsiz çaya veya bitki çaylarına bir şans verin.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'Dans ediyorum! 🕺', 'Kollarını ve bacaklarını bükebiliyor. Rahminizde akrobatik hareketler yapıyor ama siz henüz bunları hissetmiyorsunuz.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'Sebze çorbası? 🥣', 'Mideniz ağır yemekleri kabul etmiyorsa hafif bir çorba için. Hem vitamin hem de sıvı!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'Hareket zamanı 🧘‍♀️', 'Hareket etmek ister misiniz? Egzersizler bölümünde size uygun neler var, birlikte bakalım mı?'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'Babayı da dahil edin 🗣️', 'Bu yalnızca sizin maceranız değil. İlk ultrason görüntüsüne birlikte bakın, gelecek planlarınızdan konuşun.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'Dişlerim kaşınmıyor... henüz! 😬', 'Süt, yoğurt, peynir... Bugünkü beslenme listenizde bunlar var mı? 🥛'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'Et kokusundan kaçıyor musunuz? 🥩', 'Proteine ihtiyacınız var! Et yiyemiyorsanız yerine mercimek, nohut veya kuruyemiş tüketin.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'Sütyeniniz dar mı geliyor? 👙', 'Göğüsleriniz büyüyor ve hassaslaşıyor. Rahat, spor tipi ve balensiz bir sütyene geçmenin zamanı geldi.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'Vücudunuz su istiyor! 💧', 'Susuzluk baş ağrısına neden olabilir. Su Takibine girin ve bir bardak su için! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'Artık insan görünümünde! 👶', 'Peki ya yüzünüzdeki o meşhur Hamilelik Işıltısı? ✨ Bu güzelliği Galeride ölümsüzleştirin!'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'Sırrı açıklamanın zamanı geldi mi? 📢', '1. trimester bitmek üzere. Risk azaldı. Müjdeli haberi arkadaşlarınızla paylaşmaya hazır mısınız?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'İskelet güçleniyor! 🦴', 'Yumuşak kıkırdaklar kemiğe dönüşüyor. Kalsiyum ihtiyacınızı karşılayın ki bebeğiniz güçlü olsun!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'Bir okyanus yaratıyorsunuz! 🌊', 'Amniyotik sıvı yenileniyor. Bebeğinizin temiz bir havuzda yüzmesi için bol su içmeyi unutmayın.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'Karnınız kaşınıyor mu? 🌵', 'Cildiniz gerildikçe kaşınması normaldir. Badem yağı veya özel bir krem sürerek rahatlayın.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'Enerjiniz geri mi geliyor? 🔋', 'Bugün kendinizi nasıl hissediyorsunuz? Belirti Günlüğü''ne not edin! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'Size anne diyeceğim... 🥺', 'Ses tellerim oluşuyor. Şimdi sessizim ama size ilk kez sesleneceğim o günü hayal ediyor musunuz? Ben ediyorum...'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'Ceviz ve fındığın gücü 🐿️', 'Beyin gelişimi için Omega-3 önemlidir. Çantanızda kuruyemiş bulundurun: Hem tok tutar hem de bebeğinizin beyin gelişimini destekler.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'Altın dönem başladı! ✨', 'Tebrikler! 2. trimestere adım attınız. Enerjiniz artıyor, risk azalıyor. Şimdi hamileliğin tadını çıkarma zamanı.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'Enerji bombası lazım 💥', 'Bebek hızla büyüyor. Kırmızı et, yumurta veya baklagiller... Demir ve protein ihtiyacınızı karşılamayı unutmayın.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'Bir limon büyüklüğünde! 🍋', 'Yaklaşık 7-8 cm. Artık başını çevirebiliyor ve kaşlarını çatabiliyor. Mimikleri gelişiyor!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'Gardırobunuza göz atın 👗', 'Düğmeler kapanmıyor mu? Dar pantolonları kaldırın. Bol, rahat ve doğal kumaşlardan üretilmiş giysilere geçin.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'Kız mı, erkek mi? 🩷💙', 'Cinsel organları tamamen oluşuyor. Ultrasonda görmek zor olsa da o artık kim olduğunu biliyor! Sizce hangisi?'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'Lifli besinler birer kahraman 🌾', 'Sindirimi iyileştirmek için yulaf, sebze ve meyveleri tercih edin. Beslenme bölümünde lezzetli salatalar var.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'Ağırlık mı kaldırıyorsunuz? 🏋️‍♀️', 'Bebek artık yağ tabakası oluşturuyor ve iskeleti güçleniyor. Hızla ağırlaşıyoruz!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'C Vitamini patlaması 🍊', 'Portakal, kivi veya biber... Bağışıklığınızı çelik gibi güçlü tutun, hastalanmak yok!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'Böbrekler çalışmaya başladı! 🚽', 'İnanılmaz ama bebeğiniz artık idrar yapıyor. Amniyotik sıvıyı yutuyor ve idrarla dışarı atıyor. Döngü başladı!'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'Kalsiyum eksik olmasın 🥛', 'Diş tomurcukları oluşuyor. Lor peyniri, peynir veya yoğurt... Gelecekteki gülümsemesi için bunlara ihtiyacı var!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'Başınız mı ağrıyor? 🤕', 'İlaç almaya hemen yönelmeyin. Karanlık bir oda, soğuk kompres veya masaj daha iyi gelebilir.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'Kan dolaşımınız hızlanıyor! 🌊', 'Damarlarınızdaki kan miktarı artıyor, kalbiniz daha hızlı çalışıyor. Bu sistemi serin tutmak için su çok önemli. Başınız dönmesin diye su içmeyi unutmayın! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'İnşaat çalışmaları sürüyor! 🏗️', 'Bebeğin kalsiyuma ihtiyacı var! Beslenme bölümündeki süt ürünlerine göz atın. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'Balık günü! 🐟', 'Cıva oranı düşük balıkları tercih edin. Omega-3, beyin gelişimi için vazgeçilmezdir.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'Çatlaklara Hayır deyin! 🧴', 'Karnınız henüz belirginleşmese bile cildinizi nemlendirin. Badem veya Hindistan cevizi yağı kaşıntıyı da hafifletir.'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'Bir greyfurt büyüklüğünde! 🍊', 'Beliniz kalınlaşabilir. Rakamlar değişti mi? Kilo Takibine kaydedin! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'İkili tarama testi zamanı mı? 🗓️', '11-14 haftalar arası önemlidir. Down sendromu riskini değerlendirmek için doktorunuzla konuşun.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'Aç mısınız, yoksa susadınız mı? 🤔', 'Beyin bazen bu ikisini karıştırabilir. Önce bir bardak su için; hâlâ açsanız yemek zamanı gelmiş demektir.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'Jimnastik zamanı! 🤸', 'Bebeğiniz artık ellerini yumruk yapıyor ve ağzını açıyor. Siz hissetmeseniz de içeride olimpiyatlar yaşanıyor!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'Akıllı bir bebek geliyor! 🧠', 'İyot, beyin gelişimi için gereklidir. Menünüzde iyotlu tuz, balık veya süt ürünleri var mı?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'Esniyorum! 🤸', 'Siz de hareketsiz kalmayın, Anne. Egzersizler bölümündeki hafif yoga hareketlerine göz atalım mı?'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'Bacaklarınıza kramp mı giriyor? 🦵', 'Magnezyum ve kalsiyum eksikliğinden kaynaklanabilir. Muz, badem veya yoğurt yiyin. Bol su içmeyi de unutmayın!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'Bir armut büyüklüğünde! 🍐', 'Boyu uzuyor, vücudu dikleşiyor. Artık başını tamamen dik tutabiliyor. O büyüyor, siz güzelleşiyorsunuz!'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'Karnınız geriliyor mu? 😣', 'Ani hareketler yapmayın. Ilık bir duş veya hafif masaj ağrıyı azaltabilir.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'Parmak izleri hazır! 🖐️', 'Dünyada başka hiç kimsede olmayan o eşsiz desenler artık oluştu. O, şimdiden benzersiz bir birey. Muhteşem değil mi?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'Çabuk mu acıkıyorsunuz? 😋', 'İştahınızın artması harika, ancak iki kişilik yemek bir mittir. Besleyici kalorileri tercih edin: ceviz, meyve, sebze.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'Burnunuz tıkalı mı? 🤧', 'Hasta değilsiniz; bu, gebelik rinitidir. Tuzlu su spreyi kullanın ve odanın havasını nemlendirin.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'Hızlı teslimat! 🚚', 'Acıktığımda sizi dürtmeye başlayabilirim. Beslenme bölümünde bugün için faydalı neler var? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'Yağ tabakası oluşuyor 🧸', 'Bebek sıcak kalabilmek için yağ depolamaya başlıyor.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'Kabızlık peşinizi bırakmıyor mu? 🚽', 'Lifli gıdalar ve bol su en iyi çözümdür. Hareketsiz kalmayın; günlük yürüyüş bağırsakları çalıştırır.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'Kemikler sertleşiyor! 🦴', 'Lastik gibi yumuşak kıkırdaklar kemiğe dönüşüyor. Kalsiyum depolarınızı doldurun ki bebeğin iskeleti çelik gibi sağlam olsun!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'Baş dönmesine son! 🛑', 'Kan hacminiz arttıkça demir ihtiyacınız da artar. Ispanak, karabuğday veya kırmızı et... Menünüze mutlaka ekleyin!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'Karnınızda disko mu var? 💃', 'İçeride takla atmayı öğreniyorum! Hissettiniz mi?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'Tuhaf rüyalar mı görüyorsunuz? 😴', 'Hormonlar gecelerinizi sinemaya çevirebilir. Korkmayın, bu normaldir. Rüyalarınızı Ruh Hali Günlüğü''ne kaydedin!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'Doğal kremini sürüyor! 🧴', 'Cildinin buruşmaması için verniks adı verilen, beyaz ve peynirimsi bir maddeyle kaplanıyor. Doğanın kendi koruyucu kremi!'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'Müzik açalım mı? 🎶', 'Anne, dışarıdaki sesleri duyuyorum! Senin sevdiğin şarkıları ben de seviyorum. Birlikte dans edelim mi?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'Göbek deliğiniz dışarı mı çıktı? 🔘', 'Karnınız büyüdükçe göbek deliğiniz dışarı doğru çıkabilir. Endişelenmeyin, doğumdan sonra düzelecek!'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'Doğum sancısı mı, prova mı? 🤔', 'Karnınız sertleşiyor mu? Bu, yalancı sancı olabilir. Rahminiz doğuma hazırlanıyor. Ağrısızsa normaldir.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'Tuzlu yiyeceklerden kaçının 🧂', 'Ayaklarınız şişiyorsa tuzu azaltın. Bol su ve maydanoz yardımcı olabilir. Yüzüğünüz parmağınızı sıkmıyor, değil mi?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'Küçük fabrika çalışmaya başladı! 🏭', 'Artık kan hücrelerimi karaciğerim değil, kemik iliğim üretiyor. Bana destek olmak için Beslenmede demir açısından zengin neler var?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'Şşş, uyuyorum... 🤫', 'Anne, neden hareket etmiyorum? Çünkü günün büyük bir bölümünü uyuyarak geçiriyorum. Ben uyurken sen de dinlen.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'Gizli egzersiz zamanı! 🧘‍♀️', 'Kegel egzersizlerini unutmayın. Oturduğunuz yerde pelvik taban kaslarınızı sıkıp gevşetin. Doğumda işinize yarayacak!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'İlk nefes egzersizleri! 🫁', 'Akciğerlerimde sürfaktan oluşuyor. Bu madde, doğduğumda ilk nefesimi almama yardımcı olacak. Egzersiz yapıyorum!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'O ses neydi, Anne? 🔊', 'Ani seslerden irkiliyorum. Sen sakin olduğunda ben de sakinim. Bana ninni söyler misin?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'Beşiğim sensin... 💤', 'Sen yürürken sallanıp uyuyorum. Durduğunda ise uyanıyorum! Beni uyutmak için hafif yürüyüşlere devam edelim mi? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'Şekerli su içtiniz mi? 🥤', 'Gestasyonel diyabet testi önemlidir. Hem benim hem de sizin sağlığınız için mutlaka yaptırın.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'Karnınızda bir çizgi mi var? ➖', 'Linea Nigra hormonlardan kaynaklanır. Endişelenmeyin, doğumdan sonra kaybolacak. Siz her hâlinizle güzelsiniz!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'Yaşama şansım arttı! 🌟', '24 haftalık oldum! Tıbben artık rahim dışında yaşayabilme sınırına ulaştığım kabul ediliyor. Bu çok büyük bir dönüm noktası, Anne.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'Mideniz mi yanıyor? 🔥', 'Saçlarım çıktığı için değil, rahim mideye baskı yaptığı için yanıyor. Yemekten hemen sonra uzanmayın, dik oturun.'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'Demirin dostu kim? 🍊', 'Demir alıyorsanız yanında mutlaka C vitamini olsun. Böylece demir daha iyi emilir.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'Beliniz mi ağrıyor? 👠', 'Yüksek topuklu ayakkabıları dolaba kaldırın, şimdi rahatlık zamanı! Ortopedik ayakkabıları tercih edin.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'Yanlarınızda gerilme mi var? ⚡', 'Aniden sancı hissedebilirsiniz, korkmayın; sadece evimi genişletiyorum! Egzersizler bölümündeki rahatlatıcı hareketlere göz atın. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'Pasaportu hazır! 🛂', 'Parmak izleri tamamen oluştu. Dünyada başka hiç kimsede olmayan o desenlere artık sahip. Benzersiz biri geliyor!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'Suyun tadı yok mu? 💧', 'İçmekte zorlanıyorsanız salatalık, karpuz veya nane eklenmiş suyu deneyin. Susuz kalmak baş ağrısına neden olur.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'Anne, sizi duyuyorum! 👂', 'Sesiniz bana ninni gibi geliyor. Kalp atışlarınız ise en güzel ritim. Benimle daha çok konuşun, sizi tanımak istiyorum.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'Çinko: Gizli kahraman 🛡️', 'Hücrelerim hızla bölünüyor. Yapı malzemesine ihtiyacım var! Menüde kırmızı et, peynir veya kuruyemiş var mı?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'Mango kadar oldum! 🥭', 'Yaklaşık 15 cm. Cildim hâlâ ince ama yağ tabakam oluşuyor. Şimdi daha dolgun görünüyorum, Anne!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'Hissettiniz mi? Tekme! ⚽', 'Anne, ben uyanığım! O hafif kıpırtı, size merhaba deyişim. Elinizi karnınıza koyun, belki yine yaparım?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'Erkek mi, Kız mı? 💙💗', 'Cinsiyetimi öğrenmek için ultrason zamanı yaklaşıyor. Heyecanlı mısınız?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'İlk oyuncağım var!', 'Göbek kordonunu tutup oynuyorum, bazen de sıkıyorum. Parmaklarım artık kavramayı öğreniyor.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'Büyük buluşma zamanı! 🗓️', '18-22 haftalar, en ayrıntılı ultrason incelemesinin zamanıdır. Parmaklarımı, kalbimi, her şeyimi kontrol edecekler. Doktor randevunuzu aldınız mı?'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'Bir muz boyundayım! 🍌', 'Yaklaşık 18-20 cm. Artık başımdan ayaklarıma kadar ölçülüyorum. Boyum uzuyor, vücudum şekilleniyor.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'Şşşt, uyuyorum 😴', 'Benim de bir uyku düzenim var, Anne. Siz yürürken sallanıp uyuyorum, uzandığınızda ise uyanıp disko yapıyorum! Kusura bakmayın 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'Yolun yarısı bitti! 🏁', 'Tebrik ederiz! 20 hafta geride kaldı. Hamileliğinizin tam ortasındasınız. Siz harikasınız, bunu kutlamalısınız!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'Yükleniyor... 50% ⏳', 'Tebrik ederim! Yolun yarısını geride bıraktık. Bu özel günü kutlamak için Galeri''ye güzel bir fotoğraf eklemeye ne dersiniz? ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'Babam beni hisseder mi?', 'Elini karnınıza koyarsa belki ona da selam veririm.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'Renkli rüyalar görüyor musunuz?', 'Hamilelik rüyaları film gibi oluyor, değil mi? Ben de o rüyalarda mıyım? 😴'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'Demire ihtiyacım var 🏗️', 'Kırmızı kan hücreleri üretmekle meşgulüm. Bana yardım edin: dana eti, ıspanak veya mercimek yiyin.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'Ayaklarınız şişiyor mu? 👠', 'Ödem başlayabilir. İşte veya evde, fırsat buldukça ayaklarınızı yukarı kaldırın. Rahat ayakkabılar seçin!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'Hık... Hık... 🤭', 'Karnınız ritmik şekilde hareket mi ediyor? Korkmayın Anne, bu sadece hıçkırık! Diyaframımı çalıştırıyorum.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'Tatları ayırt ediyor! 👅', 'Amniyotik sıvının tadı yediklerinize göre değişiyor. Acı biber mi yediniz? Bunu hissedecek!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'Gözlerim dans ediyor...', 'Göz kapaklarım kapalı olsa da artık rüya görüyorum. Sizce rüyamda ne var?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'Mideniz yanıyor mu? 🔥', 'Rahim mideye baskı yapıyor. Az az ama sık sık yiyin. Yemekten hemen sonra uzanmayın, dik oturun.'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'Kendinize bakım günü 💅', 'Hamilelik lekeleri oluştuysa güneşten korunun. Bugün kendinize bir yüz maskesi yapmaya ne dersiniz?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'Yüzünü keşfediyor! 👶', 'Elleriyle yüzüne, burnuna, hatta göbek kordonuna dokunuyor. Dokunma duyusu gelişiyor. Kendini tanıyor!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'Turşu ve dondurma? 🥒🍦', 'Canınız tuhaf yiyecek kombinasyonları mı istiyor? Bunlar vücudunuzun sinyalleri. Ama şeker ve tuz tüketimini dengede tutmaya çalışın.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'Bir Hindistan cevizi kadar! 🥥', 'Yaklaşık 28 cm. Ağırlığı yarım kiloyu geçti! Artık daha güçlü tekmeler atıyor.'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'Kramp mı giriyor? 🦶', 'Geceleri baldırınıza kramp mı giriyor? Magnezyum eksikliğiniz olabilir. Muz, badem veya yoğurt... Kaslarınızın rahatlamaya ihtiyacı var.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'Gözlerimi açtım! 👀', 'Karanlık olsa da artık göz kapaklarımı açabiliyorum. Gözlerimi kırpıyorum. Dünyayı göreceğim güne çok az kaldı!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'Işık geliyor, Anne! ☀️', 'Gözlerimi kırpıyorum! Karnınıza güneş ışığı vurursa o parlaklığı görebiliyorum. Dünya ne renk?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'Krem sürme zamanı 🧴', 'Karnınız hızla büyüyor, cildiniz geriliyor. Kaşıntıyı önlemek için her gün nemlendirici sürün.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'İlk aşısı sizden 🛡️', 'Antikorlarınız ona geçiyor. Bunlar, doğumdan sonraki ilk aylarda onu koruyacak.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'Salatalık turşusu? Hayır! 🚫', 'Ayaklarınız şişiyorsa tuzu en aza indirin. Turşu lezzetlidir ama ödemi artırır. Limonlu suyu tercih edin.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'Dünya çok gürültülü... 🔊', 'Kulaklarım o kadar hassaslaştı ki dışarıdaki korna seslerini bile duyabiliyorum. Biraz sakinleşelim mi? Bana Beyaz Seslerden yağmur sesini açın, birlikte kestirelim. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'Ritme ayak uyduruyorum 🥁', 'Kalbim düzenli atıyor, nefes alma egzersizleri yapıyorum. Bazen de hıçkırıyorum.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'Son düzlüğe giriyoruz! 🏁', '2. trimesterin son günleri. 3. dönem başlamadan önce bol bol uyuyun!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', '3. Trimestere Hoş Geldiniz! 🏁', 'Son dönem başladı! Artık vücudunuz daha da ağırlaşacak ama bitiş çizgisi görünüyor. Sabırlı olun, Anne!'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'Mideniz yanıyor mu? 🔥', 'Rahim, mideyi yukarı doğru itiyor. Süt içmek veya bir avuç çiğ badem yemek mide yanmasını hafifletebilir.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'Bir brokoli kadarım 🥦', 'Yağ tabakam giderek kalınlaşıyor, kollarım ve bacaklarım tombullaşıyor.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'Yuvamızı hazırlayalım mı? 🐣', 'Benim yatağım, minik kıyafetlerim... Listeyi babamla birlikte Ortak Alışveriş''te hazırlayın! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'Kan grubunuz negatif mi? 🩸', 'Rh negatif anneler için kritik bir hafta. İmmünoglobulin iğnesi gerekebilir. Doktorunuzla görüşün!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'Kirpiklerim uzadı! 👁️', 'Gözlerimi açıp kapatıyorum. Aydınlığı ve karanlığı ayırt edebiliyorum. Karnınıza fener tutarsanız yüzümü çevireceğim. Denemek ister misiniz?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'Balık, balık, balık! 🐟', 'Beynimin en hızlı geliştiği dönemdeyim. Omega-3''e ihtiyacım var. Haftada 2 kez balık yiyor musunuz?'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'Karakterim nasıl olacak? ✨', 'İnatçı mı, yoksa duygusal mı? Doğacağım tarihe göre burcum ne söylüyor? Sizin burcunuzla uyumlu muyum? Haydi Yıldız Falı''na bakalım! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'Kaburgalarınız ağrıyor mu? 🥊', 'Affet Anne, yerim dar. Bacaklarımı uzattığımda kaburgalarınıza değiyorum. Dik oturmak rahatlamanıza yardımcı olabilir.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'Tekmelerimi sayıyor musunuz? 🦶', 'Artık hareket düzenim oluşuyor. Tekme Sayacı''na girin ve hareketlerimi takip edin. Her şey yolunda mı?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'Beynim kıvrımlanıyor! 🧠', 'Önceden pürüzsüzdü, şimdi ise kıvrımlar ve oluklar oluşuyor. Bu, milyarlarca nöronun devreye girdiği anlamına geliyor. Bir dâhi geliyor!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'Reflü sizi yoruyor mu? 🔥', 'Mide asidi boğazınıza mı geliyor? Yemekten sonra sakız çiğnemek veya ılık süt içmek yardımcı olabilir.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'Kabak büyüklüğündeyim! 🎃', 'Yaklaşık 39-40 sm. Ağırlığım 1.2 kq oldu! Size ağır mı geliyorum? Affet Anne, ama kilo almam gerekiyor.'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'Ben buradayım, Anne! 👋', 'Bazen sakinleşiyor, bazen de dans ediyorum. Tekmelerimi sayıyor musunuz? Her şey yolunda, sadece yerim daralıyor.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'Bacaklarınızda örümcek ağı mı var? 🕸️', 'Varisli damarlar oluşabilir. Uzun süre ayakta kalmayın. Akşamları uzanıp bacaklarınızı duvara dayayın.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'Kan fabrikası çalışmaya başladı 🩸', 'Şimdiye kadar karaciğerim, artık ise kemik iliğim kan hücreleri üretiyor. Bu, bağımsız yaşama hazırlık!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'Demir+C vitamini ikilisi 🥩🍊', 'Anemi riskine karşı: Et yerken yanında portakal suyu için. C vitamini, demir emilimini 2 kat artırır.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'Büyük bir lahana 🥬', 'Cildim pürüzsüzleşiyor, yanaklarım dolgunlaşıyor. Sizi görmek için sabırsızlanıyorum!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'Nefes alamıyor musunuz? 😮‍💨', 'Yukarı çıktıkça diyaframınıza baskı yapıyorum. Derin nefes almaya çalışın, Anne. Çok az kaldı, aşağı ineceğim.'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'Anne, sıkıldım! 🤸', 'Siz hareketsiz durduğunuzda ben uyanıyorum. Karnınızı okşayın, belki size minik bir tekmeyle karşılık veririm?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'Kavun kadar oldum! 🍈', 'Yaklaşık 600 gramım. Artık yerim biraz daralıyor. Tekmelerim daha güçlü olabilir, kusura bakmayın! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'Ayakkabılarınız sıkıyor mu? 👟', 'Ayak numaranız büyüyebilir. Artık şıklıktan çok rahatlık önemli. Geniş spor ayakkabılara geçin!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'Saçlarım renkleniyor! 🎨', 'Genetik piyango başladı. Sarışın, siyah saçlı mı, yoksa kızıl mı? Saç pigmentim oluşuyor. Sizce kime benzeyeceğim?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'Şişkinlikten bıktınız mı? 🎈', 'İşin ilginç yanı şu: Su içmek ödemi azaltır. Salatalık ve karpuz gibi su oranı yüksek besinler de yardımınıza koşabilir. Tuzdan uzak durun.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'Yanaklarım pembeleşiyor...', 'Cildim artık cam gibi şeffaf değil! Kılcal damarlarım kanla doluyor ve rengim pembeleşiyor. Kan dolaşımınız için Su Takibi''ni kullanarak suyunuzu içmeyi unutmayın! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'Hop! O ses de neydi? 😳', 'Kapı çarpınca irkildim. Çok iyi duyuyorum, Anne. Sakin bir müzik açın, birlikte dinlenelim.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'Burnum açıldı! 👃', 'Burun deliklerim tıkalıydı, şimdi açıldı. Nefes alabilmek için alıştırma yapıyorum.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'Sindiriminiz yavaşladı mı? 🐌', 'Progesteron bağırsakları yavaşlatır. Kuru kayısı, kuru erik ve kepekli ekmek kurtarıcınız olabilir.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'Yastıklardan bir kale kurun! 🏰', 'Rahat uyuyamıyor musunuz? Bacaklarınızın arasına ve karnınızın altına yastık koyun. Destek şart!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'Yoga ustasıyım! 🦶', 'İnanmayacaksınız ama ayak parmağımı tutup ağzıma sokabiliyorum! Çok esneğim. Peki siz eğilirken zorlanıyor musunuz?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'Gözlerimi açtım! 👀', 'Anne, inanmayacaksınız ama göz kapaklarımı açtım. Burası karanlık olsa da bakışlarım artık şekilleniyor. Sizi görmeme çok az kaldı!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'Babamı duyabiliyor muyum? 🗣️', 'Erkek sesi daha derinden geliyor ve ben onu daha iyi duyuyorum. Babamla konuşun, bana masal okusun.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'Siz benim kalkanımsınız!', 'Bağışıklık sistemim gelişiyor ve sizden bana antikorlar geçiyor. Beni hastalıklardan koruyorsunuz, Anne. ❤️'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'Çantayı düşündünüz mü? 👜', 'Henüz erken değil! Hastane Çantası listesine göz atın. Eksikleri şimdiden tamamlamak stresinizi azaltır.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'Bir sır vereyim mi? 🤫', 'Siz uyurken sesinizi hayal ederek uykuya dalıyorum. Sizce rüyamda kimi görüyorum? Tabii ki sizi! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'O çikolata mıydı? 🍫', 'Mmm, tadı buralara kadar geldi! Şimdi enerjim taşıyor. Haydi dans edelim, Anne! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'Bir balkabağı kadarımdır! 🎃', 'Yanaklarım öyle tombullaşıyor ki beni ısırmak isteyeceksiniz! Yerim dar ama size yakın olmak çok güzel.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'Baş aşağı duruyorum! 🙃', 'Hayatı tersten görmek çok ilginç! Doğuma hazırlanıyorum, Anne. Bu pozisyonda size daha yakınım.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'Karnınız sertleşiyor mu? 🤰', 'Korkmayın, Meleğim! Bu sadece bir prova. O büyük güne bir ekip olarak hazırlanıyoruz!'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'Babanın sesi geldi! 🧔', 'Onun sesini duyduğumda kalbim daha hızlı atıyor. Ona benim de burada olduğumu ve selam söylediğimi iletin! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'Kemiklerime güç verin! 💪', 'Kalsiyuma ihtiyacım var, Anne. Bir bardak süt içer veya yoğurt yerseniz ikimiz de süper güçlü oluruz! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'Tak tak! Kim var orada? ✊', 'Tekmelerim bazen canınızı acıtıyor mu? Özür dilerim 🥺 Sadece size dokunmak istiyorum.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'Nefesiniz daralıyor mu? 😮‍💨', 'Biraz yukarı çıktım ve akciğerlerinize baskı yapıyorum. Özür dilerim Anne, yakında aşağı ineceğim ve siz de rahatça nefes alacaksınız! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'Kokunuzu hissedeceğim...', 'Beni kucağınıza alacağınız o anı düşünüyor musunuz? Ben her gün o anın hayaliyle büyüyorum, Anne! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'Evim daralıyor... 🏠', 'Hareketlerim yumruk ve dirsek darbelerine dönüşüyor. Her şey yolunda mı? Haydi birlikte Tekme Sayacını kontrol edelim!'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'Biraz hava almaya ihtiyacınız var 🌿', 'Bugün evden çıkıp sakin ve temiz havası olan bir yerde çay içelim mi? Anne Dostu Mekanlara göz atın!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'O büyük gün... ✨', 'Acele etmeyelim ama çantamızı yavaş yavaş hazırlayalım. Hastane Çantası listesinde neler var, bakalım mı?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'Şşş... Ben uyuyorum 😴', 'Beynim o kadar hızlı gelişiyor ki çoğu zaman uyuyorum. Siz de dinlenin, Anne.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'Bana ne isim vereceksiniz? 👶', 'Henüz karar vermediyseniz babamla birlikte Bebek İsimleri listesine bir göz atın. Sizce bana en çok hangisi yakışır?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'Odam, yatağım, minik eşyalarım... 🐣', 'İhtiyacımız olan her şeyi aldınız mı? Önerilen Ürünlere göz atın, belki unuttuğunuz bir şey vardır.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'Rahim kasları doğuma hazırlanıyor.', 'Korkmayın, bu sadece bir prova. Ağrılar sıklaşıyorsa Kasılma Sayacı ile aralıklarını kontrol edin!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'Manikürüm hazır!', 'İnanamayacaksınız, tırnaklarım artık parmak uçlarıma ulaştı.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'Doktor kontrolleri sıklaşıyor! 🩺', 'Doğum yapacağınız hastaneyi ve doktoru belirlediniz mi? Doktorlar ve Klinikler listesine göz atın! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'Bir gülüp bir ağlıyor musunuz?', 'Hormonlar yine oyun oynuyor. Doğum korkusu ve kavuşma sevinci bir arada. İçinizi Duygu Günlüğüne dökün, rahatlayın. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'Süper gücünüz bana geçiyor! 🛡️', 'Hastalanmayın, Anne! Sizin bağışıklığınız benim ilk zırhım olacak. Biz yenilmez bir takımız! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'Yine uykunuz mu kaçtı? 🥺', 'Bense mışıl mışıl uyuyorum. Gözlerinizi kapatın, beni hayal edin... Belki rüyalarımız buluşur? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'Kemiklerim taş gibi oluyor! 🦴', 'Ama bunun için sizin depolarınızdan kullanıyorum... Affedin! 🙈 Bir bardak süt içerseniz barışır mıyız? 🥛'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'O şarkıyı bir daha söyleyin! 🎶', 'Sesiniz beni öyle rahatlatıyor ki... Siz şarkı söylerken ben içeride dans ediyorum, hissediyor musunuz? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'Duvarlar üstüme üstüme geliyor! 🏠', 'Yerim iyice daraldı, Anne. Ayağımı uzatınca kaburganıza değiyor... Canınızı acıttıysam öpüp geçirebilir miyim? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'Kıyafetlerimi ütülediniz mi? 👗', 'Kokuları şimdiden burnuma geliyor. Beni o kıyafetlerin içinde görmek için sabırsızlandığınızı biliyorum! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'Havuzumun suyu azaldı... 💧', 'Ben temiz ve bol suda yüzmeyi seviyorum. Benim hatırım için bir bardak su içer misiniz? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'Yolu kontrol ediyorum! 🔦', 'Başım aşağıda, çıkış kapısına bakıyorum. Siz sadece derin bir nefes alın, her şey harika olacak!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'O sıcak el kimin? 🖐️', 'Babam mı? Onun dokunuşunu hissedince sakinleşiyorum. Ona söyleyin, ben de elimi uzattım; çak bir beşlik! ✋'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'Gözlerimi kocaman açtım! 👀', 'Burası karanlık olsa da her şeyi izliyorum. Acaba size mi, yoksa babama mı benziyorum? Bahse girdiniz mi? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'Şşş... Ben uyuyorum! 😴', 'Beynim o kadar hızlı gelişiyor ki bol bol uyumam gerekiyor. Siz de benimle uyuyun, Anne? 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'Evde değişiklik mi yapıyorsunuz? 🌪️', 'Her yeri temizlemek, dolapları düzenlemek istiyorsunuz... Bu, yuva kurma içgüdüsü! Ama kendinizi yormayın, benim dinlenmiş bir anneye ihtiyacım var.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'Burası çok dar! 🏠', 'Dönmek istiyorum ama yerim yok. Dirseğimi uzatırsam karnınız yamuk görünecek. Bakıp gülersiniz! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'Yağa ihtiyacım var! 🥑', 'Avokado, ceviz veya zeytinyağı... Beni tombiş yapmak sizin elinizde!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'Kalbiniz bana ninni oluyor... 💓', 'Başım aşağıda, kulağım kalbinize daha yakın. Bu ritim, beni sakinleştiren tek müzik.'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'Odam hazır mı? 🧸', 'Beşiğime bakıp hayallere mi dalıyorsunuz? Oraya koyduğunuz oyuncağa sarılmak için sabırsızlanıyorum! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'Aşağı iniyorum, hissediyor musunuz? ⬇️', 'Leğen kemiklerinizin arasına yerleşiyorum. Artık daha rahat nefes alacaksınız ama tuvalete daha sık koşacaksınız! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'Bağışıklığım güçleniyor 🛡️', 'Sizden bana geçen antikorlar, beni mikroplarla dolu dünyaya hazırlıyor. Sütünüz de beni koruyacak, Anne!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'İlk kıyafetim nerede? 👕', 'Hastane çantasını hazırladınız mı? Bana giydireceğiniz o küçük tulumu okşayın...')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_tr = v.t, body_tr = v.b
FROM (VALUES
  ('deba1190-6096-4dec-88eb-70e669fb3ccb'::uuid, 'Sizi görmek istiyorum! 👀', 'Gözlerim açık ama burası karanlık. Yüzünüzü ve gülüşünüzü görmek için günleri sayıyorum. Çok az kaldı! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'Cildim pürüzsüzleşiyor! 🧖‍♀️', 'Tüylerim dökülüyor, yağ tabakam kalınlaşıyor. O nazik dokunuşunuza hazırlanıyorum, Anne. Yumuşacık olacağım! ☁️'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'Güç topluyorum! ⚡', 'Çok hareket etmiyor muyum? Korkmayın. Şimdi uyumam gerekiyor. Büyük gün için enerji topluyorum. Siz de dinlenin! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'Dirseğimi hissettiniz mi? 💪', 'Affedin beni, Anne! Gerinmek istiyorum ama yerim yok. Karnınız şekilden şekle girince bana gülüyor musunuz? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'Penguen gibi mi yürüyorsunuz? 🤭', 'Ben aşağıya indiğim için yürüyüşünüz değişti. Ama siz her hâlinizle, her adımınızla dünyanın en güzel annesisiniz! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'Hık... Hık... 😲', 'Yine hıçkırık tuttu! Diyaframımı çalıştırıyorum. Karnınız ritmik bir şekilde zıplıyorsa bilin ki benim!'),
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800', 'Doktorla görüştük mü? 👩‍⚕️', 'O soğuk jel karnınıza değdiğinde gıdıklanıyorum! 🙈 Ama kalp atışlarımı duymanın size huzur verdiğini biliyorum.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'Biz bir takımız! 🤝', 'Sancılar başladığında korkmayın. Derin nefes alın. Birlikte başaracağız, söz veriyorum!'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'Çantalar kapıda mı? 🎒', 'Her an Sürpriz! diyebilirim. Bana giydireceğiniz o ilk şapkayı çantaya koydunuz mu? Üşümek istemiyorum. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'Bitişe çok az kaldı! 🏆', '37 hafta bitiyor! Artık Erken Term Dönemindeyiz. Yani bugün doğsam bile akciğerlerim nefes almaya hazır!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'Rüyamda sizi gördüm... 💤', 'Sesiniz, kokunuz, sıcaklığınız... Uyanıp size gerçekten sarılmak için sabırsızlanıyorum, Anne!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'Karnınız sertleşti mi? 🤰', 'Bu sadece bir prova mı, yoksa ben geliyor muyum? Şüpheleniyorsanız Sancı Ölçer''i açın. Size net bir şekilde söyleyecek: Hastaneye mi, yoksa yatağa mı?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'Ben hâlâ buradayım! 👋', 'Yerim çok dar olduğu için daha az hareket ediyorum. Ama endişeleniyorsanız Tekme Sayacı''na girin. Gelin, birlikte sayalım! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'Çoraplarımı koydunuz mu? 🧦', 'Üşümek istemiyorum, Anne! Hastane Çantası listesini son kez kontrol edin. İlk tulumum orada mı? 🥰'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'Uyuyamıyor musunuz? 🥺', 'Gözünüze uyku girmiyor mu? Gelin, doğduğumda bana dinleteceğiniz sesleri şimdiden dinleyelim. Beyaz Sesler bölümü ikimizi de sakinleştirir. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'Bavulumu hazırladım, kapıda bekliyorum! 🚪', '38 hafta! Artık resmen doğmaya hazırım. Akciğerlerim, beynim, her şeyim tamam.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'Suyunuz gelirse ne yapacaksınız? 💦', 'Panik yapmak yok! Blog bölümündeki Doğumun 3 temel belirtisi başlıklı makaleyi okuyun.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'Aşağı doğru iniyorum... ⬇️', 'Leğen kemiklerinize baskı yaptığımı biliyorum. Ama size kavuşmamın tek yolu bu. Benim güçlü Annem! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'Uykusuz geceler? 🥱', 'Doğum yaklaştıkça uykuya dalmak zorlaşabilir. Bu, vücudunuzun sizi bebek düzenine hazırlamasıdır.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'Kalbim nasıl atıyor? 💓', 'Beni özlediğinizde elinizi karnınıza koyun. Kalplerimiz birlikte atıyor. Her şey yolunda, sadece kavuşacağımız günü bekliyoruz. 🗓️'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'Tık-Tık, benim! ✊', 'Karnınıza girip çıkan sancılar mı oluyor? Vakit kaybetmeden Sancı Ölçer düğmesine basın. Aralıklar kısalıyorsa büyük gün bugün demektir! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'Altın Süt geldi mi? ✨', 'Göğüslerden sarımsı bir sıvı gelebilir; bu, bebeğin ilk aşısı gibidir. Bloglarda emzirme hakkında bilgi edinin. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'Yalancı mı, Gerçek mi? 🤔', 'Karnınız sertleşip gevşiyor mu? Sancılar düzenli değilse yalancı sancıdır. Emin olmak için Sancı Ölçer''i açıp test edin!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'Nişan geldi mi? 🩸', 'Yoğun kıvamlı bir akıntı geldiyse rahim ağzı açılmaya başlıyor olabilir. Korkmayın, bu yalnızca hazırlanmanız gerektiğini gösteren bir işarettir.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'Şap! Bu ses de neydi? 💦', 'Suyunuz gelirse panik yapmayın. Sadece derin bir nefes alın ve doktorunuza haber verin. Ben geliyorum! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'Stresi uzaklaştırma zamanı! 😮‍💨', 'Heyecanlı mısınız? Egzersizler bölümündeki Doğum nefesi tekniklerini şimdiden öğrenin. Sancılar sırasında bunlara çok ihtiyacınız olacak.'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'Tekmelerim azaldı mı? 🦶', 'Yerim daraldı, Anne! Ama yine de hareketlerimi hissetmelisiniz. Şüpheniz varsa tatlı bir şey yiyin ve Tekme Sayacı''nı açın.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'Belgeler hazır mı? 📄', 'Kimlik, tahlil sonuçları... Çantanızı son kez kontrol edin. Hastane Çantası listesindeki her şeyi işaretlediniz mi? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'Gözlerinizi kapatın... 😌', 'Doğumdan korkmayın. Sadece beni ilk kez kucağınıza alacağınız o anı hayal edin. Kokum size tüm acıları unutturacak.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'Serviks (Rahim ağzı) 🗝️', 'Gizli bir çalışma var! Rahim ağzı yumuşuyor, inceliyor ve açılıyor. Siz hissetmeseniz de vücudunuz bana kapıyı açıyor.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'Bugün o gün mü? 🗓️', '40 hafta tamamlandı! Takvim bugünü gösteriyor. Geliyorum, yoksa biraz daha naz mı yapayım? Her an sürpriz yapabilirim! Hazır olun! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'Ben gecikmedim! 👑', 'Sadece yıldızlar sahneye en son çıkar, Anne! Biraz daha naz yapayım, sonra geleceğim. Sabırlı olun! 😌'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'Doğal yollarla destek 🍍', 'Hurma ve ananasın rahim ağzını yumuşattığı söylenir. Beslenme bölümünden bugün menünüze bunları ekleyin. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'Kalp atışları... ❤️', '40 haftayı geçtiğinizde plasentanın durumunu kontrol etmek için KTG (NST) incelemesi önemlidir. Her şeyin yolunda olduğundan emin olun.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'Merdiven çıkalım mı? 🪜', 'Bana yol gösterin! Merdiven çıkmak veya squat yapmak aşağı doğru ilerlememe yardımcı olabilir. Egzersizler bölümüne göz atın.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'Buranın havası çok güzel 🌡️', 'Sıcak, karanlık ve rahat... Çıkmak istemiyorum desem bana kızmazsınız, değil mi? 🥺 Şaka yapıyorum, geliyorum!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'Kalbim nasıl atıyor? 💓', 'Doktorda NST incelemesinde miyiz? O güm güm sesini duyduğunuzda nasıl da rahatlıyorsunuz...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'Hurma yiyor musunuz? 🌴', 'Doğal doğum için bu lezzetli yöntemi denemeye değer!'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'Ama ben kilo alıyorum! ⚖️', 'Burada kaldığım her gün biraz daha tombul oluyorum. Yanaklarım daha da tatlılaşıyor ama sizin işiniz zorlaşıyor. Affedin beni! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'Çantaya atıştırmalık koydunuz mu? 🍫', 'Doğumdan sonra çok acıkacaksınız! Hastane Çantasına sevdiğiniz bisküvi veya çikolatayı ekleyin.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'Plasenta yaşlanıyor mu? 🍂', 'Doktor suyun miktarını kontrol ediyor mu? Bana hâlâ oksijen ulaşıyorsa sorun yok demektir. Bunlar sadece son günlerimiz.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'Gece sancınız mı başladı? 🌙', 'Sizi uykudan uyandıran o ağrı... Gerçek doğum sancısı mı? Vakit kaybetmeden Kasılma Sayacını başlatın. Belki de bu gece O GECE! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'Tahliye emri mi geldi? 📢', 'Doktor suni sancı mı öneriyor? Korkmayın. Önemli olan benim sağ salim kucağınıza gelmem. Hangi yoldan geldiğim fark etmez!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'Son hamilelik fotoğrafınız... 📸', 'Bu karnınıza son kez bakın. Belki yarın kucağınızda olacağım. Bu mucizevi bedeninizle gurur duyun, Anne!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('7797557a-9277-450c-98b3-b0fa58923513'::uuid, 'После вечернего купания — пора спать! 🛁', 'Купание перед ночным сном очень полезно и поможет вашему малышу спокойно уснуть.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'Следите за количеством подгузников за день? 🧷', 'Состояние подгузников — лучший показатель того, что малыш наедается. Не забывайте отмечать каждую смену в Anacan!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'Давайте проанализируем режим сна. ⏱️', 'Когда малыш спит, включайте таймер сна и смотрите на графике, насколько соблюдается его суточная норма сна.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'Вкусный и полезный выбор для мам! 🍲', 'Загляните в наш раздел полезных рецептов, которые помогут вам восполнить энергию, и позаботьтесь о себе.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'Ваш малыш быстро растёт! ⚖', '️ Еженедельно вносите его вес в трекер развития и следите в приложении за кривой его здорового роста.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'У вас есть вопросы? 🤖', 'Даже ночью Anacan AI рядом с вами! Задавайте волнующие вас вопросы и сразу получайте поддержку.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'Первые совместные прогулки! 🌳', 'Если погода хорошая, выходите на прогулку. Малышу очень важно и полезно каждый день бывать на свежем воздухе.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'Сохраните этот миг навсегда! 📸', 'Загрузите сегодняшние милые моменты в Альбом малыша и сохраните воспоминания, которые в будущем вызовут у вас улыбку.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'Баланс сна и кормления. 📚', 'Вы уже прочитали нашу новую статью о развитии новорождённых в разделе блогов?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'Поздравляем, вам уже 2 недели! 🎈', 'Чтобы отметить эту маленькую годовщину, воспользуйтесь интересными идеями из раздела фотосессий малыша.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'Иногда кормление может затянуться. 🍼', 'Используйте таймер, чтобы анализировать процесс. Главное, чтобы и вам, и малышу было комфортно.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'Как вы себя чувствуете? 🧘‍♀', '️ Материнство прекрасно, но бывает утомительным. Откройте Дневник настроения и оцените сегодняшний день.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'Чего не хватает для ухода за малышом? 🧴', 'В разделе рекомендованных товаров вы найдёте продукцию, которую проверили и оценили другие мамы.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'Смена подгузника уже стала привычной! 👶', 'Отмечайте мочеиспускания и стул малыша в трекере подгузников, чтобы следить за состоянием его здоровья.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'Маме тоже нужно отдыхать! 🛋', '️ Если вы уже отметили режим сна малыша с помощью таймера, теперь ваша очередь отдохнуть. Налейте себе чаю и расслабьтесь.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'Малыша мучают колики? 🌪️', 'Не паникуйте. Слегка помассируйте ему животик и включите на фоне Белый шум, чтобы отвлечь малыша.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'Время полежать на животике! 🐢', 'Несколько минут на животике каждый день укрепляют мышцы шеи малыша.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'Подготовка к ночному сну. 🌙', 'Перед сном отрегулируйте температуру в комнате и запустите таймер сна в Anacan.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'Секреты увеличения лактации! 🥛', 'В разделе полезных рецептов вас ждут натуральные продукты и рецепты смузи для повышения лактации.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'Возможно, это скачок развития. 📈', 'Малыш внезапно начинает громко плакать без видимой причины? Скачок развития на 3-й неделе также совпадает с пиком кишечных колик. Не паникуйте.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'Не спускается с рук 🛋️', 'Малыш просыпается и плачет, как только вы кладёте его? Сегодня вам может казаться, что вы весь день заперты дома с малышом на руках. Но помните: ваши объятия — самое безопасное место для него. Наберитесь терпения.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'Вовлекайте партнёра в уход за малышом. 👨‍👩‍👦', 'Сегодня вечером поручите партнёру сменить подгузник или уложить малыша под белый шум, а сами отдохните.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'Время ухода за кожей. 🛁', 'Ищете кремы, подходящие для чувствительной кожи малыша? Вам поможет список рекомендованных товаров.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'Рефлексы развиваются! 🖐️', 'Замечаете, как крепко малыш держится за ваш палец? Чтобы узнать об этом подробнее, прочитайте наши статьи в разделе блогов.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'Ваш ежедневный отчёт готов! 📊', 'Откройте приложение Anacan и ознакомьтесь с анализом сегодняшних графиков сна, кормлений и смены подгузников.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'Следим за этапами роста! 📏', 'Приближается следующий месяц. Откройте в приложении раздел отслеживания развития и убедитесь, что данные обновлены.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'Вы вместе уже 20 дней! 🥰', 'Вы замечательная мама! Красиво сохраните воспоминание об этом дне с помощью инструмента «Фотосессия малыша».'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'Сегодня — только положительные эмоции! ✨', 'Откройте дневник настроения и запишите момент, когда малыш рассмешил вас больше всего. Anacan AI вас слушает!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'Период скачка развития! 📈', 'Малыш может чаще испытывать голод. Следите за кормлениями с помощью таймера.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'К вечеру малыш становится беспокойнее? 🎶', 'Причиной могут быть кишечные колики или усталость. Успокойте малыша звуками природы из раздела «Белый шум».'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'Ровно 3 недели! 🎉', 'Отметьте эту маленькую дату с помощью раздела «Фотосессия малыша» и сохраните на память трогательный момент.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'Не забывайте о себе! 🥗', 'Ваше здоровье — залог здоровья малыша. Выберите среди полезных рецептов для женщин перекус, который поможет восстановить энергию.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'Вы не обязаны быть супермамой! 🦸‍♀', '️ Не стесняйтесь просить о помощи. Для вдохновения прочитайте статьи в разделе «Блоги».'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'Следите за развитием шаг за шагом. 📏', 'Забыли внести данные об окружности головы, росте и весе в Трекер веса? Запишите их сейчас.'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'В папиных объятиях 🫂', 'Усталость первой недели уже даёт о себе знать. Сегодня вечером пусть папа уложит малыша спать у себя на груди и включит Белый шум. А вы примите тёплый душ и хотя бы на 15 минут забудьте обо всём под струями воды за закрытой дверью. Вы справитесь.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'Время выкладывания на животик! 🐢', 'Пока малыш бодрствует, положите его на животик на 1-2 минуты, чтобы укрепить мышцы.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'Поздравляем, вы уже целую неделю мама! 🥳', 'Поздравляем, вы уже целую неделю мама! 🥳 Воспользуйтесь разделом фотосессии малыша, чтобы создать памятный снимок этого особенного дня.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'Посмотрим статистику первой недели? 📊', 'Хотите проверить в приложении Anacan недельную статистику сна, смены подгузников и кормлений?'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'Физическое восстановление 🩹', 'Ваш организм всё ещё восстанавливается, и, возможно, швы пока болят. Не требуйте от себя совершенства.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'Формируется кишечная микрофлора! 🦠', 'Если начались колики, ритмы из раздела «Белый шум» в Anacan помогут малышу успокоиться.'),
  ('3258a482-400c-485d-af7c-ccb221416732', 'Ночные пробуждения вас утомляют? 😴', 'Запишите свои сегодняшние чувства в Дневнике настроения, и Anacan AI даст вам полезные советы.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'Желудок вашего малыша растёт. 🍒', 'Записывайте объём съеденного с помощью инструмента контроля кормлений и проверяйте суточную норму.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'Не пеленайте малыша слишком туго — пусть он двигается свободно! 🚫', 'Чтобы узнать больше полезной информации и о современных подходах, загляните в наши блоги.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'Ваше молоко уже становится более питательным зрелым молоком. 🥛', 'Включите таймер грудного вскармливания и точно отслеживайте, сколько сегодня ел ваш малыш!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'Как прошли первые 10 дней? 📸', 'Недосып, страхи, порой слёзы и буря огромной любви... Первые 10 дней — самое трудное начало — уже позади! Вы великолепны.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'Сегодня уделите хотя бы 15 минут только себе. 🛁', 'Примите тёплый душ и побалуйте себя полезным блюдом по рецепту из приложения.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'Взгляд вашего малыша становится более сфокусированным! 👀', 'Он уже лучше различает ваше лицо. Запишите в Дневнике настроения, какие чувства вызывают у вас эти приятные моменты.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'Как складывается режим кормлений? 🤱', 'Запустите таймер в приложении и легко отслеживайте норму кормлений с помощью инструмента контроля кормлений.'),
  ('1af46170-3a5b-41ea-bb18-ce899698f996', 'Поздравляем с первым днём! 🥳', 'Начните пользоваться таймером в приложении Anacan, чтобы отслеживать режим сна и кормления малыша.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'Отдыхайте, пока ваш малыш спит! 😴', 'Не забудьте записать в Дневнике настроения, как вы себя сегодня чувствуете.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'Молозиво — первая вакцина! 🤱', 'Легко отмечайте кормления с помощью инструмента контроля кормления в приложении.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'Не расстраивайтесь, думая, что у вас мало молока! 🥛', 'Желудок вашего малыша пока размером с вишню. Статистику кормлений за день можно отслеживать в приложении.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'Уделите время себе. 💆‍♀', '️ Мышцы матки восстанавливаются. Запишите свои сегодняшние эмоции в Дневнике настроения — это поможет вам почувствовать облегчение.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'Белый налёт на коже малыша защищает его. 👶 Не волнуйтесь.', 'Не забывайте отмечать смену подгузника в Anacan и сверяться с нормами!'),
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c', 'У вашего малыша очень сильный сосательный рефлекс! 🍼', 'Отслеживайте каждое кормление с помощью таймера, чтобы убедиться, что малыш получает достаточно молока.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'Вас одолевает беспричинная плаксивость? 😢', 'Это совершенно естественно! Вы можете поделиться своими чувствами с ИИ Anacan или в нашем Сообществе и получить поддержку.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'Не получается уложить малыша спать? 🎶', 'Включите инструмент «Белый шум» в нашем приложении, чтобы малыш погрузился в глубокий сон, как в утробе мамы.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'Остаток пуповины должен оставаться сухим и чистым. ⏱️', 'Если остаток пуповины намок, его необходимо тщательно высушить и ежедневно обрабатывать антисептическим раствором, назначенным врачом.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'Мамам очень важно получать достаточно витаминов с пищей! 🥗', 'Загляните в раздел полезных рецептов и восстановите силы.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'Малыш узнаёт вас по запаху и голосу! 👃', 'Поэтому, когда вы выходите из комнаты, малыш может беспокоиться и чувствовать себя в опасности.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', 'Не верьте мифам о том, что малыша можно приучить к рукам! 🤗', 'Обнимайте малыша как можно чаще. Это укрепит вашу связь и поможет увеличить выработку молока.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'День и ночь поменялись местами? 🛌', 'Отслеживайте режим сна и ежедневные нормы в приложении, а когда малыш спит — постарайтесь поспать и вы.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'Начинаются плановые осмотры. 💉', 'Вносите данные о росте и весе малыша в Трекер развития, чтобы создать его персональный график развития!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'Таймер поможет не забывать об интервалах. 🍼', 'С Anacan легко планировать смену подгузников и время кормлений.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'Ежедневная норма сна очень важна. 😴', 'Когда малыш засыпает, включайте таймер сна и проверяйте, насколько продолжительность его сна соответствует дневной норме.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'Пытается поднять голову! 🐢', 'Добавьте в Альбом малыша видео его движений во время лежания на животе (tummy time).'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'У вас есть вопрос? 🤖', 'Почему малыш часто просыпается ночью? Anacan AI всегда готов помочь вам с такими волнующими вопросами.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'Сколько подгузников используется за день? 🧷', 'Записи о смене подгузников — самый простой способ понять, достаточно ли питания получает ваш малыш. Добавьте их в приложение прямо сейчас!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'Первая улыбка уже близко! 😊', 'Не упустите моменты, когда малыш внимательно смотрит на ваше лицо. Запишите вызванные ими эмоции в Дневник настроения.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'Начинаем формировать режим! 🌙', 'Купайте и кормите малыша в одно и то же время, включайте Белый шум и запускайте таймер сна.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'Не забывайте о своих потребностях в материнстве. 🛍', '️Крем для сосков и прокладки для груди подарят вам больше комфорта и обеспечат необходимую защиту.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'Время для прогулки на свежем воздухе! ☀️', 'Ищете подходящее для отдыха место, куда можно пойти с малышом? Обязательно загляните в наш блог «Места, удобные для мам».'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'Читайте и узнавайте новое, когда есть время. 📚', 'Самые полезные статьи о развитии новорождённых и уходе за ними ждут вас в разделе «Блоги».'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'Приближается первый ежемесячный осмотр. ⚖️', 'Убедитесь, что вы отметили текущую прибавку в весе и росте малыша в разделе «Отслеживание развития».'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'Не стесняйтесь делиться своими чувствами. 📝', 'Вы устали или счастливы? Неважно — запишите сегодняшние эмоции в Дневник настроения, чтобы стало легче.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'Малыш становится внимательнее! 👀', 'Теперь он лучше различает контрастные чёрно-белые изображения. Не забывайте использовать развивающие карточки во время tummy time.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'Забыли, какой грудью кормили? 🤱', 'Отмечайте с помощью таймера, какой грудью вы кормите — правой или левой, а инструмент контроля кормлений всё запомнит!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'Вовлекаем пап в процесс! 👨‍🍼', 'Благодаря режиму партнёра папы тоже могут следить за развитием малыша.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'Ваша еженедельная статистика готова! 📊', 'Откройте приложение, чтобы проанализировать, насколько в последние дни сон и питание малыша соответствовали нормам.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'Свежий воздух улучшает аппетит! 🌳', 'Старайтесь каждый день гулять с малышом на свежем воздухе. Это очень полезно и для вас, и для вашего малыша.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'Повысьте качество грудного молока. 🍲', 'Чтобы питаться вкусно и полезно, загляните в раздел «Полезные рецепты» в приложении.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', 'Показатели в 1 месяц! 📏', 'Добавьте новые данные о росте и весе в Трекер развития и с гордостью наблюдайте за графиком здорового роста.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'Поздравляем, нам уже 1 месяц! 🥳', 'Создайте интересные фотографии в разделе «Фотосессия малыша», чтобы отметить этот важный день.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'Поблагодарите себя! 💖', 'Первый и самый сложный месяц уже позади. Зайдите в Дневник настроения и отметьте свои героические достижения за этот месяц.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'Вечерний распорядок нарушился? 🌙', 'Не переживайте. Выберите звук сердцебиения в разделе «Белый шум», чтобы малыш чувствовал себя в безопасности, как в утробе мамы.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'Иногда нам просто нужна передышка. ☕', 'Пока малыш спит, включите Таймер сна и выделите немного спокойного времени для себя.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'Периоды бодрствования становятся дольше. ⏱️', 'Прочитайте рекомендации по играм в разделе «Блоги», чтобы играть с малышом и поддерживать его развитие.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'Готовимся к следующему месяцу. 🛒', 'Если вы ищете подгузники и средства ухода для нового месяца, раздел «Рекомендуемые товары» обязательно вам поможет.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'Вы замечательная мама! ✨', 'Вы уже 30 дней вместе. Добавьте в Альбом малыша коллаж, показывающий разницу между первым днём и сегодняшним.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'Новый месяц — новая страница. 📊', 'Посмотрите месячную статистику кормлений, сна и смены подгузников и убедитесь, как прекрасно вам удалось наладить режим малыша!'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'Снимите усталость после долгого дня. 🛁', 'Уделите время себе и расслабьтесь, записав сегодняшние чувства в Дневник настроения.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'Мы уже вступили во 2-й месяц! 🎊', 'Разговаривайте с малышом в течение дня, чтобы поддерживать его развитие.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'Режим кормления может измениться. 🍼', 'Чтобы следить за аппетитом малыша, запустите таймер Anacan и проверяйте суточную норму.'),
  ('24927359-7877-4f99-9dea-0460583a0880', 'Следим за количеством подгузников за день. 🧷', 'Продолжайте отмечать каждую смену подгузника в Anacan, чтобы убедиться, что малыш получает достаточно питания.'),
  ('77d01c80-0ffb-4089-a192-db04bf909aa1', 'Малышу трудно заснуть? 🌙', 'Выберите шум океанских волн в разделе «Белый шум» и отдохните, пока малыш погружается в глубокий сон.'),
  ('afe3841b-76da-4cfe-9cf7-b2077153f607', 'Уже слышны первые звуки «агу»! 🗣️', 'Чтобы поддержать развитие речи, повторяйте звуки малыша и разговаривайте с ним.'),
  ('5bfad78e-cb6a-405d-8517-a356018909ca', 'Как меняются рост и вес? 📏', 'Внесите новые показатели в разделе «Отслеживание развития» и проанализируйте индивидуальный график развития.'),
  ('d87d1938-6445-47b1-b0eb-19c7a9941726', 'На поиски свежего воздуха! 🌳', 'Выберите ближайшее место, куда можно заехать с детской коляской, чтобы с комфортом погулять с малышом.'),
  ('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1', 'Anacan AI всегда рядом! 🤖', 'Есть вопросы о режиме сна? Напишите нашему искусственному интеллекту — он ответит сразу же.'),
  ('0ac0ad4d-776b-416d-a345-c0bddd639ff1', 'Способность концентрировать внимание развивается! 👀', 'Понаблюдайте, как малыш следит за предметами в комнате. Чтобы узнать больше о развитии, загляните в раздел «Блоги».'),
  ('1a8980b4-ba5e-4179-adce-580423431a55', 'Важно знать нормы сна. ⏱️', 'Включите таймер сна, когда малыш уснёт, и проверьте, соблюдается ли его суточная норма сна.'),
  ('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f', 'Мамам нужна энергия! 🍳', 'Восстановите силы с помощью вкусного и простого в приготовлении смузи из раздела полезных рецептов.'),
  ('041b2f2c-3594-4ff1-96a1-f589206d267b', 'Кормления и перерывы. 🤱', 'Сделайте свой распорядок ещё удобнее, измеряя продолжительность каждого кормления с помощью инструмента «Контроль кормления».'),
  ('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec', 'Как ваше настроение, дорогая мама? 💖', 'Иногда всё может навалиться одновременно. Откройте «Дневник настроения» и свободно поделитесь своими переживаниями.'),
  ('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b', 'Особый уход за кожей малыша. 🧴', 'Откройте для себя лучшие средства для бархатистой кожи малыша в нашем блоге «Товары, рекомендованные мамами».'),
  ('47a30b46-d385-4b3c-979c-5465d481ef29', 'Движение против колик! 🚴', 'Включите «Белый шум», пока выполняете с малышом упражнение «велосипед», чтобы ему было и весело, и спокойно.'),
  ('a7868664-8e30-4849-9648-70deec39cf3a', 'Скачок развития 6-й недели приближается! 📈', 'Малыш может плакать чаще обычного. Загляните в раздел «Блоги», чтобы узнать больше об этом этапе развития и его причинах.'),
  ('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee', 'Время ухаживать за малышом вместе с папой. 👨‍🍼', 'После вечернего кормления поручите папе помочь малышу срыгнуть, а сами немного вздремните.'),
  ('22e06076-dd91-4e1b-834c-b78c42879a13', 'Комфорт и вне дома. ☕', 'Планируете встречу с друзьями? Не выходите из дома, не заглянув на нашу карту «Места, удобные для мам».'),
  ('367f3154-4760-43d6-b507-b914372b7538', 'Приготовьтесь к улыбке! 😊', 'Социальная улыбка может появиться в любой момент. Держите телефон наготове.'),
  ('56603835-e00b-48c0-82ab-bbdf1844d6ac', 'Режим улучшает качество сна. 🛁', 'Искупайте и покормите малыша, а затем включите таймер сна, чтобы ежедневно анализировать его сон в приложении.'),
  ('173da4aa-4d6e-4106-ab0c-34773a383b02', 'Время на животике увеличивается! 🐢', 'Малыш уже держит голову увереннее. Включите эти упражнения для укрепления мышц шеи в свой ежедневный распорядок.'),
  ('3c5122e2-a92c-4444-baa3-d7b7fdd4786f', 'Посмотрим статистику смены подгузников? 📊', 'Откройте приложение Anacan и сравните данные о смене подгузников за последние дни. Всё ли в порядке?'),
  ('f653426f-c687-4b5c-806e-74f597e75cf2', 'Чтобы убедиться, что всё в порядке. 🤖', 'О любой беспокоящей вас детали можно спросить Anacan AI даже ночью.'),
  ('2a04ee0c-770e-425b-8987-e6ab25472f0b', 'Естественные способы увеличить лактацию. 🥛', 'Чтобы увеличить количество молока, попробуйте питательные супы и напитки из раздела «Полезные рецепты».'),
  ('6a605601-9da6-47e9-8d07-a1f552eb5fc0', 'Баланс питания и сна в течение дня. ⚖', '️ Проанализируйте сегодняшнюю статистику с помощью контроля кормлений и графиков сна, чтобы спланировать следующий день.'),
  ('756d2914-ecb6-4838-adb6-d312a4bc59a2', 'Малыш изучает свои ручки! 👐', 'Он уже умеет подносить ручки ко рту.'),
  ('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54', 'Сегодня малышу исполняется 40 дней! 🧿', 'Чтобы сохранить память об этом особенном дне, выберите интересные темы в разделе «Фотосессия малыша» и создайте памятные фотографии.'),
  ('92e4d1aa-c4f4-477c-ab81-176ef4f03a16', 'Настраиваемся на спокойный сон. 🌙', 'В завершение этого особенного дня приглушите свет в комнате, включите белый шум и сладко поспите, пока ваш малыш погружается в глубокий сон.'),
  ('ba92608f-780e-4381-a0e7-3f6af86021be', 'Как вы себя чувствуете? ✨', 'Вы завершили важный и особенный период длиной в 40 дней! Вы настоящая героиня!'),
  ('6dd4f975-8504-4871-83c4-a6f7bc24a950', 'Как прошёл ваш день? 📝', 'Налейте себе чашку кофе, запишите сегодняшние чувства в «Дневнике настроения» и немного расслабьтесь.'),
  ('c6c2469c-d36e-4ffe-a532-bee6050f4bac', 'Новый этап после первых 40 дней! 🌸', 'Ваш малыш проявляет всё больше интереса к окружающему миру. Развивающие карточки вокруг него будут полезны для его развития.'),
  ('d647162e-98ae-41c0-81b4-cc5ca3e15dff', 'Как складывается режим кормлений? 🍼', 'С помощью инструмента контроля кормлений и таймера в приложении проверьте, насколько ваш режим соответствует суточной норме.'),
  ('06dbea83-4e3d-4be5-8968-0961033df8d5', 'Малыш всё лучше различает цвета! 🔴', 'Обратите внимание, как он следит за яркими предметами в комнате.'),
  ('295afbf2-1104-44c2-abf4-fb0e41a0ff0e', 'Свежий воздух пойдёт на пользу вам обоим. 🌳', 'Выберите на карте «Места для мам» удобное для прогулки место, куда легко попасть с детской коляской.'),
  ('9f7dfdf1-83be-4fad-a93a-817e105844ce', 'Помогите малышу легче заснуть. 🌙', 'После вечернего купания выберите среди белых шумов звук фена или дождя, чтобы подготовить малыша к глубокому сну.'),
  ('431cbe5a-0f52-442d-a6e8-ab53cd482a5f', 'Ваша статистика за день готова! 📊', 'Проанализируйте графики в приложении, чтобы узнать, сколько малыш сегодня спал и ел.'),
  ('c4adf9ce-d711-4011-af60-94f404f59ae5', 'Следим за ростом и весом! 📏', 'Обновите последние показатели в разделе «Трекер развития», посмотрите на график здорового развития и порадуйтесь успехам малыша.'),
  ('503a0808-7061-4b7d-ae17-f65b9abb87de', 'Следите за развитием шаг за шагом. 📚', 'Прочитайте нашу последнюю статью в разделе «Блоги», чтобы узнать, какие навыки появляются у новорождённых в этом месяце.'),
  ('aeea52a4-dd88-4cf1-a812-0c13b4f98004', 'Суточная норма сна. 🛌', 'Запускайте таймер сна, когда малыш засыпает, и отслеживайте, набирает ли он суточную норму в 14-17 часов.'),
  ('c86bd995-9231-4eae-b8e0-8f84d6a46b62', 'Вы очень сильная! ✨', 'Порой бывает трудно, но вы замечательная мама!'),
  ('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5', 'Сладкое завершение прекрасного дня. 🌙', 'Приглушите свет в комнате, включите звук материнской утробы в разделе «Белый шум» и наблюдайте, как сладко спит ваш малыш.'),
  ('9d97fdbc-edef-4830-93ad-c388f586d909', 'Вы вместе уже ровно 50 дней! 🎈', 'Отметьте этот прекрасный юбилей, создав особенный снимок с помощью инструмента «Фотосессия малыша»!'),
  ('cb1a5cad-e167-45a8-b0b1-4e8ebe455866', 'Анализ последних 50 дней. 📈', 'Загляните в разделы «Трекер развития» и «Контроль питания», чтобы увидеть, как замечательно вырос ваш малыш за эти 50 дней.'),
  ('10f8db02-014b-4a08-8d7a-e5cbbb260125', 'Погружаемся в глубокий сон. 😴', 'Выберите звук фена в разделе «Белый шум», а пока малыш спокойно спит, расслабьтесь и запишите свои чувства в «Дневнике настроения».'),
  ('2cd12a68-4486-435f-ad24-55a11a2f62a2', 'Ежедневный анализ кормлений. 🍼', 'Измеряйте продолжительность грудного вскармливания с помощью таймера в приложении и сверяйтесь с нормой в разделе «Контроль питания».'),
  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'Поле зрения расширяется! 👀', 'Теперь малыш лучше следит взглядом за предметами.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'Открывает для себя новые звуки! 🗣️', 'Записывайте милое гуление малыша. Читайте «Блоги», чтобы больше узнать о развитии речи.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'Ночные пробуждения продолжаются? ⏱️', 'Отмечайте каждое пробуждение в таймере сна, чтобы анализировать общий режим сна и суточную норму.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'Не забывайте о себе! 🥗', 'Маме очень важно сохранять энергию. Выберите богатое витаминами блюдо из полезных рецептов для женщин и восстановите силы.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'Что вас беспокоит? 🤖', 'Даже ночью вы можете задать любой вопрос нашему AI-помощнику Anacan и получить профессиональную поддержку.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'Проверим трекер подгузников. 🧷', 'Отмечайте в Anacan количество подгузников за день, чтобы убедиться, что малыш получает достаточно питания.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'Всё увереннее держит голову! 🐢', 'Превратите упражнения на животике в весёлую игру.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'Пора на свежий воздух! 🌳', 'Откройте нашу карту мест для мам и найдите самое удобное место, куда можно отправиться вместе с малышом.'),
  ('ffb18a7a-0d53-482c-b130-00223f89efd3', 'Источник энергии для мам! 🥗', 'Чтобы восстановить силы, выберите в приложении витаминное и вкусное блюдо из раздела «Полезные рецепты для женщин».'),
  ('40712cc0-bb4b-4d42-9a36-7942cb47a970', 'Реакция на звуки становится активнее! 🎶', 'Замечаете, как малыш успокаивается, услышав ваш голос? Сохраните эти трогательные моменты в Альбоме малыша.'),
  ('aa025645-c5cd-4f2b-840e-6fb50bb6398b', 'Пора за покупками? 🛍', '️Загляните в наш список Рекомендованных товаров, чтобы выбрать средства ухода или игрушки, подходящие малышу в этом месяце.'),
  ('c6ae0bdf-11e6-43d9-a0ab-d021b7461194', 'Продолжайте считать подгузники! 🧷', 'Отмечайте в Anacan количество использованных за день подгузников, чтобы убедиться, что малыш получает достаточно питания.'),
  ('99125d76-b832-4f75-8c29-6320b71e5e67', 'Скачок развития на 6-й неделе! 📈', 'Сегодня малыш может быть немного требовательнее обычного. Не волнуйтесь — обратитесь за поддержкой к Anacan AI.'),
  ('9f56ae7d-2431-4cb2-8d79-fa19be16c242', 'Формируем режим ночных пробуждений. 😴', 'Не включайте свет каждый раз, когда малыш просыпается. Покормите его, используя таймер Anacan, а затем снова уложите под Белый шум.'),
  ('bef1515a-3c39-4799-b9d9-717742d94d5f', 'Отдыхайте, пока малыш спит. ⏱️', 'Включите таймер сна и, пока малыш спит, тоже закройте глаза или почитайте книгу.'),
  ('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c', 'Малыш гулит всё чаще! 🗣️', 'Запечатлейте его попытки поговорить с вами. Выберите подходящую для этого момента рамку в разделе «Фотосессия малыша».'),
  ('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179', 'Продукты для поддержания лактации. 🍲', 'Порадуйте себя супами и напитками для поддержания лактации из раздела «Полезные рецепты для женщин».'),
  ('bcfe1987-8bea-4b53-a1dc-7ef7e234e755', 'Управляйте своими эмоциями. 💖', 'Материнство может быть утомительным. Откройте Дневник настроения, запишите, что сегодня вас тревожит, и вам станет легче.'),
  ('4c289cf6-60de-4ba6-9f14-eae4086d8d21', 'Налаживаем интервалы. 🍼', 'Следите за временем кормлений и интервалами между ними с помощью инструмента «Контроль кормления», чтобы выстроить идеальный режим малыша.'),
  ('7f93cf2f-abf0-4b16-9f93-396050a7ddb9', 'Остались вопросы? 🤖', 'Мой малыш сегодня мало спал — это нормально? Задайте волнующие вас вопросы другим мамам в Сообществе.'),
  ('c505d849-65c8-4ead-80b3-2648f5feaa49', 'Упражнения на животике! 🐢', 'Малыш уже дольше удерживает голову. Ежедневно повторяйте эти упражнения для развития мышц шеи.'),
  ('65d67a55-0ffc-4c5f-8c78-443c16c7f697', 'Вовлекаем пап в заботу о малыше. 👨‍🍼', 'После вечернего кормления поручите папе помочь малышу срыгнуть и уложить его спать, а сами уделите время себе.'),
  ('c7ab2e50-8e71-4df1-97cc-6432f40c4349', 'Улыбок становится всё больше! 😍', 'Не упустите волшебный момент, когда малыш смотрит на вас и радостно гулит! Сфотографируйте его и сохраните снимок в самом красивом уголке Альбома малыша.'),
  ('dba00752-8e14-4710-8793-6a828172c915', 'Перерыв на кофе с подругами? ☕', 'Найдите в разделе «Места для мам» ближайшие уютные кафе, куда можно пойти вместе с малышом.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'Всё ли в порядке? 📝', 'Как ваше настроение? Вы чувствуете усталость или прилив сил? Дневник настроения Anacan — ваш лучший цифровой собеседник, которому можно доверить самое сокровенное.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'Прекрасное завершение месяца. ✨', 'Приглушите свет в комнате, включите белый шум и, пока ваш малыш спит, гордитесь им и собой. Вы замечательная мама!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'Поздравляем, нам ровно 2 месяца! 🎈', 'Создайте памятный снимок в разделе «Фотосессия малыша», чтобы запечатлеть этот чудесный момент!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'Отчёт о развитии за два месяца. 📈', 'Посмотрите данные трекера веса, статистику смены подгузников и кормлений, чтобы увидеть, как малыш рос и развивался в течение этих 60 дней.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'Снимите усталость после долгого дня. 🛁', 'Уделите время себе и почувствуйте облегчение, записав свои сегодняшние переживания в Дневник настроения.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'Соблюдаем режим кормления. 🍼', 'Аппетит малыша может усилиться. Запустите таймер Anacan и проверьте норму кормления с помощью инструмента контроля кормлений.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'Первый день третьего месяца! 🎉', 'Ваш малыш уже более осознанно наблюдает за окружающим миром.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'Стало сложнее укладывать малыша? 🌙', 'Затемните комнату, выберите шум океанских волн в разделе «Белый шум» и помогите малышу настроиться на глубокий сон.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'Время прогулки на свежем воздухе. 🌳', 'Прогулки на свежем воздухе очень важны для развития и спокойствия вашего малыша.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'Тянется ручками к игрушкам! 🧸', 'Как же приятно наблюдать за этими маленькими открытиями! Загрузите в Альбом малыша видео, снятые во время совместных игр.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'Источник энергии для мам! 🥗', 'Чтобы восстановить силы и поддержать лактацию, выберите богатое витаминами блюдо в разделе «Полезные рецепты».'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', 'Малыш всё чаще говорит «агу»! 🗣️', 'Малыш всё активнее пытается общаться с вами. Читайте статьи в разделе «Блоги», чтобы поддержать развитие его речи.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'Следите за нормами сна. ⏱️', 'Включайте таймер сна, когда малыш засыпает, и анализируйте, соблюдает ли он суточную норму сна.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'Слюнные железы начинают активно работать! 💧', 'У малыша может выделяться больше слюны.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'Следим за ростом малыша! 📏', 'Внесите данные о весе и росте за следующую неделю в Трекер веса, чтобы обновить индивидуальный график развития.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'Вас что-то беспокоит? 🤖', 'Даже ночью вы можете задать нашему AI-помощнику Anacan такие вопросы, как «Почему сегодня малыш спит меньше?».'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'Время разделить заботы с папой. 👨‍🍼', 'После вечернего кормления поручите папе помочь малышу срыгнуть и уложить его спать, а сами отдохните.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'Лежать на животике становится легче. 🐢', 'Малыш уже держит голову выше и дольше. Включите такие упражнения в свой распорядок дня.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'Проверим количество подгузников за день. 🧷', 'Продолжайте отмечать в Anacan каждую смену подгузника, чтобы убедиться, что малыш получает достаточно питания.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'Создаём режим. 🛁', 'Каждый вечер купайте и кормите малыша в одно и то же время, а затем запускайте таймер сна, чтобы сформировать здоровый режим.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'Не забывайте о себе, дорогая мама! 🍲', 'Загляните в раздел «Полезные рецепты» в приложении Anacan и приготовьте сегодня что-нибудь вкусное для себя.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'Малыш узнаёт вас и ваш голос! 😍', 'Обратите внимание, как он радуется, когда вы входите в комнату. 😊'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'Не стесняйтесь делиться своими чувствами. 📝', 'Устали или полны энергии? Неважно — отметьте сегодняшние эмоции в Дневнике настроения, и вам станет легче.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'Комфорт и вне дома. ☕', 'Хотите выпить кофе с друзьями? Не выходите из дома, не заглянув на нашу карту мест, удобных для мам.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'Социальные улыбки! 😊', 'Его милая улыбка заставляет забыть обо всей усталости.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'Ваша недельная статистика готова! 📊', 'Откройте приложение, чтобы проанализировать, насколько хорошо в последние дни вам удавалось соблюдать режим сна и кормления.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'Забыли, какой грудью кормили? 🤱', 'Отмечайте в таймере правую или левую грудь — пусть Anacan всё запомнит за вас!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'Дневной сон меняется. ⏱️', 'Создайте новый режим, отслеживая время бодрствования и перерывы с помощью контроля кормления и таймеров сна.'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'Звуковая терапия при беспокойстве. 🎶', 'Если сегодня вечером малыш беспокоен, включите звук сердцебиения в разделе «Белый шум», чтобы помочь ему отвлечься.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'Время играть! 🎈', 'Прочитайте рекомендации по развивающим играм в разделе «Блоги», чтобы узнать, как интересно и с пользой проводить время с малышом.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'Нужно что-нибудь купить? 🛍', 'В нашем списке рекомендованных товаров вы легко найдёте безопасные игрушки и принадлежности, подходящие малышу в этом возрасте.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'Итоги дня. 📈', 'Проанализируйте данные контроля кормления и графики сна, чтобы увидеть, как прекрасно формируется ваш режим.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'Контроль веса и роста. 📏', 'Как растёт ваш малыш? Добавляйте новые данные в Трекер веса и следите за индивидуальным графиком его развития.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'Ритуал перед сном. 🛁', 'Искупайте малыша, покормите грудью и запустите таймер сна. Пусть всё идёт по плану и спокойно!'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'Изучает свои ручки! 👐', 'Малыш уже рассматривает свои пальчики и тянет их в рот.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'Ищете средство для ухода или игрушку? 🧸', 'В нашем списке рекомендованных товаров вы легко найдёте безопасные продукты, которые помогут развитию малыша.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'Как вы себя чувствуете? 💖', 'Вы устали за день или полны энергии? Откройте Дневник настроения и отметьте, как прошёл сегодняшний день.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'Какой грудью вы кормили? 🤱', 'Таймер Anacan запомнит за вас, какой грудью вы кормили — правой или левой. Запустите кормление прямо сейчас!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'Утренняя улыбка! 😊', 'Его улыбки в ответ делают день прекраснее. Сохраните эту радость в памяти с помощью фотосессии малыша.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'Успокаивающая звуковая терапия. 🎶', 'При коликах или усталости включите среди Белых шумов звук сердцебиения — он мгновенно успокоит малыша, напомнив ему о времени в утробе мамы.'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'Он ищет ваш голос! 👂', 'Почаще разговаривайте с малышом и устанавливайте зрительный контакт. Узнайте о разных занятиях для его развития в разделе «Блоги».'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'Есть сомнения по поводу ухода за малышом? 🤖', 'Сообщество Anacan выслушает вас без осуждения и даст наиболее подходящую рекомендацию.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'Поддержите лактацию. 🥛', 'Не забывайте пить больше воды! А ещё приготовьте напиток для повышения лактации по рецепту из раздела «Полезные рецепты для женщин».'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'Планируем семейную прогулку! ☕', 'Чтобы приятно провести свободное время, выберите уютное кафе или ресторан в разделе «Места для мам».'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'Ежедневный отчёт. 📊', 'Сколько малыш сегодня спал и сколько раз ел? Посмотрите общую статистику за сегодня на графиках в приложении.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'Не забываем и о папах! 👨‍🍼', 'Цените милые и весёлые моменты, когда ваш малыш играет с папой.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'Иногда нужно отдыхать. 🛋', '️ Пока малыш спит, включите таймер сна и просто посвятите время себе, ничего не делая.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'Следим за ростом и развитием! ⚖️', 'Второй месяц подходит к концу. Зайдите в раздел «Трекер веса» в приложении и убедитесь, что вы обновили последние данные.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'Сладкое завершение прекрасного дня. 🌙', 'Приглушите свет в комнате, включите среди Белых шумов звук материнской утробы и наблюдайте, как ваш малыш сладко спит.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'Вы вместе уже ровно 70 дней! ✨', 'Вы замечательная мама! Добавьте в Альбом малыша коллаж, показывающий, как он изменился с первого дня до сегодняшнего.'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'Запасы заканчиваются? 🛒', 'Заканчиваются подгузники или влажные салфетки? Вам не нужно держать всё в голове. Добавьте их в список покупок прямо сейчас, чтобы ваш партнёр купил их по дороге домой вечером.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'Волшебный мир звуков 📖', 'Разнообразьте вечерний ритуал. Создайте для малыша успокаивающую историю в разделе Умных сказок, чтобы вам обоим было легче и быстрее настроиться на сон.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'Утренний концерт 🎶', 'Малыш уже начинает агукать? Говорите с ним на одном языке и откликайтесь на его звуки. Сегодня просто наслаждайтесь этим милым моментом и никуда не спешите.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'Такой разный плач 😭', 'Малыш плачет от голода или потому, что хочет спать? Не волнуйтесь: с помощью нашего инструмента Анализ плача мы за считанные секунды вместе разберёмся, что означают эти звуки.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'Будьте честны с собой 📝', 'Вы сегодня очень устали? Искренне опишите свои чувства в Дневнике настроения. Вы не обязаны каждый день быть идеальной — вы просто человек.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'Во что одеть малыша? ⛅', 'Погода переменчива, и вы боитесь, что малыш замёрзнет или вспотеет? Загляните в инструмент Погода и одежда и узнайте, какой комплект лучше всего подойдёт для сегодняшней погоды.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'Мы — одна команда! 💪', 'Иногда вы чувствуете себя одинокой и непонятой? Присоединяйтесь к Сообществу Anacan. Там тысячи мам, которые испытывают то же, что и вы. Поделитесь с ними сегодня одной из своих историй.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'Папина очередь 👨‍🍼', 'Сбросьте с плеч усталость дня. Передайте малыша папе — пусть сегодня вечером он уложит его спать. А вы просто налейте себе горячего чая и полюбуйтесь этой картиной со стороны.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'Слюнявые улыбки 🤤', 'У малыша часто текут слюнки, а руки постоянно во рту? Начните делать первые записи в Трекере прорезывания зубов. Да, эта волнующая подготовка начинается рано!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'Тишина под контролем 🤫', 'Малыш только что уснул, но вы боитесь, что домашний шум его разбудит? Включите Шумомер, следите за уровнем децибел в комнате и оберегайте его сон.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'Есть вопрос? 🤖', 'Среди повседневных забот вас что-то беспокоит? Кормление, сон или колики — неважно. Сразу спросите у Anacan AI и получите точный, научно обоснованный ответ.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'Смотрите, я здесь! 👀', 'Теперь малыш внимательно следит за вами даже из другого конца комнаты. Отметьте этот замечательный прогресс в установлении зрительного контакта в Трекере развития и гордитесь тем, как он растёт!'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'Звёздные сны 🌌', 'Дети любят привычные ритуалы. Создайте для малыша особенную сказку в разделе Умных сказок.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'Вы замечательная! 🌸', 'Иногда вам кажется, что вы ни с чем не справляетесь? Но взгляните, как спокойно и ровно дышит ваш малыш... Вы делаете всё, что в ваших силах, и даже больше!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'Энергия мамы 🍲', 'В ежедневной суете вы не забыли поесть? Выберите в разделе полезных рецептов быстрый рецепт супа, который поможет восстановить энергию и улучшить лактацию.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', 'Всего 15 минут 🛁', 'Малыш уснул? Перенаправьте все уведомления партнёру с помощью режима «Партнёр». А сами отправляйтесь в ванную и 15 минут наслаждайтесь тёплой водой и тишиной.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'Делимся опытом 💬', 'Какой его поступок в последние дни смешит вас больше всего? Зайдите в сообщество Anacan и поделитесь этим моментом в публикации. Истории других мам тоже поднимут вам настроение.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'Знакомство с ручками 👋', 'Малыш обнаружил свои ручки и может часами их рассматривать? Не упустите этот забавный и удивительный этап развития — запечатлейте его прямо сейчас с помощью функции «Фотосессия малыша»!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'Код плача 🧩', 'Малыш не голоден, подгузник чистый, но он всё равно беспокоится? Если вам сложно понять причину, воспользуйтесь функцией «Анализ плача», чтобы узнать, какая потребность скрывается за этим звуком.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'Честно об усталости 💖', 'Дома беспорядок, а еду заказали онлайн? Ничего страшного. Вы не одиноки на этом пути.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'Утренняя гимнастика 🐢', 'Он уже увереннее держит голову! Превратите время на животике в весёлое занятие. Положите малыша перед зеркалом и понаблюдайте за его реакцией на собственное отражение.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'Список-напоминание 📝', 'Домашние запасы постоянно заканчиваются. Не перегружайте себя мыслями: откройте список покупок, добавьте туда всё необходимое и одним касанием поделитесь им с партнёром.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'Время сказки 📖', 'Путь вашего малыша к богатому воображению начинается уже сейчас. Создайте волшебную историю с помощью функции «Умные сказки», прочитайте её и наблюдайте, как его глазки постепенно закрываются.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'Педиатр в вашем кармане 🤖', 'Хорошо ли малыш набирает вес? Стул изменил цвет? Прежде чем волноваться, напишите Anacan AI, разберитесь в сути вопроса и получите информацию, которая поможет успокоиться.'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'Умная тишина 🤫', 'Чтобы свести вечерние капризы к минимуму, важно контролировать уровень шума в комнате. Включите шумомер, избегайте слишком шумной обстановки и помогите малышу настроиться на отдых.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'Наряд исследователя ⛅', 'Хотите отправиться на прогулку, но погода вызывает сомнения? С помощью сервиса «Погода и одежда» за считаные секунды подберите комплект, который лучше всего подходит для сегодняшней температуры.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'Утренняя улыбка ☀️', 'Открыв глаза, малыш посмотрел на вас и широко улыбнулся? Вы получили самый дорогой подарок в мире. Сегодня просто вспоминайте этот момент и сохраняйте позитивный настрой.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'До праздника осталось 10 дней! 🎂', 'Приготовьтесь: до трёхмесячия осталось всего 10 дней! Приближается одна из первых важных дат. Самое время придумать красивую концепцию праздника и заказать торт!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'Командный тост 🥂', 'Сегодня вечером поблагодарите друг друга с партнёром за ваши 80 дней труда. Вы справились!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'Чудесный 80-й день! 🎉', 'Вы вместе уже ровно 80 дней! Зайдите в раздел «Фотосессия малыша», запечатлейте эту дату с помощью специальных стикеров для 80-го дня и поделитесь памятным снимком в сообществе!'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'Сила звуков 🌊', 'Беспричинные вечерние кризисы изматывают. Отнесите малыша в комнату, выберите среди белых шумов звуки океанских волн или фена — и обстановка сразу станет спокойнее.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'Где взять энергию маме? 🔋', 'Не вините себя, глядя в зеркало на свои уставшие глаза. Следите ли вы за своим питанием? Выберите среди полезных рецептов богатый железом смузи для мам, который можно приготовить за 10 минут, и восстановите силы.'),
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b', 'Семейное обсуждение 🛋️', 'Когда малыш уснёт, вместе с партнёром посмотрите свою недельную статистику в Дневнике настроения. В какие дни вы испытывали больше стресса? Что можно сделать иначе? Вы — одна команда!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'Посмотрите вниз! 👣', 'Малыш уже изучает собственные ножки! Не упустите этот забавный и милый момент, когда он пытается схватить пальчики ног. Откройте фотосессию малыша, украсьте снимок стикерами и запечатлейте этот важный этап развития.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'Ищем прорезыватель 🦷', 'Слюни текут без остановки, а малыш всё грызёт? Трекер прорезывания зубов предупреждает: самое время заглянуть в раздел Рекомендуемых товаров и выбрать прорезыватель из безопасного силикона или дерева.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'Быстрый диалог 🤖', 'Почему малыш внезапно отказывается от дневного сна? У вас нет времени читать длинные статьи. Задайте вопрос напрямую Anacan AI и получите конкретный краткий ответ о регрессии сна в 3 месяца.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'Философия сказки 🪄', 'Умные сказки снова в деле! Напишите системе: «История о фее, которая днём уставала от игр, а ночью видела прекрасные сны». Возможно, за чтением вы и сами уснёте.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'Неподходящая одежда 👗', 'Иногда вы одеваете малыша слишком легко, а иногда слишком тепло? Не сомневайтесь. Вместо того чтобы смотреть в окно, сразу проверьте Погоду и одежду и спокойно следуйте предложенной системой рекомендации по многослойной одежде.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'Защитите сон с помощью шумомера 🤫', 'Вы взволнованы, дома идёт подготовка, но сон малыша тоже нельзя нарушать. Оставьте Шумомер включённым в комнате, чтобы сразу увидеть, если уровень шума превысит допустимый предел.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'Сегодня никакой уборки! 🛑', 'Вы не обязаны наводить порядок повсюду. Включите режим партнёра: сегодня уборка дома и заказ еды — обязанность вашего партнёра. А вы просто спланируйте завтрашнюю фотосессию в честь 3 месяцев.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('a4183b3c-1979-434f-a71f-64b50e2e618c'::uuid, 'Время готовиться! 🎂', 'Внимание! Завтра большой день — малышу исполняется ровно 3 месяца! Вы ведь не забыли заказать торт или придумать небольшую тематическую фотосессию, чтобы создать особую атмосферу в 90-й день? Поторопитесь!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', 'РОВНО 3 МЕСЯЦА! ЦЕЛЫХ 90 ДНЕЙ! 🎉', 'Вы справились! Несмотря на бессонные ночи, кризисы и страхи, вы показали невероятную командную работу на протяжении всех 90 дней. Откройте фотосессию малыша, выберите стикер «3 месяца» и сразу поделитесь этой радостью с другими мамами в Сообществе Anacan!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'Поздравляем! 🥂', 'Оглянитесь назад и просмотрите все свои записи и графики развития. Посмотрите, как сильно вырос малыш и насколько сильнее стали вы. Самое время гордиться собой!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'Момент победы вашей команды 💖', 'Вы уложили малыша спать с помощью специального таймера сна. А теперь сядьте напротив своего партнёра. Поблагодарите друг друга за каждый момент этих 90 дней. Ведь это не только 3 месяца жизни малыша, но и 3 месяца вашего родительства!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'Ваша особенная сказка 🪄', 'Сегодня вечером зададим инструменту Умные сказки милую тему: «История о самой прекрасной звёздочке, упавшей с неба». Пусть в комнате звучит только эта сказка, а вокруг царит полная тишина.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'Папина площадка 👨‍👧', 'Ваше терпение на исходе? Сегодня ненадолго передайте родительскую смену партнёру. Пусть они немного побудут вдвоём, а вы просто вытяните ноги и отдохните.'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'Ваша личная сказка уже создаётся 🪄', 'Пусть сегодня вечером главным героем станет ваш малыш! Откройте инструмент «Умные сказки» и задайте тему: «Приключение маленького рыцаря, который не хотел спать по ночам». Пусть искусственный интеллект создаст уникальную и милую историю специально для вас.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'Готовы к диалогу? 🗣️', 'Малыш уже не просто издаёт звуки, а пытается отвечать на ваш голос разными интонациями! Откройте трекер развития, отметьте этот удивительный скачок в общении и поговорите с малышом на его языке.'),
  ('f027a882-3827-4905-9807-216432d88e53', 'Мамин туман в памяти 🌫️', 'Не помните, что ели вчера? Мамина забывчивость (Baby brain) — совершенно реальное явление. Не перегружайте мозг: внесите всё необходимое для дома в список покупок, а партнёр пусть обо всём позаботится.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'Правда о растрёпанных волосах 💇‍♀️', 'Вас пугает выпадение волос, когда вы смотрите в зеркало? Это одна из самых неприятных реалий послеродового периода! Вы не одиноки: прямо сейчас зайдите в сообщество Anacan и узнайте, как другие мамы справляются с этим кризисом.'),
  ('41393920-01a7-42fe-a049-e26e1148a375', 'В поисках тишины 🤫', 'Иногда домашний шум незаметно мешает малышу заснуть. Включите шумомер, проверьте акустику комнаты и создайте для малыша идеальную тихую обстановку.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'Чешутся дёсны? 🦷', 'Малыш тянет в рот всё подряд, особенно свои ручки? Началось обильное слюноотделение? Сразу отметьте первые признаки в трекере прорезывания зубов и подготовьтесь к этому длительному процессу.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'Знакомство с ручками 🤲', 'Малыш осознанно тянется к подвесным игрушкам? Его двигательные навыки развиваются. Загляните в раздел «Рекомендуемые товары» и выберите безопасные игрушки для хватания, которые поддержат этот новый интерес.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'Сюрпризы погоды ⛅', 'Хотите выйти на улицу, но по виду из окна не можете понять, какая там погода? Не кутайте малыша в несколько слоёв, чтобы он не вспотел. Инструмент «Погода и одежда» за считаные секунды подскажет идеальный наряд для сегодняшней температуры.'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'Папины плечи 👨‍👧', 'Терпение на исходе, а руки уже отваливаются? Сегодня вечером включите партнёрский режим. Помочь малышу срыгнуть и поносить его по комнате — полностью папина задача. А вы просто отдохните на диване.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'Не голоден — тогда почему плачет? 🧩', 'Малыш никак не успокаивается, а его плач звучит необычно? Перестаньте гадать: дайте инструменту «Анализ плача» прослушать звук и сразу узнайте, что беспокоит малыша — колики или недосып.'),
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589', 'Наушники и кофе 🎧', 'Сегодня был действительно очень тяжёлый день. Выплесните свои чувства в дневнике настроения. Затем наденьте наушники, включите любимую музыку и 10 минут наслаждайтесь горячим кофе в настоящей тишине.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'Утреннее наводнение 💩', 'Едва открыв глаза, вы обнаружили малыша, перепачканного по шею, и простыни, которые нужно менять? С улыбкой отметьте эту грандиозную катастрофу в трекере подгузников. Да, материнство — это ещё и такое!'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'Засекайте время ⏱️', 'Беспорядочные кормления вас утомляют? С помощью таймера контроля кормления измеряйте, сколько времени малыш проводит у груди или с бутылочкой, и постепенно разберитесь в его формирующемся режиме.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'Упрямство во время утренней гимнастики 🐢', 'Малыш не хочет лежать на животике (Tummy time) и плачет? Не заставляйте его. Спросите у Anacan AI: «Как сделать время на животике весёлым для 3-месячного малыша?» — и получите быстрые советы.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'Давайте создадим ещё одну сказку! 🪄', 'На этот раз дадим «Умным сказкам» более забавное задание: «История гномика, который спрятался в папиной бороде». Пусть ваш партнёр озвучит созданную искусственным интеллектом историю, а комнату наполнит смех.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'Побег из четырёх стен 🏃‍♀️', 'Домашние стены давят, но вы не знаете, куда пойти с малышом? Найдите в разделе «Места для мам» ближайшее кафе, куда удобно заехать с коляской и где есть комната для кормления, и немного пообщайтесь с людьми.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'Время хохотать! 😂', 'Теперь малыш не просто улыбается, а громко смеётся! Играйте с ним, щекочите ему животик. Этот смех — лучшая награда за все бессонные ночи.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'Сигналы сонливости 🥱', 'Малыш трёт глаза, тянет себя за ухо или смотрит в пустоту? Не ждите вечерней истерики. Как только заметите эти сигналы, сразу приглушите свет в комнате и начинайте привычный ритуал укладывания.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'Исследуем мир ртом 🤤', 'Малыш сразу тянет в рот руки, игрушки и всё, что находит? Так он познаёт мир. Не отбирайте у него всё подряд — просто убедитесь, что окружающие предметы чистые.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'Почему дома такой беспорядок? 🌪️', 'Смотрите на гору игрушек посреди комнаты и немытую посуду и вините себя? Сегодня пусть эта посуда так и останется на месте. Растить малыша — уже само по себе огромная работа!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'Учимся переворачиваться 🤸‍♂️', 'Малыш пытается перевернуться со спины на живот! Для такого маленького тела это большая работа. Поддерживайте его забавные попытки, но обязательно будьте особенно внимательны у краёв кровати.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'Вы — достаточно хорошая мама! 💖', 'Этим утром вы посмотрели в зеркало и почувствовали себя уставшей, а может, даже недостаточно хорошей мамой? Сделайте глубокий вдох. Для малыша, который смотрит на вас своими невинными глазами, вы — самый прекрасный человек на свете. Вы — достаточно хорошая мама!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'Насколько мы устали? 🛋️', 'Малыш уснул, а вы? Откройте Дневник настроения и вместе с партнёром с юмором опишите сегодняшний хаос. Трудные дни проходят, а командный дух остаётся.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'Регресс сна уже близко? 🤖', 'Малыш внезапно начал часто просыпаться по ночам? Не пугайтесь: приближается регресс сна четвёртого месяца. Сразу попросите Anacan AI кратко и спокойно объяснить этот естественный процесс.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'Пора на прогулку ⛅', 'Одеться и собраться может быть непросто, но даже 20 минут на свежем воздухе отлично повлияют и на малыша, и на ваше эмоциональное состояние. Проверьте погоду, подберите одежду и откройте не окно, а дверь!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'Папа — герой ночи 🦸‍♂️', 'Лучшее правило первых месяцев: помогать малышу срыгнуть и петь колыбельные нужно по очереди! Сегодня вечером малыш на руках у папы, а вы надеваете наушники и наслаждаетесь музыкой.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'Мамина чашка ☕', 'Что вы сегодня сделали для себя? Ничего? Как только малыш уснёт днём, отложите телефон. Налейте себе горячего кофе (или чая) и 10 минут ни о чём не думайте.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'Искусство дёргать за волосы 💇‍♀️', 'Малыш запускает ручки прямо в ваши волосы и изо всех сил тянет их? Хватательный рефлекс становится сильнее! Обязательно снимите на видео этот забавный, хотя и болезненный этап развития и сохраните на память.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'Чудо телесного контакта 🫂', 'Малыш никак не хочет засыпать и начинает кричать, как только вы кладёте его в кроватку? Иногда не нужны никакие приспособления. Положите его себе на грудь и почувствуйте, как контакт «кожа к коже» успокаивает вас обоих.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'Воротник промокает каждые 10 минут?', 'Первые признаки из трекера прорезывания зубов становятся реальностью. Почаще осматривайте нижнюю десну — возможно, первая белая жемчужинка уже на подходе!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', 'Всего 15 минут тишины 🤫', 'К концу дня голова раскалывается от усталости? Когда уложите малыша, включите Шумомер, возьмите обстановку под контроль, объявите домашним режим тишины и дайте своему мозгу отдохнуть.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'А что делают другие мамы? 💬', 'Думаете: «Неужели только мой малыш так делает?» Вы не одиноки! Загляните в сообщество Anacan, почитайте реальные истории мам и с облегчением выдохните.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'Домашние дела могут подождать 🛑', 'Не переживайте из-за беспорядка в комнате. Вы растите человека и не обязаны быть идеальной хозяйкой.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'Папина очередь 👨‍🍼', 'Сегодня вечером помочь малышу отрыгнуть воздух и спеть колыбельную — задача папы. А вы идите отдыхать.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'Не забывайте о себе 🍲', 'Малыш сыт, а вы? Чтобы восстановить силы, вам нужно хорошо питаться. Сегодня закажите для себя что-нибудь вкусное и сытное.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'Вдруг услышали в комнате звонкий смех? 😂', 'Да, малыш уже смеётся в голос! Этот звук стоит всей вашей усталости.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'Контакт «кожа к коже» 🫂', 'Малыш очень беспокоен? Если ничего не помогает, положите его себе на грудь. Стук вашего сердца — лучшее успокоительное.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'Игра с мамиными волосами 💇‍♀️', 'Малыш наматывает ваши волосы на пальчики и сильно тянет? Так развивается хватательный рефлекс. Постарайтесь с улыбкой отнестись к этому немного болезненному этапу развития.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'Полная тишина 🤫', 'Малышу трудно заснуть? Полностью затемните комнату и устраните все звуки. Темнота и тишина — его лучшие помощники для сна.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'Появляются первые зубки? 🦷', 'Слюноотделение усилилось? Делайте отметки в трекере прорезывания зубов и держите под рукой чистые прорезыватели.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'Ваша особенная сказка 🪄', 'Сделайте отход ко сну проще с помощью Умных сказок. Создайте и прочитайте малышу особенную добрую историю.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'Мы — одна команда! 💪', 'Чувствуете себя одинокой и уставшей? Сделайте глубокий вдох. Вы — самая сильная героиня этих бурных дней.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'Впечатляющий переворот 🤸‍♂️', 'Малыш пытается перевернуться со спины на живот? Он так старается! Наблюдайте за его попытками, но никогда не оставляйте его одного на кровати.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'Во что одеть малыша? ⛅', 'Не ломайте голову над тем, во что одеть малыша перед прогулкой. Загляните в раздел погоды и одежды и за считаные секунды подберите идеальный комплект.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'Быть без сил — нормально 🔋', 'Не считайте себя плохой мамой, когда терпение на исходе. Такая усталость естественна. Не стесняйтесь просить партнёра о поддержке.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'Вы достаточно хорошая мама! 🌸', 'Сегодня всё идёт наперекосяк? Ничего страшного. Вашему малышу никто не нужен так, как вы. Для него вас более чем достаточно.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'Магия звуков 🌊', 'Если по вечерам малыш заходится плачем, не паникуйте. Включите для него Белый шум и мгновенно измените атмосферу в комнате.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'Спросите у искусственного интеллекта 🤖', 'В голове тысячи вопросов? Не тратьте время на поиски — сразу спросите у Anacan AI и получите точный, научно обоснованный ответ.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Понаблюдайте, как он удивлённо и с улыбкой смотрит на своё отражение. Он пока не понимает, что в зеркале видит себя, но эта игра прекрасно способствует его умственному развитию.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'Отпустите чувство вины 🛑', 'Сегодня у вас не хватило терпения, возможно, вы немного разозлились и теперь испытываете угрызения совести? Остановитесь. Вы ведь не робот. Примите свои чувства, простите себя и завтра начните новый день.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'Запас энергии для мамы 🍲', 'Покормили малыша, а сами остались голодной? Приготовьте легко усваиваемый и питательный перекус из раздела полезных рецептов. Вам нужны силы, чтобы дарить их малышу.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'Поговори со мной! 🗣️', 'Малыш смотрит на вас и произносит необычные слоги? Отвечайте на его звуки и паузы. Сейчас он ведёт с вами настоящий диалог! Это один из важнейших первых шагов в развитии речи.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'Незаметные нужды 🛒', 'В повседневной суете что-то заканчивается? Туалетная бумага, подгузники, шампунь? Сразу добавьте это в список покупок, пока не забыли, — ваш партнёр получит уведомление на телефон.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'Остановить мгновение 📸', 'Малыш растёт так быстро... Сегодня вечером, когда он уснёт, внимательно рассмотрите черты его лица. Сохраните на память снимок его маленьких ручек и личика с помощью Фотосессии малыша — пусть время остановится на мгновение.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'Что означает этот звук? 🧩', 'Малыш начинает хныкать и плакать сразу после пробуждения? Если вы не можете понять причину, воспользуйтесь Анализом плача и за считаные секунды разгадайте, что стоит за этим беспокойством.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'У сказки нет конца 📖', 'Сегодня вечером дайте Умным сказкам более творческое задание: «История маленького медвежонка, который искал мамин запах». Завершите вечер добрым и спокойным финалом, наполненным любовью.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'Пора выбраться из дома! 🌳', 'Не знаете, куда можно пойти с ребёнком? Утомились от прогулок в парке? Найдите в разделе Места для мам заведение, где можно удобно расположиться с ребёнком и выпить чашечку кофе.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'Большая победа, общая гордость 🥂', '100 ночей, 100 дней... Посмотрите на своего партнёра, который разделил с вами эту огромную нагрузку. Запишите в Дневнике настроения, как вы гордитесь 100-м днём, и поаплодируйте друг другу стоя. Это победа вашей команды!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', '100 ДНЕЙ ЧУДА! 🎉', 'Да, сегодня ровно 100 дней с тех пор, как ваша жизнь полностью изменилась! Вы совершаете нечто невероятное.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'Поаплодируйте себе 👏', 'Оглядываясь назад, вы видите, какими страшными казались первые дни и как многому они вас научили. Гордитесь собой. За эти 100 дней вырос не только малыш — вы тоже выросли.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'Время отдохнуть 🛋️', 'Когда малыш играет самостоятельно, не спешите сразу заниматься делами. Присядьте, просто понаблюдайте за ним издалека 5 минут и выпейте свой кофе.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'Утренняя энергия ⚡', 'Малыш начинает гулить, как только просыпается? Он хочет с вами поговорить. Улыбнитесь и ответьте ему — это основа развития речи.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'Регресс сна? 🌙', 'Малыш стал часто просыпаться по ночам? Возможно, это признаки регресса сна в 4 месяца. Наберитесь терпения — этот этап тоже временный.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'Новые открытия 🤲', 'Малыш тянет в рот всё, что попадается ему в руки? Не паникуйте — так он познаёт мир. Просто следите за чистотой окружающих предметов.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'Посмотрите вниз! 👣', 'Малыш уже изучает пальчики на своих ногах! Внимательно наблюдайте за этим забавным и удивительным моментом и наслаждайтесь тем, как он развивается.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Наблюдать, как он с удивлением рассматривает своё отражение и смеётся, — отличное занятие.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'Пора на прогулку 🌳', 'В четырёх стенах становится душно. Посадите малыша в коляску и выйдите на свежий воздух хотя бы на 15 минут. Это пойдёт на пользу вам обоим.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'Ночной герой 🦸‍♂️', 'Устали от ночных пробуждений? Не стесняйтесь будить папу. Быть командой — значит делить нагрузку поровну.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'Подготовка к крепкому сну 🛀', 'Тёплая ванна, нежный массаж и приглушённый свет в комнате... Соблюдение ритуала перед сном — секрет спокойных ночей без пробуждений.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'Не вините себя 💖', 'Вам кажется, что вы уделяете малышу мало времени? 10 минут тёплого общения с улыбкой ценнее, чем 1 час, проведённый в стрессе.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'Я сам возьму! 🧸', 'Малыш уже уверенно тянется к подвешенным игрушкам? Его зрительно-моторная координация улучшается. Поощряйте его с помощью предметов разных цветов.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'Утренняя гимнастика 🐢', 'Лежание на животе укрепляет мышцы шеи. Даже если малыш плачет, продолжайте выкладывать его на живот каждый день хотя бы ненадолго.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'Эмоциональная разрядка 📝', 'Сегодня всё навалилось разом? Запишите в Дневник настроения все трудности и усталость. Не подавляйте свои чувства.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', 'Победа 110-го дня! 🥂', 'Вот уже ровно 110 дней вы заботитесь о новой жизни. Поблагодарите друг друга с партнёром и насладитесь сегодня вечером тишиной.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'Разумная тишина 🤫', 'Малыш просыпается от внезапных звуков, когда засыпает? Контролируйте уровень децибел в комнате с помощью шумомера.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'Голоден или устал? 😭', 'Малыш плачет без видимой причины, и его плач звучит иначе? Возможно, дело не в голоде, а просто в недосыпе. Внимательно следите за режимом сна.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', '10 минут для мамы ☕', 'Не спешите заниматься домашними делами, как только малыш уснёт. Присядьте на диван, выпейте кофе и просто отдохните 10 минут, глядя в стену.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'Передайте смену 🛋️', 'Если, когда малыш засыпает, вам тоже хочется упасть и уснуть, поручите остальные домашние дела партнёру. Ваше здоровье важнее всего.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'Разные интонации 🗣️', 'Голос малыша становится всё громче и выразительнее. Слушайте его и повторяйте за ним, чтобы рассмешить.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'Список для памяти 🛒', 'Недосып ухудшил вашу память? Не пытайтесь удержать в голове всё, что нужно для дома, — запишите это в список покупок.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'Что делают другие мамы? 💬', 'Вы переживаете? Присоединяйтесь к сообществу Anacan и задайте свой вопрос. Поверьте, все мамы проходят через похожие ситуации.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'Успокаивающий голос 📖', 'Сегодня вечером прочитайте малышу короткую сказку просто своим голосом. Ничего больше не нужно — мамин голос обладает самым настоящим волшебством.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'Весёлые игры 🎈', 'Лёжа, малыш двигает ножками в воздухе, будто крутит педали велосипеда? Это его новое развлечение. Присоединитесь к игре и пощекочите его.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'Берегите себя 🥑', 'В послеродовой период кости и зубы становятся более уязвимыми. Не забывайте добавлять в рацион продукты, богатые кальцием. Заботьтесь о себе.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'Сегодня утром малыш всем недоволен? ☁️', 'Возможно, у него скачок роста. Просто чаще обнимайте его и помогите ему почувствовать себя в безопасности.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'Сигналы сонливости 🥱', 'Не ждите, пока малыш начнёт тереть глаза и зевать. Как только его взгляд станет рассеянным, сразу переходите к ритуалу укладывания.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'Что-то не даёт вам покоя? 🤖', 'Вместо того чтобы часами читать форумы, задайте свой вопрос Anacan AI и быстро получите ответ.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'Ровно 4 месяца и 5 дней! 🎂', 'Если у вас есть традиция фотографироваться с тортом, самое время его заказать.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'Терпение на исходе, а руки устали? 👨‍👧', 'Сегодня вечером передайте малыша папе, закройте дверь и побудьте наедине с собой 15 минут.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'Райский беспорядок 🌪️', 'Весь дом завален детскими вещами? Пусть так и будет. Беспорядок дома говорит не о том, что вы плохая мама, а о том, что сейчас ваш главный приоритет — малыш.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'Устали сидеть дома? ☕', 'Устали сидеть дома? В разделе «Места, дружественные мамам» выберите ближайшее кафе, куда удобно зайти с детской коляской.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'Время умных сказок 🪄', 'Создайте в «Умных сказках» особенную историю для этого вечера — о храбром малыше, который спит на облаках.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'Море слюней 🤤', 'Весь воротник промокает за считаные секунды? Дёсны малыша постепенно готовятся к прорезыванию зубов. Силиконовые нагрудники станут лучшими помощниками.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'Свежий воздух — лучшее лекарство 🌳', 'Если малыш сильно беспокоится, сразу выйдите с ним на свежий воздух. Это одно из самых простых и действенных средств от приступов плача.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'Мы — одна команда! 💖', 'После трудного дня сядьте вместе с партнёром и откровенно поговорите о том, что вас беспокоит. Взаимная поддержка помогает разделить нагрузку пополам.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'Сила музыки 🎶', 'Попробуйте успокоить беспричинный вечерний плач с помощью медленной классической музыки. Часто это действительно помогает.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'Старается! 🤸‍♂️', 'Лёжа на животике, малыш пытается приподняться на руках и посмотреть вверх. Его мышцы крепнут с каждым днём — молодец!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'Остановить мгновение 📸', 'Малыш растёт так быстро... Нарядите его и сохраните этот момент навсегда с помощью фотосессии малыша.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'Всё больше смеха 😂', 'На каждое ваше забавное действие малыш отвечает заливистым смехом. Не забудьте снять этот чудесный момент на видео!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'Основа здорового сна ⏱️', 'На четвёртом месяце очень важно наладить правильный режим сна. Старайтесь не нарушать привычный распорядок, чтобы ночи проходили спокойно.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'Всё в порядке ✔️', 'Иногда вам кажется, что вы ничего не успеваете. Но посмотрите: малыш чисто одет и сыт. Вы прекрасно справляетесь!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', 'НЕВЕРОЯТНЫЕ 4 МЕСЯЦА! 🎉', 'Можете поверить? Вы идёте по этому волшебному пути вместе уже целых 120 дней! Сохраните этот момент на память с помощью фотосессии малыша!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'Оглянитесь назад 📈', 'Вспомните свои страхи в первые дни. А теперь посмотрите, какой опытной мамой вы стали. Гордитесь собой!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', 'Отпразднуйте эти 4 месяца.  🥂', 'Сегодня вечером, когда малыш уснёт, не забудьте вместе с партнёром отметить вашу общую победу!'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'Я разговариваю! 🗣️', 'Малыш произносит слоги вроде «ба-ба» и «ма-ма»? Откройте трекер развития, отметьте этот большой скачок в развитии речи и побольше разговаривайте с ним.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'Минута тишины ☕', 'Беспорядок в комнате никуда не денется. Пока малыш играет самостоятельно, просто выпейте кофе и насладитесь тишиной.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'Ваша особенная сказка 🪄', 'Сегодня вечером откройте «Умные сказки», создайте для малыша особенную сказку и прочитайте её.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'Дольше лежит на животике?  🐢', 'Мышцы малыша крепнут с каждым днём. Положите перед ним яркую игрушку, чтобы сделать этот процесс ещё увлекательнее.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'Слюни рекой 🤤', 'Воротничок стал часто намокать? Обязательно держите под рукой силиконовый прорезыватель.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'Контроль громкости 🤫', 'Когда малыш спит, вас пугает каждый звук в доме? Включите шумомер, проверьте уровень шума в комнате и позаботьтесь о спокойном сне малыша.'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'Вы столько всего умеете! 💖', 'Посмотрите в зеркало на свои уставшие глаза и улыбнитесь. Вы растите настоящее чудо без всякой инструкции!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'Пора на прогулку ⛅', 'С помощью инструмента «Погода и одежда» за считаные секунды подберите подходящий по погоде комплект и отправляйтесь дышать свежим воздухом.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'Папины плечи 👨‍👧', 'Сегодня вечером носить малыша по комнате и помогать ему выпустить газы — полностью папина задача.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'Мастер хватания 🧸', 'Малыш уже уверенно хватает подвешенные игрушки? Его моторика развивается замечательно. С любовью наблюдайте за его попытками и поддерживайте его.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'Не переживайте из-за беспорядка дома. 🌪️', 'Ваш приоритет — не идеальный дом, а здоровый и счастливый малыш. Расслабьтесь.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'Есть вопрос? 🤖', 'Запутались в вопросах сна, питания или газов? Не тратьте время на форумах — просто напишите Anacan AI и получите конкретный научно обоснованный ответ.'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'Эмоциональная разрядка 📝', 'День был трудным? Искренне опишите всю свою усталость в дневнике настроения.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'Запасы заканчиваются? 🛒', 'Заканчиваются подгузники или влажные салфетки? Добавьте их в список покупок, пока не забыли, — на телефон вашего партнёра придёт уведомление.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'Звонкий смех 😂', 'Малыш отвечает громким смехом на ваши забавные действия? Обязательно запишите этот смех на видео.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'Поделитесь опытом 💬', 'Думаете: «Неужели я одна такая?» Присоединяйтесь к сообществу Anacan и поделитесь переживаниями с мамами, которые испытывают похожие чувства.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'Сигналы сонливости 🥱', 'Малыш трёт глаза или тянет себя за ухо? Не дожидайтесь переутомления и капризов: сразу затемните комнату и начинайте вечерний ритуал.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'Чемпион по переворотам 🤸‍♂️', 'Малыш пытается переворачиваться со спины на живот и обратно? Никогда не оставляйте его одного на кровати и наслаждайтесь этим активным периодом.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'Вы не обязаны всё успевать. 🌸', 'Для малыша, который смотрит на вас полными любви глазами, вы — самый совершенный человек в мире.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'Новая сказка 📖', 'Пусть этот вечер будет особенным. Создайте в «Умных сказках» историю о русалочке, отправившейся исследовать подводный мир, и наполните комнату волшебством.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'Не голоден — тогда почему плачет? 🧩', 'Малыш не успокаивается, что бы вы ни делали? Перестаньте гадать: дайте функции «Анализ плача» прослушать его плач и сразу узнайте причину.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'Новый мир красок 👀', 'Теперь малыш видит цвета ярче и чётче. Показывайте ему игрушки контрастных цветов.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'Не забывайте о себе 🍲', 'Малыш сыт — теперь ваша очередь. Выберите среди полезных рецептов питательный перекус, который готовится за 10 минут, и позаботьтесь о себе.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'Время папы и малыша 🫂', 'Папам тоже важен телесный контакт с малышом. Вечером оставьте их вдвоём: они смогут укрепить связь, а вы — отдохнуть.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'Регресс сна? 🤖', 'Малыш вдруг стал чаще просыпаться по ночам? Возможно, это связано со скачком развития. Узнайте у Anacan AI о регрессе сна в 4-5 месяцев.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'Он смотрит на меня! 📸', 'В какой бы части комнаты вы ни находились, малыш следит за вами взглядом.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', 'Всего 10 минут 🛀', 'Малыш уснул, и вокруг наконец стало тихо. Вместо того чтобы разгружать посудомоечную машину, встаньте под тёплый душ и 10 минут просто слушайте шум воды.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'Мы — одна команда! 🌟', 'Устали от ночных пробуждений? Не стесняйтесь разбудить папу. Быть командой — значит с любовью разделять заботы.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'Сюрпризы погоды ⛅', 'Собираясь на прогулку, не дайте переменчивой погоде застать вас врасплох и не переохладите малыша. Помощник по погоде и одежде поможет легко выбрать наиболее подходящий вариант для прогулки.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', '«Возьми меня на ручки!» 🛋️', 'Малыш не хочет слезать с ваших рук? Это не каприз — ему нужен ваш родной запах. Крепко обнимите его: эти дни быстро пройдут.'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'Как идёт режим? 📈', 'Проанализируйте статистику за последние дни с помощью трекера кормлений и таймера сна.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'Часто бросает игрушки на пол? 🧸', 'Так малыш изучает причинно-следственные связи. Новые игрушки можно найти в разделе «Рекомендуемые товары».'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'Познаём мир через рот 🦷', 'Малыш активно грызёт всё подряд, особенно собственные пальчики? Трекер прорезывания зубов предупреждает! Пора подготовить чистые прорезыватели.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'Сила поддержки 💬', 'Загляните сегодня вечером в сообщество Anacan и обсудите развитие малышей с мамами, чьи дети того же возраста, что и ваш малыш.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'Гордитесь собой 👏', 'Оглянитесь вокруг и подумайте, какой большой путь вы уже прошли. Страх первых недель сменился настоящей материнской уверенностью. Вы великолепны!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'Пальчики ног во рту 👣', 'Малыш обнаружил свои ножки и пытается засунуть их в рот! Обязательно снимите этот забавный и чудесный момент развития, чтобы поделиться им с близкими.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'Продолжайте считать подгузники! 🧷', 'Отмечайте в Anacan ежедневное количество использованных подгузников, чтобы убедиться, что ваш малыш получает достаточно питания.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'Энергия для мамы 🔋', 'Во время грудного вскармливания ваш организм расходует калории. Прямо сейчас найдите в разделе «Полезные рецепты» лёгкий суп из продуктов, поддерживающих лактацию.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'Следим за ростом и весом! 📏', 'Обновите последние показатели в разделе «Трекер развития» и с гордостью посмотрите на график здорового развития вашего малыша.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'Упорные попытки 🐢', 'Лёжа на животе, малыш пытается ползти вперёд и сердится, когда не получается? Ему уже хочется двигаться! Положите впереди игрушки, чтобы побудить его тянуться к ним.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'Прорезыватели идут в ход! 💧', 'Малышу хочется тянуть всё в рот. Загляните в Блоги, чтобы узнать больше о безопасности и развитии.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'Сегодня никакой уборки 🛑', 'Вы устали? Сообщите об этом партнёру. Сегодня никакой домашней еды и уборки. Сегодня у мамы просто день отдыха!'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'Малыш от вас без ума! 🥰', 'Во время кормления грудью или приёма пищи малыш не сводит с вас глаз? Он изучает черты вашего лица и очень вас любит!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'Немного отдыха 🛋️', 'После трудного дня запишите свои чувства в Дневнике настроения. Помните: изложить всё на бумаге и выговориться — лучший бесплатный психолог.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'Педиатр в вашем кармане 🤖', 'Стул малыша изменил цвет или на теле появилась небольшая сыпь? Прежде чем паниковать, напишите Anacan AI и узнайте о возможных причинах.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'Ручки в деле 👐', 'Малыш пытается одновременно удерживать крупные предметы обеими руками? Отметьте это в Трекере развития и проверьте навык, предложив ему мягкий мячик.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'Малышу холодно или жарко? ⛅', 'Выбор одежды постоянно вызывает трудности? Инструмент погоды и одежды точно подскажет, сколько слоёв надеть на малыша. Не ломайте голову.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'Волшебство маминого голоса 🎶', 'Ни одно приложение не заменит мамину колыбельную. Сегодня вечером просто прижмите малыша к груди и тихо спойте его любимую колыбельную.'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'Чего не хватает дома? 🛒', 'Закончился шампунь или детское масло? Не нужно держать всё в голове. Заполните список покупок, а остальное — задача вашего партнёра.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'Отфильтруйте лишние звуки 🤫', 'Уличный шум мешает глубокому сну. Проверьте уровень шума с помощью шумомера и при необходимости включите белый шум в качестве фона.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'Прекрасная и настоящая 💇‍♀️', 'На вашей одежде могут быть пятна, а волосы — растрёпаны. Но в глазах вашего малыша вы самое прекрасное существо на свете. Не корите себя.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'Налаживаем режим. 🍼', 'Создайте идеальный режим, отслеживая время кормления и бодрствования с помощью инструмента Контроля кормления.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'Папина забота 💖', 'Он тоже работал весь день, но теперь настала папина смена. Понаблюдайте со стороны, как бережно он укладывает малыша спать, и наслаждайтесь этим счастьем.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'Я здесь! 👀', 'Позовите малыша по имени из другого конца комнаты. Вы увидите, как он сразу повернётся на звук и посмотрит на вас. Слух и внимание развиваются превосходно!'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'Интерес к еде? 🍽️', 'Когда вы едите, малыш внимательно смотрит на вашу тарелку и рот? У него постепенно появляется интерес к твёрдой пище (прикорму)!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'Вечерний ритуал — билет на поезд в страну сна.🚂', 'Тёплая ванна, массаж и приглушённый свет в комнате... Никогда не нарушайте этот ритуал.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'Не обедайте на ходу в ежедневной суете. 🥑', 'Приготовьте простой салат по одному из полезных рецептов, сядьте и поешьте с удовольствием.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'Кадр со смехом 📸', 'С каждым днём малыш смеётся всё чаще! Откройте фотосессию малыша и запечатлейте его весёлый смех, который прогонит весь сегодняшний негатив.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'Утешительная сказка 🪄', 'Создайте в «Умных сказках» историю о маленьком герое, которому скоро исполнится 5 месяцев, и наполните комнату уютной атмосферой.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', 'НАВСТРЕЧУ 5-МУ МЕСЯЦУ! 🎂', 'Внимание! Всего через 10 дней наступит важный день — малышу исполнится 5 месяцев! Вы ведь не забыли заказать особенный торт или продумать тематику праздника? Начинайте подготовку уже сейчас!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'Малыш не успокаивается, а вы ужасно устали?  🛑', 'Безопасно положите малыша в кроватку и на 5 минут выйдите в другую комнату. Вы тоже имеете право перевести дух.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'Анализатор звука 😭', 'Вы вернулись в комнату, а малыш снова плачет. Не изматывайте себя! Сразу включите «Анализ плача», определите потребность малыша и помогите ему успокоиться.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'Руки постоянно во рту 🦷', 'Малыш усиленно всё грызёт? Тёплые чистые салфетки помогут успокоить его дёсны.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'Ночные герои 🦸‍♀️', 'Мы знаем, как сильно вас изматывают ночные пробуждения. Запишите в дневнике настроения, что вы устали, и попросите партнёра поддержать вас.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'Ты меня видишь? 🧸', 'Наполовину спрячьте игрушку под одеялом. Малыш ищет и находит её? Это важный шаг в развитии понимания постоянства объектов!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'Прогулка обязательна ⛅', 'Проверьте погоду и рекомендации по одежде, оденьте малыша и погуляйте в парке не менее 20 минут. Это обязательно нужно и вам, и малышу.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'Умный, как врач 🤖', 'В движениях малыша вас что-то настораживает? Вместо того чтобы читать пугающие статьи в интернете, получите точный ответ от Anacan AI.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'Колыбельная от папы 👨‍🍼', 'Включите режим партнёра, чтобы уведомления приходили вашему партнёру. Пусть сегодня он прочитает сказку и споёт колыбельную перед сном, а вы просто наблюдайте.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'Утренний концерт 🎶', 'Малыш смотрит на вас, широко улыбается и произносит разные слоги. Прямо сейчас он даёт самый прекрасный утренний концерт — слушайте внимательно!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'Сомневаетесь насчёт режима сна? 🤖', 'Задайте в Сообществе Anacan свои вопросы об изменениях сна ближе к 5-му месяцу и получите поддержку других мам.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'Контроль шума 🤫', 'К концу четвёртого месяца малышу иногда становится сложнее засыпать. Включите шумомер, проверьте уровень шума и обязательно затемните комнату.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'Вы лучшая! 💖', 'Идеальных людей не бывает, но именно вы — лучшая мама для своего малыша.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'Что делают другие мамы? 💬', 'Беспокоитесь? Присоединяйтесь к Сообществу Anacan. Вам станет легче, когда вы увидите, что другие мамы тоже сталкиваются с бессонными ночами и похожими трудностями.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'Запасы заканчиваются 🛒', 'Закончились подгузники или детское масло? Не забивайте голову мелочами: добавьте всё в список покупок, чтобы ваш партнёр купил по дороге домой.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'Есть вопрос? 🤖', 'В голове тысячи вопросов о развитии малыша? Вместо того чтобы часами читать форумы, напишите Anacan AI и получите краткий, научно обоснованный ответ.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'Следим за подгузниками каждый день. 🧷', 'Отмечайте в Anacan каждую смену подгузника, чтобы убедиться, что малыш получает достаточно питания, и следить за работой его пищеварительной системы.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'Сила взаимной поддержки 🛋️', 'После трудного дня сядьте рядом с партнёром и поговорите по душам. Поддержка друг друга и ощущение, что вы — одна команда, помогут разделить нагрузку пополам.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'Гордитесь собой 👏', 'Оглянитесь назад и вспомните, как вы переживали в первые недели. А теперь посмотрите, как уверенно вы со всем справляетесь! Вы великолепны!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'До вкусных открытий совсем немного! 🥦', 'Подготовьтесь к следующему месяцу: загляните в раздел «Рецепты» и изучите идеи первых пюре для малышей, начинающих прикорм.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'Педиатр в вашем кармане 🤖', 'Режим сна внезапно изменился? Прежде чем тревожиться, узнайте у Anacan AI о регрессе сна в 5 месяцев и получите полезные рекомендации.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'Самостоятельные перевороты 🤸‍♂️', 'Малыш уже легко переворачивается со спины на живот? Положите его на просторный коврик, чтобы он мог свободно двигаться и укреплять мышцы.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'Остановить мгновение 📸', 'Он растёт так быстро... Пока малыш спит, запечатлейте его милые, спокойные черты с помощью функции «Фотосессия малыша» и сохраните эти воспоминания.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'Превращаем ночные пробуждения в привычный ритуал. 😴', 'Не включайте свет при каждом пробуждении. Покормите малыша, используя таймер Anacan, а затем снова уложите под Белый шум.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'Сегодня без уборки 🛑', 'Устали? Скажите об этом партнёру. Сегодня без домашней еды и без уборки. Сегодня у мамы день отдыха и кофе!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'Поговори со мной! 🗣️', 'Малыш внимательно вас слушает и издаёт разные звуки? Он ведёт с вами настоящий диалог. Отвечайте на его звуки и поддерживайте это общение.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'Первые попытки сидеть 🪑', 'Когда вы усаживаете малыша с поддержкой, он держит голову и спину ровнее? Это признак того, что мышцы укрепляются. Начинайте ненадолго усаживать его с поддержкой.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'Побег из четырёх стен ☕', 'Устали сидеть дома? Найдите ближайшее кафе, куда удобно зайти с коляской, и выпейте кофе в новой обстановке.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'Сигналы сонливости 🥱', 'Если малыш трёт глаза и смотрит в одну точку, не ждите капризов. Сразу приглушите свет в комнате и начинайте ритуал укладывания.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'Запаситесь энергией 🍲', 'Если вы здоровы, то и малыш здоров. Выберите среди полезных рецептов вкусный кекс, который придаст вам сил, и насладитесь им за чашкой кофе.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'ВЫ ЗАКАЗАЛИ ТОРТ? 🎂', 'Всего через 5 дней малышу исполнится 5 месяцев! Поторопитесь заказать особый торт или наряд в тематике 5-го месяца!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'Умный сказочник 🪄', 'Сегодня вечером создайте в «Умных сказках» особенную трогательную историю о том, как быстро малыш вырос к 5-му месяцу.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'На пути к самостоятельности 🤸‍♂️', 'Он уже легко переворачивается со спины на живот? Его мышцы быстро развиваются. Регулярно выкладывайте малыша на коврик, чтобы он мог свободно двигаться.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'Отпустите чувство вины 🛑', 'Сегодня у вас закончилось терпение и вы повысили голос? Не вините себя. Вы не неутомимый робот. Завтра вы попробуете снова.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'Вы не одни 💬', 'Загляните в публикации других мам 5-месячных малышей в сообществе Anacan. В каждом доме царят одинаковые хаос, недосып и любовь!'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'Не пропустите сигналы усталости 🥱', 'Малыш смотрит в одну точку отсутствующим взглядом? Сразу отложите все дела. Уложите его спать, пока не закрылось окно сна.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'Прорезыватель спешит на помощь 🦷', 'Малыш пытается всё грызть? Охлаждённые силиконовые прорезыватели быстро успокоят его дёсны.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'Я вас узнаю! 🥰', 'Когда вы входите в комнату, малыш улыбается вам особенно радостно и совсем иначе? Да, он выделяет вас среди всех и обожает ваш запах!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'Уделите время себе 🛋️', 'Когда малыш спит, уделите время не домашним делам, а себе. В комнате может остаться беспорядок, но вам обязательно нужно восстановить силы.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'Магия природы ⛅', 'Малыш сильно беспокоится? Ни одна игрушка не помогает? Проверьте погоду, подберите подходящую одежду и сразу отправляйтесь с ним на прогулку. Природа успокаивает лучше всего.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'Почему он снова плачет? 😭', 'Приступы плача без видимой причины изматывают. Не мучайте себя догадками: воспользуйтесь анализом плача и расшифруйте скрытое послание в голосе малыша.'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'Сила мам 🤖', 'Оглянитесь вокруг и гордитесь тем, какой путь вы прошли за эти 5 месяцев. Если вас что-то тревожит, напишите Anacan AI и получите поддержку.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'ДО ЮБИЛЕЯ ОСТАЛСЯ 1 ДЕНЬ! 🎈', 'Завтра большой день! Готов ли торт в честь 5 месяцев, поглажены ли наряды? Откройте инструмент «Фотосессия малыша» и уже сейчас сделайте пробные снимки!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'Поговорите по душам с партнёром 🥂', 'Сегодня вечером вместе вспомните первые дни и посмейтесь. Вы прошли огромный путь!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'РОВНО 5 МЕСЯЦЕВ! 🎉', 'Невероятно! Уже ровно 150 дней, целых 5 месяцев, вы вместе растите это маленькое чудо. Откройте «Фотосессию малыша» и прямо сейчас сохраните этот особенный день в памяти!'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'Похвалите себя 👏', 'Оглянитесь на все свои записи и графики развития. Посмотрите, как сильно вырос малыш и каким профессионалом стали вы!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'Вечер победы 🪄', 'Сегодня вечером включите в «Умных сказках» добрую историю, наполненную любовью, и вместе с партнёром отпразднуйте вашу общую победу!'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', '10 минут для мамы ☕', 'Беспорядок никуда не денется. Когда малыш уснёт, не спешите сразу браться за дела. Налейте себе чашку горячего кофе и 10 минут просто смотрите на стену.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'Из руки в руку 🧸', 'Малыш умеет перекладывать игрушку из одной руки в другую? Это признак отличной работы полушарий мозга! Отметьте этот важный навык в трекере развития.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'Поделитесь своим настроением 📝', 'Сегодня вы очень устали или полны энергии? Искренне опишите свои чувства в дневнике настроения. Возможность выговориться поможет вам почувствовать себя лучше.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'Сказки в аудиоформате 🪄', 'Давайте сегодня добавим в атмосферу комнаты немного волшебства. Создайте в «Умных сказках» историю о смелом коте, который полетел на Луну, и превратите подготовку ко сну в увлекательное приключение.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'Природное успокоительное ⛅', 'Малыш очень беспокоен и не хочет оставаться дома? Проверьте погоду, подберите подходящую одежду и отправляйтесь в парк. Свежий воздух — лучшее лекарство для вас обоих.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'Тянет в рот всё, что попадается под руку? 🤤', 'Так малыш познаёт мир. Просто следите, чтобы окружающие его предметы были чистыми и безопасными.'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'Код плача 😭', 'Утреннее хныканье вызвано голодом или прорезыванием зубов? Не гадайте: дайте «Анализу плача» прослушать звук и сразу узнайте, что нужно малышу.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'Терпение на исходе?  👨‍👧', 'Пусть сегодня вечером папа полностью возьмёт заботу о малыше на себя, а вы наденьте наушники и отдохните.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'Мы — одна команда! 🌟', 'Чувствуете себя одинокой и непонятой? Сделайте глубокий вдох. Вы — самая сильная героиня этих бурных дней и прекрасно справляетесь.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'Полная тишина 🤫', 'Малышу стало трудно засыпать? Проверьте уровень шума в комнате с помощью шумомера. Выключите звук телевизора и полностью затемните комнату.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'Чешутся дёсны? 🦷', 'Малыш постоянно держит пальцы во рту, и у него обильное слюноотделение? Пора использовать охлаждённые прорезыватели.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'Не забывайте о себе 🥑', 'Пока кормили малыша, сами остались голодной? Выберите среди полезных рецептов питательное блюдо, которое придаст энергии и готовится всего за 10 минут.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'Колыбельная на ночь 🎶', 'Ни один звук не успокаивает так, как мамин голос. Сегодня вечером просто прижмите малыша к груди и тихонько спойте его любимую колыбельную.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'Вся комната завалена игрушками? 🌪️', 'Вся комната завалена игрушками? Не переживайте из-за беспорядка в доме. Вы замечательная мама, и ваш приоритет — малыш, а не уборка.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'Голоден или устал? 🧩', 'Что бы вы ни делали, малыш не успокаивается? Возможно, он просто сильно устал. Воспользуйтесь Анализом плача, чтобы по звуку определить причину.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'Контроль шума 🤫', 'Малыш просыпается от внезапных звуков, когда засыпает? Следите за уровнем шума в комнате с помощью шумомера.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'Мамина энергия 🔋', 'К середине дня у вас совсем не осталось сил? Загляните в раздел полезных рецептов и выберите смузи, который поможет поддержать лактацию и зарядит вас энергией.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'Сила музыки 🎶', 'Попробуйте успокоить беспричинный вечерний плач с помощью медленной классической музыки или белого шума.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'Сюрпризы погоды ⛅', 'Не дайте переменчивой погоде застать вас врасплох и не переохладите малыша на прогулке. Помощник по погоде и одежде подскажет, как одеть его с учётом условий на улице.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'Интерес к еде? 🍽️', 'Пока вы едите, малыш не сводит глаз с вашей тарелки? Появляются признаки готовности к твёрдой пище. Но пока не спешите — дождитесь 6-го месяца.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'Делимся опытом 💬', 'Новое движение малыша удивило вас? Присоединяйтесь к Сообществу Anacan и обсудите это открытие с другими мамами.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'Сказка без конца 📖', 'Сегодня вечером дайте Умным сказкам чудесное задание: история о фее, которая спит на радуге.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'Вы справляетесь! 💖', 'Сегодня всё пошло наперекосяк? Не вините себя. Вы ведь не робот. Примите свои чувства, простите себя и улыбнитесь.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'На пути к полугоду 📈', 'Можете поверить? До конца 6-го месяца осталось совсем немного! Откройте Трекер развития и с гордостью посмотрите, какой невероятный путь вы уже прошли.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'Передайте смену 🛋️', 'Если, когда малыш засыпает, вам тоже хочется рухнуть в кровать, поручите остальные домашние дела партнёру.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'Туман в памяти 📝', 'Забывчивость — часть послеродового периода. Активно пользуйтесь списком покупок, чтобы ничего не упустить.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Разглядывать своё отражение и лепетать — отличное и увлекательное занятие для его умственного развития.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'Разговор по душам 🥂', 'Откройте Дневник настроения, оставьте сегодняшний негатив позади и вместе с партнёром насладитесь тем, что вы — одна команда.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'В поисках прорезывателя 🦷', 'Слюноотделение усиливается, а дёсны зудят всё сильнее. Чистые кольца-прорезыватели — ваши лучшие помощники.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'Ты меня видишь? 🧸', 'Спрячьте игрушку под одеялом. Малыш ищет и находит её? Это замечательный этап развития, который помогает ему понять, что предметы продолжают существовать, даже когда их не видно!'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'Папа — герой ночи 🦸‍♂️', 'Лучшее правило первых месяцев: укладывать малыша спать нужно по очереди! Сегодня вечером малыш на руках у папы, а вы отдыхаете.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'Время прогуляться 🌳', 'Посадите малыша в коляску и выйдите на свежий воздух хотя бы на 15 минут. Воздух нужен вам обоим.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'Утренний концерт 🎶', 'Малыш смотрит на вас, широко улыбается и издаёт новые звуки. Сейчас он даёт лучший концерт в комнате — слушайте внимательно!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'Основа крепкого сна ⏱️', 'Тёплая ванна, массаж и приглушённый свет в комнате... Старайтесь не нарушать ритуал перед сном, чтобы ваши ночи проходили спокойно.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid, 'Умный помощник, почти как врач 🤖', 'Вместо того чтобы читать пугающие новости в интернете, задайте Anacan AI вопросы о введении прикорма и будьте спокойны.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'Разумная тишина 🤫', 'Резкие звуки будят малыша, когда он засыпает? Контролируйте уровень шума в комнате с помощью шумомера.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'Непредсказуемый гардероб 👗', 'То одеваете малыша слишком легко, то слишком тепло? Не сомневайтесь. Проверьте погоду и рекомендации по одежде и уверенно выбирайте подходящий наряд.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'Пир для мамы 🥑', 'В ежедневной суете не обедайте на ходу. Приготовьте простой салат по одному из полезных рецептов, сядьте и поешьте с удовольствием.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'Берегите себя 🛋️', 'Пока малыш спит, уделите время не домашним делам, а себе. Комната может остаться неубранной, но вам необходимо восстановить силы.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'Бросает игрушки на пол и наблюдает? 🎯', 'Так малыш изучает силу притяжения и причинно-следственные связи! Терпеливо возвращайте ему игрушку.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'Вы не одни 💬', 'Волнуетесь? Присоединяйтесь к сообществу Anacan и задайте свой вопрос. Поверьте, все мамы проходят через похожие ситуации.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'Подготовка к прикорму 🥣', 'До 6-го месяца осталось совсем немного. Интересуетесь первыми пюре? Спросите у Anacan AI об основных принципах введения прикорма.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'Сила единства 🥂', 'Сегодня вечером обсудите с партнёром, как вы вместе дошли до этого важного этапа. Вы проделали потрясающую работу как команда.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'ДО ПОЛУГОДИЯ ОСТАЛОСЬ 10 ДНЕЙ! 🎂', 'Готовьтесь! Ровно через 10 дней малышу исполнится 6 месяцев — целых полгода! Самое время заказать праздничный торт и выбрать особый наряд!'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'Сила свежего воздуха 🌳', 'Если малыш сильно капризничает, сразу выйдите с ним на улицу. Свежий воздух — самое простое и действенное средство от приступов плача.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'Мастер хватания 👐', 'Малыш пытается одновременно взять крупный предмет обеими руками? Дайте ему мягкий мяч и понаблюдайте.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'Аудиосказки 🪄', 'Сегодня вечером создайте в «Умных сказках» историю о храбром рыцаре, которому уже исполнилось 6 месяцев.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'Совершенства не существует 🛑', 'Сегодня вам не хватило терпения и вы, возможно, разозлились? Не вините себя. Запишите свои чувства в дневнике настроения, чтобы вам стало легче.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'Колыбельная от папы 👨‍🍼', 'Включите режим партнёра, чтобы уведомления приходили ему. Пусть сегодня вечером он споёт малышу колыбельную перед сном.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'Я ищу тебя! 👀', 'Когда вы выходите из комнаты, малыш ищет вас глазами и плачет? Возможно, постепенно начинает проявляться тревога разлуки. Дайте ему почувствовать себя в безопасности.'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'Приступы плача без понятной причины изматывают. 😭', 'Не изнуряйте себя — воспользуйтесь анализом плача и узнайте, какое послание скрывается в голосе малыша.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', '«Ку-ку» — любимая игра малыша! 🙈', 'Закройте лицо руками, а затем откройте и посмотрите, как обрадуется малыш. Больше подобных игр вы найдёте в разделе «Блоги».'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'Колыбельная на ночь 🎶', 'Ни один звук не успокаивает так, как мамин голос. Сегодня вечером прижмите малыша к груди и тихонько спойте ему.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', '10 минут для мамы ☕', 'Беспорядок в комнате никуда не денется. Когда малыш уснёт, не спешите сразу браться за дела. Налейте себе кофе и просто отдохните 10 минут.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'Отфильтруйте шум 🤫', 'Уличный шум мешает глубокому сну. Проверьте уровень шума с помощью шумомера и при необходимости включите белый шум.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'Зубки уже на подходе? 🦷', 'Нижняя десна болезненная и припухшая? Первые зубки могут появиться примерно в 6 месяцев.'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'Мы — одна команда! 💖', 'На протяжении 6 месяцев вы поддерживали друг друга в бессонные ночи. Откройте дневник настроения и поблагодарите партнёра за вашу слаженную командную работу.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'Стульчик для прикорма 🪑', 'Думаете о покупке стульчика для кормления? Загляните в раздел «Рекомендуемые товары» и присмотритесь к эргономичным моделям, которые легко чистить.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'ДО ПОЛУГОДА ОСТАЛОСЬ 5 ДНЕЙ! 🎈', 'До полугода всего 5 дней! Торт уже заказан? Заранее выберите специальные рамки к 6 месяцам в инструменте для фотосессии малыша и спланируйте съёмку.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'Откройте для себя новую сказку 📖', 'Давайте сделаем этот вечер особенным. Создайте уникальную историю в «Умных сказках» и наполните комнату волшебством.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'Ежедневно следим за содержимым подгузников. 🧷', 'Перед введением прикорма важно убедиться, что пищеварительная система малыша работает нормально. Для этого отмечайте в Anacan каждую смену подгузника.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'Я сижу! 🪑', 'Малыш уже увереннее сидит с поддержкой? Поддержите его подушками и ненадолго предложите посидеть.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'Я ищу вас! 👀', 'Малыш начинает плакать, как только вы выходите из комнаты? Тревога разлуки уже проявляется в полной мере. Он просто боится, что вы больше не вернётесь. Успокойте его своим голосом.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'Изменения в пищеварении. 🧷', 'С введением прикорма стул малыша изменится. Отмечайте каждую смену подгузника в Anacan, чтобы внимательно следить за его состоянием.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'Не ест пюре и выплёвывает его?', 'Не сомневайтесь в своих силах. Для малыша это совершенно новый опыт — наберитесь терпения.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'Аудиосказки 🪄', 'Сегодня вечером создайте сказку в разделе «Умные сказки» и завершите день весело.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'Чешутся дёсны? 🦷', 'В период введения прикорма дискомфорт при прорезывании зубов тоже может усилиться. Используйте гель для дёсен по рекомендации врача.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'Что делают другие мамы? 💬', 'Ваш малыш не любит тыквенное пюре? Присоединяйтесь к сообществу Anacan, чтобы узнать об опыте других мам и найти разные рецепты.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'Сигналы сонливости 🥱', 'Если малыш трёт глаза и смотрит в одну точку, не ждите капризов. Сразу затемните комнату и приступайте к привычному ритуалу перед сном.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'Попытки сидеть без поддержки 🪑', 'Малыш уже меньше опирается на подушки? Совсем скоро он будет сидеть без поддержки!'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'Поделитесь своим настроением 📝', 'Сегодня вы очень устали? Искренне запишите свои чувства в дневнике настроения. Если вы выговоритесь, вам станет легче.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'У него что-то болит или это газы? 😭', 'Переход на прикорм может вызвать запор или повышенное газообразование. Если малыша никак не удаётся успокоить, воспользуйтесь анализом плача, чтобы определить причину по звуку.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'Запасы заканчиваются 🛒', 'Нужны новые овощи для пюре? Добавьте их в список покупок, чтобы ваш партнёр купил свежие продукты по дороге с работы.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'Перекладывание из руки в руку 🧸', 'Малыш уже свободно перекладывает игрушку из одной руки в другую? Полушария его мозга отлично взаимодействуют. Предлагайте ему предметы с разной текстурой.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'Разговоры становятся длиннее! 🗣️', 'Звуки «да-да-да» и «ба-ба-ба» разносятся по всему дому. Посетите раздел «Блоги», чтобы больше узнать о развитии речи малыша.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'Папа — герой ночи 🦸‍♂️', 'Лучшее правило первых месяцев: петь колыбельную нужно по очереди! Сегодня вечером малыш на руках у папы, а вы отдыхаете.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'Забыли, какой грудью кормили? 🤱', 'Отмечайте в таймере правую или левую грудь, а Anacan всё запомнит за вас!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'Разрешайте играть с едой! 🥦', 'Пусть малыш трогает, разминает и исследует еду. Запечатлейте эти милые и немного неряшливые моменты с помощью фотосессии малыша и сохраните их на память!'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'Свежий воздух полезен вам обоим. 🌳', 'Выберите ближайший парк и наслаждайтесь прогулкой.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'Одежда не по погоде 👗', 'Иногда малыш мёрзнет, а иногда вы одеваете его слишком тепло? Не сомневайтесь. Сверьтесь с погодой и рекомендациями по одежде, чтобы уверенно одеть малыша.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'Умная тишина 🤫', 'Внезапные звуки будят малыша, когда он засыпает? Контролируйте уровень шума в комнате с помощью шумомера.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'Я сам схвачу! 🧸', 'Малыш уже уверенно тянется к подвесным игрушкам? Его зрительно-моторная координация улучшается. Поддерживайте его интерес предметами разных цветов.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'Не вините себя 💖', 'Вам кажется, что вы уделяете малышу мало времени? 10 минут радостного и качественного общения ценнее, чем 1 час, проведённый в стрессе.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'Подготовка к глубокому сну 🛀', 'Тёплая ванна, нежный массаж и приглушённый свет в комнате... Ритуал перед сном — золотое правило.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'Посмотрите вниз! 👣', 'Малыш уже обнаружил пальчики на ногах и тянет их в рот! Обязательно понаблюдайте за этим забавным моментом и порадуйтесь его развитию.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'Грудное молоко по-прежнему остаётся основой питания! 🍼', 'Несмотря на введение прикорма, запускайте таймер кормления, чтобы убедиться, что малыш получает необходимое количество молока в течение дня.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'Обмениваемся опытом 💬', 'Ищете рецепты блюд для прикорма? Загляните в раздел «Полезные рецепты» и найдите подходящие варианты.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'Всё больше попыток ползать! 🐢', 'Малыш ползёт назад на животе или пытается встать на четвереньки? Сохраните эти моменты активного развития в Альбоме малыша.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'Время умной сказки 🪄', 'Создайте в «Умных сказках» особенную историю для этого вечера.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'Формируем привычку пить воду. 💧', 'Не забывайте предлагать малышу воду вместе с прикормом.'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'Слюни рекой 🤤', 'Воротничок малыша промокает за считаные секунды? Его дёсны готовятся к прорезыванию зубов. Используйте силиконовые нагрудники.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'Мы — одна команда! 💖', 'После трудного дня сядьте напротив партнёра и поговорите по душам. Взаимная поддержка помогает разделить нагрузку пополам.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'Начался страх незнакомцев? 🙈', 'Если малыш плачет, когда не видит вас или замечает незнакомого человека, это нормальная часть развития. Посоветуйтесь об этом с Anacan AI.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'Быстрые ответы 🤖', 'Что-то не даёт вам покоя? Вместо того чтобы часами читать форумы, задайте вопрос Anacan AI и быстро получите ответ.'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'Превращаем ночные пробуждения в привычный ритуал. 😴', 'Не включайте свет при каждом пробуждении. Покормите малыша, используя таймер Anacan, а затем снова уложите под белый шум.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'Остановить мгновение 📸', 'Он растёт так быстро... Пока малыш спит, запечатлейте его милые, спокойные черты с помощью фотосессии малыша и сохраните эти воспоминания.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'Есть вопросы? 🤖', 'У вас тысячи вопросов о введении прикорма и воды? Напишите в Anacan AI и получите точные рекомендации педиатра.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'Я вас знаю! 🥰', 'Малыш прижимается к вам, когда в дом приходит незнакомый человек? Не волнуйтесь: он просто уже умеет отличать близких от чужих. Это признак здорового умственного развития.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'Поговори со мной! 🗣️', 'Малыш стал отчётливее произносить слоги вроде «ба-ба» и «ма-ма»? Отвечайте на его звуки и поддерживайте это общение.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'Семейный разговор 🛋️', 'После трудного дня сядьте с партнёром лицом к лицу и поделитесь своими переживаниями. Взаимная поддержка помогает разделить груз забот пополам.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'Гордитесь собой 👏', 'Оглянитесь назад и вспомните, как вам было страшно в первые недели. А теперь вы настоящая мастерица по приготовлению пюре!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'Колыбельная на ночь 🎶', 'Ни один звук не успокаивает так, как мамин голос. Сегодня вечером просто прижмите малыша к груди и тихонько спойте ему.'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'Первые попытки ползать! 🐢', 'Малыш вертится на животе, ползёт назад или пытается встать на колени? Сразу добавьте эти моменты активного развития в Альбом малыша.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'Сомневаетесь, всё ли в порядке с развитием? 🤖', '«Мой малыш всё ещё не ползает — это нормально?» Задайте этот и другие вопросы Anacan AI и получите ответ специалиста.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'Открываем новые вкусы! 🍎', 'Какой фрукт или овощ вы попробуете сегодня? Обязательно загляните в Рецепты для малышей, начинающих прикорм, чтобы найти вдохновение.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'Сказка никогда не заканчивается 📖', 'Сегодня вечером создайте в Умных сказках историю о смелом и умном ребёнке.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'Большой любитель поесть 🥣', 'Малыш уже с удовольствием ест пюре? Он растёт!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'Утренний концерт 🎶', 'Малыш смотрит на вас и придумывает разные слоги. Прямо сейчас он даёт лучший утренний концерт в комнате — слушайте внимательно!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'Умный, как доктор 🤖', 'После перехода на твёрдую пищу стул малыша изменился? Вместо того чтобы волноваться, спросите у Anacan AI, нормально ли это.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'Основа здорового сна ⏱️', 'Тёплая ванна, массаж и приглушённый свет... Старайтесь не нарушать ритуал отхода ко сну, чтобы ваши ночи проходили спокойно.'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'Папины плечи 👨‍👧', 'Терпение на исходе? Включите режим партнёра. Пусть сегодня вечером малышом полностью займётся папа.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'Остались вопросы? 🤖', 'С какого овощного пюре начать прикорм? – Задайте этот и другие волнующие вас вопросы Anacan AI и получите точную информацию.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'Водопад слюней 🤤', 'Одежда на груди стала часто намокать? Подготовьте силиконовые прорезыватели.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'Контроль децибелов 🤫', 'Когда малыш спит, вас пугает каждый звук в доме? Включите шумомер и проверьте акустику комнаты.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'Беспорядок дома — счастливый малыш 🌪️', 'Вся комната завалена игрушками? Весёлые 10 минут, проведённые с малышом, важнее уборки.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'Самостоятельные перевороты 🤸‍♂️', 'Малыш уже уверенно переворачивается со спины на живот и обратно? Отметьте эту победу в трекере развития!'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'Сигналы сна 🥱', 'Малыш трёт глаза? Не ждите капризов от переутомления: сразу затемните комнату и начинайте вечерний ритуал.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'Энергия для мамы 🍲', 'Вам понадобятся силы для завтрашнего праздника. Выберите сытный перекус среди полезных рецептов и отдохните.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'ПОСЛЕДНИЕ ПРИГОТОВЛЕНИЯ! 📸', 'Завтра важный день! Торт в честь полугодия готов? Подготовьте самые красивые наряды для фотосессии малыша — завтра будем много фотографироваться!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', 'РОВНО 6 МЕСЯЦЕВ! ПОЛГОДА! 🎉', 'Поздравляем! Вы растите это чудо уже ровно 180 дней. Прямо сейчас создайте в фотосессии малыша особенное фото в честь этого дня и поделитесь им в Сообществе Anacan!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'Похвалите себя 👏', 'Оглянитесь на все свои записи. Посмотрите, как вырос малыш и каким профессионалом стали вы! Вы отличная команда.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'Вечер победы 🥂', 'Сегодня вечером, когда малыш уснёт, сядьте рядом со своим партнёром. Почувствуйте гордость за эти 180 дней и обнимите друг друга!'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'Новый этап: прикорм! 🥣', 'Малышу исполнилось 6 месяцев! Пора знакомиться с овощными пюре. Узнайте у Anacan AI о правиле 3 дней для проверки на аллергию.'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'Полная тишина 🤫', 'Малышу стало сложнее засыпать? Проверьте уровень шума в комнате с помощью шумомера и полностью затемните её.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'Одежда в пятнах 👗', 'Прикорм означает, что пачкаться будет всё вокруг. Не расстраивайтесь: используйте силиконовые нагрудники и наслаждайтесь этими забавными моментами.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'Сюрпризы погоды ⛅', 'Собираясь на прогулку, не дайте погоде себя обмануть и не замёрзните. Воспользуйтесь помощником по погоде и одежде, чтобы выбрать подходящий вариант для улицы.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'Пытается! 🤸‍♂️', 'Лёжа на животе, малыш пытается продвигаться вперёд. Его мышцы крепнут с каждым днём — положите перед ним игрушку, чтобы мотивировать его.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'Сила музыки 🎶', 'Если ближе к вечеру малыш начинает плакать без видимой причины, попробуйте успокоить его медленной классической музыкой.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'Основа здорового сна ⏱️', 'Очень важно наладить правильный режим сна. Старайтесь не нарушать привычный распорядок, чтобы ваши ночи проходили спокойно.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', 'ДО 200 ДНЕЙ ОСТАЛСЯ 1 ДЕНЬ! 🎂', 'Завтра малышу исполнится 200 дней! Вы уже придумали, как отметить эту большую и прекрасную дату? Начинайте подготовку!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'Всё в порядке ✔️', 'Иногда вам кажется, что вы ничего не успеваете. Но посмотрите на чистую одежду малыша и его сытый животик. Вы прекрасно справляетесь!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'Оглянитесь назад 📈', 'Вспомните свои страхи в первые дни. А теперь посмотрите, какой опытной мамой вы стали и как уверенно вводите прикорм. Гордитесь собой!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', 'НЕВЕРОЯТНЫЕ 200 ДНЕЙ! 🎉', 'Можете поверить? Вы идёте по этому волшебному пути вместе уже ровно 200 дней! Сделайте этот момент праздничным с помощью специального стикера на фотосессии малыша и поделитесь снимком в Сообществе!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', 'Насладитесь гордостью за эти 200 дней. 🥂', 'Сегодня вечером, когда малыш уснёт, не забудьте вместе с партнёром отметить эту большую победу вашей команды!'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'ГОТОВИМСЯ К ПРАЗДНИКУ! 🎂', 'Всего через 9 дней малышу исполнится 7 месяцев! Вы уже придумали необычную тематику или особенный торт для этого месяца? Начните подготовку заранее, чтобы не откладывать всё на последний день.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'Руки свободны 👐', 'Лёжа на животе, малыш тянется к игрушке одной рукой, опираясь на другую? Баланс мышц становится всё лучше!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'Папино время 👨‍👧', 'Сегодня ненадолго передайте родительскую эстафету партнёру. Пусть они поиграют, а вы просто вытяните ноги и отдохните.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'Не забывайте о себе 🍲', 'Малыш съел своё пюре, а вы поели? Чтобы восстановить силы, вам необходимо полноценно питаться. Сегодня закажите для себя сытное блюдо.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'Я тебя знаю 👀', 'Когда в дом приходят гости, малыш прижимается к вам и настороженно смотрит на них? Так проявляется тревога разлуки. Просто рядом с мамой он чувствует себя в безопасности — отнеситесь к этому с пониманием.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'Ваша особенная сказка 🪄', 'Сегодня вечером предложите инструменту «Умные сказки» милую тему: «История самой милой звёздочки, упавшей с неба». Пусть в комнате звучит только эта сказка.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'Ночные пробуждения 🌙', 'В преддверии прорезывания зубов малыш стал часто просыпаться по ночам? Наберитесь терпения: боль в дёснах беспокоит его. Дайте ему почувствовать, что вы рядом.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'Попытки ползать 🐢', 'Малыш встаёт на четвереньки и раскачивается вперёд-назад? Он готовится ползать!'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'Минута тишины ☕', 'Беспорядок в комнате никуда не денется. Пока малыш играет самостоятельно, не спешите сразу же наводить порядок. Присядьте на диван и 10 минут ничего не делайте.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'Исследуем дёсны 🦷', 'Малыш всё усиленно грызёт, а слюни текут рекой? Следите за процессом в трекере прорезывания зубов. Охлаждающие прорезыватели станут настоящим спасением в эти дни.'),
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e', 'Мы — одна команда! 💪', 'Чувствуете себя одинокой и уставшей? Сделайте глубокий вдох. Вы и ваш партнёр — самые сильные герои этих непростых дней.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'Погода и одежда ⛅', 'Не ломайте голову над тем, как одеть малыша на прогулку. Загляните в раздел «Погода и одежда», за считаные секунды подберите идеальный комплект и отправляйтесь на свежий воздух.'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'Голосовые сказки 🎶', 'Ни одно приложение не заменит мамину колыбельную. Сегодня вечером просто прижмите малыша к груди и тихонько спойте его любимую колыбельную.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'Фестиваль пюре 🥣', 'Пюре оказалось на лице, носу и даже волосах? Вместо того чтобы расстраиваться, сохраните этот милый момент с помощью функции «Фотосессия малыша».'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'Не мучайтесь чувством вины 💖', 'Вам кажется, что вы уделяете малышу мало времени или не успеваете справляться с домашними делами? Перестаньте себя винить. Вы прекрасно справляетесь.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'Полная тишина 🤫', 'Малышу трудно заснуть? Полностью затемните комнату и устраните все звуки. Темнота и тишина — его лучшие помощники для сна.'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'Изменился цвет стула? 💩', 'После введения прикорма стул может приобретать разные цвета, и это нормально. Но если вы беспокоитесь, узнайте возможную причину у Anacan AI.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'Чувствовать истощение — нормально 🔋', 'Когда терпение на исходе, не считайте себя плохой мамой. Такая усталость естественна.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', 'ДО 7 МЕСЯЦЕВ ВСЕГО 3 ДНЯ! 🎂', 'Торт уже заказан? Наряд выбран? До семимесячной даты осталось совсем немного. Запланируйте небольшую домашнюю фотосессию, чтобы отметить это прекрасное событие!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Наблюдать, как он с удивлением рассматривает своё отражение и улыбается, — прекрасное и успокаивающее занятие.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'Папина очередь 👨‍🍼', 'Сегодня вечером купание малыша и подготовка ко сну — папина задача.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'Я вас слышу 🗣️', 'Малыш внимательно вас слушает и пытается произносить похожие слоги (ма-ма, ба-ба)? Он разговаривает с вами! Отвечайте ему, щедро одаривая улыбками.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'Время прогуляться 🌳', 'Посадите малыша в коляску и отправляйтесь на 20-минутную прогулку на свежем воздухе. Это пойдёт на пользу вам обоим.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'Ночной герой 🦸‍♂️', 'Устали от ночных пробуждений? Не стесняйтесь разбудить папу. Быть командой — значит поровну делить нагрузку.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'Сидение без поддержки 🪑', 'Малыш уже может хотя бы недолго сидеть прямо без подушек? Подстраховывайте его и внимательно наблюдайте за развитием мышц.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'Не обедайте на ходу и в спешке. 🥑', 'Приготовьте себе вкусный салат и уделите хотя бы 15 минут только себе.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'Подготовка к глубокому сну 🛀', 'Тёплая ванна, нежный массаж и приглушённый свет в комнате... Соблюдение ритуала перед сном — секрет спокойных ночей без пробуждений.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', 'РОВНО 7 МЕСЯЦЕВ! 🎉', 'Невероятно! Вот уже ровно 7 месяцев вы вместе растите это чудо. Сохраните этот день в разделе «Фотосессия малыша» и поделитесь снимком в Сообществе!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'Завершение прекрасного дня. ✨', 'Вы очень сильная мама! Напишите в Дневнике настроения, что гордитесь собой, расслабьтесь под Белый шум и насладитесь спокойным сном.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'Оглянитесь назад 📈', 'Вспомните, как неопытны вы были в первые дни. А теперь посмотрите, какой уверенной мамой вы стали. Гордитесь собой!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'Список — настоящее спасение 🛒', 'Забыли что-то в повседневной суете? Не перегружайте себя: внесите всё необходимое для дома в Список покупок.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'Следим за пищеварением. 🧷', 'Твёрдая пища меняет стул малыша. Отмечайте каждую смену подгузника в Anacan, чтобы анализировать реакцию малыша на новые продукты.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'Голоден или устал? 😭', 'Малыш плачет без видимой причины, а его плач звучит непривычно? Не волнуйтесь. Сразу включите запись для Анализа плача и узнайте причину.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'Меры безопасности дома! 🛡', '️ Чем активнее он становится, тем больше опасностей его окружает. Загляните в наш список Рекомендованных товаров, чтобы выбрать детские блокираторы и защитные накладки на углы.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'Пора переходить на еду кусочками? 🥦', 'Малыш уже хочет брать еду самостоятельно? Безопасные варианты вы найдёте в Рецептах для малышей, начинающих прикорм.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'Упражнения для ползания! 🐢', 'Малыш ползёт назад на животе или пытается встать на колени? Спросите у Anacan AI о полезных упражнениях, которые помогут ему научиться ползать.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'Грудное молоко всё ещё остаётся основой питания! 🍼', 'Несмотря на введение прикорма, запускайте таймер кормления, чтобы убедиться, что малыш получает достаточно молока в течение дня.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'Источник энергии для мам! 🥗', 'Вам тоже важно питаться правильно! Приготовьте по одному из Полезных рецептов витаминный салат или смузи, который зарядит вас энергией.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'Успокаивающий голос 📖', 'Сегодня вечером прочитайте малышу короткую сказку своим голосом. Голос мамы — самая любимая музыка для малыша.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'Сигналы сонливости 🥱', 'Не ждите, пока малыш начнёт тереть глаза и зевать. Как только его взгляд станет рассеянным, сразу переходите к ритуалу перед сном.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'Повторение первых слогов 🗣️', 'Малыш часто повторяет звуки вроде «да-да», «ба-ба»? Так он тренирует речевой аппарат. С улыбкой повторяйте за ним каждый слог, чтобы он учился вести диалог.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'Вопросы к педиатру 🤖', 'Нормально ли, что к 8-му месяцу нарушается режим сна? Вместо многочасовых поисков в интернете узнайте у Anacan AI конкретные научные факты о регрессе сна в 8 месяцев.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'Вечерняя мелодия 🎶', 'Если малыш сопротивляется укладыванию, включите в комнате спокойную классическую музыку. Её звучание поможет мягко успокоить его перевозбуждённую нервную систему.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'Начало сюжетных игр 🧸', 'Малыш пытается напоить игрушечного мишку или куклу? У него развивается воображение и начинаются символические игры. С удовольствием наблюдайте со стороны за этим милым режиссёром.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'Не обедайте на ходу в ежедневной суете. 🥑', 'Вы делаете всё, чтобы накормить малыша. А как же вы сами? Приготовьте для себя отдельную сытную тарелку еды, богатой железом.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'Делимся сокровенным 💬', 'Переживаете: «Почему мой малыш ещё не ползает?» Прямо сейчас зайдите в Сообщество Anacan. Читайте реальные истории тысяч мам или задайте свой вопрос — и убедитесь, что каждый ребёнок уникален.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'Тревога разлуки 🥺', 'Малыш плачет вам вслед, когда вы выходите из комнаты? Ему кажется, что вы больше не вернётесь. Спокойно повторяйте: «Я всегда рядом», чтобы ваш голос дарил ему чувство безопасности.'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'Дёсны всё ещё чешутся 🦷', 'Малыш усиленно всё грызёт, и у него текут слюни? Охлаждённые в морозильной камере прорезыватели станут настоящим спасением в эти дни.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'Папина ответственность 👨‍🍼', 'Не берите все ночные пробуждения исключительно на себя. Будите и партнёра, ведь быть командой — значит поровну делить эту ответственность.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'Я тебя нашёл! 🙈', 'Малыш звонко смеётся, когда вы закрываете лицо руками и играете в «ку-ку»? У него активно формируется понимание постоянства объектов. Сделайте эту игру частью вашего ежедневного распорядка.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'Стойкие пятна 👗', 'Период введения прикорма означает постоянные пятна дома и на одежде. Не расстраивайтесь из-за этого. Пользуйтесь силиконовыми нагрудниками и просто наслаждайтесь этими забавными, яркими моментами.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'Перестаньте себя винить. 🛑', 'Сегодня малыш слишком долго смотрел на экран или дома остался беспорядок? Вы просто устали и делаете всё, что в ваших силах.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'Игра в бросание предметов на пол 🥄', 'Малыш бросает игрушку со стульчика для кормления и ждёт, пока вы её поднимете? Так он изучает силу притяжения и причинно-следственные связи. Наберитесь терпения и улыбнитесь.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'Привыкаем к темноте 🌙', 'Чтобы малыш быстрее заснул, выключите в комнате все лишние источники света и экраны. Выработка гормона мелатонина ускоряется только в спокойной и тёмной обстановке.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'Капризные утра ☁️', 'Малыш начинает плакать обо всём, едва открыв глаза, и ничем не доволен? Возможно, он как раз переживает скачок роста. Чаще обнимайте его и дарите чувство безопасности.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'Не спешите разгружать посудомоечную машину, как только малыш уснёт! 🛋️', 'Прилягте на диван, закройте глаза и на 15 минут растворитесь в этой редкой, абсолютной тишине дома.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', '10 минут для мамы ☕', 'Как только малыш уснёт, не спешите заниматься домашними делами. Присядьте на диван, выпейте кофе и просто 10 минут смотрите перед собой и спокойно дышите.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'Капризное утро ☁️', 'Сегодня утром малыш всем недоволен? Возможно, у него режутся зубы или происходит скачок развития. Просто чаще обнимайте его и дайте почувствовать себя в безопасности.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'Игра на постоянство объектов! 🧸', 'Спрячьте игрушку под покрывалом и позвольте малышу найти её. Пока вы играете в эту развивающую игру, запечатлейте его радость с помощью Фотосессии малыша.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'Детские вещи по всему дому? 🌪️', 'Детские вещи разбросаны по всему дому? Пусть. Беспорядок дома говорит не о том, что вы плохая мама, а о том, что ваш малыш сейчас для вас важнее всего.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'Звуковая терапия от беспокойства 🎶', 'Если этим вечером малыш не может уснуть из-за возбуждения от новых навыков, включите в разделе Белого шума звуки материнской утробы.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', 'Кризис «Это моё!» 🛑', 'Малыш сердится, когда вы забираете у него опасный предмет? Вместо строгого запрета переключите его внимание на другую, более яркую и звучную игрушку — это поможет мягко пережить такие маленькие кризисы.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'Произведение искусства на тарелке 🥦', 'Малыш не ест пюре? Иногда дело не во вкусе, а во внешнем виде. Используйте полезные рецепты и создавайте забавные рожицы из разноцветных овощей, чтобы пробудить его аппетит.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'Чуткий сон 🤫', 'Малыш вздрагивает от малейшего стука, едва заснув? Проверьте акустику комнаты с помощью шумомера и включите белый шум, чтобы заглушить звуки, доносящиеся из окна.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'Папин голос 📖', 'Давайте сегодня вечером создадим в комнате особую атмосферу. Придумайте в Умных сказках историю о храбром лесном обитателе, а прочитать её доверьте папе — его низкий, уверенный голос подарит малышу чувство безопасности.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'За пределы четырёх стен ☕', 'Домашняя рутина начинает вас утомлять. Добавьте сегодня немного разнообразия.  Выберите поблизости кафе, куда удобно зайти с детской коляской, и насладитесь чашечкой кофе.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'Ваш малыш развивается с каждым днём🤏', 'Он пытается захватить большим и указательным пальцами даже самое крошечное пятнышко или крошку на полу? Мелкая моторика развивается полным ходом!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'Покорение мебели 🧗‍♂️', 'Малыш хватается за диван или стул и подтягивается вверх? Мышцы его ног готовятся к самостоятельному стоянию. Обеспечьте безопасность, но не мешайте этим маленьким альпинистским попыткам.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'Ночная буря 😭', 'Малыш без видимой причины проснулся среди ночи с плачем? Определите причину с помощью Анализа плача и помогите ему успокоиться.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'Не перегружайте себя 🛒', 'Из-за недосыпа ухудшилась память, и в магазине вы забываете, что нужно купить? Запишите всё в Список покупок, чтобы ваш супруг купил необходимое по дороге домой.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'Природа — лучшее лекарство ⛅', 'Малыш очень беспокоен, и его ничем не удаётся отвлечь? Откройте инструмент «Погода и одежда», оденьте его по погоде и сразу отправляйтесь на 20-минутную прогулку в парк.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'Тихие слёзы 📝', 'Сегодня всё навалилось разом, и вам хочется плакать? Это совершенно естественно... Запишите всю свою усталость в Дневник настроения. Если вы дадите волю чувствам, вам станет легче.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'Командное собрание 🥂', 'Вы пережили трудный день. Когда малыш уснёт, налейте себе чаю вместе с партнёром и не забудьте поблагодарить друг друга, сказав: «Мы действительно отличная команда».'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'Друг в зеркале 👀', 'Поднесите малыша к зеркалу. Понаблюдайте, как он с удивлением рассматривает своё отражение и пытается к нему прикоснуться. Это замечательное занятие для развития самосознания.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'Быстро пополнить запасы 🛒', 'Детское масло или влажные салфетки заканчиваются? Список покупок уже ждёт вас в приложении. Запишите туда всё необходимое, чтобы партнёр купил это по дороге с работы.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'Сюрпризы погоды ⛅', 'Собираясь на прогулку, не дайте переменчивой погоде застать вас врасплох, чтобы малыш не замёрз. Не судите о погоде только по виду из окна — помощник по погоде и одежде поможет вам точно подобрать подходящий наряд для малыша.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'Я буду есть сам! 🥦', 'Малыш уже не хочет есть пюре с ложки, а предпочитает брать овощи руками? Поддержите его самостоятельность. Да, вокруг станет грязно, зато это поможет его развитию.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'Волшебный мир сказок 🪄', 'Сегодня вечером попробуйте что-нибудь совершенно новое в «Умных сказках». Подстраивайте тон голоса под ритм повествования.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'Маленький исследователь 👣', 'Малыш уже обнаружил пальчики на своих ногах и пытается тянуть их в рот!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'Ночная смена папы 👨‍🍼', 'Вы и так достаточно устали за день. Поручите папе вечернюю подготовку малыша ко сну и переодевание в пижаму, а сами просто наблюдайте со стороны.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'Есть вопрос? 🤖', 'К 8-му месяцу вас беспокоит график роста и веса малыша? Вместо чтения пугающих статей в интернете попросите Anacan AI составить точную и научно обоснованную таблицу.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'Восстановите силы 🍲', 'Усталость пробирает до костей? Выберите среди полезных рецептов особый смузи, который готовится за 10 минут, поддержит лактацию и поможет вам взбодриться.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'Отфильтруйте шум 🤫', 'Первые полчаса после засыпания — самый чуткий период сна. Проверьте обстановку с помощью шумомера и постарайтесь исключить внезапные звуки из соседней комнаты или телевизора.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'Ползком к цели 🐢', 'Малыш уже выбирает цель и быстро ползёт к ней. Немедленно уберите с пола все мелкие и опасные предметы, которые он может проглотить.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'Обмен опытом 💬', 'Новое действие малыша, например удары головой о стену, напугало вас? Напишите в Сообщество Anacan и узнайте, как другие мамы проходили через этот этап.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'Смелые шаги 🧗‍♂️', 'Малыш держится за диван и пытается отпустить одну руку? Его чувство равновесия стремительно развивается. С улыбкой наблюдайте за этими бесстрашными попытками со стороны, оставаясь рядом, чтобы подстраховать.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'Дайте волю чувствам 📝', 'Вы чувствуете себя очень одинокой и непонятой? Это совершенно естественно. Откровенно запишите свои чувства в дневнике настроения, ничего не скрывая.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'Домашний хаос 🌪️', 'Вся комната завалена игрушками? Весёлые 10 минут, проведённые с малышом, важнее уборки. Игрушки никуда не денутся до завтра — не изматывайте себя.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', 'Готовимся к 8 месяцам! 🎂', 'Внимание! Всего через 10 дней малышу исполнится ровно 8 месяцев! Посмотрите в трекере развития, какой путь вы уже прошли. Уже сейчас подумайте о том, чтобы заказать в Anacan небольшой торт к этому мини-юбилею.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'Засыпаем под музыку 🛀', 'Вечерние ритуалы стали даваться сложнее? Включите спокойную музыку, пока малыш принимает тёплую ванну. Гармония воды и мелодии успокоит даже самого упрямого непоседу.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'Капризы без видимой причины изматывают. 😭', 'Капризы без видимой причины изматывают. Перестаньте гадать: воспользуйтесь Анализом плача, чтобы сразу распознать скрытое послание за звуками — боль или усталость.'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'Время выйти на прогулку 🌳', 'Четыре стены давят на вас. Посадите малыша в коляску и выйдите подышать свежим воздухом хотя бы на 20 минут. Спокойствие природы благотворно повлияет и на малыша, и на ваше эмоциональное состояние.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'Указательный пальчик ☝️', 'Малыш показывает пальцем на предмет вдали и смотрит на вас? Так он говорит: «Посмотри на меня» или «Я хочу это». Это большой скачок в развитии общения! Назовите ему этот предмет.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'Колыбельная на ночь 🎶', 'Ни одно приложение и ни один звук не заменят мамину колыбельную. Сегодня вечером просто прижмите малыша к груди и тихонько спойте его любимую колыбельную, которая дарит ему чувство безопасности.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'Хлопаем в ладоши 👏', 'Малыш выражает радость, хлопая в ладоши? Как только заметите это замечательное достижение в развитии моторики, устройте дома маленький победный танец и присоединитесь к нему!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'Список — не пожелание, а необходимость 🛒', 'Не забудьте украшения для праздника в честь 8 месяцев! Не перегружайте себя: сразу внесите всё в Список покупок и согласуйте дела с партнёром.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'Знакомые лица 🥰', 'Заметили эту широкую, особенную улыбку на лице малыша, когда вы входите в комнату? Он отличает вас и вашего партнёра от всех остальных. Его безусловная любовь — самая сильная мотивация.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'Папины забавные гримасы 🤡', 'Самый быстрый способ рассмешить малыша — папины забавные звуки и гримасы. Сегодня вечером отдыхайте в сторонке, слушая звонкий смех.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'Не теряйтесь на форумах 🤖', 'Сомневаетесь, можно ли давать малышу тот или иной продукт прикорма? Не тратьте часы на поиски — пусть Anacan AI ответит на ваши вопросы, словно цифровой педиатр у вас в кармане.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'Место для мамы ☕', 'Силы на исходе из-за постоянного пребывания дома? Выберите среди Мест для мам тихое кафе, где удобно разместиться с детской коляской, и устройте небольшое свидание с самой собой.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'Исследование мусора 🗑️', 'Малыш с огромным интересом изучает всё, что находит на полу или у края ковра. Не сердитесь и не отбирайте у него всё подряд — он исследователь. Просто следите, чтобы рядом не было предметов, которые можно проглотить.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'Сегодня в Умных сказках 🪄', 'Создайте в Умных сказках историю о большом герое, которому всего через несколько дней исполнится 8 месяцев. Пусть тишину ночи наполнит только эта волшебная история.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', 'До 8 месяцев осталось 5 дней! 🎈', 'Волнение нарастает! Всего через 5 дней малышу исполнится 8 месяцев! Если вы хотите заказать особенный торт или продумать концепцию праздника, не откладывайте это на последний день.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'Тишина и кофе 🤫', 'Малыш уснул! Вместо того чтобы разгружать стиральную машину, посидите в полумраке комнаты. Включите шумомер, чтобы контролировать обстановку, и насладитесь 15 минутами тишины.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'Совершенства не существует 🛑', 'Сегодня всё пошло не по плану? Не вините себя. Вы настоящая мама, а не отфильтрованная иллюзия из социальных сетей. Вашему малышу нужны только вы.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'Освободитесь от эмоционального груза 📝', 'День был трудным? Выплесните накопившееся, записав весь сегодняшний негатив и стресс в дневник настроения. Все мамы переживают такие кризисы, и вы вовсе не одиноки.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'Разведка погоды ⛅', 'Погода за окном кажется непонятной? Инструмент погоды и одежды мгновенно подскажет скорость ветра, которую не видно из окна, и подходящий комплект одежды — отправляйтесь на прогулку без сомнений.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'Не отдам мою игрушку! 🧸', 'Малыш протестует и громко плачет, когда у него что-то забирают? У него развивается чувство собственности и индивидуальности. Это совершенно естественный психологический этап — не пытайтесь с ним бороться.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'Здоровая мама — здоровый малыш 🥑', 'Ваши запасы железа и кальция истощились. Побалуйте себя быстрым в приготовлении, питательным и заряжающим энергией блюдом из раздела полезных рецептов.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'Юный любитель книг 📖', 'Малыш самостоятельно перелистывает страницы книг из плотного картона и реагирует на картинки? Его зрительная память отлично работает. Читайте вместе и называйте животных на картинках.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'Кадр, останавливающий время 📸', 'Когда малыш будет увлечённо играть в комнате, сразу откройте «Фотосессию малыша» и сохраните в памяти его изменившееся, повзрослевшее личико в преддверии 8-го месяца, выбрав особую тему.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'Хочется поговорить по душам 💬', 'Мысль «Не могу поверить, что ему уже скоро 8 месяцев» вызывает у вас прилив эмоций? Поделитесь этим прекрасным и трогательным чувством с мамами в Сообществе Anacan.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'Метод проб и ошибок 🧱', 'Малыш пытается поставить два игрушечных кубика друг на друга, но они падают. Он внимательно пробует снова. Молча и с гордостью наблюдайте за этими маленькими инженерными экспериментами.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин быстро вырабатывается только в спокойной обстановке с приглушённым освещением.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'Кто займётся домашними делами? 🌪️', 'Остались дела перед завтрашним маленьким праздником? Пусть остаются. Попросите своего партнёра сегодня взять домашние заботы на себя. А вы отдохните перед завтрашним днём.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, сделайте друг другу массаж плеч, чтобы вместе с партнёром снять накопившийся за день стресс. Обязательно наберитесь сил перед завтрашней прекрасной победой!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'Завтра уже 8 месяцев! 📸', 'Вы готовы? Завтра важный день! Ровно 8 месяцев! Освободите память телефона — завтра понадобится много места для «Фотосессии малыша». Одежду погладьте уже сегодня.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'Танец победы 🥂', 'Сегодня вечером отметьте вместе с партнёром усталость, слёзы и радость этих 8 месяцев. Поставьте на стол свечу и поздравьте друг друга с победой вашей нерушимой команды!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'Оглянитесь назад 📈', 'Какой огромный путь прошёл ваш малыш! Хрупкий страх первых дней теперь сменился колоссальной уверенностью. Вы с огромной гордостью прошли эти 8 месяцев! Вы действительно великолепны!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', 'Великолепные 8 месяцев! 🎉🎂', 'ПОЗДРАВЛЯЕМ! Вы уже ровно 240 дней вместе идёте по этому удивительному пути! Малышу исполнилось ровно 8 месяцев. Непременно устройте праздник в честь этого особенного дня и с гордостью поделитесь им в Сообществе Anacan!'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'Кричит, когда у него забирают игрушку?🧸', 'Чувство собственности становится сильнее. Это важная часть формирования характера.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'Грудное молоко по-прежнему остаётся основой! 🍼', 'Несмотря на введение прикорма, запустите таймер кормления, чтобы убедиться, что малыш получает необходимое количество молока в течение дня.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'Читайте книги вместе! 📖', 'Книги со звуками и яркими картинками очень привлекают его внимание. Сделайте развивающие минуты чтения ещё интереснее с помощью рекомендаций в Блогах.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'Забыли, какой грудью кормили? 🤱', 'Таймер Anacan запомнит за вас, какой грудью вы кормили — правой или левой. Запустите таймер кормления прямо сейчас!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'Формируем привычку пить воду. 💧', 'Не забывайте предлагать воду вместе с прикормом. Подходящие поильники вы найдёте в Рекомендуемых товарах.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'Иди ко мне 👏', 'Малыш хлопает в ладоши или протягивает к вам руки? Это прекрасный способ общения. Обнимите его.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'Остановить мгновение 📸', 'Он растёт так быстро... Пока малыш спит, сфотографируйте его милое, безмятежное личико на память.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'У вас есть вопрос? 🤖', 'В голове тысячи вопросов о развитии малыша? Напишите ИИ Anacan и получите точные рекомендации педиатров.'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', 'Готовимся к 250-му дню! 🌟', 'Завтра вас ждёт большая дата! Ровно 250 дней! Создайте дома небольшую праздничную атмосферу и приготовьтесь с гордостью отметить этот день.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'Сегодня никакой уборки 🛑', 'Устали? Скажите об этом партнёру. Сегодня без домашней еды. Сегодня у мамы выходной!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'У сказки нет конца 📖', 'Сегодня вечером создайте в Умных сказках историю о смелом и умном ребёнке и проведите время в спокойной атмосфере.'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', 'Гордитесь этими 250 днями🥂', 'Сегодня вечером, когда малыш уснёт, не забудьте вместе с партнёром отпраздновать эту грандиозную победу вашей команды!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', 'НЕВЕРОЯТНЫЕ 250 ДНЕЙ! 🎉', 'Можете поверить? Уже ровно 250 дней вы вместе проходите этот бурный и волшебный путь! Украсьте этот момент специальным стикером в фотосессии малыша!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'Оглянитесь назад 📈', 'Вспомните свои страхи в первые дни. А теперь вы мама малыша, который уже пытается встать! Гордитесь собой!'),
  ('01890bf6-ab5a-403c-96d2-696020ff0863', 'Опасности на полу 🧸', 'Теперь комнаты для него — зона исследований. Ползая, он может добраться куда угодно. Самое время проверить безопасность дома.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'Проверка силы притяжения 🥄', 'Малыш намеренно бросает предмет на пол и смотрит на вас? Он просто изучает причинно-следственные связи. Будьте терпеливы и присоединитесь к игре.'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'Быстрый список 🛒', 'Вчера дома закончились все запасы? Откройте список покупок, за считаные секунды добавьте молоко, фрукты и всё необходимое, а затем отправьте список на телефон партнёра.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'Персональная сказка 🪄', 'Создайте в разделе умных сказок особенную историю, главным героем которой станет ваш ребёнок.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'Хаос после праздника 🌪️', 'После вчерашнего празднования 8 месяцев дома полный беспорядок? Не спешите убираться. Посвятите этот день отдыху и знакомству с новыми игрушками вместе с вашим уже 8-месячным малышом.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'Контроль шума 🤫', 'Первые полчаса после засыпания — самое чуткое время. Проверьте обстановку с помощью шумомера и избегайте внезапного шума, звуков телевизора или улицы.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'Я вас слышу 🗣️', 'Малыш внимательно слушает вас и пытается произносить похожие слоги? Он с вами разговаривает! Отвечайте ему улыбкой и всячески поддерживайте это общение.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'Сегодня ваше терпение было на исходе и вы, возможно, разозлились?  🛑', 'Не вините себя. Не поддавайтесь иллюзиям из интернета. Вы настоящая мама и имеете право испытывать разные эмоции.'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'Умный, как врач 🤖', 'Сомневаетесь, соответствует ли развитие малыша нормам после 8 месяцев? Не теряйтесь в интернете — получите от Anacan AI достоверный, научно обоснованный и одобренный педиатрами ответ.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'Еда руками 🥦', 'Малыш уже не хочет пюре, а стремится сам брать овощи руками! Поддерживайте его попытки есть самостоятельно и обязательно оставайтесь рядом, даже если вокруг станет грязно.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'Ночная смена папы 👨‍🍼', 'Не справляйтесь со всеми ночными пробуждениями в одиночку. Разбудите партнёра: быть командой — значит поровну делить ответственность. Сегодня ночью укладывает он.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'Просыпается среди ночи с криком и не успокаивается?  😭', 'Дайте функции «Анализ плача» послушать этот звук, чтобы понять, обычный ли это ночной страх или физическая боль.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'Танцы под музыку 🎶', 'Малыш раскачивается в ритм, когда звучит весёлая музыка? Связь между слухом и моторикой развивается прекрасно! Включите весёлую песню и потанцуйте вместе с ним по комнате.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'Если малыш сыт, теперь ваша очередь.', 'Выберите питательный перекус из полезных рецептов и хотя бы 10 минут полежите на диване, чтобы восстановить силы.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'Дневник эмоций 📝', 'Когда вам одиноко и вы устали, излейте свои чувства в Дневнике настроения. Все женщины проходят через такие бури — вы сильная и обязательно справитесь!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'Дёсны всё ещё чешутся? 🦷', 'Малыш постоянно держит пальцы во рту и у него обильно текут слюни? Пора снова достать охлаждённые в морозильной камере прорезыватели.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac'::uuid, 'Свежий воздух — лучшее лекарство 🌳', 'Малыш весь день плакал и капризничал? Решение простое: проверьте погоду, подберите подходящую одежду, посадите его в коляску и сразу отправляйтесь в парк. Природа успокаивает быстрее всего.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'Игра на постоянство объектов! 🧸', 'Спрячьте игрушку под покрывалом и позвольте малышу её найти.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'Реальность остывшего кофе ☕', 'Ваш кофе сегодня опять остыл? Ничего страшного, ведь вы — героиня, которая ни на минуту не останавливается. Опишите сегодняшний хаос в дневнике настроения с юмором.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'Роскошь принять душ в одиночестве 🛀', 'Вы весь день бегали за малышом, и у вас уже нет сил. Передайте эстафету партнёру и подарите себе 15 минут непрерывной водной терапии.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'Прогулки вдоль дивана 🛋️', 'Малыш встаёт, держась за мебель, и передвигается боком? Это огромный шаг к самостоятельности. Обязательно отметьте этот момент в трекере развития.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'Малыш узнаёт своё имя! 🗣️', 'Когда вы зовёте малыша по имени из другой комнаты, он оборачивается? Его слух и понимание речи совершенствуются. Чаще обращайтесь к нему по имени и поддерживайте диалог.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'Исследователи шкафов 🕵️‍♂️', 'Кухонные шкафы стали любимой целью малыша? Сложите безопасную посуду в нижний шкаф — пусть он обнаружит своё сокровище и играет с ним часами.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'Мастер игры в прятки 🙈', 'Закрывать лицо руками и играть в «ку-ку» — его любимое вечернее занятие.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'Вы не только мама, но и женщина 💄', 'Вы мама и защитница, но при этом вы — самостоятельная личность. Посмотрите на себя в зеркало, улыбнитесь и сегодня сделайте для себя что-нибудь приятное.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'Не теряйтесь на форумах 🤖', 'Сомневаетесь в чём-то, что касается режима питания? Не тратьте часы на поиски — пусть Anacan AI ответит на ваши вопросы, опираясь на логику педиатра у вас в кармане.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'Время папиных сказок 📖', 'Сегодня вечером создайте в «Умных сказках» историю о храброй козочке, которая взбиралась на горы. Пусть папа читает, а вы наслаждайтесь этой тишиной.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'Еда руками 🥦', 'Малыш уже не хочет пюре — ему хочется самостоятельно брать овощи руками! Поддерживайте его попытки есть самостоятельно, но обязательно оставайтесь рядом.'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'Окно бодрствования меняется 🥱', 'Ночные пробуждения вас измотали? Возможно, малыш переходит с 3 дневных снов на 2. Пересмотрите интервалы между периодами дневного сна.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'Пюре в волосах 🤦‍♀️', 'Каждый приём пищи превращается в поле боя? Когда малыш трогает и исследует еду, это способствует сенсорному развитию. Не обращайте внимания на пятна.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'Природа приходит на помощь 🌳', 'Малыш постоянно капризничает и не может усидеть дома? Воспользуйтесь помощником по погоде и одежде и сразу отправляйтесь на 20-минутную прогулку в парк.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'Не сравнивайте себя с другими 🛑', 'Забудьте фразу «А вот у них ребёнок уже ходит». У каждого малыша свой уникальный темп развития. Поделитесь переживаниями с мамами, которые понимают вас, в Сообществе Anacan.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', 'В ожидании слова «мама» 🥰', 'Малыш произносит разные слоги. Первое осознанное слово «мама» или «папа» уже совсем близко! С любовью реагируйте на его голос и поддерживайте его.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'Музыка — пища для души 🎶', 'Попробуйте успокоить внезапные вечерние капризы лёгкой классической музыкой. Часто этот простой приём творит чудеса.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'Босоногие открытия 👣', 'Не любит ходить дома в носках? Контакт нервных окончаний стоп с полом отлично стимулирует развитие мозга. Позвольте малышу двигаться свободно!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'Список спасает 🛒', 'Туман в голове всё ещё не отпускает? Закончилось мыло, осталось мало фруктов? Сразу добавьте всё в список покупок — пусть ваш партнёр этим займётся.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'Семейное совещание 🥂', 'Сегодня вечером, когда малыш уснёт, откройте вместе с партнёром дневник настроения и посмейтесь над хаосом этой недели.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'Зубки снова наступают 🦷', 'Беспричинный плач может быть связан с напряжением и дискомфортом в дёснах. Обновите трекер прорезывания зубов и достаньте охлаждённые прорезыватели.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'Акустика комнаты 🤫', 'Просыпается даже от малейшего шороха, когда засыпает? Проверьте уровень шума с помощью шумомера и поддержите сон малыша ровным белым шумом.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'Показывает пальцем на далёкий предмет и издаёт звуки? ☝️', 'Так малыш говорит вам: «Посмотри на меня» или «Я хочу это». Это огромный скачок в развитии общения!'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'Витамины для мамы 🥑', 'Вы делаете всё, чтобы малыш был сыт. А как же вы? Выберите в разделе полезных рецептов лёгкий обед, богатый железом и кальцием.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'Внимание! До полных 9 месяцев осталось всего 10 дней!  🎂', 'Пора уже сейчас подумать о небольшом торте или семейной тематической фотосессии в честь этой особенной даты.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'Подальше от экранов 📱', 'За 1 час до ночного сна выключите дома телевизор и все экраны. Выработка мелатонина усиливается в спокойной и тёмной обстановке.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'О чём будет сегодняшняя сказка?🪄', 'Пусть сегодня сказку сочинит искусственный интеллект: «Маленький бельчонок, который ищет свои игрушки». И пусть ночную тишину нарушает лишь ваш ласковый голос.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'Маленький попугайчик 🦜', 'Малыш повторяет ваш кашель, смех или движения рук? Лучшее зеркало в комнате — это вы. Покажите ему самые забавные выражения лица!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'Дайте волю чувствам 📝', 'Иногда вам хочется просто закрыть дверь и поплакать? Это совершенно нормально... Записи помогут вам почувствовать себя лучше. Перенесите свои чувства в дневник настроения.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'Формируется характер 🌟', 'Малыш уже ясно показывает, что ему нравится, а чего он совсем не хочет. Когда его упрямство утомляет вас, помните: на самом деле так формируется личность.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'Материнская дружба 💬', 'Когда вы делитесь трудностями, становится легче. В сообществе Anacan есть тысячи женщин, которые чувствуют то же, что и вы. Поговорить по душам можно бесплатно.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'Папа спешит на помощь 🫂', 'Не пытайтесь справляться с ночными кризисами в одиночку. Подключите к процессу и партнёра. Иногда другой запах и объятия мгновенно успокаивают малыша.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'Команда аплодисментов 👏', 'Малыш хлопает в ладоши, выражая радость? Отметьте это замечательное достижение моторики в трекере развития и устройте дома небольшой танец победы.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'Быстрый чек-ап 🤖', 'Какие навыки ожидаются в 9 месяцев? Забудьте о длинных статьях. Задайте свой вопрос напрямую Anacan AI и получите ответ с точностью педиатра.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'Подготовка ко сну 🛀', 'Тёплая ванна всегда помогает. Не нарушайте вечерний ритуал: он даёт мозгу малыша сигнал, что пора спать.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'Он смотрит на вас 👀', 'Где бы вы ни находились в комнате, его глаза следят за вами. Вы — его зона безопасности. Когда терпение заканчивается, вспомните об этой безусловной любви.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'Искусство беспорядка 🌪️', 'Он разбрасывает вокруг всё, с чем играет. Сейчас важнее не уборка, а ваш отдых. Игрушки и завтра будут на месте, а малышу уже сегодня нужна отдохнувшая мама.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'Ночная тишина 🤫', 'Если шум машин или другие звуки с улицы беспокоят малыша, обязательно оставляйте на фоне постоянный источник белого шума.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'Папин массажный салон 💆‍♀️', 'Пусть ваш партнёр уложит малыша спать, а затем устроит 5-минутный массаж для ваших затёкших мышц шеи!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'Интерес к лестницам 🧗‍♂️', 'Если дома есть лестницы или возвышения, малыш так и стремится к ним. Самое время установить защитные ворота.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'Битвы за едой 🥣', 'Отталкивает пюре? Не кормите насильно. Чтобы не испортить отношение малыша к еде, превратите процесс в игру и поищите в сообществе альтернативные рецепты.'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', 'До 9 месяцев — 5 дней! 🎈', 'До маленького юбилея осталось совсем немного! Торт, небольшие украшения или просто самые красивые домашние наряды... Поторопитесь с подготовкой к фотосессии малыша.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'Общие воспоминания 📸', 'Он так чудесно улыбается! Сфотографируйте его невинное личико перед сном — эти мгновения больше не повторятся.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'Запасы железа 🥩', 'Анемия может снизить и аппетит, и уровень энергии малыша. Пересмотрите режим питания и при необходимости спросите Anacan AI о продуктах, богатых железом.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'Время сказать «пока-пока» 👋', 'Малыш машет рукой на прощание, когда кто-то уходит из дома? Это очень милый показатель социального развития! Обязательно поддерживайте и поощряйте его.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'В поисках спокойствия ⛅', 'Когда напряжение нарастает, лучший выход — выйти из дома. Проверьте погоду, посадите малыша в коляску и просто прогуляйтесь, чтобы проветрить голову.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'Иллюзия совершенства 🛑', 'Сегодня всё пошло не по плану? Не вините себя. Вы настоящая мама, а не отфильтрованная иллюзия из социальных сетей.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'Повседневные мелочи забываются. 🛒', 'Закончились подгузники или влажные салфетки? Добавьте их в список покупок, чтобы ваш партнёр купил всё по дороге из магазина.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'Переход на два дневных сна 🥱', 'Малыш, который спал днём 3 раза, теперь сопротивляется последнему сну? Он растёт! Пора скорректировать режим и перейти на 2 дневных сна.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'Волшебный мир сказок 🪄', 'Создайте в «Умных сказках» историю о главном герое, которому всего через 5 дней исполнится 9 месяцев.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'Смелые шаги 🧗‍♂️', 'Малыш держится за мебель и пытается отпустить одну руку? У него развивается чувство равновесия. Возьмите его за руку и придайте ему немного уверенности.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'Разговор по душам 🥂', 'Откройте дневник настроения и обсудите с партнёром, как эти месяцы изменили вас. Быть командой — ваша главная сила.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'Всё в порядке ✔️', 'Иногда страхи берут над вами верх? Посмотрите на чистую одежду малыша, его сытый животик и улыбающиеся вам глаза. Вы прекрасно справляетесь!'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'Завтра важный день! 🎉', 'Ровно 9 месяцев! Вы уже подготовили наряды? Освободите память телефона: завтра понадобится много места для фотосессии малыша!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'Колыбельная на ночь 🎶', 'Сегодня вечером сделайте комнату совершенно тёмной. Никаких гаджетов — только ваш тихий, нежный голос.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'Болит или просто устал? 😭', 'Не теряйтесь, когда малыш плачет без видимой причины. Воспользуйтесь анализом плача, чтобы быстро определить и устранить причину.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'Оглянитесь назад 📈', 'Какой большой путь уже прошёл ваш малыш! Волнение первых дней сменилось уверенностью. Вы с огромным успехом преодолели этот путь!'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'Немного романтики 💖', 'Сегодня вечером отметьте вместе с партнёром при свечах усталость и гордость этих 9 месяцев. Вы — прекрасная команда!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'Ровно 9 месяцев! 🎂', 'Поздравляем! С рождения прошло ровно 9 месяцев. Малыш рос 9 месяцев у вас под сердцем и ещё 9 месяцев — в ваших объятиях! Отпразднуйте этот чудесный момент и поделитесь воспоминанием в сообществе!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'Потребность в энергии 🍲', 'Усталость пробирает до костей. Выберите среди полезных рецептов блюдо, богатое железом и белком, которое можно приготовить за 10 минут, и восстановите силы.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'Контролируйте уровень шума 🤫', 'Домашний шум мешает глубокому сну малыша. С помощью шумомера поддерживайте стабильный фоновый звук, чтобы и вы могли спокойно отдохнуть.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', 'Сила слова «нет» 🛑', 'Малыш уже отодвигает еду, которая ему не нравится, и, качая головой, говорит «нет»? У него формируется характер! Уважайте его волю.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'Вы и так устали за день. 👨‍🍼', 'Вечером возиться и играть с малышом на полу в комнате — исключительно папина задача.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'Поиск сокровищ 🧺', 'Опустошать корзину для белья или исследовать шкафы — для малыша лучшее развлечение. Позвольте ему свободно играть: это развивает моторику.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'Не стесняйтесь спрашивать 🤖', 'Какие специи можно добавлять в детское питание? Обо всём, что вызывает у вас сомнения, можно сразу спросить у Anacan AI и больше не беспокоиться.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'От пюре к пище с кусочками! 🍲', 'Малыш уже может есть пищу, которую нужно жевать? Попробуйте в приложении рецепты пюре и супов разной текстуры из раздела «Малыши, начинающие прикорм».'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'Список покупок 🛒', 'Закончились брокколи или овсянка? Сразу добавьте их в список покупок и отправьте список на телефон партнёра.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'Достаёт игрушки из коробки! 🧸', 'Малышу нравится по одной доставать вещи из коробки и разбрасывать их. Запечатлейте этот весёлый и немного хаотичный момент исследования с помощью функции «Фотосессия малыша», чтобы потом вспоминать его с улыбкой.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'Первые шаги уже близко? 🧗‍♂️', 'Малыш уже не просто встаёт, держась за диван, но и ходит вдоль стены? Удвойте меры безопасности.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'Засыпаем под сказку 🪄', 'Создайте в «Умных сказках» историю о храбрых и милых животных и превратите комнату в волшебное место.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'Малыш понимает тон вашего голоса 🗣️', 'Когда вы строгим голосом говорите «нет», малыш замирает и смотрит на вас? Он уже начинает понимать эмоции и запреты!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'Проверка развития 🤖', 'Вам кажется, что физическое развитие ребёнка задерживается? Получите от Anacan AI понятную информацию о двигательных навыках в 9 месяцев.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'Следим за пищеварением. 🧷', 'Твёрдая пища меняет стул. Отмечайте в Anacan каждую смену подгузника, чтобы анализировать состояние здоровья малыша.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'Боль при прорезывании зубов 🦷', 'Дёсны снова покраснели, а слюнотечение не прекращается? Подготовьте охлаждённые прорезыватели.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'Забыли, какой грудью кормили? 🤱', 'Таймер Anacan запомнит за вас, какой грудью вы кормили — правой или левой. Включите таймер кормления прямо сейчас!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'Следите за нормами сна. ⏱️', 'Когда малыш засыпает, включите таймер сна и проверьте на графике, соответствует ли продолжительность его сна суточной норме для 9-месячного ребёнка.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'Забирается на кресло 🧗‍♂️', 'Малышу уже мало ползать по полу, и он пытается залезать на мебель? Вот это настойчивость в освоении двигательных навыков! Обязательно присматривайте за ним.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'Свежий воздух — лучшее лекарство 🌳', 'Малыш весь день плакал и капризничал? Решение очень простое: проверьте погоду, выберите подходящую одежду, посадите малыша в коляску и сразу отправляйтесь в парк.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'Акустика комнаты 🤫', 'Во время сна малыша будит даже тихий щелчок. Проанализируйте обстановку с помощью шумомера и обеспечьте непрерывную тишину.'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'Чувствуете, что вы недостаточно хорошая мама? 💬', 'Зайдите прямо сейчас в сообщество Anacan, почитайте поддерживающие комментарии других мам и успокойтесь.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'Сегодня всё пошло наперекосяк?', 'Ничего страшного: если ребёнок сыт и чист, вы — лучшая мама в мире.'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'Час волшебной сказки 🪄', 'Пусть сегодня вечером прозвучит необычная история — о волшебном облаке, которое любило засыпать. Говорите тише и создайте уютную атмосферу.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'Разделите душевную нагрузку 💬', 'Загляните в Сообщество Anacan. Иногда комментарий незнакомой мамы заряжает энергией лучше, чем чашка кофе.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'Доступ к опасным зонам ⚡', 'Розетки и провода привлекают внимание малыша. Чётко обозначьте дома зоны «Нельзя» и ещё раз проверьте безопасность.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'Открытия с помощью пинцетного захвата 🤏', 'Малыш находит и поднимает кончиками пальцев даже самую крошечную соринку на полу! Его мелкая моторика на высоте.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'Спокойствие ночи 🛀', 'Не меняйте привычный ритуал. Одна и та же ванна, то же массажное масло и та же тёмная комната — золотой ключик к крепкому сну.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'Синдром четырёх стен ☕', 'Устали сидеть дома? Найдите среди Мест, дружественных к мамам, ближайшее место, где вы сможете подышать свежим воздухом, а малышу будет комфортно.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'Кто займётся домашними делами? 🌪️', 'Малыш боится шума пылесоса, а дела накапливаются? Пусть подождут. Попросите своего партнёра сегодня взять домашние дела на себя.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'Дневник эмоций 📝', 'Когда вам одиноко, излейте свои чувства в Дневнике настроения. Все женщины проходят через это — вы сильная.'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'Исследование мусора 🗑️', 'Малыш с огромным интересом изучает всё, что находит на полу. Не сердитесь и не отбирайте у него всё подряд — он исследователь. Просто присматривайте за ним.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'Папино утешение 🫂', 'Когда малыш просыпается ночью, вставайте по очереди: один раз вы, другой — ваш партнёр. Иногда малыша лучше всего успокаивают ритмичные поглаживания папы.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'Не доверяйте погоде за окном ⛅', 'Собираясь на прогулку, не решайте, как одеться, лишь взглянув в окно. С помощью инструмента «Погода и одежда» найдите золотую середину в многослойной одежде.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'Не отдам свою игрушку! 🧸', 'Малыш протестует и плачет, когда у него что-то забирают? У него развивается чувство собственности и индивидуальности. Это совершенно естественный этап психологического развития.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'Не понимаете, почему малыш так странно плачет?  😭', 'Сразу включите запись для Анализа плача, узнайте, что беспокоит малыша — зубы или газы, — и успокойтесь.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'Потребность в тишине 🤫', 'Поддерживайте тишину в комнате с помощью Шумомера. Прерванный ночью сон портит утреннее настроение и малыша, и ваше.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'Танцы под музыку 🎶', 'Малыш раскачивается в такт, когда звучит весёлая музыка? Значит, формируется связь между слухом и моторикой! Включите весёлую песню и потанцуйте вместе с ним.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'Листает книги 📖', 'Малыш пытается переворачивать страницы книг из плотного картона? Предлагайте ему побольше красочных тактильных книг со сказками.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'Учит названия предметов 🧸', 'Когда вы спрашиваете: «Где мяч?», малыш ищет его глазами и находит? Его восприятие совершенствуется! Играйте с ним, называя разные предметы.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'Баланс на двух ногах 🤸‍♂️', 'Когда вы держите малыша под мышки, он стоит на ногах увереннее и крепче? Обязательно отметьте этот базовый шагательный рефлекс в трекере развития!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'Время волшебной сказки 🪄', 'Добавьте красок в вечерний ритуал с историей «Секреты засыпания Маленького героя» из раздела умных сказок.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'Список спасает 🛒', 'Домашние дела и заботы никогда не заканчиваются. Не перегружайте себя: заполните список покупок и ждите, когда вернувшийся с работы папа придёт на помощь.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'Что спросить у врача? 🤖', 'Не знаете, о чём спросить врача перед ежемесячным осмотром? Попросите Anacan AI составить список для осмотра в 9 месяцев.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'Маленький помощник по дому 🧺', 'Пока вы складываете одежду, малыш приходит и «помогает», разбрасывая её? Не отстраняйте его от процесса — дайте ему полотенце.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'Дайте волю чувствам 📝', 'Вечером возьмите чашку кофе и оставьте небольшую запись в Дневнике настроения, сравнив свои нынешние чувства с ощущениями прошлых месяцев.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'Берегите себя 🍲', 'Если вы здоровы, здоров и малыш. Выберите среди полезных рецептов лёгкий салат для мам, который готовится за 10 минут, и подкрепитесь.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'Тёплая ванна, массаж и затемнение комнаты. 🛀', 'Соблюдение ритуала перед сном — главный секрет спокойных ночей без пробуждений.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'Разные слоги и попытки говорить целыми предложениями 🗣️', 'Малыш подолгу говорит на своём языке, словно строит целые предложения. Внимательно слушайте самого милого диктора в доме!'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'Звуки в комнате 🤫', 'Малышу стало труднее засыпать? Проверьте уровень шума в комнате с помощью шумомера и убавьте громкость телевизора до фонового уровня.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'Мы — одна команда! 💖', 'После трудного дня сядьте рядом с партнёром и поговорите по душам. Взаимная поддержка помогает разделить нагрузку пополам.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', 'Жест «иди ко мне» 👏', 'Малыш научился подзывать к себе руками? Обязательно снимите эту милую попытку подражания на видео и добавьте в альбом воспоминаний.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'Разговоры становятся разнообразнее! 🗣', '️ Чтобы превратить милые диалоги из слогов «ма-ма» и «ба-ба» в полезное занятие, прочитайте в Блогах рекомендации по развитию речи.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'Продукты, поддерживающие лактацию. 🍲', 'Сегодня попробуйте супы для усиления лактации из раздела полезных рецептов для женщин и позаботьтесь о своих силах.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'Приступы плача без понятной причины изматывают. 😭', 'Не мучайте себя догадками: воспользуйтесь Анализом плача и узнайте причину проблемы.'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'Звуковая терапия против беспокойства. 🎶', 'Если сегодня вечером ваш малыш беспокоится, включите в разделе «Белые шумы» звуки материнской утробы, чтобы быстро его успокоить.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', 'Готовимся к 10 месяцам! 🎂', 'Внимание! Всего через 10 дней малышу исполнится 10 месяцев! Не забудьте заказать особенный торт в честь перехода к двузначному возрасту в месяцах!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'Засыпаем под сказку 🪄', 'Создайте в «Умных сказках» историю о смелых и милых животных и превратите комнату в волшебное место.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', 'До 10 месяцев осталось 10 дней! 🎈', 'До юбилея осталось 10 дней! Уже сейчас выберите особые рамки в инструменте для фотосессии малыша и всё спланируйте.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'Не доверяйте погоде на глаз ⛅', 'Собираясь на прогулку, не оценивайте погоду только по виду из окна. С помощью инструмента «Погода и одежда» найдите золотую середину в многослойной одежде.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'Колыбельная от папы 👨‍🍼', 'Сегодня вечером все колыбельные и сказки перед сном — задача папы.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'Ночная тишина 🤫', 'Если малыша беспокоит шум машин или другие звуки с улицы, обязательно оставьте на фоне постоянный источник белого шума.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'Учимся, падая и вставая 🧗‍♂️', 'Малыш ходит, держась за диван, садится на попу и снова встаёт? Он учится преодолевать трудности. Не тревожьтесь и подбадривайте его.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'Боль при прорезывании зубов 🦷', 'Дёсны снова покраснели, а слюни текут не переставая? Приготовьте охлаждённые прорезыватели.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'Малыш хочет то же, что едите вы 🥣', 'Он тянется ко всему, что лежит у вас на тарелке? Интерес к еде сейчас на пике. Предлагайте ему небольшие кусочки пищи, которые он сможет есть руками.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'Дневник эмоций 📝', 'Когда вам одиноко, излейте свои чувства в «Дневнике настроения». Вам станет легче, если вы запишете их.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'Проверка развития 🤖', 'У вас есть вопросы о прикорме? Попросите Anacan AI рассказать о меню для 9-месячного малыша.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'Время умной сказки 🪄', 'Пусть сегодня будет необычная история: о волшебном облаке, которое любит засыпать. Говорите тише и создайте сказочную атмосферу.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'Пытается складывать предметы 🧸', 'Малыш кладёт игрушку в коробку, а затем снова достаёт? Так он знакомится с понятиями «внутри» и «снаружи».'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'Формируем привычку пить воду. 💧', 'Не забывайте предлагать воду вместе с прикормом. Подходящие поильники вы легко найдёте в разделе «Рекомендуемые товары».'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'Маленький попугайчик 🦜', 'Малыш повторяет за вами кашель или смех? Вы для него — лучшее зеркало. Покажите ему самые забавные выражения лица!'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'Энергетическая бомба для мам! 🥗', 'Чтобы бегать за активным малышом, нужны силы! Приготовьте витаминный салат или смузи по одному из полезных рецептов для женщин.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'Папин массажный салон 💆‍♀️', 'Пусть ваш супруг уложит малыша спать, а затем сделает вам 5-минутный массаж плеч, чтобы расслабить напряжённые мышцы шеи!'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'Свежий воздух — лучшее лекарство 🌳', 'Малыш весь день плакал и капризничал? Решение очень простое: проверьте погоду, оденьте малыша, посадите в коляску и сразу отправляйтесь в парк.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', 'До 10 месяцев всего 5 дней! 🎂', 'До круглой даты осталось совсем немного! Самое время подготовить торт и наряд к 10 месяцам. Вы шаг за шагом приближаетесь к первому дню рождения!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'Сигналы сонливости 🥱', 'Если малыш трёт глаза и смотрит в одну точку, не ждите истерики. Сразу затемните комнату и начинайте ритуал перед сном.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'Протестует и плачет, когда вы что-то у него забираете? 🧸', 'У малыша развивается чувство собственности и осознание своей индивидуальности. Это совершенно естественный этап психологического развития.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'Машем ручкой на прощание! 👋', 'Малыш уже научился махать вслед уходящим? Сохраните это осознанное и милое движение на память с помощью фотосессии малыша.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'Меры безопасности дома! 🛡', '️ По мере того как малыш пытается вставать, опасностей становится больше. Обязательно загляните в наш список рекомендованных товаров, чтобы выбрать детские замки и защитные накладки на углы.'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'Уделите время себе. 🛁', 'Пока ваш малыш спит, позаботьтесь о волосах и коже и немного отдохните.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'Малышу нравится есть самостоятельно! 🥦', 'Приготовьте по нашим рецептам полезную еду, которую удобно брать руками, для малышей, начинающих знакомство с прикормом.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'Малыш понимает простые просьбы! 🧠', 'Когда вы говорите: «Дай мне это», малыш протягивает вам игрушку? Чтобы поддержать этот скачок в интеллектуальном развитии, прочитайте развивающие статьи в блоге.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'Остались дела? Пусть подождут.  🌪️', 'Попросите супруга сегодня взять домашние дела на себя. А вы отдохните.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'Спокойствие ночи 🛀', 'Тёплая ванна, массаж и приглушённый свет в комнате. Соблюдение ритуала перед сном — главный секрет спокойных ночей без пробуждений.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'С большим интересом изучает всё, что находит на полу.  🗑️', 'Не раздражайтесь и не отбирайте у малыша всё подряд — он маленький исследователь. Просто присматривайте за ним.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'Малыш голоден или устал? 😭', 'Не теряйтесь, если малыш плачет без видимой причины. Воспользуйтесь анализом плача, чтобы быстро определить и устранить проблему.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'Папа спешит на помощь 🫂', 'Когда малыш просыпается ночью, вставайте к нему по очереди с супругом. Разделите эту нагрузку поровну, как настоящая команда.'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', 'Волнительные 300 дней! 🌟', 'Завтра большой двойной юбилей — 10 месяцев и 300 дней! Создайте дома праздничную атмосферу и освободите память на телефоне.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'Какой большой путь прошёл ваш малыш!  📈', 'Волнение первых дней сменилось уверенностью. Вы с триумфом прошли этот путь — вы великолепны!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'Есть вопросы? 🤖', 'Даже ночью вы можете спросить нашего помощника Anacan AI о любых беспокоящих вас нюансах развития и получить профессиональную поддержку.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', 'Невероятные 10 месяцев и 300 дней! 🎉', 'Поздравляем! Вы растите это чудо уже ровно 300 дней — целых 10 месяцев.'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'Водная настойчивость 💧', 'Малыш хочет самостоятельно держать чашку и пить, но бо́льшая часть воды проливается на него? Поддерживайте его стремление к самостоятельности — влажные салфетки как раз для этого и нужны.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'Время подзарядки партнёра 🔋', 'За день вы отдали малышу всю свою энергию. Пусть сегодня вечером ваш партнёр побудет с ним, а вы перейдите в режим offline.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'Первые секунды без опоры 🧗‍♂️', 'Малыш внезапно отпускает руки, когда стоит, держась за диван? Он учится сохранять равновесие! Будьте рядом и осторожно страхуйте его в эти короткие, но волнительные секунды.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'Что же приготовить? 🍲', 'Закончились идеи для меню прикорма? Не теряйтесь в интернете. Попросите Anacan AI составить список простых блюд, которые 10-месячный малыш сможет есть руками.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'Присоединяется к разговору 🗣️', 'Пока вы говорите по телефону, малыш тоже что-то произносит на своём языке и повышает голос? Его коммуникативные навыки стремительно развиваются — теперь в комнате появился второй собеседник!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'Внезапно проснулся с криком? 😭', 'Возможно, начались ночные страхи. Запишите звук с помощью Анализа плача, чтобы понять, связана ли проблема с физическим дискомфортом или психологическими причинами.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'Интерес к книгам 📖', 'Добавьте бумажные книги в вечерний ритуал. Малыш уже пытается самостоятельно перелистывать страницы. Меняйте тон голоса в соответствии с темпом сказки.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'Башня из еды рухнула 🥣', 'Малыш нарочно бросает со стульчика ложку или еду, а затем смотрит на вас? Он проверяет границы дозволенного и изучает силу притяжения. Сохраняйте терпение.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'Ваше изменившееся тело 👗', 'Вы грустите, глядя в зеркало на изменившиеся очертания тела? С помощью этого тела вы создали человека. Напишите в дневнике настроения слова благодарности самой себе.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'Тихий герой 🤫', 'Как только малыш засыпает, каждый звук в доме кажется взрывом бомбы. Настраивая допустимый уровень шума с помощью шумомера, постарайтесь и сами ступать тише.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'Детектив у шкафа 🕵️‍♀️', 'Все кастрюли из кухонного шкафа оказались на полу? Позвольте малышу играть с безопасными предметами — это развивает логическое мышление. Просто уберите подальше всё острое.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'Мамы делятся сокровенным 💬', 'Вас не оставляют в покое вопросы вроде «Почему мой малыш до сих пор не ползает?» Напишите об этом в Сообществе Anacan. Вы увидите, что у каждого малыша свой идеальный темп развития.'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'Указательный палец активен ☝️', 'Малыш показывает пальцем на кошку или игрушку вдали и реагирует на неё. Это высший этап развития способности направлять внимание.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'Парк или дом? ⛅', 'Хотите выйти на прогулку, но на улице ветрено. Помощник по погоде и одежде подскажет не только температуру, но и какую непродуваемую одежду надеть на малыша.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'Смешные гримасы папы 🤡', 'Лучший способ рассмешить малыша — дать папе издавать забавные звуки. Сохраните в памяти весёлые моменты этого вечера с помощью фотосессии малыша.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'Настойчивое желание быть рядом с мамой 🥰', 'Даже когда вы идёте в туалет, малыш ждёт вас за дверью и плачет. Тревога разлуки достигла пика. Каждый раз успокаивайте его словами: «Я здесь».'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'Сегодня в умной сказке 🪄', 'Создайте в умных сказках особенную историю, главным героем которой станет ваш малыш: днём он устаёт, а ночью летит к звёздам.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'Список в вашем кармане 🛒', 'Закончились яблоки для фруктового пюре? Доверьте покупки партнёру. Добавьте всё необходимое в список покупок, а поход в магазин — его задача.'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'Следим за пищеварением. 🧷', 'Разные виды твёрдой пищи меняют стул малыша. Отмечайте в Anacan каждую смену подгузника, чтобы отслеживать состояние его здоровья.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'Непростые ночи 🥱', 'Малыш изо всех сил сопротивляется сну? Возможно, пришло время убрать один дневной сон. Пересмотрите режим.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'Место для мамы ☕', 'Постоянное пребывание дома лишило вас сил. Выберите среди мест для мам кафе с детским меню и удобными местами для отдыха и уделите время себе.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'Похвалите себя 👏', 'Смотрите не на беспорядок в комнате, а на то, как счастлив сегодня ваш малыш. Вы замечательная мама — этому не научит ни одна книга.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'Танцуем под музыку 🎶', 'Стоит малышу услышать ритмичную мелодию по телевизору или телефону, как он начинает покачивать попой. У него развивается восприятие музыки — присоединяйтесь и танцуйте вместе!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, устройте с партнёром сеанс массажа плеч, чтобы снять накопившийся за день стресс. Вы — команда!'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'Быстрый педиатр 🤖', 'На теле малыша появились небольшие покраснения? Перед визитом к врачу быстро узнайте у Anacan AI о признаках пищевой аллергии.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'Реакция на своё имя 🗣️', 'Когда вы зовёте малыша, он не только смотрит на вас, но даже оставляет своё занятие и пытается подойти.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке с приглушённым освещением.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'Отпустите чувство вины 📝', 'Думаете, что сегодня мало играли с малышом? 10 минут полноценного общения ценнее, чем 1 час игры без сил.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'Кадр, остановивший время 📸', 'С каждым днём он всё больше похож на подросшего ребёнка, а младенческие черты постепенно исчезают. Скорее открывайте Детскую фотосессию и запечатлейте эти перемены.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', 'Первые сигналы на пути к 11 месяцам! 🎈', 'Внимание! Всего через 20 дней малышу исполнится 11 месяцев, и мы начнём большой обратный отсчёт до первого дня рождения. Улыбнитесь!'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'Папина колыбельная 👨‍🍼', 'Сегодня вечером испытание по самостоятельному укладыванию малыша в комнате предстоит пройти вашему партнёру.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'Уборка или отдых? 🛋️', 'Когда малыш уснёт, не бегите к посудомоечной машине. Лягте на диван, закройте глаза и просто спокойно подышите 15 минут. Вы робот? Нет.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', 'Начинается битва «Нет!» 🛑', 'Теперь, когда вы даёте малышу то, что ему не нравится, он качает головой и отталкивает это. У него формируется воля. Старайтесь уважать его маленькие решения.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'Контроль звуков 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте обстановку с помощью шумомера и избегайте внезапных громких звуков.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'Здоровая мама — здоровый малыш 🥑', 'Ваши запасы железа и кальция истощились. Выберите среди полезных рецептов быстрый в приготовлении питательный салат, который наполнит вас энергией.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', 'Упрямое «Отдай мою игрушку!» 🧸', 'Когда у малыша что-то забирают, он бурно реагирует и плачет. Чувство собственности уже активно формируется. Вместо запретов постарайтесь переключить его внимание на что-нибудь другое.'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'Засыпаем под сказку 🪄', 'Создайте в Умных сказках особый фон, состоящий только из музыки и звуков природы. Никаких слов — лишь умиротворение.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'Дружба с парком 🌳', 'Малышу скучно гулять в коляске? Проверьте погоду и его одежду, а затем позвольте ему свободно потрогать траву и листья в парке.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'Ходит, держась за стену 🧗‍♀️', 'Шагать боком вдоль мебели — его любимое упражнение. Самое время ещё раз проверить защитные приспособления и острые углы.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'Машем «Пока-пока» 👋', 'Когда кто-то выходит за дверь, малыш сам машет рукой на прощание! Прекрасный социальный навык.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'Малыш проснулся посреди ночи и непрерывно плачет без видимой причины? 😭', 'Спокойно возьмите его на руки и не пытайтесь разбудить. Дайте Анализу плача послушать этот звук, чтобы убедиться, что всё в порядке.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'Нужно выговориться 💬', 'Вас мучает мысль: «Я уже никогда не стану прежней»? Поделитесь этим временным переживанием с мамами в Сообществе Anacan. Вы не одиноки.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'Сегодня вас всё раздражало?', 'Когда малыш уснёт, запишите свои чувства в Дневник настроения. Завтра будет новый и более прекрасный день.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'Быстрые покупки 🛒', 'Ваш партнёр возвращается с работы? Сразу откройте Список покупок и за считаные секунды отправьте ему список: молоко, фрукты и всё остальное, чего не хватает дома.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'Подражает взрослым 🧹', 'Пока вы убираете дом, малыш тоже берёт тряпочку и пытается повторять за вами? Он словно зеркало и копирует всё, что вы делаете.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'Поддержка команды 🥂', 'Чтобы сбросить с плеч усталость за весь день, выпейте чаю вместе с партнёром и скажите друг другу: «Мы и сегодня справились».'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'Вопросы к педиатру 🤖', 'Какой должна быть порция у 10-месячного малыша? Не тратьте силы на поиски — попросите у Anacan AI точную таблицу, одобренную педиатром.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'Зуд в дёснах продолжается 🦷', 'Малыш постоянно держит пальцы во рту и всё грызёт? Возможно, скоро появятся задние зубы. Отметьте это в трекере прорезывания зубов.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'Разведка погоды ⛅', 'За окном непонятная погода? Инструмент погоды и одежды мгновенно подскажет скорость ветра, которую не видно из окна, и поможет подобрать подходящий комплект.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'Музыкальные вечера 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую песню, обнять малыша и потанцевать вместе с ним.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'Сам снимает обувь 👟', 'Одевание уже превратилось в настоящую борьбу? Малыш сам стягивает носки и обувь. Восхититесь его двигательными навыками!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'Логические игры 🧩', 'Малыш складывает игрушки в коробку, а потом всё из неё высыпает? Так он осваивает понятия «внутри» и «снаружи» и развивает логику. Не мешайте ему заниматься этим.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения только на себя. Будите и партнёра: быть командой — значит делить ответственность поровну.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'Ищем место для мамы ☕', 'Даже при такой усталости вам тоже нужно развеяться. Найдите поблизости тихое кафе в разделе «Места для мам» и отправляйтесь туда.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'Метод проб и ошибок 🧱', 'Малыш пытается поставить один игрушечный кубик на другой, но башенка падает. Он внимательно пробует снова. Просто понаблюдайте за этими маленькими инженерными экспериментами.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'Идеи для меню 🍲', 'Устали готовить одно и то же? Загляните в раздел полезных рецептов и найдите новые вкусные блюда, которые 10-месячный малыш сможет есть руками.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'Тихая комната — спокойный мозг 🤫', 'Во время подготовки ко сну важно снизить уровень шума в комнате. С помощью шумомера проверьте громкость своего голоса и окружающих звуков.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'Особенная сказка 🪄', 'Создайте в «Умных сказках» историю о герое, который станет старше всего через 10 дней, и наполните комнату волшебством.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', 'До 11 месяцев осталось всего 10 дней! 🎂', 'Невероятно! Ровно через 10 дней малышу исполнится 11 месяцев. Самое время начать продумывать празднование первого дня рождения!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'Улыбки на фото 📸', 'С каждым днём малыш становится всё интереснее и милее. Скорее откройте «Фотосессию малыша», украсьте снимок стикерами и сохраните этот весёлый момент.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'Списки и забывчивость 🛒', 'Туман в голове не проходит? Не держите в памяти мелкие покупки для дома — сразу добавляйте их в список покупок, а партнёр обо всём позаботится.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', 'Объятия «Я тебя люблю» 🫂', 'Малыш неожиданно подходит, обнимает вас за шею или гладит по лицу? Теперь он выражает свою любовь физически. Наслаждайтесь этим моментом.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'Волшебство спокойной ночи 🪄', 'Создайте в «Умных сказках» историю о храбрых и милых животных и превратите комнату в волшебное место.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'Вы делаете всё, чтобы накормить малыша. А как же вы?', 'Выберите в разделе полезных рецептов обед, богатый железом и белком, и восстановите силы.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'Листаем страницы книги 📖', 'Малыш уже самостоятельно переворачивает страницы книг из плотного картона? Отметьте эту победу моторики в трекере развития.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'Сегодня всё пошло не по плану?', 'Когда малыш уснёт, не мучайте себя чувством вины. Вы настоящая мама, и вы прекрасны.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'Меткие броски ⚾', 'Малыш намеренно пытается бросить игрушку в определённую цель. Зрительно-моторная координация стремительно развивается.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'Педиатр за секунду 🤖', 'Сколько должен длиться дневной сон у 11-месячного малыша? Сразу задайте Anacan AI любой волнующий вас вопрос и успокойтесь.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'Завтра важный день! 🎉', 'Вы готовы? Завтра малышу исполнится ровно 11 месяцев! До первого дня рождения останется всего 1 месяц! Подготовьте необычное место и наряд для фотосессии малыша.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'Дух единства 🥂', 'Откройте дневник настроения, вспомните вместе с партнёром первые дни и посмейтесь. Эти 11 месяцев дались вам нелегко!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'Мамин перерыв на кофе ☕', 'Беспорядок в комнате никуда не убежит, а вот ваши силы могут закончиться. Пока малыш играет самостоятельно, не спешите сразу заниматься делами. Присядьте и выпейте кофе.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'Танец победы 💖', 'Сегодня вечером отметьте вместе с партнёром усталость и гордость, накопившиеся за 11 месяцев. Вы вышли на финишную прямую к первому дню рождения!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'Грудное молоко всё ещё играет важную роль! 🍼', 'До 1 года грудное молоко очень важно. Запускайте таймер кормления, чтобы убедиться, что малыш получает необходимое количество молока в течение дня.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', 'Ровно 11 месяцев! 🎂', 'Поздравляем! С момента родов прошло ровно 11 месяцев! Выберите стикер «11 месяцев» в разделе фотосессии малыша и поделитесь этой радостью в Сообществе Anacan!'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'Доступ к опасным зонам ⚡', 'Малыш стал ещё выше и теперь дотягивается до полок, которые раньше были недоступны. Ещё раз проверьте безопасность дома: острые углы, тяжёлые предметы и другие риски.'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'Сила музыки 🎶', 'Попробуйте успокаивать внезапные вечерние капризы лёгкой классической музыкой. Часто этот простой приём творит чудеса.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'Управление эмоциями 📝', 'Ваши нервы на пределе, и вы вот-вот взорвётесь? Перенесите весь стресс в дневник настроения и сделайте глубокий вдох.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'Дружба с темнотой 🌙', 'Чтобы малыш быстрее заснул, добавьте к вечернему ритуалу знакомство с темнотой. Выключите в комнате все лишние источники света.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'Узнаёт части тела 👀', 'Когда вы спрашиваете: «Где носик?», малыш показывает на него пальцем? Его способность понимать сейчас на пике!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'Вечер победы 🥂', 'Сегодня вечером, когда малыш уснёт, поднимите с партнёром тост: «Мы отличная команда». Вы действительно прекрасно справляетесь!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'Подозрение на аллергию 🤖', 'Вы дали малышу новый продукт и заметили покраснение на щеках? Прежде чем паниковать, узнайте у Anacan AI, что делать в первую очередь.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', 'Упрямое «Я сам поем» 🥦', 'Малыш хочет забрать у вас ложку? Позвольте ему. Он испачкается, но ощущение самостоятельности сейчас очень важно для него.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'Список необходимого не заканчивается 🛒', 'В повседневной суете забыли, что закончилось — шампунь или подгузники? Не держите всё в голове: добавьте в список покупок и синхронизируйте его с партнёром.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'Ночная смена папы 👨‍🍼', 'Вы и так устали за день. Пусть вечерняя подготовка малыша ко сну и чтение сказки станут обязанностью папы.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'Всё в доме — игрушка 🥄', 'Пластиковые контейнеры и деревянные ложки интересуют малыша больше самой дорогой игрушки. Позвольте ему свободно изучать безопасные кухонные принадлежности.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'Анализ плача спешит на помощь 😭', 'Малыш проснулся посреди ночи и никак не успокаивается? Не гадайте — воспользуйтесь Анализом плача, чтобы сразу определить причину.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'Свежий воздух спасает 🌳', 'Если дома назревает кризис, проверьте погоду и одежду, посадите малыша в коляску и сразу отправляйтесь в парк. Природа — самый быстрый способ помочь ему успокоиться.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'Капризы на пике ☁️', 'Малыш всем недоволен и плачет по любому поводу? Возможно, это скачок роста или дискомфорт при прорезывании зубов. Просто почаще обнимайте его.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'Давайте разберёмся вместе 💬', 'Устали задаваться вопросом: «Почему мой ребёнок так делает?» Загляните в Сообщество Anacan и убедитесь, что в тысячах семей происходит ровно то же самое!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'Переход ко сну 🛀', 'Тёплая ванна всегда помогает. Не нарушайте вечерний ритуал: он подаёт мозгу малыша сигнал, что пора спать.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'Учимся методом проб и падений 🧗‍♂️', 'Малыш встаёт, падает на попу, смеётся и снова поднимается. Такие падения формируют мышечную память, поэтому не вмешивайтесь без необходимости.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'Потребность в тишине 🤫', 'Малыш просыпается от малейшего шороха, когда засыпает? Проанализируйте обстановку с помощью шумомера и обеспечьте непрерывную тишину.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'Начинается подготовка к годику! 🎈', '11 месяцев позади. Всего через 30 дней — первый день рождения! Выбрать тематику, место или просто отметить дома? Понемногу начинайте планировать праздник.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'Я сам нахожу свою игрушку 🧸', 'Малыш идёт и находит игрушку там, где вы спрятали её у него на глазах? Значит, он уже полностью понимает, что предметы продолжают существовать, даже когда их не видно!'),
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения только на себя. Разбудите и партнёра: быть командой — значит поровну делить ответственность.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'Дайте волю чувствам 📝', 'По мере приближения первого дня рождения вы чувствуете странную грусть и думаете: «Как же быстро малыш вырос»? Запишите эти чувства в дневнике настроения.'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'Побег из четырёх стен ⛅', 'Устали сидеть дома? Проверьте погоду, подберите подходящую одежду и позвольте малышу в парке свободно трогать траву и листья.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'Помогает одеваться 👕', 'Когда вы надеваете на малыша кофточку, он сам вытягивает руки или поднимает ногу? Значит, он сотрудничает с вами. Отметьте эту маленькую помощь в трекере развития.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'Дружба с темнотой 🌙', 'Чтобы малыш быстрее засыпал, добавьте знакомство с темнотой в вечерний ритуал. Выключите все дополнительные источники света в комнате.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'Не теряйтесь на форумах 🤖', 'Заметили что-то необычное в движениях малыша? Не ищите ответы часами в интернете — задайте вопрос напрямую Anacan AI и успокойтесь.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1'::uuid, 'Понимает значение слов 🗣️', 'Когда вы говорите: «Принеси мяч», малыш действительно идёт его искать. Его словарный запас — слова, которые он понимает, — быстро растёт. Говорите с ним более сложными предложениями.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'Время умной сказки🪄', 'Создайте в умных сказках историю о герое, которому всего через 1 месяц исполнится 1 год. Пусть тишину ночи нарушает лишь эта сказка.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', 'Нужны украшения и шары для празднования 1 года?  🛒', 'Не ломайте голову — уже сейчас начинайте составлять список покупок.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'Упорные попытки 🧗‍♂️', 'Малыш пытается встать, держась за мебель, даже когда у него в руке игрушка. Его способность сохранять равновесие невероятно окрепла. Наблюдайте со стороны, не вмешиваясь.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'Бесшумный герой 🤫', 'Как только малыш засыпает, каждый звук в доме кажется взрывом бомбы. Установив с помощью шумомера допустимый уровень звука в комнате, старайтесь и сами ступать тише.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'Мамины секреты 💬', 'Мысль «Как отметить день рождения?» не даёт вам покоя? Напишите в сообщество Anacan и получите от мам креативные идеи на любой бюджет.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'Кадр, останавливающий время 📸', 'С каждым днём малыш всё больше становится похож на подросшего ребёнка. Скорее откройте фотосессию малыша и сохраните на память этот искренний момент танца.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'Танцы и ритмы 🎶', 'Малыш начинает танцевать, как только слышит ритмичную мелодию по телевизору или телефону? Его восприятие музыки активно развивается — присоединяйтесь и танцуйте вместе!'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'Уборка или отдых? 🛋️', 'Когда малыш уснёт, не спешите к посудомоечной машине. Прилягте на диван, закройте глаза и просто спокойно подышите 15 минут.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'Строит башню из кубиков 🧱', 'Малыш пытается поставить друг на друга два или три игрушечных кубика. Спокойно наблюдайте за этими маленькими инженерными экспериментами и хвалите его.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'Отвечает языком тела 🗣️', 'Когда вы спрашиваете: «Пойдём?», малыш поднимает руки, а когда говорите «Нет» — качает головой. Его способность понимать речь невероятно выросла.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'Похвалите себя 👏', 'Смотрите не на беспорядок в комнате, а на то, как счастлив сегодня ваш малыш. Вы прекрасная мама — этому не научит ни одна книга.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'Сегодня в «Умной сказке» 🪄', 'Создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: «Маленький львёнок готовится к своему первому дню рождения».'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', 'Тревоги перед первым днём рождения? 💬', 'Вас не оставляют мысли вроде: «Мой малыш ещё не ходит — это задержка?» Напишите в Сообществе Anacan. Вы увидите, что каждый малыш развивается в своём идеальном темпе и что вы не одиноки.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения исключительно на себя. Разбудите партнёра — быть командой означает поровну делить ответственность.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'Разведка погоды ⛅', 'Не вполне понятно, какая погода на улице? Инструмент прогноза погоды и подбора одежды мгновенно подскажет скорость ветра и подходящий комплект.'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'Здоровая мама — здоровый малыш 🥑', 'Запасы железа и кальция в вашем организме истощились. Приготовьте по нашим полезным рецептам быстрый питательный салат, который поможет вам восстановить силы.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', 'До первого дня рождения всего 20 дней! 🎂', 'Как быстро летит время! Начните записывать идеи для приглашений, списков и маленьких сюрпризов ко дню рождения.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'Кадр, остановивший время 📸', 'Когда малыш будет мило играть в комнате, сразу откройте «Фотосессию малыша» и запечатлейте проявления его уже такого взрослого характера.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома яркий свет и все экраны. Мелатонин вырабатывается в спокойной обстановке при слабом освещении.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'Продукты для поддержания лактации. 🍲', 'Сегодня попробуйте приготовить супы для поддержания лактации из раздела полезных рецептов для женщин и восстановите свои силы.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'Забыли, какой грудью кормили? 🤱', 'Таймер Anacan запомнит за вас, какой грудью вы кормили — правой или левой. Включите таймер кормления прямо сейчас!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'Меняется дневной сон? 🥱', 'Малыш отказывается от одного из двух дневных снов? Ближе к году может наступить время скорректировать режим сна.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'Своё место за семейным столом! 🍲', 'Малышу уже нравится есть вместе с вами. Откройте для всей семьи новые вкусные блюда из раздела нашего приложения «Рецепты для малышей, начинающих прикорм».'),
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e', 'Здоровая мама — здоровый малыш 🥑', 'Ваши запасы железа и кальция истощены. Выберите среди полезных рецептов быстрый в приготовлении и питательный салат, который наполнит вас энергией.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'Весёлые папины забавы 🤡', 'Лучший способ рассмешить малыша — это папины забавные звуки. Насладитесь вместе с малышом весёлыми моментами этого вечера.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'Полный переход на мелко нарезанную пищу! 🍲', 'Теперь малыш уже может есть пищу, которую нужно пережёвывать. Попробуйте новые текстуры с помощью Рецептов для малышей, начинающих прикорм, в нашем приложении.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'Время самостоятельной игры 🧸', 'Теперь малыш может самостоятельно играть с игрушками в течение 10-15 минут. Это значит, что продолжительность концентрации внимания увеличивается. Наблюдайте за ним со стороны и наслаждайтесь тишиной.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'Парк или дом? ⛅', 'Хотите выйти на прогулку, но на улице ветрено? Помощник по погоде и одежде подскажет не только температуру, но и какую непродуваемую одежду надеть на малыша.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'Непростые ночи 🥱', 'Малыш изо всех сил сопротивляется засыпанию? Пересмотрите режим дневного сна и ритуал укладывания.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'Список у вас в кармане 🛒', 'Чтобы заказать торт на 1 год, ознакомьтесь с вариантами тортов в Anacan.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'Большие эмоции в маленьком теле 🛑', 'Малыш падает на пол или плачет, когда не получает желаемого? Ему пока трудно управлять своими эмоциями. Опуститесь до его уровня и спокойно поговорите с ним, чтобы вместе пережить истерику.'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'Внезапно проснулся с криком? 😭', 'Это может быть ночной ужас. Загрузите звук в Анализ плача, чтобы определить, связана ли проблема с физическим состоянием или психологическими причинами.'),
  ('a7923459-9b74-4330-949d-00e94d185768', 'Что означает слово «нет»! 🛑', 'Малыш уже смотрит на вашу реакцию, когда делает то, чего делать нельзя? Посоветуйтесь с Anacan AI о первых шагах в воспитании.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, устройте с партнёром сеанс массажа плеч, чтобы снять накопившийся за день стресс. Вы — команда!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'До первого дня рождения всего 25 дней! 🎈', 'Обратный отсчёт официально начался! Вы уже выбрали место и наряд для фотосессии на 1 год? Ускорьте подготовку!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'Безопасность дома! 🛡', '️ Чем свободнее малыш передвигается, тем больше опасностей его окружает. Обязательно ознакомьтесь с нашим списком Рекомендуемых товаров, где представлены детские замки и защитные ворота для лестниц.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'Время ухода за малышом вместе с папой. 👨‍🍼', 'После вечернего кормления поручите папе чтение книги и укладывание малыша, а сами немного вздремните.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'Показывает на всё указательным пальцем! ☝', '️ Вместо вопроса «Что это?» малыш показывает на всё пальцем. Сохраните этот момент любознательности в Альбоме малыша.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'Контроль звуков 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума с помощью шумомера и избегайте внезапных громких звуков.'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'Есть вопросы? 🤖', 'Даже поздно вечером вы можете задать нашему AI-помощнику Anacan такие важные вопросы, как «Как перейти на коровье молоко после 1 года?», и получить поддержку.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'Вопросы о здоровье малыша 🤖', 'Что меняется в питании ближе к 1 году? Не утруждайте себя — попросите у Anacan AI точный список, одобренный педиатрами.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'Поддержка друг друга 🥂', 'Чтобы сбросить с плеч усталость за весь день, выпейте чаю вместе с партнёром и скажите друг другу: «Мы и сегодня справились».'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'Полностью выполняет простые просьбы! 🧠', 'Малыш понимает вас, когда вы говорите: «Дай мне мяч» или «Иди сюда». Помогите ему развиваться дальше с помощью статей в Блогах.'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'Пытается есть своей ложкой! 🥄', 'Малыш уже берёт ложку и пытается поднести её ко рту? Чтобы поддержать эти весёлые попытки, выберите подходящие блюда в разделе «Прикорм для малышей».'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'Засыпание под сказку 🪄', 'Создайте в «Умных сказках» особый фон, состоящий только из музыки и звуков природы. Никаких слов — лишь спокойствие.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'Поцелуи, полные любви 🥰', 'Когда вы целуете малыша, он тоже наклоняется к вам, вытягивает губы или оставляет мокрый след на вашей щеке? Его маленькие поцелуи способны прогнать всю вашу усталость.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'Смешные гримасы папы 🤡', 'Лучший способ рассмешить малыша — дать папе издавать забавные звуки. Насладитесь сегодняшними весёлыми моментами всей семьёй.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'Хочется поделиться чувствами 💬', 'Мысль «Не могу поверить, что ему уже 1 год» вызывает у вас сильные эмоции? Поделитесь этим прекрасным чувством с мамами в Сообществе Anacan.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', 'До 1 года осталось всего 15 дней! 🎈', 'Нахлынула ностальгия! Помните тот первый день после выписки из роддома? А теперь вы уже готовитесь отмечать 1 год! Разместите в фотосессии малыша рядом его первый и сегодняшний снимки!'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'Всего 2 недели! 🎈', 'До дня рождения осталось всего 14 дней! Нахлынула ностальгия... Откройте фотосессию малыша, разместите рядом снимки в день рождения и сегодня и полюбуйтесь тем, как замечательно он вырос.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'Вечерняя обязанность папы 👨‍🍼', 'Дневной усталости с вас достаточно. Вечером подготовить малыша ко сну и прочитать ему сказку — задача папы. А вы просто наденьте наушники.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'Несколько секунд без опоры 🧗‍♂️', 'Стоя и держась за диван, малыш ненадолго отпускает руки? Он учится сохранять равновесие.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'Что же приготовить? 🍲', 'Закончились идеи для меню ближе к 1 году? Попросите у Anacan AI список простых продуктов для еды руками, которые ребёнок сможет самостоятельно брать и есть.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'Дружба с темнотой 🌙', 'Чтобы малыш быстрее засыпал, сделайте темноту частью вечернего ритуала. Выключите в комнате все лишние источники света и экраны.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'Присоединяется к разговору 🗣️', 'Пока вы говорите, малыш тоже что-то произносит на своём языке и повышает голос? Его навыки общения стремительно развиваются: теперь в комнате появился второй собеседник — обязательно выслушайте его!'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'Упрямые ночи 🥱', 'Малыш изо всех сил сопротивляется засыпанию? Возможно, пришло время отказаться от одного дневного сна. Пересмотрите режим.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'Проверим рост и прибавку веса! 📏', 'До осмотра в 1 год осталось совсем немного. Обновите последние данные в разделе отслеживания развития и с гордостью взгляните на график здорового роста.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'Башня из еды рухнула 🥣', 'Малыш намеренно бросает ложку на пол и смотрит на вас? Так он проверяет силу притяжения и вашу реакцию. Сохраняйте терпение — для него это своего рода игра.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'Сегодня в «Умной сказке» 🪄', 'Создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'Уборка или отдых? 🛋️', 'Когда малыш уснёт, не спешите к посудомоечной машине. Прилягте на диван, закройте глаза и просто подышите 15 минут. Вы же не робот.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'Детектив у шкафа 🕵️‍♀️', 'Все кастрюли на кухне оказались на полу? Игра с безопасными предметами развивает логическое мышление малыша. Позвольте ему свободно искать сокровища.'),
  ('11e743be-fb20-462f-8c74-07c143992d51', 'До 1 года осталось 10 дней! 🎂', 'Волнение нарастает! Праздничный торт, наряды, список гостей... Запишите всё в разделе специальных заметок Дневника настроения, чтобы упорядочить свои мысли.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'Разговор по душам между мамами 💬', 'Вас утомляют вопросы вроде «Почему мой малыш до сих пор не ходит?» Присоединяйтесь к Сообществу Anacan, и вы увидите, что каждый малыш развивается в своём темпе.'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'Выбираем первую обувь! 👟', 'Шаги становятся увереннее! Обязательно загляните в наш список Рекомендованных товаров, чтобы выбрать первую обувь, которая поддерживает правильное развитие стопы, с ортопедической конструкцией и мягкой подошвой.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'Меры безопасности дома! 🛡', '️ Когда малыш начинает самостоятельно ходить, опасностей становится больше. Ознакомьтесь с Рекомендованными товарами: детскими замками и воротами безопасности для лестниц.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'Ваше изменившееся тело 👗', 'Вы смотрите в зеркало на изменившиеся очертания тела и грустите? С помощью этого тела вы создали человека. Обнимите себя и вспомните, насколько вы сильны.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'Малыш ни на шаг не отпускает маму 🥰', 'Даже когда вы идёте в туалет, малыш ждёт за дверью и плачет. Тревога разлуки достигла пика. Каждый раз успокаивайте его словами: «Я здесь».'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'Иллюзия совершенства 🛑', 'Сегодня всё пошло не по плану? Не вините себя. Вы настоящая мама, а не отфильтрованная иллюзия из социальных сетей.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'Бесшумный герой 🤫', 'Как только малыш засыпает, любой звук в доме кажется взрывом. Установив допустимый уровень шума с помощью шумомера, старайтесь и сами ступать тише.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'Указательный пальчик в деле ☝️', 'Малыш показывает пальцем на предмет вдали и реагирует на него. Это важный этап развития совместного внимания. Посмотрите на этот предмет вместе с ним.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'Можно ли давать коровье молоко? 🥛', 'Ближе к 1 году рацион меняется. Если у вас есть вопросы о переходе на коровье молоко или о таких продуктах, как мёд, сразу задайте их Anacan AI.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'Семейная прогулка и планы! ☕', 'До дня рождения осталось совсем немного! Найдите в разделе «Места для мам» кафе, куда удобно заехать с коляской, чтобы встретиться с друзьями и семьёй.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, устройте вместе с партнёром сеанс массажа плеч, чтобы снять накопившийся за день стресс. Вы — команда!'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'Место для мамы ☕', 'Сидеть дома уже утомительно. Выберите в разделе «Места для мам» уютное кафе с детским меню и уделите немного времени себе.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'Интерес к книгам 📖', 'Включите бумажные книги в вечерний ритуал. Малыш уже пытается самостоятельно переворачивать страницы. Меняйте интонацию в соответствии с темпом сказки.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'Танцы под музыку 🎶', 'Стоит малышу услышать по телевизору ритмичную мелодию, как он начинает покачивать попой. У него развивается восприятие музыки — присоединяйтесь и проживите этот чудесный момент вместе.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'Забыли, какой грудью кормили? 🤱', 'Таймер Anacan запомнит за вас, какой грудью вы кормили — правой или левой. Запустите таймер кормления прямо сейчас!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'Завершение прекрасного дня. ✨', 'Вы невероятная мама и уже целый год совершаете настоящий подвиг! Напишите в Дневнике настроения, что гордитесь собой, и спокойно ложитесь спать.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', 'До 1 года всего 5 дней! 🎈', 'Обратный отсчёт почти завершён! Первый день рождения! Украшения, маленькие гости... Загляните в Сообщество Anacan и узнайте у других мам креативные идеи для празднования первого дня рождения.'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'Боль при прорезывании зубов 🦷', 'Дёсны снова покраснели, а слюнотечение не прекращается? Возможно, скоро появятся первые коренные зубы.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'Контроль уровня шума 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума с помощью шумомера и избегайте внезапных громких звуков.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'Ответы с помощью языка тела 🗣️', 'Когда вы спрашиваете: «Пойдём?», малыш поднимает руки, а услышав «Нет», качает головой. Его способность понимать речь выросла невероятно!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'Свежий воздух — настоящее спасение 🌳', 'Если дома назревает истерика, проверьте погоду, подберите подходящую одежду, посадите малыша в коляску и сразу отправляйтесь в парк. Природа поможет ему успокоиться быстрее всего.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'Строит башню из кубиков 🧱', 'Малыш пытается поставить друг на друга два или три игрушечных кубика. Молча наблюдайте за его маленькими инженерными экспериментами и аплодируйте успехам.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'Сегодня вас всё раздражало? 📝', 'Когда малыш уснёт, запишите свои чувства в Дневнике настроения. Завтра будет новый и более прекрасный день.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'Вспомните с партнёром первые дни и посмейтесь вместе.', 'Этот первый год дался вам нелегко! Это ваша общая командная победа.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'До большого дня осталось 2 дня! 🗣', '️ Самый прекрасный подарок — услышать, как малыш называет вас мамой или папой. Прочитайте рекомендации в Блоге, чтобы поддержать развитие первых слов.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке при тусклом освещении.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'Переход ко сну со сказкой 🪄', 'Создайте в «Умных сказках» особый фон, состоящий только из музыки и звуков природы. Никаких слов — лишь покой и предвкушение сна.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'Последние приготовления 📸', 'Свечи, торт и наряды готовы? Освободите память телефона — завтра для фотосессии малыша понадобится много места!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'Завтра малышу 1 год! 🎉', 'Время предаться воспоминаниям! Помните тот первый день, когда вы вышли из роддома? Откройте дневник настроения и сегодня вечером напишите малышу трогательное письмо, которое он прочитает в будущем.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'Танец победы 💖', 'Сегодня вечером при свечах отметьте вместе с супругом усталость и гордость, накопившиеся за 1 год. Вы — идеальная команда!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'ОДИН ГОД! ПЕРВЫЙ ДЕНЬ РОЖДЕНИЯ! 🎂🎉', 'ВЫ ПОТРЯСАЮЩАЯ! Ровно 365 дней, бессонные ночи, первый смех, первые шаги! Малышу уже 1 год! Откройте фотосессию малыша и запечатлейте этот исторический день в самых прекрасных кадрах!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'Поаплодируйте себе 👏', 'Малыш рос 9 месяцев у вас под сердцем и 1 год у вас на руках! Сегодня день рождения не только малыша, но и вашего Материнства. Гордитесь собой!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'Начинается период раннего детства 🌟', 'Младенчество осталось позади! Теперь малыш официально заявляет о своей самостоятельности и хочет всё делать сам. Начинается новое приключение, полное терпения и любви!'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'Время умной сказки 🪄', 'Продолжайте привычный ритуал: создайте в «Умных сказках» историю о подросшем герое, которому уже исполнился 1 год и который исследует мир.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'Капризы меняются 🛑', 'Начались новые приступы гнева — например, малыш падает на пол? Он пока не умеет справляться со своими чувствами. Присядьте, чтобы оказаться с ним на одном уровне, и спокойно поговорите — так вы поможете ему преодолеть кризис.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'Контроль уровня шума 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте обстановку с помощью шумомера и избегайте внезапных громких звуков.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'Настойчивость с ложкой 🥄', 'Малыш хочет сам держать ложку и есть пюре. Он будет проливать и пачкаться, но это очень важно для развития моторики. Позвольте ему пробовать.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'Потребность в энергии 🍲', 'Темп жизни становится всё быстрее. Выберите среди полезных рецептов богатый железом и белком обед, который придаст вам сил и энергии.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения только на себя. Разбудите супруга: быть командой — значит поровну делить ответственность.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'Первые самостоятельные шаги? 🧗‍♂️', 'Может быть, сегодня, а может, завтра... Малыш уже пытается сделать один-два шага без опоры. Будьте готовы отметить это в трекере развития!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'Разведка погоды ⛅', 'Собираясь на прогулку, не оценивайте погоду только по виду из окна. Инструмент «Погода и одежда» мгновенно подскажет вам скорость ветра и подходящий комплект одежды.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'Ночная смена папы 👨‍🍼', 'Во время ночных пробуждений вставайте по очереди: один раз вы, другой — ваш партнёр. Иногда малыша лучше всего успокаивают именно ритмичные поглаживания папы.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'Кто займётся домашними делами? 🌪️', 'Домашние дела не сделаны? Пусть подождут. Попросите партнёра сегодня взять их на себя, а сами отдохните.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'Дневник эмоций 📝', 'Когда вам одиноко, излейте свои чувства в Дневнике настроения. Все женщины проходят через это, и вы сильная.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'Как отучить от пустышки/бутылочки? 🍼', 'Думаете о том, чтобы после 1 года отучить малыша от пустышки? Спросите у мам в Сообществе Anacan о самых мягких способах сделать это.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'Свежий воздух — лучшее лекарство 🌳', 'Малыш весь день плакал и капризничал? Решение может быть очень простым: проверьте погоду, оденьте его по погоде, посадите в коляску и сразу отправляйтесь в парк.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'Мы — одна команда! 💖', 'После трудного дня сядьте с партнёром лицом к лицу и поделитесь переживаниями. Взаимная поддержка помогает разделить груз забот пополам.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'Проверка развития 🤖', 'Нужна информация о двигательных навыках малыша в 12 месяцев? Попросите Anacan AI составить краткий, точный и одобренный педиатрами список.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'Геометрические фигуры и развивающие игры! 🧩', 'Малыш пытается вставить круг или квадрат в подходящие отверстия. Сохраните эти познавательные открытия в Альбоме малыша.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'Витамины для мамы 🥑', 'Вы делаете всё, чтобы малыш был сыт. А как же вы? В разделе полезных рецептов выберите лёгкий обед, богатый железом и кальцием.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'Меняется дневной сон? 🥱', 'Малыш совсем отказывается от одного из двух дневных снов? После 1 года может начаться переход на один дневной сон. Постепенно скорректируйте режим.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'Засыпаем со сказкой 🪄', 'Придумайте в Умных сказках историю о смелых и милых животных и превратите комнату в волшебное место.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома яркий свет и все экраны. Мелатонин вырабатывается только в спокойной обстановке с приглушённым освещением.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'Туман в голове 🛒', 'Забывчивость всё ещё не проходит? Не держите в голове мелкие покупки для дома — сразу добавьте их в Список покупок, а партнёр пусть с ними разберётся.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'Броски в цель ⚾', 'Малыш намеренно пытается бросить игрушку в определённую цель. Зрительно-моторная координация быстро развивается. Бросайте и ловите мяч вместе.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'Доступ к опасным местам ⚡', 'Малыш подрос и теперь дотягивается до полок, которые раньше были ему недоступны. Срочно проверьте безопасность дома ещё раз.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'Ночная тишина 🤫', 'Если малыша беспокоит шум машин или другие звуки с улицы, обязательно проверьте уровень шума с помощью Шумомера и включите белый шум в качестве фона.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'Разбрасывает всё, с чем играет.  🌪️', 'Сейчас важнее не уборка, а ваш отдых. Игрушки и завтра останутся на месте, а малышу уже сегодня нужна бодрая мама.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'Оставьте всю усталость позади.', 'Сегодня вечером, когда малыш уснёт, не забудьте вместе с партнёром отпраздновать вашу командную победу!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'Не сравнивайте себя с другими 🛑', 'Забудьте фразу «А вот чей-то ребёнок заговорил раньше». У каждого малыша свой уникальный темп развития. Просто дарите ему свою любовь.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', 'На пути к 1 году и половине месяца! 📸', 'Ему уже 12.5 месяцев! Откройте фотосессию малыша и сохраните на фотографиях самые забавные моменты этого активного и бурного периода детства.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'Веселье во время еды! 🥦', 'Если малыш отказывается от еды, загляните в раздел рецептов для малышей, начинающих прикорм, и приготовьте яркие, привлекательные порции.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'Узнаёт части тела 👀', 'Когда вы спрашиваете: «Где глазки?», малыш касается их пальцем и показывает? Сейчас его познавательные способности на пике! С гордостью отметьте это в трекере развития.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'Вы делаете всё возможное! 💖', 'Воспитание ребёнка похоже на марафон. Сегодня вечером уделите немного времени себе: посмотрите любимый фильм или просто отдохните.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', 'Упрямое «Я буду есть сам!» 🥦', 'Малыш хочет забрать у вас ложку. Позвольте ему. Он испачкается, но это ощущение самостоятельности очень важно для него.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'Дружба с темнотой 🌙', 'Чтобы малыш быстрее засыпал, добавьте в вечерний ритуал знакомство с темнотой. Выключите в комнате все дополнительные источники света.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'Подозрение на аллергию 🤖', 'После 1 года вы начали вводить новые продукты? Если что-то вызывает беспокойство, сразу узнайте у Anacan AI, какие шаги предпринять в первую очередь.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'Развивается мелкая моторика. 🖍', '️ Малышу может понравиться рисовать карандашом на бумаге. Дайте ему подходящие толстые мелки и наблюдайте за его творчеством.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'Ритуал сна даёт чувство безопасности. 🌙', 'Одинаковая последовательность действий каждый вечер (ванна, сказка, приглушённый свет) поможет малышу легче заснуть.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'Боль при прорезывании зубов 🦷', 'Дёсны снова покраснели, а слюнотечение не прекращается? Отметьте этот процесс в трекере прорезывания зубов и подготовьте охлаждённые прорезыватели.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'Список спасает 🛒', 'Закончились фрукты или овсянка? Сразу заполните список покупок и отправьте его на телефон партнёра.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'Ходит, держась за стену 🧗‍♀️', 'Ходить боком вдоль мебели — его любимое упражнение. До самостоятельных шагов осталось совсем немного! Загляните в трекер развития.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'Контроль уровня шума 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте обстановку с помощью шумомера и избегайте внезапных громких звуков.'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'Хочется выговориться 💬', 'Вас пугают рассказы о том, что после года становится сложнее? Напишите в Сообществе Anacan и почитайте реальные позитивные истории мам.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'Спокойствие ночи 🛀', 'Тёплая ванна, массаж и приглушённый свет в комнате. Соблюдение ритуала перед сном — главный секрет спокойных ночей без пробуждений.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'Выполняет простые просьбы 🧸', 'Когда вы просите принести мяч, малыш действительно находит и приносит его? Сейчас его способность понимать слова активно развивается! Чаще вовлекайте его в игры.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'Выбор первой обуви 👟', 'Малыш готовится ходить, но нужно ли ему носить обувь дома? Спросите Anacan AI об обуви для первых шагов и пользе ходьбы босиком.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'Список очень выручает 🛒', 'После 1 года меню меняется. Нужно купить домой коровье молоко или другие продукты? Сразу заполните список покупок и отправьте его партнёру.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'Уделите время себе. 🛁', 'Весь день бегать за малышом, который уже ходит, непросто. Запишите свои чувства в Дневник настроения, чтобы снять напряжение, и отдохните.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'Листает книги 📖', 'Малыш уже самостоятельно переворачивает страницы книг из плотного картона и реагирует на картинки? Чаще читайте ему красочные книги со сказками.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'Первые самостоятельные шаги! 🧗‍♂', '️ Малыш отпускает мебель, стоит самостоятельно и, возможно, делает тот самый долгожданный первый шаг! Не упустите этот незабываемый исторический момент и сразу загрузите видео в Альбом малыша.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'Музыкальные вечера 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую песню, обнять малыша и потанцевать вместе с ним.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'Нужна тишина 🤫', 'Следите за тишиной в комнате с помощью Шумомера. Прерванный ночной сон испортит утреннее настроение и малыша, и ваше.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', 'Сила слова «нет» 🛑', 'Когда вы что-то предлагаете, малыш уже умеет качать головой в знак отказа! Это не упрямство, а способ выразить своё мнение. Предлагайте ему варианты выбора, чтобы помочь успокоиться.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'Логические игры 🧩', 'Малыш складывает игрушки в коробку, а затем высыпает их все обратно? Так он осваивает понятия «внутри» и «снаружи» и развивает логику. Не мешайте ему заниматься этим.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'Здоровая мама 🥑', 'Если малыш наелся, теперь ваша очередь. Выберите полезный и питательный перекус из Здоровых рецептов и полежите на диване хотя бы 10 минут.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'Интерес к лестницам 🧗‍♂️', 'Малышу уже недостаточно ходить по полу, и он пытается взбираться по лестнице и на мебель? Двигательные навыки развиваются полным ходом! Обязательно следите за ним.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'Волшебный час сказок 🪄', 'Добавьте красок в вечерний ритуал с историей «Секреты засыпания самого маленького героя» из Умных сказок.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'Капризы на пике ☁️', 'Малыша ничто не радует, и он плачет по любому поводу? Возможно, у него прорезываются задние коренные зубы. Подготовьте охлаждённые прорезыватели.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'Парк или дом? ⛅', 'Хотите выйти на прогулку, но на улице ветрено? Помощник по погоде и одежде мгновенно подскажет, что лучше надеть.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'Непростые ночи 🥱', 'Малыш изо всех сил сопротивляется сну? Пересмотрите режим дневного сна и вечерние ритуалы.'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'Конец дня — ваше время. 🛁', 'Вы сегодня очень устали? Примите тёплый душ, отдохните и поблагодарите себя за всё, что сделали.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'Изучаем части тела! 👃', 'Показывает ли малыш пальчиком на нос, когда вы спрашиваете: «Где твой носик?» Превратите эти милые открытия в игру перед зеркалом и повеселитесь вместе.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'Время полезного перекуса. 🍎', 'Для неугомонных малышей отлично подойдут ломтики фруктов или овощные палочки. Позвольте малышу брать их и есть самостоятельно.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'Маленький художник за работой! 🖍', '️ Дайте малышу толстые мелки и позвольте свободно рисовать каракули на листе бумаги. Это очень полезно для мелкой моторики и творческого развития.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'Свежий воздух пойдёт на пользу вам обоим. 🌳', 'Найдите на нашей карте «Места для мам» новый парк, где удобно гулять с коляской, и отправляйтесь на прогулку.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'Ритуал сна дарит чувство безопасности. 🌙', 'Одинаковая последовательность действий каждый вечер (ванна, сказка, приглушённый свет) поможет малышу быстрее заснуть.'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'Мы — одна команда! 💖', 'После трудного дня сядьте рядом с партнёром и поговорите по душам. Взаимная поддержка помогает разделить нагрузку пополам.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'Малыш понимает значение слов 🗣️', 'Когда вы просите принести мяч, малыш действительно идёт его искать. Словарный запас быстро растёт. Говорите с малышом более сложными предложениями.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'Список у вас в кармане 🛒', 'В повседневной суете трудно вспомнить, что закончилось — шампунь или подгузники? Не держите всё в голове: добавьте нужное в список покупок и синхронизируйте его с партнёром.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'Большие эмоции в маленьком теле. 🌪', '️ Когда малыш не может выразить себя, вполне нормально, что он сердится и плачет. Присядьте, чтобы оказаться на одном уровне с ним, и спокойным голосом скажите, что понимаете его чувства.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'Игры с водой успокаивают. 💧', 'Наполните небольшой таз водой и положите туда пластиковые ёмкости. Игры с водой помогают малышам выплеснуть энергию и расслабиться.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'Есть вопрос? 🤖', 'Даже ночью вы можете задать нашему помощнику Anacan AI такие важные вопросы, как «Как справиться с кризисом 1 года?», и получить экспертный совет.'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'Кадр, остановивший время 📸', 'С каждым днём малыш становится немного взрослее. Откройте фотосессию малыша прямо сейчас и сохраните этот искренний момент в памяти.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома яркий свет и все экраны. Мелатонин вырабатывается только в спокойной обстановке.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения на себя. Будите и партнёра: быть командой — значит поровну делить ответственность.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'Мамы делятся переживаниями 💬', 'Не справляетесь с истериками? Скорее присоединяйтесь к Сообществу Anacan, почитайте поддерживающие комментарии других мам и почувствуйте облегчение.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'Большие эмоции в маленьком теле 🛑', 'Малыш бросается на пол, когда не получает желаемого? Присядьте, чтобы оказаться с ним на одном уровне, и спокойно поговорите — так вы поможете ему справиться с кризисом.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'Потребность в тишине 🤫', 'Поддерживайте тишину в комнате с помощью Шумомера. Прерванный ночью сон портит утреннее настроение и малыша, и ваше.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'Место для мамы ☕', 'Сидение дома лишило вас сил. Выберите уютное кафе в разделе «Места для мам», где можно спокойно посидеть, и уделите время себе.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'Танцы и ритмы 🎶', 'Малыш начинает танцевать, едва услышав ритмичную мелодию по телевизору или телефону? Его музыкальное восприятие уже активно развивается — присоединяйтесь и танцуйте вместе!'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'Первые попытки одеваться самостоятельно. 👕', 'Малыш уже пытается самостоятельно снять или надеть носки? Терпеливо поддерживайте развитие его мелкой моторики.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'Пить воду очень важно. 💧', 'Активные дети быстро начинают испытывать жажду. Не забывайте предлагать малышу воду в течение дня, особенно после ужина.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'Нужна новая игрушка? 🛒', 'Если вы ищете развивающие игрушки, соответствующие возрасту малыша и стимулирующие его мышление, загляните в наш список Рекомендуемых товаров.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'Уборка или отдых? 🛋️', 'Когда ребёнок уснёт, не спешите к посудомоечной машине. Прилягте на диван, закройте глаза и просто подышите 15 минут.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'Метод проб и ошибок 🧱', 'Малыш пытается поставить два игрушечных кубика друг на друга, но они падают. Тогда он внимательно пробует снова. Просто тихо наблюдайте за его инженерными экспериментами.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'Дневник эмоций 📝', 'Когда почувствуете себя одиноко, доверьте свои чувства Дневнику настроения. Все женщины проходят через это — вы сильная.'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'Вечерняя сказка творит чудеса. 📖', 'Короткая история перед сном не только развивает воображение малыша, но и укрепляет эмоциональную связь между вами.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'Умение играть самостоятельно. 🧩', 'Если малыш может хотя бы недолго играть самостоятельно, это говорит о развитии его внимания. В такие моменты с любовью наблюдайте за ним издалека.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'Следим за ростом. 📏', 'Одежда вашего ребёнка становится мала? Добавьте новые показатели в раздел «Трекер веса», чтобы отмечать его здоровое развитие.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'Подражание взрослым 🧹', 'Пока вы убираете дом, малыш тоже берёт тряпку и пытается повторять за вами? Он словно зеркало! Он копирует всё, что вы делаете.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'Время самостоятельной игры 🧸', 'Малыш уже может 10-15 минут самостоятельно играть со своими игрушками. Присматривайте за ним со стороны и наслаждайтесь тишиной.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'Разведка погоды ⛅', 'Не уверены, какая погода на улице? Инструмент погоды и одежды мгновенно подскажет вам скорость ветра и подходящий комплект одежды.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения только на себя. Разбудите партнёра: быть командой — значит делить ответственность поровну.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'Я сам нахожу свою игрушку 🧸', 'Малыш находит игрушку там, где вы спрятали её у него на глазах? Значит, он уже понимает, что предметы продолжают существовать, даже когда их не видно!'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'Ваш маленький помощник! 🧹', 'Подражая вам, малыш берёт салфетку и пытается вытирать пыль? Обязательно сохраните эти милые и познавательные моменты на будущее, добавив видео в Альбом малыша.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'Спокойствие под музыку. 🎶', 'Вечером вместо активных игр послушайте вместе спокойную музыку, чтобы подготовить малыша ко сну, а себя — к отдыху.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'Избирательность в еде. 🍲', 'Если малыш отказывается от некоторых продуктов, не волнуйтесь. Предлагайте их снова в разные дни и в разном виде (например, не как пюре, а кусочками, которые можно брать руками).'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'Башни растут! 🧱', 'Малыш уже умеет ставить 3-4 кубика друг на друга. Поддержите его похвалой: такая игра требует внимания и хорошей зрительно-моторной координации.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'Время общаться. 👶', 'Малыш внимательно наблюдает за другими детьми в парке? Даже если они пока не играют вместе, игра рядом друг с другом (параллельная игра) — первый большой шаг к социализации.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'Малыш понимает тон вашего голоса 🗣️', 'Когда вы серьёзным голосом говорите «нет», малыш останавливается и смотрит на вас? Он уже начинает понимать эмоции и запреты!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', 'В предвкушении 400-го дня! 🌟', 'Завтра большой, четырёхсотый день! Уже больше 1 года и 1 месяца! Создайте дома атмосферу маленького праздника и освободите память на телефоне.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, устройте вместе с партнёром сеанс массажа плеч, чтобы снять накопившийся за день стресс. Вы — команда!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'Вечер прощения себя 📝', 'Сегодня вас всё раздражало? Когда малыш уснёт, запишите свои чувства в Дневник настроения. Завтра будет новый и ещё более прекрасный день.'),
  ('165064a6-acf5-4848-b342-4a3782635921', 'Невероятные 400 дней! 🎉', 'Поздравляем! Вот уже ровно 400 дней вы вместе проходите этот бурный путь! Обязательно отпразднуйте этот особенный день прямо сейчас!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'Продолжаем есть самостоятельно. 🥄', 'Даже если малыш испачкается с ног до головы, позвольте ему пробовать есть своей ложкой. Это развивает его уверенность в себе и координацию движений.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'Вы лучше всех! ✨', 'Ваша самоотдача на протяжении 400 дней бесценна. А теперь глубоко вдохните, откиньтесь назад и спокойно отдохните.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'За пределы четырёх стен ⛅', 'Малыш не может выплеснуть энергию дома и капризничает? Природа — лучшее успокоительное. Проверьте погоду, подберите подходящую одежду и сразу отправляйтесь в парк.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'Время игр с папой 👨‍👧', 'Вы весь день бегали за малышом и совсем выбились из сил. Теперь пора включить режим партнёра. Пусть папа возьмёт на себя игры с кувырками и катанием на спине. А вы отдохните.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'Марафон по комнатам 🏃‍♂️', 'Ходьбы малышу уже недостаточно — начались забеги из комнаты в комнату! Он всё увереннее держит равновесие стоя. Отметьте эту большую победу крупной моторики в трекере развития.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'Диктатор меню 🥣', 'Сегодня малыш отодвигает еду, которую любил ещё вчера? Избирательность в питании после 1 года — это нормально. Не паникуйте и поищите другие варианты в разделе «Полезные рецепты».'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', 'Период «Что это?» ☝️', 'Малыш показывает на всё пальцем и издаёт особый звук. Так он просит вас называть предметы окружающего мира. Терпеливо произносите название каждого предмета, на который он показывает.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'Отпустите чувство вины 📝', 'Сегодня я мало читала малышу, он слишком долго смотрел на экран... Заглушите эти голоса! Вы делаете всё, что в ваших силах. Оставьте в дневнике настроения добрую и бережную запись для себя.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'Переход на один дневной сон 🥱', 'Малыш не хочет ложиться на утренний сон, и весь график сбился? Он растёт! Возможно, начался переход от двух дневных снов к одному. Постепенно скорректируйте режим.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'Волшебная комната 🪄', 'Создайте в «Умных сказках» особую историю о смелом герое, который исследует мир. Пусть эта милая сказка поможет малышу легче настроиться на ночной сон.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'Новое место для мамы ☕', 'Вид одних и тех же стен дома вас утомил. Найдите в разделе «Места для мам» кафе с детским игровым уголком. Пусть малыш играет, а вы наслаждайтесь кофе.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'Читайте книги вместе. 📖', 'Малыш уже хочет сам переворачивать страницы. Книги с плотными страницами и аудиосказки идеально подходят для этого периода.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'Проверяет границы. 🛑', 'Несмотря на ваше «нет», малыш смотрит вам прямо в глаза и снова тянется к этому предмету? Это не упрямство, а лишь способ проверить и понять границы. Будьте терпеливы и последовательны.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'Ночные пробуждения. 😴', 'Прорезывание зубов или скачок роста могут нарушить сон. При необходимости следите за таймером сна и отмечайте изменения в режиме.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'Папины объятия успокоят 🫂', 'Обязательно сменяйте друг друга во время ночных пробуждений. Иногда в темноте именно ритмичные поглаживания и запах папы мгновенно успокаивают малыша.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'Маленькое зеркало взрослых 🧹', 'Пока вы убираете дом, малыш тоже берёт тряпочку и пытается повторять за вами. Он — ваша маленькая копия! Дайте ему безопасный предмет и позвольте участвовать в домашних делах.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'Борьба с забывчивостью 🛒', 'Память снова вас подвела? Сразу добавляйте в список покупок любую мелочь, которая закончилась дома, чтобы ваш партнёр купил её по пути с работы.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'Логические игры 🧩', 'Малыш складывает игрушки в коробку, а затем высыпает их все обратно? Так он осваивает понятия «внутри» и «снаружи». Спокойно наблюдайте за его повторяющимися попытками.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'Сила вечернего ритуала 🛀', 'Тёплая ванна всегда помогает. Старайтесь не нарушать вечерний ритуал, ведь он даёт мозгу малыша чёткий сигнал о том, что пора спать.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'Восстановите силы 🥑', 'Малыш сыт — теперь ваша очередь. В ежедневной суете не обедайте на ходу. Выберите полезный и питательный перекус и немного отдохните на диване.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'Хочется выговориться 💬', 'Мысль «Почему мой ребёнок так делает?» не даёт вам покоя? Присоединяйтесь к Сообществу Anacan, почитайте похожие истории других мам и почувствуйте облегчение.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'Юный любитель книг 📖', 'Малыш листает книги с плотными страницами и реагирует на картинки? Так развивается зрительная память. Чаще читайте ему красочные книги со сказками.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'Время с вами прекрасно. ✨', 'Каждый день для малыша — новое приключение. Пока он спит, посмотрите на его маленькие ручки и улыбнитесь, вспоминая сегодняшние небольшие успехи.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'Хочу есть самостоятельно 🥄', 'Малыш забирает у вас ложку и хочет есть сам. Он будет ронять еду и пачкаться, но это важно для развития моторики. Позвольте ему проявлять самостоятельность.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'Есть вопрос? 🤖', 'Если вас беспокоят вопросы о поведении или развитии ребёнка в 13-14 месяцев, вы можете сразу получить совет от нашего помощника Anacan AI.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'Выплеснуть энергию! 🏃‍♂', '️ Перед дневным сном поиграйте с малышом в активные игры, которые помогут ему немного устать, например в догонялки или мяч. Так ему будет легче уснуть.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'Режутся коренные зубы? 🦷', 'Дёсны опухли, а малыш грызёт всё подряд? Возможно, у него режутся задние зубы. Положите охлаждающие прорезыватели в морозильную камеру.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'Приглушите свет 🌙', 'За 1 час до сна выключите яркий свет и все экраны в доме. Мелатонин вырабатывается только в спокойной обстановке с приглушённым освещением.'),
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c', 'Доступ к опасным местам ⚡', 'Малыш подрос и теперь дотягивается до полок, которые раньше были недоступны. Тумба под телевизором, острые углы... Срочно заново проверьте безопасность дома.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'Внезапные пробуждения 😭', 'Малыш просыпается среди ночи с криком и никак не успокаивается? Дайте функции «Анализ плача» послушать его голос, чтобы выяснить возможную причину.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'Темпы роста. 📏', 'Вы замечаете, как быстро растёт малыш, даже по его одежде. Записывайте показатели веса и роста в трекере, чтобы следить за его здоровым развитием.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'Сильные эмоции в маленьком теле 🛑', 'Малыш бросается на пол, когда не получает желаемого? Это знаменитые истерики раннего детского возраста. Сохраняйте спокойствие, установите с ним зрительный контакт и покажите, что вы рядом.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'Карманный педиатр 🤖', 'Нужна информация о скачках развития в 13.5 месяцев? Не тратьте силы на поиски — попросите у Anacan AI точный список, одобренный педиатрами.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'Выполняет простые просьбы 🧸', 'Просите малыша принести обувь, и он действительно приносит её? Его словарный запас и способность понимать речь сейчас активно развиваются! Чаще вовлекайте его в игры.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'Папа-весельчак 🤡', 'Лучший способ рассмешить малыша — это забавные звуки, которые издаёт папа. Наслаждайтесь сегодняшними весёлыми моментами вместе с ребёнком.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'Вечерний ритуал помогает подготовиться ко сну. 🌙', 'Небольшие привычные действия, которые каждый день выполняются в одно и то же время (чистка зубов, чтение сказки), значительно облегчают засыпание.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'Любознательный исследователь! 🔍', 'Каждый уголок и каждый шкаф в доме — это для малыша новый мир. Создайте безопасную обстановку и позвольте ему свободно исследовать дом.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'Свежий воздух и море энергии! 🌳', 'Активные игры на свежем воздухе помогают детям легче уснуть днём. Отправляйтесь вместе в парк.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'Хочет есть самостоятельно. 🥦', 'Даже если малыш испачкается, позвольте ему самому держать ложку. Это поможет развить самостоятельность и зрительно-моторную координацию.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'Вы заслуживаете отдыха. 🛁', 'Вы весь день были на ногах. Когда ребёнок уснёт, налейте себе горячего чая и просто насладитесь тишиной.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'Быстрые шаги! 🏃‍♂', '️ Малыш уже свободно ходит из комнаты в комнату и даже пытается бегать. Успевать за ним — настоящая тренировка для мам!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'Где глазки? 👀', 'Игра на изучение частей тела по-прежнему остаётся одной из любимых. Играйте перед зеркалом, чтобы сделать её ещё веселее.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'Планирование помогает расслабиться. 📝', 'Продумайте дела или меню на завтра, сделайте небольшие заметки и ложитесь спать со спокойной душой.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'В поисках уютного отдыха. ☕', 'Иногда хочется выйти из дома и сменить обстановку. Найдите поблизости в разделе «Места для мам» кафе, куда удобно прийти с ребёнком, и насладитесь чашечкой кофе.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', 'Любит говорить «нет»? 🛑', 'Подражая вашим возражениям, малыш тоже может на всё отвечать «нет». В этот период важно сохранять терпение и предлагать ему несколько простых вариантов на выбор.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'Превратите питьё воды в весёлое занятие. 💧', 'Регулярно предлагайте малышу воду в яркой бутылочке, чтобы после активных игр его организм не страдал от обезвоживания.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'Время папиных сказок. 👨‍🍼', 'Сегодня поручите папе прочитать вечернюю сказку и уложить малыша спать, а сами устройте себе небольшую передышку.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'Сила белого шума. 🎶', 'Если после активного дня малыш не может уснуть, включите в разделе «Белый шум» звуки океана или дождя, чтобы создать в комнате спокойную атмосферу.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'Нежные объятия! 🤗', 'Когда малыш неожиданно обнимает вас и пытается поцеловать, так он выражает свою любовь. Наслаждайтесь этими неповторимыми мгновениями нежности!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'Вовлекайте малыша в разговор. 🗣', '️ Называйте предметы в комнате и просите малыша повторять за вами. Именно такие простые игры помогают пополнять словарный запас.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'Спокойствие ночи 🛀', 'Тёплая ванна, массаж и приглушённый свет в комнате. Соблюдение ритуала перед сном — главный секрет спокойных ночей без пробуждений.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'Танцы под музыку 🎶', 'Как только малыш слышит ритмичную музыку по телевизору, сразу начинает пританцовывать. У него развивается восприятие музыки — присоединяйтесь и танцуйте вместе!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8'::uuid, 'Разговоры по душам с мамами 💬', 'Чувствуете, что недостаточно хорошо справляетесь? Загляните в Сообщество Anacan, прочитайте добрые комментарии других мам и почувствуйте их поддержку.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'Открывайте новые места. ☕', 'Устали от повседневной рутины? Найдите в нашем приложении кафе, куда удобно зайти с детской коляской, и устройте себе перерыв на чашечку кофе.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'Помощник по дому! 🧹', 'Малыш берёт тряпочку и пытается вытирать пыль или хочет поиграть с веником? Подражание вам — прекрасный показатель его развития.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'Есть вопросы о развитии малыша? 🤖', 'Если вас что-то беспокоит в период 13-14 месяцев, напишите нашему помощнику Anacan AI даже поздно ночью.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'Дневник эмоций 📝', 'Когда вам одиноко, поделитесь своими чувствами в Дневнике настроения. Все женщины проходят через это, и вы сильная.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'Потребность в тишине 🤫', 'Поддерживайте тишину в комнате с помощью Шумомера. Прерывистый ночной сон портит утреннее настроение и малыша, и ваше.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'Машем «пока-пока» 👋', 'Когда кто-то выходит за дверь, малыш уже сам машет рукой на прощание! Это прекрасный социальный навык. Обязательно поощряйте его.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'Не стесняйтесь спрашивать 🤖', 'Думаете, что допускаете ошибки в ритуале перед сном? Сразу задайте Anacan AI любой волнующий вас вопрос и развейте свои сомнения.'),
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f', 'Ночные пробуждения продолжаются? 😴', 'Если в последние дни сон малыша снова нарушился, проанализируйте график с помощью таймера сна Anacan и найдите пробелы в режиме.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', 'Скоро 14 месяцев! Осталось 10 дней! 🎂', 'Невероятно! Ровно через 10 дней малышу исполнится 14 месяцев. С каждым днём он становится всё более самостоятельным.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'Первые опыты с карандашами. 🖍', '️ Дайте малышу подходящие толстые карандаши и с любовью наблюдайте, как он рисует каракули на бумаге. Возможно, у вас растёт будущий художник!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'Самостоятельная игра с игрушками. 🧩', 'Умение играть самостоятельно, пусть даже недолго, — большой шаг к независимости. Наблюдайте за малышом со стороны.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'Продолжаем расти. 📏', 'Одежда вашего малыша становится мала! Добавьте новые показатели роста и веса в раздел «Трекер развития», чтобы следить за его развитием.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'Как справиться с избирательностью в еде. 🍲', 'Иногда малыш может отказаться даже от любимого блюда. Не заставляйте его есть, а просто предложите другие варианты.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'Вечерняя ванна. 🛁', 'Тёплая ванна не только поможет весело смыть накопившуюся за день пыль и грязь, но и расслабит малыша, прекрасно подготовив его ко сну.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'Узнаёт части тела. 👃', 'Поиграйте в игру «Где твой нос?» или «Где твоё ухо?». Когда малыш показывает правильно, похвалите его аплодисментами.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'Вы лучшая! 💖', 'Воспитание ребёнка похоже на марафон. Сегодня вечером уделите немного времени себе: посмотрите любимый фильм или просто спокойно отдохните.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'Тянет за собой игрушки! 🧸', 'Игрушки на верёвочке и небольшие тележки, которые можно толкать, теперь могут стать его любимым развлечением. Это отличная тренировка равновесия!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'Позаботьтесь и о своём питании. 🥗', 'Успевать за энергичным ребёнком непросто. Приготовьте вкусное и богатое витаминами блюдо по одному из полезных рецептов для женщин, чтобы восполнить силы.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', 'Упрямое «Я сам!». 🧦', 'Если малыш пытается самостоятельно надеть носки или поесть, не мешайте ему. Чувство самостоятельности развивается именно благодаря таким маленьким попыткам.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'Эмоциональная разрядка. 📝', 'Иногда всего становится слишком много. Запишите в Дневнике настроения свои переживания и усталость, чтобы снять накопившийся за день стресс.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'Открытия на свежем воздухе. 🌳', 'Прикосновения к листьям и собирание камешков в парке развивают органы чувств малыша. Выберите для прогулки новый парк.'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'Не забывайте пить воду. 💧', 'Это важно и для малыша, и для вас! Обязательно пейте воду после активных игр и между приёмами пищи, чтобы поддерживать водный баланс организма.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'Маленький помощник за работой! 🧹', 'Малыш подражает вам, берёт тряпочку и вытирает пыль или играет с веником? Дети лучше всего учатся, наблюдая за другими.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'Изменился режим сна? 😴', 'Если малыш начинает переходить на один дневной сон, в переходный период продолжительность ночного сна может увеличиться. Отслеживайте график последних дней с помощью таймера сна.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'Время для самостоятельной игры 🧸', 'Теперь малыш уже может самостоятельно играть с игрушками в течение 10-15 минут. Это признак того, что он способен дольше удерживать внимание. Насладитесь тишиной.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'Понимает тон вашего голоса 🗣️', 'Когда вы серьёзным голосом говорите «нет», малыш останавливается и смотрит на вас? Значит, он уже начинает понимать эмоции и запреты!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'Сила музыки 🎶', 'Попробуйте успокоить внезапные беспричинные вечерние капризы с помощью лёгкой классической музыки. Часто этот простой приём творит чудеса.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'Красочные каракули! 🖍', '️ Выделите малышу уголок в комнате и дайте ему толстые мелки и большой лист бумаги. Не забудьте сохранить его первые произведения искусства в Альбоме малыша!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'Нужна поддержка эксперта? 🤖', 'Задавайте нашему помощнику Anacan AI даже ночью такие вопросы, как «Как развивать речь ребёнка в 14 месяцев?».'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'Пора обновить меры безопасности. 🛡', '️ По мере того как малыш начинает самостоятельно ходить и открывать шкафы, опасностей становится больше. Загляните в наш список рекомендуемых товаров и выберите детские замки.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'Время полезного перекуса. 🍎', 'Для малышей с неиссякаемой энергией отлично подойдут ломтики фруктов или овощные палочки. Позвольте малышу брать их руками и есть самостоятельно.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', 'Период «Что это?». ☝', '️ Малыш показывает на всё пальцем и спрашивает, как это называется. Терпеливо называйте каждый предмет — это поможет быстро расширить его словарный запас.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'Время папиных сказок. 👨‍🍼', 'Сегодня поручите папе прочитать вечернюю сказку и уложить малыша спать, а сами устройте себе небольшую передышку.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'Карабкается, как обезьянка! 🧗‍♂', '️ Малыш пытается самостоятельно забираться на диван или невысокую мебель. Сделайте пространство безопасным и позвольте ему осваивать эти смелые двигательные навыки под вашим присмотром.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'Воздушные поцелуи! 👋', 'Малыш уже осознанно машет вслед уходящим и посылает воздушные поцелуи? Наслаждайтесь этими милыми проявлениями общительности.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'Засыпать становится легче. 🌙', 'Одинаковая последовательность действий каждый вечер (ванна, сказка, приглушённый свет) поможет малышу легче засыпать.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'РОВНО 14 МЕСЯЦЕВ! 🎉', 'Поздравляем! Со дня родов прошло ровно 14 месяцев! Прямо сейчас создайте особенное тематическое фото в разделе «Фотосессия малыша» и поделитесь этой радостью в Сообществе Anacan!'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'Усталость и гордость💖', 'Сегодня вечером отметьте вместе с партнёром 14 месяцев, наполненных усталостью и гордостью. Вы прекрасная команда!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'Какой большой путь прошёл ваш малыш! 📈', 'Страх первых дней сменился крепкой материнской уверенностью. Гордитесь собой!'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'Уделите время себе. 🛁', 'Вы весь день провели на ногах. Запишите свои чувства в Дневник настроения, чтобы стало легче, и отдохните за чашкой горячего чая.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'Искусство бросать предметы. 🎾', 'Если малыш бросает игрушки или еду на пол и смотрит им вслед, это не баловство, а изучение гравитации. Наберитесь терпения и разрешайте ему играть с небьющимися предметами.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'Шаги назад и в стороны! 🦀', 'Малыш уже пробует шагать не только вперёд, но и назад и в стороны. Это прекрасная тренировка равновесия и двигательных навыков!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'Энергетическая бомба для мам! 🥗', 'Активные малыши требуют от мам вдвое больше сил! Побалуйте себя: выберите интересное блюдо среди полезных рецептов и приготовьте его.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'Алло, кто это? 📱', 'Малыш прикладывает пульт или телефон к уху и пытается разговаривать, как вы? Не упустите эти милые моменты подражания.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'Следите за режимом сна. ⏱️', 'Дневной сон полностью сократился до одного раза? Включайте таймер сна, когда малыш засыпает, и следите по графику за адаптацией к новому режиму.'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'Время разделить заботы с папой. 👨‍🍼', 'Вечерние игры бывают очень энергичными. Сегодня вечером поиграйте с малышом в догонялки, а укладывание доверьте папе и немного отдохните.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'Пробуждается эмпатия! 💖', 'Когда кто-то плачет или грустит, малыш подходит и пытается его погладить? Эмоциональный интеллект вашего ребёнка развивается замечательно.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'Неиссякаемая энергия на свежем воздухе! 🌳', 'Чтобы ваш малыш, который уже уверенно ходит, мог выплеснуть энергию, найдите безопасные новые парки в разделе «Места, дружественные мамам».'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'Отказ от дневного сна. 😴', 'Играть гораздо интереснее, чем спать! За полчаса до сна прекратите активные игры и перейдите к более спокойным занятиям.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'У вас есть вопрос? 🤖', 'Даже ночью вы можете задать нашему ИИ-помощнику Anacan важные вопросы, например: «Почему мой ребёнок в некоторые дни совсем ничего не ест?» — и получить поддержку.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'Как справиться с избирательностью в еде. 🍲', 'Иногда малыш может отказаться даже от любимого блюда. Не заставляйте его есть — просто попробуйте другие варианты рецептов из нашего приложения.'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'Я сам вытру! 🧽', 'Когда вы вытираете стол, малыш тоже просит салфетку? Дайте своему маленькому помощнику простое и безопасное задание. Это значительно укрепит его уверенность в себе.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'Сила белого шума. 🎶', 'Если малыш не может уснуть после активного дня или из-за прорезывания зубов, включите звук дождя в разделе «Белый шум», чтобы создать в комнате спокойную атмосферу.'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'Полезные перекусы. 🍎', 'Кусочки фруктов или йогурт — отличный перекус для этого возраста. Откройте для себя разнообразные и вкусные идеи среди детских рецептов в нашем приложении.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'Первые рисунки! 🖍', '️ Малыш обожает рисовать каракули на бумаге толстыми мелками. Сохраните его первые произведения искусства на будущее в разделе «Фотосессия малыша».'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'Малыш не отходит от мамы 🥰', 'Даже когда вы идёте в туалет, малыш ждёт вас за дверью и плачет. Тревога разлуки достигла пика. Каждый раз давайте ему почувствовать, что он в безопасности.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'Важно приучать малыша пить воду. 💧', 'Чем активнее двигается малыш, тем сильнее он хочет пить. Не забывайте предлагать ему воду во время игр и после еды.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'Исследуем кухню! 🍳', 'Кастрюли, ложки и пластиковые контейнеры стали любимыми игрушками малыша. Оставьте безопасные шкафы доступными для его исследований.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'Пора усилить меры безопасности! 🛡', '️ Когда малыш начинает самостоятельно ходить и открывать шкафы, опасностей становится больше. Обязательно загляните в наш список рекомендованных товаров, чтобы подобрать детские замки и защитные накладки на углы.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'Успокаивающая ванна. 🛁', 'Тёплая ванна помогает весело выплеснуть накопившуюся за день энергию, расслабляет мышцы и прекрасно подготавливает малыша ко сну.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'Магия вечерней сказки. 📖', 'Короткая история перед сном развивает воображение и укрепляет эмоциональную связь между вами и малышом.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'Первые рисунки! 🖍', '️ Малыш обожает рисовать каракули на бумаге толстыми мелками. Сохраните его первые произведения искусства на память в разделе «Фотосессия малыша».'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'Начинаются ролевые игры. 🧸', 'Малыш пытается покормить плюшевого мишку или дать ему воды? Это самое милое доказательство того, как внимательно он наблюдает за вами и подражает вам!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'Есть вопрос? 🤖', '«Нормально ли, что мой ребёнок привередлив в еде?» — задайте этот или любой другой волнующий вас вопрос нашему помощнику Anacan AI даже ночью.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'Отказывается от дневного сна. 😴', 'Играть всегда интереснее, чем спать. Если малышу трудно заснуть, просмотрите график последних дней с помощью таймера сна Anacan и скорректируйте его режим.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'Не совсем понятно, какая погода на улице? ⛅', 'Инструмент «Погода и одежда» мгновенно подскажет вам скорость ветра, которую не определить по виду из окна.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'Персональная сказка 🪄', 'Создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: «Храбрый ребёнок, взобравшийся к звёздам».'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', '5 дней до 15 месяцев! 🎈', 'Обратный отсчёт почти завершён! Теперь вы делите дом с маленькой личностью, которая уже самостоятельно ходит и всё понимает. Улыбнитесь!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'Вместе на кухне. 🥦', 'Пока вы готовите еду, дайте малышу небьющуюся пластиковую миску и деревянную ложку — пусть он тоже приготовит своё блюдо.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'Планирование успокаивает. 📝', 'Мысленно составьте план дел или меню на завтра, добавив небольшие заметки, и ложитесь спать со спокойной душой.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'Показывает на всё пальцем. ☝', '️ Это безмолвная версия вопроса «Что это?». Чтобы поддерживать любознательность малыша, терпеливо называйте всё, на что он показывает.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения исключительно на себя. Будите и партнёра: быть командой — значит делить ответственность поровну.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'Проверка развития 🤖', 'Хотите узнать о скачках развития в 15 месяцев? Загляните в «Календарь кризисов».'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'Любовь к чтению. 📖', 'Перелистывание страниц книжек с картинками и ваши чтение вслух прекрасно помогают расширять словарный запас малыша. Читайте вместе каждый день хотя бы 10 минут.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'Понимает тон вашего голоса 🗣️', 'Когда вы серьёзным голосом говорите «нет», малыш останавливается и смотрит на вас? Он уже начинает понимать эмоции и запреты!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'Вечерний ритуал. 😴', 'Тёплая ванна и чистая пижама помогут малышу расслабиться и отлично подготовят его ко сну.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'В поисках самостоятельности. 🥣', 'Когда малыш хочет сам держать миску или ложку, дайте ему такую возможность. Беспорядок — прекрасная часть обучения.'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'Темп роста ускоряется. 📏', 'Одежда вашего малыша снова становится мала! Добавьте новые показатели роста и веса в раздел отслеживания развития и отмечайте его здоровый рост.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'Ответ на языке тела 🗣️', 'Когда вы спрашиваете: «Пойдём?», малыш поднимает руки, а когда говорите «Нет» — качает головой. Его способность понимать вас выросла невероятно!'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'Строит башню из кубиков 🧱', 'Малыш пытается поставить друг на друга два или три игрушечных кубика. Просто наблюдайте за его первыми инженерными экспериментами.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'Сила белого шума. 🎶', 'Если после активного дня или из-за прорезывания зубов малыш не может уснуть, включите в разделе «Белый шум» звук дождя и создайте в комнате спокойную атмосферу.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'Весёлая чистка зубов. 🪥', 'Малыш хочет сам держать зубную щётку? Чистите зубы вместе перед зеркалом, используя подходящие мягкие щётки, чтобы сформировать у него эту полезную привычку.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'Лёгкое засыпание. 🌙', 'После активного дня приглушите свет в комнате, говорите тише и почитайте малышу сказку спокойным голосом, чтобы подготовить его ко сну.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'Ваша энергия тоже может иссякнуть. 🥗', 'Очень устали? Приготовьте витаминный смузи по одному из полезных рецептов для женщин, чтобы быстро восстановить силы и побаловать себя.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'Принеси мне мяч! 🧠', 'Теперь малыш отлично понимает простые просьбы. Если он с радостью приносит то, о чём вы просите, это говорит о быстром развитии его интеллекта.'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'Приключение на свежем воздухе! 🌳', 'Малышу не удаётся выплеснуть энергию дома? Выберите безопасный парк, где удобно гулять с коляской, и вместе наслаждайтесь свежим воздухом.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'Дайте волю своим эмоциям. 📝', 'Не каждый день проходит легко, и порой всего становится слишком много. Запишите свои чувства в дневник настроения, чтобы снять накопившийся за день стресс.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'Повторяем слова! 🗣', '️ Малыш пытается повторять ваши слова или звуки животных? С радостью поддерживайте эти попытки, чтобы у него росло желание выражать себя.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'Прекрасное завершение дня. ✨', 'Сегодня вы снова сделали всё лучшее, что могла сделать мама. Закройте глаза, почувствуйте гордость за себя и спокойно засыпайте.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'Шаги становятся увереннее! 🏃‍♂', '️ Теперь малыш самостоятельно ходит по дому и порой даже пытается бегать. Его смелые движения одновременно наполняют вас гордостью и заставляют всегда быть начеку!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'Подозрение на аллергию 🤖', 'Дали малышу новый продукт и заметили покраснение на щеках? Прежде чем паниковать, узнайте у Anacan AI, что следует сделать в первую очередь.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'Боль при прорезывании зубов 🦷', 'Дёсны снова покраснели, а слюнотечение не прекращается? Подготовьте охлаждённые прорезыватели.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'Привычка пить воду очень важна. 💧', 'Чем активнее малыш двигается, тем сильнее испытывает жажду. Не забывайте предлагать ему воду во время игр и после еды.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'Вам тоже нужна энергия. 🥗', 'Вы весь день на ногах. Приготовьте вкусный перекус по одному из полезных рецептов для женщин, чтобы восстановить силы.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'Стремительные открытия! 🏃‍♂', '️ Он уже уверенно ходит из комнаты в комнату и хочет всё потрогать. Убедитесь, что дом безопасен, и наслаждайтесь этим активным периодом.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'Эмоциональная разгрузка. 📝', 'После утомительного дня запишите свои чувства в Дневнике настроения, чтобы снять накопившийся стресс. Вы замечательная мама!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'Вы — героиня! ✨', 'Любовь и забота, которыми вы окружали малыша на протяжении 450 дней, бесценны. А теперь устройтесь поудобнее и после этого прекрасного дня спокойно погрузитесь в сон.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'Ровно 15 месяцев! 🎉', 'Как же летит время! С рождения малыша прошло ровно 1 год и 3 месяца. Поздравляем.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'Счастье за семейным столом. 🍲', 'Он уже может есть те же блюда, что и вы. Откройте для себя блюда для всей семьи по рецептам из нашего приложения и отметьте этот маленький юбилей.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'Марафон по комнатам 🏃‍♂️', 'Он уже не просто ходит, а почти бегает! С каждым днём он всё лучше держит равновесие. С гордостью отметьте этот активный период в трекере развития.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'Папа на игровой площадке 👨‍👧', 'Вы устали весь день бегать за малышом. Вечерняя смена — за папой! Пусть теперь он кувыркается на полу и играет с малышом в догонялки.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'Не переживайте из-за того, что сегодня дома беспорядок.', 'Дети запоминают не идеальный порядок, а счастливых мам. Налейте себе кофе и отдохните.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'Малыш не может выплеснуть энергию дома и капризничает?  ⛅', 'Природа успокаивает лучше всего. Проверьте погоду, подберите подходящую одежду и сразу отправляйтесь в парк.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', 'Период «Что это?» ☝️', 'Он показывает на всё пальцем и издаёт особый звук. Так он просит вас называть предметы окружающего мира. Терпеливо называйте каждый предмет, на который он указывает.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'Нужна тишина 🤫', 'Первые полчаса после засыпания — самое чуткое время сна. Проверьте уровень шума в помещении с помощью шумомера и избегайте внезапных громких звуков.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'Есть вопрос? 🤖', 'Вас беспокоят какие-либо детали развития 15-месячного малыша? Не теряйтесь в интернете — напишите напрямую Anacan AI и получите научно обоснованный ответ.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'Волшебная сказка 🪄', 'Создайте в разделе умных сказок особую историю о том, как отважный герой исследует мир. Сделайте переход ко сну приятнее.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'Переход на один дневной сон 🥱', 'Малыш не хочет укладываться утром, и весь режим сбился? Он растёт! Начинается переход от двух дневных снов к одному. Постепенно корректируйте распорядок.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'Тёплая ванна расслабляет. 🛁', 'Игры с водой помогут малышу смыть пыль и усталость дня, развлекут его и прекрасно подготовят ко сну.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'Истерики? 🌪', '️ Когда малыш не может выразить свои мысли и желания, он может рассердиться и заплакать. Если вам нужна помощь, проконсультируйтесь с Anacan AI и узнайте, как правильно реагировать.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'Способность понимать слова. 🧠', 'Когда вы просите принести обувь, малыш находит и приносит её? Это говорит о быстром развитии его интеллекта. Хвалите его как можно чаще!'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'Время фруктов! 🍎', 'Чтобы восстановить энергию малыша, приготовьте яркую и привлекательную тарелку с сезонными фруктами.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'Сила белого шума. 🎶', 'Если после насыщенного дня малыш не может уснуть, создайте спокойную атмосферу, включив в комнате звуки океана или дождя из раздела «Белый шум».'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'Диктатор меню 🥣', 'Малыш сегодня отодвигает еду, которая нравилась ему ещё вчера? Избирательность в питании в этом возрасте нормальна. Не паникуйте — поищите другие варианты в разделе «Полезные рецепты».'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'Подражаем голосам животных! 🐱', 'Поиграйте в игру «Как говорит кошка?». Эти простые и весёлые подражания станут отличной основой для развития речи малыша.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'Восстановите силы 🥑', 'Если малыш наелся, теперь ваша очередь. В повседневной суете не обедайте на ходу. Выберите питательный перекус в разделе «Полезные рецепты» и прилягте на диван.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'Сила вечернего ритуала 🛀', 'Тёплая ванна всегда помогает. Старайтесь не нарушать вечерний ритуал, ведь он подаёт мозгу малыша сигнал о том, что пора спать.'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'Милые моменты дня. 📸', 'Сохраните забавный поступок малыша или новый навык, который он освоил сегодня, с помощью «Фотосессии малыша».'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'Проверяет границы. 🛑', 'Несмотря на ваше «нет», малыш снова тянется к этому предмету? Это не упрямство, а способ проверить и усвоить правила. Будьте терпеливы.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'Маленький любитель книг 📖', 'Малыш перелистывает страницы картонных книг и реагирует на картинки? Так развивается зрительная память. Чаще читайте ему красочные книги со сказками.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'Уборка или отдых? 🛋️', 'Когда малыш уснёт, не спешите к посудомоечной машине. Прилягте на диван, закройте глаза и просто спокойно подышите 15 минут. Вы робот? Нет.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'С каждым днём малыш становится немного взрослее.📸', 'Откройте «Фотосессию малыша» прямо сейчас и сохраните этот искренний момент на память.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'Хочу есть самостоятельно 🥄', 'Малыш забирает ложку из ваших рук и хочет есть сам. Он будет ронять еду и пачкаться, но это важно для развития моторики. Позвольте ему проявлять самостоятельность.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'Доступ к опасным местам ⚡', 'Малыш подрос и теперь дотягивается до полок, которые раньше были ему недоступны. Тумба под телевизором, углы... Срочно пересмотрите безопасность дома.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'Прорезываются коренные зубы? 🦷', 'Дёсны малыша опухли, и он тянет руку в рот? Возможно, прорезываются задние зубы. Проверьте трекер прорезывания зубов и предложите малышу охлаждённые прорезыватели.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке с приглушённым освещением.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'Внезапные пробуждения 😭', 'Малыш просыпается посреди ночи с криком и не успокаивается? Дайте Анализу плача прослушать его голос, чтобы понять, что это — ночной ужас или боль.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'Большие эмоции в маленьком теле 🛑', 'Малыш падает на пол, когда не получает желаемого? Это знаменитые истерики периода раннего детства. Сохраняйте спокойствие, установите с ним зрительный контакт и скажите, что вы рядом.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'Командный дух 🥂', 'Вместе с партнёром вспомните первые дни и те бессонные ночи и посмейтесь. Вы не так легко дошли до этого момента! Это победа вашей команды.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'Малыш всё ещё привередлив в еде? 🥦', 'Если малыш отказывается от некоторых блюд, не переживайте. Попробуйте необычные и весёлые варианты подачи из Рецептов для малышей, начинающих прикорм.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'Эмоциональная разгрузка. 📝', 'День выдался очень утомительным? Когда малыш уснёт, запишите свои чувства в Дневнике настроения, чтобы снять накопившийся за день стресс.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'Марафон по дому! 🏃‍♂', 'Малышу уже мало просто ходить — кажется, он пытается бегать. Наслаждайтесь топотом маленьких ножек, но не спускайте с него глаз!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'Догонялки на свежем воздухе. 🌳', 'Малышу не удаётся выплеснуть энергию дома? Выйдите вместе на свежий воздух и позвольте ему свободно гулять в парке, пока он как следует не устанет.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'Помощник за работой! 🧹', 'Малыш стремится взять тряпку и вытереть пыль или поиграть с веником? Подражание вам — самая милая часть процесса его обучения.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'Ритуал сна дарит чувство безопасности. 🌙', 'Действия, которые каждый вечер выполняются в одной и той же последовательности (ванна, сказка, приглушение света), помогут малышу легче заснуть.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'Понимание речи. 🧠', 'Когда вы просите принести обувь, малыш находит и приносит её? Это говорит о быстром развитии его интеллекта. Чаще хвалите и подбадривайте его!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'Вам тоже нужна энергия. 🥗', 'Вы весь день на ногах. Не забудьте приготовить для себя вкусный и богатый витаминами перекус.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'Приступы гнева? 🌪', '️ Малыш может злиться и плакать, когда ему не удаётся выразить свои чувства. Если вам нужна поддержка, посоветуйтесь с Anacan AI и узнайте, как правильно действовать.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'Папина очередь. 👨‍🍼', 'Сегодня поручите папе прочитать вечернюю сказку и уложить малыша спать, а сами устройте себе небольшую передышку.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'Искусство строить башню. 🧱', 'Ставить 3-4 кубика друг на друга, а затем разрушать башню — одно из любимых занятий малыша. Эта игра быстро развивает зрительно-моторную координацию.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'Комфорт вне дома. ☕', 'Устали от ежедневной рутины? Найдите в разделе Места для мам кафе, куда удобно зайти с детской коляской, и устройте себе перерыв на кофе.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'Сила белого шума. 🎶', 'Если после активного дня малыш не может уснуть, создайте спокойную атмосферу, включив в комнате белый шум — звуки океана или дождя.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'Темпы роста. 📏', 'Одежда снова стала мала! Добавьте новые показатели роста и веса в раздел «Отслеживание развития» и обновите график здорового развития.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'Первые рисунки! 🖍', '️ Малышу нравится рисовать каракули на бумаге толстыми мелками. С любовью наблюдайте за созданием его первых произведений искусства.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'Хочет есть самостоятельно! 🥄', 'Даже если одежда и всё вокруг испачкаются, позвольте малышу самому держать ложку. Это очень важно для развития координации движений и самостоятельности.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'Нежные объятия! 🤗', 'Когда малыш неожиданно обнимает вас и пытается поцеловать, так он выражает свою любовь. Наслаждайтесь этими неповторимыми мгновениями и сохраните их на фотосессии малыша.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'Любовь к чтению. 📖', 'Позвольте малышу самостоятельно перелистывать страницы книг с картинками. Сказки, услышанные в вашем исполнении, обогащают его словарный запас.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'Следим за режимом сна. ⏱️', 'Если малыш перешёл на один дневной сон, вечером он будет уставать раньше. Попробуйте немного раньше укладывать его на ночь.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'Не забывайте о воде. 💧', 'Чем активнее малыш двигается, тем сильнее хочет пить. Регулярно предлагайте ему воду во время игр и после еды.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', 'Период «Что это?». ☝', '️ Малыш показывает пальцем на всё вокруг и спрашивает, как это называется. Терпеливо называйте каждый предмет — так он познаёт окружающий мир.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'Танцует под музыку! 🎶', 'Услышав ритмичную музыку, малыш сразу начинает раскачиваться из стороны в сторону и танцевать? Загрузите видео этих энергичных моментов в Альбом малыша.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'Умение играть самостоятельно. 🧩', 'Если малыш может хотя бы недолго играть самостоятельно, это говорит о развитии его внимания. В такие моменты с любовью наблюдайте за ним со стороны.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'Тёплая ванна расслабляет. 🛁', 'Игры с водой помогут смыть усталость и пыль прошедшего дня, развлекут малыша и прекрасно подготовят его ко сну.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'Проверяет границы. 🛑', 'Несмотря на ваше «нельзя», малыш снова тянется к этому предмету? Это не упрямство, а способ понять правила. Будьте последовательны и терпеливы.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'Время фруктов! 🍎', 'Чтобы малыш восстановил силы, приготовьте для него яркую и привлекательную тарелку с сезонными фруктами.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'Не забывайте о себе! 💖', 'Пусть первый час после того, как малыш уснёт, принадлежит только вам. Ничего не делайте — просто займитесь тем, что любите, и отдохните.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', 'До 16 месяцев осталось всего 10 дней! 🎂', 'Невероятно! Ровно через 10 дней малышу исполнится 16 месяцев. Начните планировать небольшой праздничный торт или фотосессию.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'Не стесняйтесь спрашивать 🤖', 'Думаете, что допускаете ошибки в режиме сна? Задайте Anacan AI любой волнующий вас вопрос и сразу получите ответ, который поможет успокоиться.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'Забудьте обо всей усталости. 🥂', 'Сегодня вечером, когда малыш уснёт, не забудьте вместе с партнёром отметить вашу общую победу!'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'Когда терпение на исходе. 📝', 'Иногда энергия малыша может полностью вас измотать. Откройте Дневник настроения и свободно напишите о том, что сегодня утомило вас больше всего.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'Учимся пользоваться вилкой. 🍴', 'Малыш уже пытается накалывать кусочки еды на вилку. Приготовьте по Рецептам для начала прикорма блюда, которые легко брать вилкой.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'Сам снимает обувь 👟', 'Одевание уже превратилось в настоящую борьбу? Малыш сам стягивает носки и обувь. Полюбуйтесь его двигательными навыками!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'Это моё! 🧸', 'Малыш протестует и плачет, когда у него что-то забирают? У него укрепляется чувство собственности. Это важная часть формирования характера.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'Сегодня купает папа. 👨‍🍼', 'Сегодня поручите папе вечернее купание с водными играми и обилием пены, а также укладывание малыша спать — и отдохните.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'Что же приготовить? 🍲', 'Закончились идеи для меню прикорма? Не теряйтесь в интернете — найдите новые вкусные блюда в разделе «Полезные рецепты».'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'Играем в мяч! ⚽', 'Малыш уже не просто катит мяч, а поднимает руки и пытается бросить его вам! Сразу добавьте видео этих спортивных попыток в Альбом малыша.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'Кто есть в семейном альбоме? 🖼', '️ Когда вы рассматриваете фотографии и спрашиваете: «Где бабушка?», малыш правильно показывает на неё пальцем? Память и способность распознавать лица быстро развиваются.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'Первые инженерные опыты 🧱', 'Малыш пытается поставить два игрушечных кубика друг на друга, но они падают. Он внимательно пробует снова. Тихо понаблюдайте за его попытками.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'Место для мамы ☕', 'Вы устали постоянно находиться дома. Выберите уютное кафе в разделе «Места для мам» и уделите время себе.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'Капризы на пике ☁️', 'Малыша ничто не радует и он плачет по любому поводу? Возможно, у него прорезываются задние коренные зубы. Отметьте этот процесс в трекере прорезывания зубов.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'Колыбельная на ночь 🎶', 'Ни один звук не успокаивает так, как мамин голос. Сегодня вечером просто прижмите малыша к груди и тихонько спойте ему.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'Проверка развития 🤖', 'Нужна информация о скачках развития в 16 месяцев? Попросите Anacan AI составить краткий и точный список, одобренный педиатрами.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', 'До 16 месяцев всего 5 дней! 🎈', 'Обратный отсчёт почти завершён! Торт заказан, а наряды готовы? Уже сейчас посмотрите весёлые идеи для фотосессии малыша.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'Звуки, дарящие спокойствие. 🎶', 'Если после дня, полного активных открытий, ваш малыш никак не может успокоиться, включите в комнате звук дождя из раздела «Белый шум» и создайте умиротворяющую атмосферу.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'Сенсорные игры. 🌾', 'Насыпьте в большую ёмкость немного риса или макарон и спрячьте внутри игрушки. Пусть малыш находит их руками и развивает осязание.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'Время самостоятельной игры 🧸', 'Теперь малыш уже может 10-15 минут самостоятельно играть с игрушками. Это значит, что он способен дольше удерживать внимание. Насладитесь тишиной.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'Сила музыки 🎶', 'Попробуйте успокоить внезапные вечерние капризы с помощью лёгкой классической музыки. Часто этот простой приём творит чудеса.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'Поддержка специалиста. 🤖', 'Задайте нашему AI-помощнику Anacan новые волнующие вас вопросы о поведении малыша, например: «Мой ребёнок меня кусает — как реагировать?»'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'Искусство раздеваться. 🧦', 'Одеваться сложно, а вот раздеваться очень весело! Позвольте малышу самому попробовать снять шапку, носки или обувь.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'Вещи взрослых так интересны. 👜', 'Копаться в вашей сумке или пытаться надеть папину обувь — любимое занятие малыша. Позвольте ему изучать ваши безопасные вещи.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'Здоровая мама — здоровый малыш 🥑', 'Ваши запасы железа и кальция истощились. Выберите среди полезных рецептов салат, который можно быстро приготовить и который придаст вам сил.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'Искусство рисовать каракули 🖍️', 'Когда вы даёте малышу карандаш, он пытается рисовать каракули на бумаге? Это отличное упражнение для мелкой моторики. Убедитесь, что карандаши безопасны.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения только на себя. Будите и партнёра: быть командой — значит делить ответственность поровну.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'Нужно выговориться 💬', 'Вас тяготит мысль: «Я уже никогда не стану прежней»? Поделитесь этим временным переживанием с мамами в Сообществе Anacan.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'Завтра 16 месяцев! 🎉', 'Готовы? Завтра малышу исполнится ровно 16 месяцев! Освободите память телефона: завтра вам понадобится место, чтобы запечатлеть самые милые выражения лица во время фотосессии малыша.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'Сегодня в «Умных сказках» 🪄', 'Создайте в «Умных сказках» историю о смелых и милых животных и превратите комнату в волшебное место.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'Вечерняя сказка волшебна. 📖', 'Теперь малыш и сам показывает вам картинки в книге. Небольшая история, которую вы читаете вместе перед сном, невероятно укрепляет вашу связь.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', 'РОВНО 16 МЕСЯЦЕВ! 🎂', 'Невероятно, правда? С того волнительного дня, когда вы впервые взяли малыша на руки, прошло ровно 16 месяцев! Самое время отметить, как замечательно он вырос. Выберите тему для фотосессии малыша, сохраните самый милый кадр на память и обязательно поделитесь своей гордостью с другими мамами в Сообществе Anacan!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'Время наполнять и опустошать! 📦', 'Сложить игрушки в большую коробку, а затем разом высыпать их на пол! Такая игра на понимание причин и следствий развивает логику малыша.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'Поиск сокровищ на природе. 🍂', 'Во время прогулки в парке собирайте разные листья или шишки. Открывайте для себя новые парки с разнообразными природными пейзажами в разделе «Места, дружественные мамам».'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'Звуки животных 🐶', 'Увидев кошку, малыш пытается мяукать, а увидев собаку — говорить «гав-гав»? Словарный запас начинает пополняться со звуков животных. Поиграйте с ним в эту игру.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'Поиск сокровищ на природе. 🍂', 'Во время прогулки в парке собирайте разные листья или шишки. Открывайте для себя новые парки с разнообразными природными пейзажами в разделе «Места, дружественные мамам».'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'Успокаивающие звуки. 🎶', 'Если после дня, наполненного активными открытиями, ваш малыш не может успокоиться, включите в комнате звук дождя из раздела «Белый шум», чтобы создать умиротворяющую атмосферу.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'Время наполнять и опустошать! 📦', 'Сложить игрушки в большую коробку, а затем разом высыпать их на пол! Эта игра на понимание причин и следствий развивает логику малыша.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'Время только для вас. 🛁', 'Малыш уснул, и дома стало тихо. Теперь отложите телефон, включите любимый фильм и просто насладитесь тем, что можно ничего не делать.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'Шаги назад и в стороны! 🦀', 'Теперь малыш ходит не только вперёд, но и пробует делать шаги назад и в стороны, проверяя равновесие. Обязательно запечатлейте эти забавные моменты на фото.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'Скачок роста! 📏', 'Замечаете, что ваш малыш подрос? Внесите его новые показатели в раздел «Контроль веса» и посмотрите, как растёт график развития.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'Расчёсывание волос и чистка зубов. 🪥', 'Наблюдая за вами, малыш проводит расчёской по волосам или подносит зубную щётку ко рту. Сейчас самое подходящее время, чтобы в игровой форме привить ему навыки ухода за собой.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'Семейный ужин. 🍲', 'Не хотите сегодня готовить дома? Найдите на карте в нашем приложении рестораны с отдельным детским меню и детскими стульчиками.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'Сделайте глубокий вдох. ✨', 'Не каждый день проходит по плану, и иногда дома может оставаться беспорядок. Вы не обязаны быть идеальной — для малыша вы самая лучшая.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'Лёгкое засыпание. 🌙', 'После активного дня приглушите свет в комнате и тихим голосом спойте малышу колыбельную, чтобы помочь ему погрузиться в глубокий сон.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'Предоставьте право выбора. 👕', '«Ты наденешь красную футболку или синюю?» Небольшой выбор помогает уменьшить упрямство и укрепляет у малыша ощущение собственного «я».'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'Усложнённые прятки! 🙈', 'Малыш легко находит игрушку, даже если вы прячете её под двумя разными покрывалами? Значит, у него полностью сформировалось понимание постоянства объектов.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'Начинаются тренировки по бегу! 🏃‍♂', '️ Быстрые шаги уже превращаются в короткие пробежки. Хотя защищать коленки становится всё сложнее, радость малыша от этой свободы того стоит!'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'Открыт к разным текстурам. 🥦', 'Меняйте цвета и формы блюд, чтобы улучшить аппетит малыша. Вдохновляйтесь идеями из раздела «Рецепты для малышей, начинающих прикорм».'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'Вы настоящая героиня. 🛁', 'Весь день вы справлялись с неугомонным малышом. А теперь налейте себе горячего чая и просто отдохните, ни о чём не думая.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'Ритуал, дарящий спокойствие. 🌙', 'Перед ночным сном приглушите свет в комнате и говорите шёпотом — это поможет малышу успокоиться и подготовиться ко сну.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'От каракулей к осознанным линиям! 🖍', '️ Взяв карандаш, малыш уже пытается рисовать не только точки, но и длинные линии. Сфотографируйте этот маленький шедевр и сразу добавьте его в Альбом малыша.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'Поиск сокровищ на природе. 🍂', 'Собирать и рассматривать листья и небольшие камешки во дворе или в парке — прекрасное занятие для сенсорного развития малыша.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'Расслабление с играми в воде. 🛁', 'Игры с игрушками в тёплой ванне помогают снять накопившееся за день напряжение и дарят много веселья.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'Понимает инструкции из двух действий! 🧠', 'Когда вы говорите: «Возьми обувь и принеси мне», выполняет ли малыш оба действия по очереди? Это признак замечательного скачка в его интеллектуальном развитии!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'Мамина энергия очень важна. 🥗', 'Вы устали постоянно бегать за малышом. Приготовьте для себя что-нибудь вкусное и богатое витаминами из раздела полезных рецептов для женщин.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'Поддержка специалиста. 🤖', 'Задайте нашему AI-помощнику Anacan волнующие вас вопросы, например: «Почему малыш понимает слова, но мало говорит?», и получите необходимую поддержку.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'Самостоятельно пользуется ложкой. 🥄', 'Поднося ложку ко рту, малыш уже меньше проливает. Похвалите его за этот навык мелкой моторики и позвольте ему проявлять самостоятельность.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'Сочувствие к игрушкам. 🧸', 'Малыш гладит плюшевого мишку, кормит его или укрывает одеялом? Эти милые ролевые игры показывают, как прекрасно развивается его эмоциональный интеллект.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'Время папиных сказок. 👨‍🍼', 'Сегодня поручите папе прочитать вечернюю сказку и уложить малыша спать, а сами устройте себе небольшой перерыв.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'Пора усилить меры безопасности. 🛡️', 'Открывать шкафы и ящики — любимое занятие малыша. Обязательно загляните в наш список рекомендуемых товаров, чтобы выбрать детские блокираторы.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'Покоряются новые высоты! 🧗‍♂', '️ Теперь малыш может дотянуться ещё выше и легче забраться на мебель. Пора ещё раз проверить все меры безопасности в доме.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'Превратите питьё воды в весёлое занятие. 💧', 'Активный бег и игры вызывают жажду. Чаще предлагайте малышу воду в ярком поильнике, чтобы поддерживать водный баланс.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'Итоги дня. ✨', 'Вы не обязаны быть идеальной каждый день. Если сегодня вы что-то не успели — ничего страшного. Для своего малыша вы самая лучшая.'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'Чувство ритма развивается! 🎶', 'Начинает двигаться и улыбаться, едва услышав первые секунды любимой песни? Запечатлейте эти энергичные моменты с помощью функции «Фотосессия малыша» и отправьте снимки в семейную группу.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'Малыш всё лучше узнаёт части тела. 👂', 'Если малыш правильно отвечает на новые вопросы вроде «Где животик?» или «Где ушко?», это говорит о том, как быстро он учится.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'Читайте книги вместе. 📖', 'Теперь малыш не только переворачивает страницы, но и показывает пальцем на животных или предметы в книге, ожидая, что вы их назовёте.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'Как идёт рост? 📏', 'Рукава и штанины снова стали короткими! Внесите новые показатели в раздел «Трекер веса» и следите за ростом графика развития.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'Злость из-за невозможности выразить себя. 🌪', '️ Если малыш сердится и плачет, когда не получает желаемого или не может объяснить, чего хочет, — это нормально. Присядьте, чтобы оказаться с ним на одном уровне, и скажите, что понимаете его чувства.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'Дайте волю своим чувствам. 📝', 'День был очень утомительным? Когда малыш уснёт, запишите свои чувства в «Дневнике настроения», чтобы снять накопившийся за день стресс.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'Открывайте новые места. ☕', 'Устали от повседневной рутины? В разделе «Места для мам» найдите кафе с детским меню, куда удобно ходить вместе с малышом.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'Играем в уборку. 🧺', 'Ваш малыш, который любит высыпать игрушки из коробки, теперь учится складывать некоторые из них обратно. Спойте вместе песенку про уборку и превратите это занятие в весёлую игру.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'Меняется режим сна? ⏱️', 'Если малыш окончательно перешёл на один дневной сон, время укладывания на ночь может немного измениться. Следите за сегодняшним графиком с помощью таймера сна Anacan и настройте новый режим.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'Сортировка фигур (Puzzles). 🧩', 'Малыш пытается вставить круг в круглое отверстие, а квадрат — в квадратное. Такие логические игры развивают его терпение и внимание.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'Стало сложнее укладывать малыша? 😴', 'Активное познание мира иногда перевозбуждает малыша. Включите таймер сна, приглушите свет в комнате перед сном и почитайте сказку.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'Спасибо и пожалуйста. 🙏', 'Когда малыш что-то даёт или получает, он уже кивает или по-своему выражает благодарность. Самое время учиться правилам общения!'),
  ('eb807359-495c-4338-a628-e4dd3e405226', 'Следим за ростом и прибавкой веса. 📏', 'Одежда снова стала мала? Обновите показатели в разделе «Трекер веса» и подготовьте график развития к 500-му дню.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'Малыш узнаёт животных в книге. 🐶', 'Показывает пальцем, когда вы спрашиваете: «Где собака?» Чтобы расширить словарный запас малыша, начните также называть цвета изображённых в книге предметов.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'Пора обновить меры безопасности. 🛡️', 'Теперь малыш может дотянуться до более высоких предметов. Ещё раз проверьте скатерти и острые углы. При необходимости загляните в раздел «Рекомендуемые товары».'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'Время озорных игр с папой. 👨‍🍼', 'Поручите папе самую энергичную часть вечера. Их совместные игры, наполненные смехом, укрепят связь между ними и позволят вам отдохнуть.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'Сенсорные игры. 🌾', 'Насыпьте рис или песок в большую ёмкость и спрячьте там игрушки. Поиск игрушек руками незаменим для развития мелкой моторики.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'Право выбирать одежду. 👕', '«Ты хочешь надеть синюю футболку или зелёную?» Предлагая малышу два варианта, вы укрепляете его чувство самостоятельности и немного уменьшаете упрямство.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'Расслабляющие игры с водой. 🛁', 'Тёплая ванна и журчание воды помогут снять накопившуюся за день усталость. Положите в воду ёмкости разного размера, чтобы познакомить малыша с понятием объёма.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'Делитесь своими чувствами. ✨', 'Иногда всё может навалиться одновременно. В конце дня уделите время любимому занятию, чтобы обрести внутреннее спокойствие.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'Бросает мяч в цель! ⚽', 'Малыш уже не просто катит мяч, а старается бросить его в определённом направлении. Это явный признак развития зрительно-моторной координации.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'Превратите питьё воды в увлекательное занятие. 💧 A', 'Активные дети быстро испытывают жажду. Регулярно предлагайте малышу воду в яркой и интересной бутылочке, чтобы поддерживать водный баланс организма.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'Двухэтапные команды. 🧠', '«Возьми игрушку и положи её в коробку». Способность выполнять такие сложные задания говорит о хорошем развитии восприятия малыша.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'Танцует под музыку в своём ритме. 🎶', 'Теперь малыш не просто раскачивается, а хлопает в ладоши или кружится в такт музыке.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'Вечерняя сказка творит чудеса. 📖', 'Позвольте малышу рассматривать картинки и пересказывать сказку своими словами. Это основа будущей привычки читать книги.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'Празднуем юбилей! 🎈', 'Отметьте этот день маленьким тортом или любимым фруктом малыша. Видеть, как быстро он растёт, — ваша самая большая награда.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'Поблагодарите себя. ✨', 'Поблагодарите себя за самоотдачу, любовь и терпение, которые вы проявляли на протяжении 500 дней. А теперь спокойно отдохните: завтра начинается новый этап!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', 'Потрясающие 500 дней.🎉', 'Можете поверить?! Со дня родов прошло ровно 500 дней!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ru = v.t, body_ru = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'Подзарядка для мамы 🔋', 'Дневная суета лишила вас всех сил? Забывать о себе, воспитывая ребёнка, — не героизм. Оставьте малыша в безопасном месте и устройте себе 10-минутный перерыв на кофе.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'Превышение скорости 🏃‍♂️', 'Малыш уже не ходит, а почти бегает! Успевать за ним становится всё труднее. Отметьте новый рекорд скорости в трекере развития и уберите домашние препятствия с его пути.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'Понимание без слов 🫂', 'Сегодня вы очень устали. Когда малыш уснёт, просто посидите рядом с партнёром на диване, ни о чём не разговаривая, и насладитесь тишиной.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'Потребности вашего тела 🥑', 'У вас болят руки или спина? Малыш стал тяжелее. Поддержите мышцы, выбрав среди полезных рецептов лёгкое блюдо, богатое кальцием и белком.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'Начинаются игры воображения 🧸', 'Пытается покормить игрушечного мишку или уложить его спать? У малыша пробуждается воображение! С гордостью наблюдайте за этими прекрасными проявлениями эмпатии.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'Время игр с папой 👨‍👧', 'Ваше терпение на исходе? Пусть сегодня вечером папа возьмёт на себя возню на полу и игры с щекоткой.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'Исследования на кухне. 🍎', 'Когда моете фрукты, позвольте малышу помочь вам. Шум воды и яркие цвета фруктов поддержат его интерес.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'Попытки составлять фразы. 🗣', '️ Пытается соединять два слова, например «Ма-ма, дай» или «Па-па, смотри»? Это огромный скачок в развитии речи!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'Волшебный фон для сна 🪄', 'Малышу трудно заснуть? Включите успокаивающий белый шум со звуками журчащего ручья.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'Маленький художник за работой 🖍️', 'Когда даёте малышу карандаш, он разрисовывает бумагу (или стену)? Его мелкая моторика быстро развивается. Самое время купить смываемые краски.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'Вечер историй с папой. 👨‍🍼', 'Доверьте папе последние активные игры перед сном. Их совместный смех станет для вас лучшим фоном для отдыха.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'Исследуем погоду ⛅', 'На улице ветрено или просто прохладно? Не пытайтесь определить это, глядя в окно. Инструмент погоды и одежды за считаные секунды подберёт для вас подходящий комплект.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'Делитесь опытом 💬', 'Мысль «Только мой ребёнок так делает?» не даёт вам покоя? Присоединяйтесь к сообществу Anacan, почитайте истории других мам 16-месячных малышей и спокойно выдохните.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'Успокаивающая ванна. 🛁', 'Игры в тёплой воде перед сном помогут снять всё напряжение дня. Добавьте в воду немного эфирного масла и создайте умиротворяющую атмосферу.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'Пытается самостоятельно подниматься по лестнице. 🪜', 'Держась за вашу руку, малыш уже поднимается увереннее. Не мешайте ему укреплять мышцы ног — просто следите за безопасностью.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'Список в вашем кармане 🛒', 'В повседневной суете сложно вспомнить, что закончилось — шампунь или влажные салфетки? Не держите всё в голове: добавьте это в список покупок и синхронизируйте его с партнёром.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'Есть вопрос? 🤖', 'Даже ночью вы можете спросить нашего AI-помощника Anacan, например, почему малыш стал чаще просыпаться, и мгновенно получить ответ.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'Я тебя вижу! 🙈', 'Закрывает глаза руками и играет в «ку-ку»? Его понимание постоянства объектов становится всё более совершенным.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'Мы — одна команда! 💖', 'После трудного дня сядьте с партнёром друг напротив друга и поделитесь переживаниями. Взаимная поддержка помогает разделить физическую и эмоциональную нагрузку пополам.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'Вопросы к педиатру 🤖', 'Чего ожидать от развития малыша в 16-18 месяцев? Вместо того чтобы читать пугающие истории в интернете, попросите Anacan AI подготовить точное экспертное резюме.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'Любовь к книгам 📖', 'Самостоятельно перелистывает страницы книги и трогает пальчиком картинки? Привычка к чтению формируется уже сейчас. Вместе называйте то, что изображено на картинках.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'Внезапно проснулся с криком?', 'Это может быть ночной ужас. Дайте Анализу плача послушать звук, чтобы выяснить, связана ли проблема с физическим или психологическим состоянием.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'Домашние дела могут подождать 🛑', 'Пол не вымыт? Пусть подождёт. Беспорядок в доме можно убрать, а восстановление истощённой мамы занимает много времени. Прилягте на диван и просто насладитесь тишиной.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'Логические игры 🧱', 'Строит башню, ставя друг на друга 3-4 кубика? Отметьте эту победу моторики в трекере развития! Похвалите малыша за эти первые инженерные попытки.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'Чтобы было легче заснуть. 🌙', 'Приглушите свет в комнате до минимума и говорите тихим шёпотом. Это подаст нервной системе малыша сигнал о том, что пора отдыхать.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'Время восстановить силы. 🍎', 'Пока малыш спит, вы тоже закройте глаза на 20 минут. Домашние дела не закончатся, а вот ваши силы могут. Берегите себя.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'Маленький помощник. 🧺', 'Когда вы собираете игрушки в коробку, малыш тоже приносит и кладёт одну из них? Обязательно похвалите его за такую небольшую помощь и поблагодарите.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'Волшебство умной сказки 🪄', 'Создайте в Умных сказках особенную историю, главным героем которой станет ваш малыш: отважный кроха, гуляющий по волшебному лесу.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'Личное время мамы 🎧', 'Не бегите на кухню, как только малыш уснёт. Наденьте наушники, включите любимую песню и хотя бы 15 минут побудьте просто собой.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'Настаивает на том, чтобы есть самостоятельно. 🥄', 'Если малыш забирает у вас ложку, не мешайте ему. Даже если он испачкается, самостоятельная еда — важнейшее проявление его независимости.'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'Посмотри на меня! ☝️', 'Издаёт звуки, чтобы привлечь внимание, и показывает пальцем на заинтересовавший его предмет. Разделяйте с малышом радость открытий и подтверждайте: «Да, это мяч».'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'Упрямство с ложкой 🥄', 'Хочет есть самостоятельно и половину еды проливает на себя? Не сосредотачивайтесь на чистоте. Именно сейчас закладывается основа навыка самостоятельного приёма пищи.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'Итоги дня 📝', 'Когда чувствуете, что делаете недостаточно, запишите в Дневнике настроения свои маленькие успехи за сегодня. (Например: Рассмешила малыша, накормила досыта). Вы замечательная.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'Разговор становится всё серьёзнее 🗣️', 'Малыш что-то рассказывает вам непонятными словами и даже жестикулирует? Поддерживайте диалог с такой же серьёзностью — это необходимо для развития речи.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'Сила свежего воздуха 🌙', 'Отказывается спать? Откройте окно и полностью проветрите комнату. Прохладный и свежий воздух всегда помогает легче заснуть.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'Подозрение на аллергию? 🤖', 'Дали новый фрукт, и появилось покраснение? Прежде чем паниковать, узнайте у Anacan AI, что делать в первую очередь при пищевой аллергии у детей.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'Сладких снов 🌙', 'Сегодня вы очень устали. Пока малыш засыпает, включите в разделе «Белый шум» звуки океанских волн — пусть он спокойно спит, а вы отдохнёте.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'Таймер кормления ⏱️', 'Следить за временем приёма пищи стало ещё проще! Включите таймер кормления и внимательно контролируйте соблюдение суточной нормы питания малыша.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'Началась беготня! 🏃‍♀️', 'Ваш 17-месячный исследователь переворачивает весь дом вверх дном? Найдите поблизости новый парк в разделе «Места для мам», чтобы малыш мог выплеснуть энергию.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'Вкусно и необычно! 🥦', 'Думаете, что необычного приготовить малышу сегодня? В разделе «Рецепты» есть вкусные идеи для малышей, начинающих знакомство с прикормом.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'Запишите свои чувства 📝', 'Материнство порой утомляет, и это совершенно нормально. Запишите в «Дневнике настроения», что сегодня утомило вас больше всего, и почувствуйте облегчение.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'Утренний сюрприз 💩', 'Уже сменили первый за день подгузник? Не забудьте отметить это в трекере подгузников в приложении, чтобы легко контролировать режим гигиены!'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'Дневной сон 😴', 'Запустите таймер сна! Анализируйте продолжительность дневного сна 17-месячного малыша, чтобы точнее планировать вечернее укладывание.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'В поисках удобства 🍼', 'Ищете лучшую чашку-непроливайку, чтобы малыш мог пить самостоятельно? Посмотрите самые популярные среди мам варианты в разделе «Рекомендуемые товары».'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'Не забывайте о себе! ☕', 'Ваша энергия очень важна для малыша. Приготовьте себе вкусный и питательный смузи по одному из полезных рецептов.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'Блог и кофе 📖', 'Малыш уснул — теперь время для себя! Прочитайте нашу новую статью в блоге и узнайте много интересных фактов о психологии активных детей.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'Комфортная прогулка 👟', 'Вам и малышу нужна удобная обувь для активных прогулок в парке? Ознакомьтесь с лучшими вариантами в разделе «Рекомендуемые товары».'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'Есть вопрос? 🤔', 'Не знаете, как справиться с растущим упрямством малыша? Anacan AI готов сразу ответить на ваш вопрос и дать экспертные рекомендации!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'Глубоко вдохните ✨', 'Необязательно, чтобы всё было идеально. Вы и так самая лучшая мама! Оставьте дневной стресс в «Дневнике настроения» и отдохните.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'Подрос? 🦒', 'Замечаете, что одежда стала мала? Внесите новые данные в «Трекер развития» и посмотрите, как меняется график роста.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'Норма питания 🥣', 'Получил ли малыш сегодня достаточно белка? Проанализируйте его ежедневное меню с помощью инструмента контроля питания и восполните недостающее.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'Успокаивающий звук 🌧️', 'Малыш не может уснуть после насыщенного дня? Выберите звук дождя в разделе «Белый шум» и помогите его нервной системе успокоиться естественным образом.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'Пусть этот день будет особенным 🌟', 'Домашняя рутина утомляет? Откройте нашу карту мест для мам и найдите новое кафе, где можно с комфортом посидеть вместе с малышом.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'Маленькая звезда! 📸', 'Его милая улыбка бесценна! Сохраните этот день навсегда с помощью функции фотосессии малыша, используя разные рамки.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'Проверка пищеварения ⏱️', 'Ежедневный учёт использованных подгузников помогает оценить качество питания. Вы уже отметили в приложении сегодняшние смены подгузника?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'Семейный ужин 🍲', 'Что вы дадите малышу на ужин? В рецептах прикорма есть идеи полезных блюд, которые с удовольствием будет есть вся семья.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'Ваша история материнства 📝', 'История каждой мамы уникальна. Читайте в наших блогах о реальном опыте и историях других мам и вдохновляйтесь.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'Пробежка в парке 👟', 'После первых шагов начинаются первые пробежки. Подходящие модели первой обуви можно найти в разделе «Рекомендуемые товары».'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'Умиротворение в комнате 🌊', 'Сегодня малышу трудно уснуть? Включите шум океанских волн в разделе «Белый шум»: он поможет успокоить нервную систему и облегчить засыпание.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'Достаточно ли белка? 🍗', 'Белок необходим для роста ребёнка! С помощью инструмента контроля питания оцените баланс его ежедневного рациона и восполните недостающее.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'Таймер сна включён? ⏳', 'Начинаете укладывать малыша? Включите таймер, проанализируйте продолжительность засыпания и узнайте, как улучшить этот ритуал.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'Ваш умный помощник 🤖', 'Почему у ребёнка внезапно пропал аппетит? Задайте этот или другой волнующий вас вопрос Anacan AI и сразу получите научно обоснованный ответ.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'Зарядитесь энергией 🔋', 'Готовы к активному дню? Выберите для себя вкусный и богатый витаминами завтрак из раздела полезных рецептов для женщин.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'В поисках удобства 🍼', 'Ищете лучший поильник-непроливайку, чтобы малыш мог пить самостоятельно? Посмотрите варианты, которые больше всего нравятся мамам, в разделе «Рекомендуемые товары».'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'Вы справляетесь! 💪', 'День выдался трудным? Прислушайтесь к своему внутреннему голосу в Дневнике настроения. Помните: это всего лишь трудный день, а не плохая жизнь.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'Отчёт о питании 📊', 'Внесите сегодняшний рацион ребёнка в инструмент контроля питания. Давайте посмотрим, получил ли он сегодня все необходимые витамины.'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'Чудо дня 🖼️', 'Особенный штрих к 520-му дню! Загрузите самые ценные и забавные фотографии в Альбом малыша, чтобы спустя годы вспоминать их с улыбкой.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'Скачок развития? 📈', 'Малыш много плачет или у него нарушился сон? Проконсультируйтесь с Anacan AI, чтобы узнать, не связаны ли эти изменения со скачком развития в 17-м месяце.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'Расслабляющий ритуал 🌙', 'Завершение прекрасного дня. Запустите таймер сна, выберите колыбельную в разделе «Белые шумы» и спокойно наслаждайтесь окончанием дня.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'В поисках свежего воздуха 🌳', 'Заскучали дома? Откройте нашу карту мест, дружественных к мамам, и найдите новый парк, где можно с комфортом погулять вместе с малышом.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'Пора спать ⏱️', 'Начинаете укладывать малыша? Включите таймер сна, отмечайте соблюдение режима и анализируйте норму сна.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'Как утренний аппетит? 🥣', 'Важно начинать день правильно! Рассчитайте сегодняшнюю потребность в витаминах с помощью инструмента контроля питания и спланируйте меню.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'Утренний ритуал 💩', 'Уже сменили первый за день подгузник? Цвет и консистенция стула могут многое рассказать о здоровье кишечника. Сразу внесите данные в трекер подгузников!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'Энергия для женщин 🥗', 'Повседневная суета утомляет. Не забывайте о себе! Приготовьте вкусный и питательный салат по одному из полезных рецептов для женщин.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'Магия белого шума 🌧️', 'День выдался очень активным? Включите в комнате звук дождя из раздела «Белые шумы», чтобы малыш легко заснул, а вы смогли спокойно отдохнуть.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'Самый милый момент дня 📸', 'Сегодня малыш сделал что-то необычное и забавное? Запечатлейте этот момент с помощью весёлых рамок для детской фотосессии и сохраните его на всю жизнь.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'Хочет есть самостоятельно! 🥦', 'Малыш стремится к самостоятельности? Выберите в разделе «Рецепты» вкусные порции прикорма, которые удобно держать в руках и сложно рассыпать.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'Как справиться с упрямством 🤖', 'На всё отвечает «нет»? Если вы не знаете, как справляться с кризисами этого периода, прямо сейчас посоветуйтесь с Anacan AI.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'Одежда стала мала? 📏', 'Заметили, что ваш ребёнок неожиданно подрос? Внесите новые показатели в трекер веса и посмотрите график здорового роста.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'Таймер кормления ⏱️', 'Сколько времени занимает приём пищи? Запустите таймер кормления и следите за режимом, чтобы пища успевала полностью перевариваться.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'Полезное чтение 📖', 'Ребёнок уснул — чем займётесь вы? Читайте новейшие статьи в разделе «Блоги», чтобы больше узнавать о материнстве.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'В поисках идеального поильника 🥤', 'Ищете удобный поильник-непроливайку? Загляните в раздел «Рекомендуемые товары» и ознакомьтесь с продуктами, которые чаще всего проверяют мамы.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'Перерыв на кофе ☕', 'Хотите сегодня выбраться из дома? Найдите среди мест, дружественных к мамам, кафе с детским уголком и уделите немного времени себе.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'Эмоциональная разгрузка 📝', 'Сегодня всё пошло не по плану? Не вините себя. Запишите свои переживания в дневник настроения, чтобы освободиться от накопившихся мыслей.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'Проверим норму сна 😴', 'Как малыш спал ночью? Посмотрите записи таймера сна и проанализируйте, соблюдает ли ваш малыш суточную норму сна.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'Что вас беспокоит? 🤖', 'У вас есть сомнения по поводу развития ребёнка? Напишите нашему экспертному AI-помощнику Anacan, получите научно обоснованные ответы и развейте свои тревоги.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'Каждое блюдо — новый вкус 🍲', 'Больше не нужно ломать голову над тем, что приготовить сегодня. В разделе «Рецепты» вас ждут разнообразные и полезные меню для малышей, начинающих прикорм.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'Ежедневный отчёт о выделениях 💩', 'Не забудьте сделать запись при утренней смене подгузника! Отслеживание смены подгузников в течение дня помогает понять, получает ли ребёнок достаточно жидкости.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'У вас тоже есть потребности 🥗', 'Силы на исходе? Приготовьте витаминный смузи по одному из полезных рецептов для женщин. Вам нужно оставаться сильной!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'Незабываемые воспоминания 🖼️', 'Загрузите самые красивые фотографии в Альбом малыша и храните их в безопасном месте, чтобы однажды с улыбкой вспоминать эти милые моменты.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'Что вы чувствовали сегодня? 💖', 'Даже если вы очень устали, стоит вдохнуть его родной запах — и всё проходит, правда? Запишите сегодняшние чувства в Дневнике настроения и отдохните.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'Приём пищи по таймеру ⏱️', 'Ребёнок слишком долго сидит за столом? Включите таймер питания, соблюдайте рекомендуемую продолжительность приёма пищи и помогите предотвратить снижение аппетита.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'Утренние игры 🧩', 'Учимся вместе! Обязательно прочитайте в разделе «Блоги» нашу статью об играх, способствующих интеллектуальному развитию детей в возрасте 17.5 месяцев.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', 'Объятия «Я тебя люблю» 🫂', 'Малыш неожиданно подходит, обнимает вас за шею или гладит по лицу? Теперь он выражает свою любовь и прикосновениями. Наслаждайтесь этим моментом.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'Папино утешение 🫂', 'Когда малыш просыпается ночью, вставайте по очереди: один раз вы, другой — ваш партнёр. Разделите нагрузку поровну, как одна команда.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'Подозрение на аллергию 🤖', 'Вы дали малышу новый продукт и заметили покраснение на щеках? Прежде чем паниковать, узнайте у Anacan AI, какие первые шаги нужно предпринять.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'Устали сидеть дома?☕', 'Найдите в разделе «Места для мам» ближайшее кафе, где вы сможете сменить обстановку, а малыш — весело провести время.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'Малыш понимает тон вашего голоса 🗣️', 'Когда вы строгим голосом говорите «нет», малыш замирает и смотрит на вас? Он уже хорошо понимает эмоции и запреты. Сохраняйте установленные границы.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'Приглушите свет 🌙', 'За 1 час до сна выключите дома весь яркий свет и экраны. Мелатонин вырабатывается только в спокойной обстановке.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'Норма сна ⏱️', 'Пора спать! Включите таймер сна. Проанализируйте график, чтобы убедиться, что малыш соблюдает суточную норму сна.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'Выполняет простые просьбы 🧸', 'Когда вы просите принести обувь, малыш действительно идёт и приносит её? Сейчас активно развиваются словарный запас и понимание речи! Чаще вовлекайте малыша в игры.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'Похвалите себя 👏', 'Не обращайте внимания на беспорядок в комнате — лучше посмотрите, как счастлив сегодня ваш малыш. Вы прекрасная мама, и этому не научит ни одна книга.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'Анализ сна с таймером ⏱️', 'Дневной сон стал короче? Запустите таймер сна, проанализируйте график за эту неделю и скорректируйте время вечернего укладывания.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'Поддерживайте друг друга! 💖', 'После трудного дня сядьте напротив партнёра и поговорите по душам. Взаимная поддержка помогает разделить груз забот пополам.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'Дневной аппетит 🥣', 'Получил ли малыш сегодня достаточно белка? Внесите продукты в трекер питания и убедитесь, что дневная норма выполнена.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'Скачок в развитии интеллекта 🧠', 'Что происходит в мозге вашего малыша? Прочитайте в разделе блогов новую статью о когнитивном развитии детей в возрасте 17-18 месяцев.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'График сна ⏱️', 'Время пробуждения изменилось? Просмотрите статистику таймера сна, чтобы точно оценить баланс между дневным и ночным сном.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'Утренний отчёт 💩', 'Пищеварение — один из первых показателей здоровья. При смене подгузника добавляйте данные о стуле в приложение и отслеживайте изменения в течение дня.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'Маленькая звёздочка 🌟', 'Не упустите эту милую улыбку! Сохраните сегодняшнее настроение малыша с помощью интересных тем в инструменте для детской фотосессии.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'Уделите время себе 🍵', 'Малыш уснул — теперь ваша очередь восстановить силы. Приготовьте успокаивающий травяной чай по одному из полезных рецептов.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'Что вас беспокоит? 🤔', 'Малыш внезапно отказывается от еды? Задайте Anacan AI любой вопрос о материнстве и мгновенно получите ответ экспертного уровня.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'Лёгкое засыпание 🎶', 'Малыш не может уснуть после дня, полного активных открытий? Выберите колыбельную в разделе «Белый шум» и создайте в комнате волшебную атмосферу спокойствия.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'Открываем природу 🍂', 'Свежий воздух пойдёт на пользу вам обоим. Найдите новый парк в разделе «Места для мам» и позвольте малышу вволю побегать и выплеснуть энергию.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'Ваш внутренний голос 💖', 'Вы не обязаны быть идеальной мамой — для своего малыша вы самая лучшая. Запишите сегодняшние чувства в дневник настроения, чтобы стало легче.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'Учимся есть самостоятельно ⏱️', 'Малыш пытается есть самостоятельно? Не обращайте внимания на беспорядок! Запустите таймер питания и узнайте, сколько времени занимает самостоятельный приём пищи.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'Полезное лакомство 🍪', 'Магазинные сладости не нужны. Приготовьте по одному из рецептов простое, вкусное печенье без сахара для малышей, начинающих знакомство с прикормом.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'Позаботьтесь о себе 🥗', 'Устали бегать за малышом? Откройте для себя вкусный салат из раздела полезных рецептов для женщин, который мгновенно зарядит вас энергией.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'Утренняя чистота 🧻', 'Как прошла первая за день смена подгузника? Запишите данные о выделениях в приложении, чтобы легко следить за работой желудочно-кишечного тракта малыша.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'Кладезь витаминов 🥦', 'Проверьте сегодняшнее меню с помощью инструмента контроля питания. В рецептах для малышей вас ждут красочные блюда, которые помогут восполнить недостающие витамины!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'Слишком упрямый? 🤖', 'Слово «нет» не сходит с языка малыша? Получите у нашего помощника Anacan AI научно обоснованные психологические советы о том, как справляться с кризисами у ребёнка в возрасте 17.5 месяцев.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'Спокойный вечер 🌊', 'Пора создать в комнате спокойную атмосферу. Включите шум океанских волн в разделе «Белый шум», чтобы помочь нервной системе малыша настроиться на глубокий сон.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'Испытание за обеденным столом ⏱️', 'Приём пищи слишком затягивается? Включите таймер кормления, чтобы соблюдать норму и анализировать причины отсутствия аппетита.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'Ежедневная терапия 📝', 'Материнство порой напоминает эмоциональные американские горки. Откройте Дневник настроения, опишите свою сегодняшнюю усталость и почувствуйте облегчение.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'Время выпить кофе ☕', 'Устали сидеть в четырёх стенах? Найдите в разделе «Места для мам» кафе, куда удобно пойти с ребёнком, и порадуйте себя.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'Милые воспоминания 📸', 'Добавьте в Альбом малыша самый забавный момент сегодняшнего дня. Спустя годы вы будете листать эти снимки и от души смеяться.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'Непроливайка 🥤', 'Малыш любит пить воду на бегу, но обливается? Загляните в раздел «Рекомендуемые товары» и выберите самые удобные поильники по мнению мам.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'Одежда становится мала! 📏', 'Рукава малыша снова стали короткими? Внесите новые показатели в Трекер веса и с гордостью оцените прибавку в росте и весе на графике развития.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'Время самостоятельной игры 🧸', 'Малыш уже может самостоятельно играть с игрушками в течение 10-15 минут. Это значит, что он способен дольше удерживать внимание. Насладитесь тишиной.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'На улице не совсем ясно? ⛅', 'Инструмент «Погода и одежда» мгновенно подскажет вам скорость ветра, которую не определить из окна, и поможет подобрать подходящий комплект одежды.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'Время массажа 💆‍♂️', 'Когда малыш уснёт, сделайте друг другу массаж плеч вместе с партнёром, чтобы снять накопившийся за день стресс. Вы — команда!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'Контроль звуков 🤫', 'Первые полчаса после засыпания — самое чувствительное время. Проверьте уровень шума с помощью шумомера и постарайтесь избегать внезапных громких звуков.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'Быстрый педиатр 🤖', 'Беспокоитесь о развитии речи у ребёнка в возрасте 18 месяцев? Спросите Anacan AI и узнайте, какие слова считаются нормой в этом возрасте.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'Правильная игрушка 🧩', 'Ищете игрушку, которая будет развивать логическое мышление? Откройте для себя полезные пазлы по возрасту в разделе «Рекомендуемые товары».'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'Вечерний ритуал 🌙', 'Укладывание в одно и то же время каждый день формирует привычку. Включите таймер сна, проверьте норму и наслаждайтесь лёгким укладыванием.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'Растём здоровыми 📈', 'До 18-го месяца осталось совсем немного! Проанализируйте темпы развития с помощью инструмента «Отслеживание веса» и проверьте, соответствуют ли рост и вес малыша норме.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'Прекрасное завершение дня 🖼️', 'Добавьте вашу самую весёлую и тёплую совместную фотографию в Альбом малыша, чтобы навсегда сохранить память об этом особенном дне (540 дней!).'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'Вы — героиня! ✨', '540-й день вашего материнства! Расскажите Anacan AI о сегодняшнем достижении, и он подарит вам особую мотивацию, которая сделает ваш день прекраснее.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'Семейный стол 🍲', 'Малыш уже может есть те же блюда, что и вы. С помощью инструмента контроля питания легко рассчитайте пищевую ценность ваших общих блюд.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'Переход к глубокому сну 🌙', 'Включите таймер сна. Если малыш стал чаще просыпаться ночью, успокойте его нервную систему звуком океанских волн из раздела «Белый шум».'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'Утренний сюрприз 💩', 'Сделайте запись при смене первого подгузника за день! Это лучший способ следить за пищеварением и потреблением жидкости у растущего малыша.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'Не выпускает ложку из рук? 🥄', 'Включите таймер кормления. Проанализируйте, сколько времени занимают попытки малыша есть самостоятельно, и проверьте суточную норму питания.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'Дайте волю чувствам 📝', 'Не каждый день бывает идеальным, и это нормально. Запишите свои сегодняшние чувства в Дневнике настроения, освободитесь от стресса и спокойно отдохните.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'Официально 1.5 года! 🎈', 'В этом возрасте ваш малыш растёт очень быстро. Внесите последние показатели в Трекер развития и с гордостью взгляните на график его развития.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'Побалуйте себя ☕', '18 месяцев материнства — это совсем непросто! Найдите уютное кафе на нашей карте мест для мам и закажите себе чашку горячего кофе.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'Готовы к первым пробежкам? 👟', 'Для первых уверенных пробежек нужна правильная обувь! Откройте для себя ортопедические модели, которые больше всего нравятся мамам, в разделе «Рекомендуемые товары».'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'Милые кадры 📸', 'Упал во время бега и рассмеялся? Сразу добавьте этот милый момент в Альбом малыша, превратив его в яркое воспоминание на всю жизнь.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'Достаточно ли железа? 🥩', 'С помощью инструмента контроля питания проверьте, получил ли малыш сегодня достаточно железа. Если есть дефицит, загляните в раздел «Рецепты для малыша».'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'Особенная сказка 🪄', 'Создайте в «Умных сказках» особенную историю, главным героем которой станет ваш малыш: приключения исследователя в возрасте 1.5 года.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'Продолжаем расти! 🌟', 'Ваш малыш уже старше 18 месяцев! Начинается новый этап с самостоятельно ходящим, ярко выражающим эмоции, упрямым, но очень ласковым ребёнком!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', 'Регресс сна в 18 месяцев? 🥱', 'Малыш сопротивляется укладыванию или просыпается ночью? Это известный регресс сна, характерный для данного возраста. Получите у Anacan AI научную информацию об этом биологическом процессе.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', 'Упрямое «Я сам!» 🛑', 'Малыш хочет сам брать всё, даже опасные предметы. Будьте готовы к бурной реакции, когда заберёте их у него. Вместо запрета попробуйте переключить его внимание на что-нибудь более интересное.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'Массаж и тишина 💆‍♀️', 'Спина болит после целого дня беготни? Когда малыш уснёт, попросите партнёра сделать вам 10-минутный массаж плеч. Вы это заслужили!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'Вы на беговой дорожке 🏃‍♂️', 'Малыш стремительно бегает из комнаты в комнату и не может остановиться? В этом возрасте у него окончательно формируется равновесие при ходьбе. Уберите мелкие опасные предметы и просто наблюдайте со стороны за этими энергичными моментами.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'Папина площадка 👨‍👧', 'Терпение на исходе? Закройте дверь комнаты и оставьте ребёнка наедине с папой. Пусть сегодня вечером он станет главным на домашней игровой площадке.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'Фруктовая неприязнь 🍎', 'Сегодня малыш бросает на пол яблоко, которое любил ещё вчера? Избирательность в еде — одна из самых типичных проблем этого возраста. Не теряйтесь в интернете — найдите в разделе «Полезные рецепты» идеи для весёлой подачи фруктов.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'Долгий разговор 🗣️', 'Проснувшись утром, малыш подолгу что-то рассказывает на своём языке? Его речевой центр переживает настоящий скачок развития. Серьёзно выслушайте его и ответьте: «Правда?», «И что было потом?».'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'Полная темнота 🌙', 'Малыш сопротивляется укладыванию? Даже небольшой источник света в комнате отвлекает его внимание. Выключите экраны и полностью затемните комнату, чтобы ускорить выработку мелатонина.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'Память снова вас подвела? 🛒', 'Закончились подгузники или йогурт? Не перегружайте память — сразу добавьте нужное в список покупок, чтобы партнёр купил всё по дороге с работы.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'Детали в книгах 📖', 'Малыш листает книгу и показывает пальцем на самые мелкие детали картинки, например маленькую птичку? Отметьте эту познавательную способность в трекере развития. Зрительная память работает превосходно!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'Проверим режим сна ⏱️', 'Малыш не хочет ложиться вечером? Проанализируйте график таймера сна. Возможно, стоит немного сократить дневной сон.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'Мамина энергия 🔋', 'Не забывайте о себе! Выберите в разделе рецептов вкусное, богатое белком блюдо, которое можно быстро приготовить на завтрак.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', 'Кризисы «Нет!» 🛑', 'Малыш на всё отвечает отказом? Обсудите упрямство в возрасте 1.5 лет с нашим помощником Anacan AI, чтобы получить психологическую поддержку и найти решение.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'Витаминная бомба 🥗', 'Мамины силы не должны иссякать! Приготовьте вкусный смузи, который быстро придаст энергии, выбрав рецепт в разделе полезных рецептов для женщин.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'Ритуал подготовки ко сну 🌙', 'Включите таймер сна и затемните комнату. Анализируя график, вы легко сформируете привычку укладывать малыша каждый вечер в одно и то же время.'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'Развивающие игрушки 🧩', '18 месяцев — идеальный возраст для логических игр. Откройте для себя подходящие по возрасту пазлы и кубики в разделе рекомендаций товаров и развивайте мышление малыша.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'Тепло семейного стола 🍲', 'Теперь малыш уже может полноценно есть вместе с вами! Выберите в разделе рецептов общий полезный ужин, подходящий малышам, которые начали получать прикорм.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'Проверка работы кишечника ⏱️', 'Отмечайте изменения в течение дня в трекере подгузников, чтобы легко оценить, получает ли малыш достаточно жидкости и клетчатки.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'Умиротворяющий шум дождя 🌧️', 'Активный день может утомить мозг малыша. Включите шум дождя в разделе белого шума, чтобы создать в комнате идеальный успокаивающий фон для сна.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'Вы справляетесь! 💖', 'Когда почувствуете усталость, откройте дневник настроения. Просто напишите там «Я со всем справляюсь» и отдохните.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'Исследуем природу 🌳', 'Малышу стало тесно в четырёх стенах? Найдите просторный и безопасный парк в разделе мест для мам и помогите ему выплеснуть энергию.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'Таймер приёма пищи ⏱️', 'Малыш слишком много играет с едой? Включите таймер кормления, чтобы оценить продолжительность приёма пищи и его аппетит.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'Логические игры 🧱', 'Малыш ставит друг на друга 4-5 кубиков и строит башню? Отметьте это достижение моторики в трекере развития! Не забывайте хвалить его за эти маленькие инженерные эксперименты.'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'Ночная смена папы 👨‍🍼', 'Не берите все ночные пробуждения малыша только на себя. Разбудите партнёра: быть командой — значит делить ответственность поровну. Сегодня ночью успокаивать малыша — его очередь.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'Парк или дом? ⛅', 'Хотите выйти на прогулку, но погода переменчива? Помощник по погоде и одежде подскажет не только температуру, но и какую непродуваемую одежду надеть на малыша.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'Звонкий смех 📸', 'Вспомните самый забавный и милый момент сегодняшнего дня и обязательно добавьте небольшое видео или фотографию в альбом малыша.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'Не тревожьтесь 🤖', 'Заметили необычное поведение у малыша? Не ждите наступления ночи — сразу напишите Anacan AI и развейте свои тревоги.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'Потребность в кальции 🦷', 'С помощью инструмента контроля питания подсчитайте, сколько кальция малыш получил сегодня. Для здоровья костей и зубов следите, чтобы он получал необходимое количество молочных продуктов.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'Теперь ваша очередь 🥗', 'Малыш уснул? Отправляйтесь на кухню! Найдите среди полезных рецептов для женщин богатый белком салат, который быстро восполнит силы.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'Дайте волю чувствам 📝', 'День выдался слишком шумным? Запишите свои чувства в дневнике настроения — это поможет освободить голову от накопившихся мыслей.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'Одежда снова стала мала? 📏', 'После 18 месяцев ожидается скачок роста. Внесите новые показатели в трекер веса и с гордостью посмотрите на кривую развития.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'Утренняя гигиена 💧', 'Уже сменили первый за день подгузник? Внесите данные о выделениях в приложение, чтобы легко отслеживать, достаточно ли малыш получает жидкости.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'Капризы за столом 🥣', 'Отказывается от еды? Вместо того чтобы кормить насильно, положите на тарелку овощи разных цветов и пробудите интерес малыша. Новые идеи можно найти среди полезных рецептов.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'Контроль шума 🤫', 'Во время подготовки ко сну контролируйте уровень шума в комнате с помощью Шумомера. Прерывистый ночной сон негативно влияет и на развитие малыша, и на ваше утреннее настроение.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'Музыкальные вечера 🎶', 'Самый простой способ справиться с вечерними капризами — включить любимую песню, обнять малыша и потанцевать вместе.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'Почему он так делает? 🤖', 'Начались беспричинные вспышки гнева (истерики)? Сразу обратитесь за советом к Anacan AI и узнайте об эффективных психологических подходах от экспертов.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'Энергия без сахара 🍌', 'Днём малышу хочется сладкого? Поддерживайте сбалансированное питание с помощью полезных перекусов с бананом и овсянкой из раздела рецептов для малышей.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'Список покупок не заканчивается 🛒', 'Закончились шампунь, подгузники или овсянка? Не держите всё в голове — добавьте в Список покупок и синхронизируйте его с партнёром.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'Пора выйти из дома ☕', 'Устали от рутины? Найдите в разделе Места для мам кафе с детским уголком и насладитесь чашкой горячего кофе.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'Засыпаем со сказкой 🪄', 'Создайте особенную историю в Умных сказках.  Прочитайте её своему малышу.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'Ест самостоятельно! 🥣', 'Не выпускает ложку из рук? Запустите таймер кормления, чтобы отслеживать продолжительность приёма пищи и контролировать норму питания.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'Первые рисунки 🖍️', 'Начал рисовать каракули? Загляните в раздел Рекомендуемые товары и выберите лучшие безопасные смываемые краски.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'Маленький художник 📸', 'Весь перепачкался краской? Вместо того чтобы сердиться, сохраните этот забавный момент с помощью весёлых рамок в Фотосессии малыша.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'Запас кальция 🧀', 'Кальций необходим для зубов и костей. С помощью инструмента контроля питания проверьте, получил ли сегодня малыш необходимую норму молочных продуктов.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'Самый милый момент дня 🖼️', 'Помните, какой поступок малыша сегодня рассмешил вас больше всего? Сразу загрузите этот момент в Альбом малыша и сохраните на будущее.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'Развитие интеллекта 🧠', 'Обязательно прочитайте в разделе Блоги новую статью об удивительных процессах, происходящих в мозге детей в возрасте 1.5 лет.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'Утренний баланс 🧻', 'Вы уже отметили в приложении первый за день подгузник? Цвет и консистенция выделений точно показывают, получает ли ребёнок достаточно жидкости.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'Испытание за столом ⏱️', 'Малыш подолгу сидит за столом и играет с едой? Включите таймер кормления и начните анализировать причины отсутствия аппетита.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'Регресс сна? 🤖', 'Малыш часто просыпается по ночам? Напишите ИИ-эксперту Anacan и сразу узнайте, не связан ли такой сон со скачком роста.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'Вы — героиня 💖', 'Вы не обязаны быть идеальной. Просто напишите в Дневнике настроения «Я со всем справляюсь» и отдохните.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'Исследуем свежий воздух 🌳', 'Малышу уже тесно в четырёх стенах. Найдите просторный и безопасный парк в разделе «Места для мам» и помогите ему выплеснуть энергию.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'Не дайте энергии иссякнуть 🔋', 'Вы выбились из сил от постоянной беготни? Выберите среди полезных рецептов для женщин вкусный завтрак, который мгновенно зарядит вас энергией.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'Дневной сон ⏱️', 'Включите таймер сна. Уточнив часы дневного сна, вы сможете легко скорректировать переход к вечернему укладыванию.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'Семейный стол 🍲', 'Малыш уже может есть ту же пищу, что и вы. С помощью инструмента контроля питания легко рассчитайте пищевую ценность ваших общих блюд.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'Успокаивающие волны 🌊', 'Малыш не может уснуть после дня, полного активных открытий? Выберите шум океанских волн в разделе «Белый шум» и создайте в комнате волшебную атмосферу покоя.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'Игрушки на логику 🧩', 'Ближе к 18.5 месяцам наступает идеальное время для логических игр. Найдите подходящие по возрасту пазлы и кубики в разделе «Рекомендуемые товары».'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'Темпы роста 📈', 'Проанализируйте темпы развития в инструменте «Трекер развития». Следите по графику, соответствуют ли рост и вес малыша норме.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'Настоящий искатель приключений 📸', 'Добавьте в Альбом малыша самую весёлую фотографию, сделанную во время лазанья или игры в догонялки, и сохраните этот момент на память.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'РОВНО 19 МЕСЯЦЕВ! 🎂', 'Поздравляем! Со дня рождения прошло ровно 19 месяцев! Выберите специальный стикер в разделе «Фотосессия малыша» и поделитесь этой радостью в Сообществе Anacan!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'Звонкий смех 📸', 'Добавьте в Альбом малыша самую весёлую фотографию, сделанную во время лазанья или игры в догонялки, и превратите усталость этого дня в улыбку.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'Проследим за ростом 📈', 'Физическая активность малыша возросла. Но соответствует ли прибавка в весе норме? Проанализируйте темпы развития в инструменте «Трекер веса» и избавьтесь от тревог.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'Как работает пищеварение? 💩', 'Во время смены подгузника добавляйте в приложение данные о стуле. Так вы сможете легко отслеживать, как богатые клетчаткой продукты влияют на пищеварение в течение дня.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'График сна ⏱️', 'Пора спать! Запустите таймер сна и проанализируйте режим малыша, чтобы убедиться, что он получает необходимое количество сна в сутки.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'Не хочет делиться? 🤖', 'Не делится игрушкой в парке и кричит? Узнайте у Anacan AI, как вести себя в этой ситуации, и примените рекомендации на практике.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'Утренний сюрприз 💩', 'Уже сменили первый за день подгузник? Внесите данные о стуле в приложение, чтобы внимательно следить за работой желудочно-кишечного тракта и потреблением жидкости.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'Таймер сна запущен! ⏱️', 'Начинается вечерний ритуал. Включите таймер и с лёгкостью проанализируйте, как активный день влияет на время засыпания.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'Разноцветные тарелки 🥦', 'Не ест овощи? Если малыш уже знакомится с прикормом, выберите в разделе «Рецепты» блюдо с интересной подачей и весело восполните норму в инструменте контроля питания.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'Мамина энергия 🔋', 'Повседневная суета лишила вас сил? Не забывайте о себе! Приготовьте по одному из полезных рецептов белковый смузи, который мгновенно зарядит энергией.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'Трудное утро? 🌪️', 'Приступы упрямства утомляют. Сделайте глубокий вдох и сразу спросите Anacan AI, как вести себя в этой ситуации.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'Прислушайтесь к внутреннему голосу 📝', 'Ребёнок уснул. Откройте «Дневник настроения» и выплесните сегодняшние чувства в строки, которые никто не прочитает, — вам станет легче.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'Успокаивающий звук 🌧️', 'Не может уснуть после дня, полного новых открытий? Включите звук дождя в разделе «Белый шум», чтобы естественным образом успокоить нервную систему.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'Свежий воздух и море энергии 🌳', 'Дома стало тесно? Найдите в разделе «Места для мам» новый парк с разными игровыми площадками и помогите ребёнку выплеснуть энергию.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'Скачок в развитии интеллекта 🧠', 'Что происходит в мозге малыша в 18.5 месяцев? Прочитайте новейшую статью в разделе «Блоги» и узнайте больше о процессах развития.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'Долго сидит за столом? ⏱️', 'Начался период игр с едой. Включите таймер кормления и проанализируйте продолжительность приёма пищи, чтобы предотвратить снижение аппетита.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'Одежда снова стала мала? 📏', 'Кажется, малыш внезапно подрос? Внесите новые показатели в «Трекер развития» и с гордостью наблюдайте, как растёт график развития.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'Милые кадры 📸', 'Пытается прыгать или танцевать? Украсьте этот момент весёлыми рамками из «Фотосессии малыша» и создайте воспоминание на всю жизнь.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'Может, болят зубки? 🤖', 'Малыш без видимой причины отказывается от еды или плачет? Спросите Anacan AI об экспертном мнении по поводу признаков прорезывания коренных зубов.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'Безопасные шаги 👟', 'Малыш бегает всё быстрее! Для первых уверенных шагов ознакомьтесь с лучшими моделями ортопедической обуви в разделе «Рекомендуемые товары».'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'Наследие для будущего 🖼️', 'Вы уже добавили в «Альбом малыша» поступок, который сегодня рассмешил вас больше всего? Пусть воспоминания всегда остаются в безопасности, даже если память телефона переполнится.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'Регресс сна? ⏱️', 'Часто просыпается по ночам? Посмотрите график таймера сна. Если дневной сон слишком долгий, возможно, пора немного его сократить.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'Запас кальция 🧀', 'Кальций необходим для зубов и костей. С помощью инструмента контроля питания проверьте, получили ли вы сегодня достаточное количество молочных продуктов.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'Ежедневный баланс 💧', 'Не забудьте сделать отметку во время дневной смены подгузника! Частота выделений помогает оценить потребность малыша в жидкости с учётом его активности и работу пищеварения.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'Теперь ваша очередь 🥗', 'Малыш уснул днём? Самое время заглянуть на кухню! Приготовьте для себя что-нибудь вкусное из раздела полезных рецептов для женщин.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'Перерыв на кофе ☕', 'Домашние дела и рутина вас утомили? Найдите среди Мест, дружественных к мамам, кафе с детским уголком. Вы совершенно точно заслуживаете чашку горячего кофе.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'Идеальных мам не бывает 💖', 'Если сегодня всё пошло не по плану, не вините себя. Запишите свои переживания в Дневнике настроения и спокойно выдохните.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'Успокаивающие волны 🌊', 'После чрезмерной стимуляции мозгу нужно помочь замедлиться. Включите в комнате шум океанских волн из раздела Белых шумов, чтобы успокоить малыша.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', 'Этап «Что это?» 🤖', 'Вас удивляют бесконечные вопросы малыша и его стремление всё исследовать? Узнайте больше об этом скачке познавательного развития у нашего AI-помощника Anacan.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'Хочет есть самостоятельно 🥣', 'Не выпускает ложку из рук? Запустите таймер кормления, следите за продолжительностью процесса и выберите в рецептах для малышей блюда, которые удобно брать руками.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'Запас белка 🥚', 'Белок необходим мышцам активного малыша! С помощью инструмента контроля питания оцените его ежедневный рацион и восполните недостающее.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'Внимание и память 🧠', 'Как учится ваш малыш? В разделе «Блоги» нашего приложения прочитайте статью о развитии внимания и памяти после 1.5 лет.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'Конец дня 🌙', 'Пора спать! Запустите таймер сна, отмечайте режим малыша, чтобы убедиться, что он соблюдает суточную норму сна, и отдыхайте.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'Операция «Брокколи»! 🥦', 'Отказывается от овощей? Не переживайте. Узнайте в рецептах для малышей, как спрятать брокколи во вкусных блинчиках.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'Признайтесь себе 🛋️', 'Сегодня вы очень устали и хотели всё бросить? Это нормально! Откройте Дневник настроения, напишите «Мне нужен отдых» и посвятите этот вечер только себе.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'Подгузники всё чаще остаются сухими? 🧻', 'Проверьте утренний подгузник. Если он остаётся сухим более 2 часов, это может быть первым сигналом готовности к приучению к горшку! Внесите данные в трекер подгузников и проверьте статистику.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'Водный баланс мамы 💧', 'Забегались за малышом и забыли попить? Это может быть причиной головной боли. Приготовьте детокс-воду по полезным рецептам, чтобы восстановить силы.'),
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d', 'До сна 10 минут... ⏱️', 'Запустите таймер сна и приглушите свет в комнате. Включите шум леса из раздела «Белый шум», чтобы превратить подготовку ко сну в волшебный процесс и для малыша, и для себя.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'Макаронный монстр! 🍝', 'Пока малыш ел самостоятельно, он испачкал одежду и даже волосы? Не упустите этот забавный момент! Украсьте фото весёлыми рамками из детской фотосессии и добавьте его в альбом.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'Бьётся и кусается? 🛑', 'Эмоции, которые малыш пока не умеет выражать, иногда превращаются в агрессию. Спросите у Anacan AI, как правильно реагировать на укусы и удары в этом возрасте.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'Как привить любовь к книгам? 📖', 'Читаете перед сном? В разделе «Блоги» узнайте золотые правила, которые помогут ребёнку полюбить книги и удерживать внимание на страницах.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'Новые открытия и опасности ⚠️', 'Малыш уже забирается повсюду! Чтобы сделать дом безопаснее, обязательно найдите мягкие накладки на углы мебели в разделе «Рекомендуемые товары».'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'Достаточно ли железа? 🥩', 'Чтобы активный малыш не столкнулся с анемией и сохранял энергию, проверьте сегодняшнее потребление железа в инструменте контроля питания и восполните нехватку.')
) AS v(id, t, b)
WHERE x.id = v.id;
